window.DATA_A1_G=[{"id":"G1","q":"A mis alumnos de lengua ____ gusta aprender palabras nuevas.","o":["le","les","los","se"],"a":1,"k":"gustar 구문","t":"우리 어학 수업 학생들은 새 단어 배우는 것을 좋아한다.","e":"gustar(~가 마음에 들다)는 '좋아하는 사람'을 간접목적격 대명사(~에게에 해당: me, te, le, nos, os, les)로 나타냅니다. 'A mis alumnos(내 학생들에게)'는 3인칭 복수이므로 les를 씁니다. 스페인어에서는 'a + 사람'을 앞에 두더라도 대명사를 함께 쓰는 것이 원칙입니다.","x":["le: 3인칭 단수(그/그녀/당신에게)용이라 복수인 학생들과 맞지 않습니다 ✗","les: 3인칭 복수 간접목적격(그들에게)으로 alumnos와 일치합니다 ✓","los: 직접목적격(그들을)이라 gustar 구문에 쓰지 않습니다 ✗","se: 재귀·무인칭 대명사로 이 문장 구조에 맞지 않습니다 ✗"]},{"id":"G2","q":"Papá, ¿qué es ____? —Un reloj de pulsera.","o":["estos","este","esto","esta"],"a":2,"k":"중성 지시대명사","t":"아빠, 이게 뭐예요? — 손목시계야.","e":"무엇인지 아직 모르는 물건을 가리킬 때는 성(남성/여성)이 정해지지 않은 중성 지시대명사 esto(이것)를 씁니다. '¿Qué es esto?(이건 뭐예요?)'는 아주 자주 쓰는 표현입니다. 대답을 듣고 나서야 'un reloj(남성)'임을 알게 되므로 질문 단계에서는 esto가 자연스럽습니다.","x":["estos: 남성 복수 '이것들'로, 물건 하나를 묻는 상황과 맞지 않습니다 ✗","este: 남성 단수 지시사로, 정체를 모르는 물건을 물을 때는 보통 쓰지 않습니다 ✗","esto: 정체를 모르는 것을 가리키는 중성 '이것' → 정답 ✓","esta: 여성 단수 지시사라 정체를 모르는 물건을 묻는 데 맞지 않습니다 ✗"]},{"id":"G3","q":"Los profesores ____ tenemos este año son muy simpáticos.","o":["quien","que","los que","quienes"],"a":1,"k":"관계대명사 que","t":"올해 우리가 배우는 선생님들은 아주 친절하시다.","e":"'Los profesores'를 뒤에서 꾸며 주는 관계대명사(앞의 명사를 설명하는 절을 이어 주는 말)가 필요합니다. 관계절 안에서 profesores는 tenemos의 직접목적어(~을)이므로 전치사 없이 que를 씁니다. que는 사람·사물 모두에 쓸 수 있는 가장 기본적인 관계대명사입니다.","x":["quien: 전치사 없이 목적어 자리에 쓰지 않으며, 복수 선행사와도 맞지 않습니다 ✗","que: 사람·사물 모두 받는 기본 관계대명사 → 정답 ✓","los que: 선행사 바로 뒤 제한적 관계절에서는 전치사 없이 쓰지 않습니다 ✗","quienes: 전치사 없이 제한적 관계절의 목적어로는 쓰지 않습니다 ✗"]},{"id":"G4","q":"Hay ____ comprar toallas nuevas.","o":["que","porque","para que","como"],"a":0,"k":"hay que + 동사원형","t":"새 수건을 사야 한다.","e":"'hay que + 동사원형'은 '(누구든) ~해야 한다'라는 일반적인 의무를 나타내는 고정 표현입니다. 주어를 특정하지 않고 '해야 할 일'을 말할 때 씁니다. 예: Hay que estudiar.(공부해야 한다.)","x":["que: hay que + 동사원형 '~해야 한다' → 정답 ✓","porque: '왜냐하면'이라는 이유 접속사라 이 구조에 맞지 않습니다 ✗","para que: '~하도록'이라는 목적 표현으로 뒤에 접속법 절이 와야 합니다 ✗","como: '~처럼/~하므로'라는 뜻이라 의무 표현을 만들지 못합니다 ✗"]},{"id":"G5","q":"En mi barrio no ____ ningún parque.","o":["hay","está","es","tiene"],"a":0,"k":"hay (존재)","t":"우리 동네에는 공원이 하나도 없다.","e":"'~이 있다/없다'처럼 어떤 것의 존재 자체를 말할 때는 hay를 씁니다. hay는 단수·복수 상관없이 형태가 변하지 않습니다. 특정한 것의 위치를 말할 때는 estar를 쓰지만, ningún parque(어떤 공원도)처럼 불특정한 것은 hay와 함께 씁니다.","x":["hay: 존재(있다/없다)를 나타내는 표현 → 정답 ✓","está: 특정한 대상의 위치를 말할 때 쓰며 ningún 같은 불특정 명사와는 쓰지 않습니다 ✗","es: ser 동사로 정체·성질을 말할 때 쓰지 존재를 나타내지 않습니다 ✗","tiene: '가지다'라는 뜻으로 주어(동네)가 소유하는 구조가 아니어서 어색합니다 ✗"]},{"id":"G6","q":"Hace mucho tiempo ____ no vemos a Manolo.","o":["de que","de","que","como"],"a":2,"k":"hace + 시간 + que","t":"우리는 마놀로를 못 본 지 오래되었다.","e":"'hace + 시간 + que + 현재형'은 '~한 지 (시간)이 되었다'라는 뜻의 고정 표현입니다. 시간 표현 뒤에 que를 넣어 뒤의 문장과 연결합니다. 예: Hace dos años que vivo aquí.(여기 산 지 2년 되었다.)","x":["de que: hace ... que 구문에 de를 넣지 않습니다 ✗","de: 이 구문에서는 de만으로 문장을 이을 수 없습니다 ✗","que: hace + 시간 + que '~한 지 ~되었다' → 정답 ✓","como: '~처럼'이란 뜻이라 이 구문에 맞지 않습니다 ✗"]},{"id":"G7","q":"No cojas ____ paraguas, Alberto; no es tuyo.","o":["esas","esos","ese","esa"],"a":2,"k":"지시형용사 일치","t":"알베르토, 그 우산 가져가지 마. 네 것이 아니잖아.","e":"지시형용사(이/그/저)는 뒤에 오는 명사의 성·수에 맞춥니다. paraguas(우산)는 -s로 끝나지만 단수·복수 형태가 같은 남성 명사이고, 뒤에 'no es tuyo(단수)'가 나오므로 남성 단수 ese가 맞습니다. 참고로 스페인에서는 coger가 '잡다/가져가다'지만, 중남미 일부 지역에서는 비속어로 쓰이니 tomar를 쓰는 것이 안전합니다.","x":["esas: 여성 복수형이라 남성 명사 paraguas와 맞지 않습니다 ✗","esos: 남성 복수형인데 뒤의 es tuyo가 단수라 맞지 않습니다 ✗","ese: 남성 단수 '그' → 정답 ✓","esa: 여성 단수형이라 남성 명사와 맞지 않습니다 ✗"]},{"id":"G8","q":"El domingo vamos a ir ____ campo con nuestros amigos.","o":["en","en el","a","al"],"a":3,"k":"전치사 a + el = al","t":"일요일에 우리는 친구들과 시골에 갈 거야.","e":"ir(가다)는 방향을 나타내는 전치사 a와 함께 씁니다. 여기서 el campo(시골)의 정관사 el과 a가 만나면 반드시 al로 합쳐집니다(a + el = al). 예: Voy al cine.(나는 영화관에 간다.)","x":["en: '~에서'라는 장소 표현으로 이동 동사 ir와는 맞지 않습니다 ✗","en el: 역시 en이라 이동 방향을 나타내지 못합니다 ✗","a: 관사 el이 빠져서 'ir a campo'는 부자연스럽습니다 ✗","al: a + el의 축약형으로 방향을 나타냅니다 → 정답 ✓"]},{"id":"G9","q":"¿A qué hora ____ tus padres?","o":["levantando","se levantan","levantan","levantarse"],"a":1,"k":"재귀동사 활용","t":"너희 부모님은 몇 시에 일어나시니?","e":"levantarse(일어나다)는 재귀동사(주어가 자기 자신에게 하는 동작을 나타내는 동사)로, 주어에 맞는 재귀대명사를 함께 써야 합니다. 주어 tus padres는 3인칭 복수이므로 se levantan이 됩니다. se 없이 levantar만 쓰면 '(무언가를) 들어 올리다'라는 뜻이 됩니다.","x":["levantando: 현재분사(~하는 중)라 혼자서 문장의 동사가 될 수 없습니다 ✗","se levantan: 3인칭 복수 재귀동사 활용 '(그들이) 일어나다' → 정답 ✓","levantan: 재귀대명사 se가 빠져 '들어 올리다'라는 뜻이 됩니다 ✗","levantarse: 동사원형이라 활용이 필요합니다 ✗"]},{"id":"G10","q":"Yo ____ peino cada día antes de salir de casa.","o":["mi","a mí","se","me"],"a":3,"k":"재귀대명사 me","t":"나는 매일 집을 나서기 전에 머리를 빗는다.","e":"peinarse(머리를 빗다)는 재귀동사이므로 주어 yo에 맞는 재귀대명사 me를 활용형 앞에 둡니다. yo → me, tú → te, él/ella → se 처럼 주어에 따라 바뀝니다. 예: Me lavo las manos.(나는 손을 씻는다.)","x":["mi: 소유형용사 '나의'라 재귀대명사 자리에 올 수 없습니다 ✗","a mí: 전치사 + 대명사 형태로 강조할 때 쓰며 단독으로 재귀대명사를 대신하지 못합니다 ✗","se: 3인칭 재귀대명사라 주어 yo와 맞지 않습니다 ✗","me: 1인칭 단수 재귀대명사 → 정답 ✓"]},{"id":"G11","q":"En esa clase hay ____ personas que hablan inglés muy bien, casi todas.","o":["pocas","muy pocas","suficiente","bastantes"],"a":3,"k":"수량 표현","t":"그 반에는 영어를 아주 잘하는 사람이 꽤 많다, 거의 모두가 그렇다.","e":"뒤의 'casi todas(거의 모두)'가 많은 수를 나타내므로 '꽤 많은'이란 뜻의 bastantes가 맞습니다. bastante는 명사의 수에 맞춰 복수 personas 앞에서는 bastantes가 됩니다. 반대로 pocas(적은)는 의미가 정반대입니다.","x":["pocas: '적은'이라 casi todas(거의 모두)와 모순됩니다 ✗","muy pocas: '아주 적은'이라 문맥과 정반대입니다 ✗","suficiente: '충분한'이고 단수형이라 복수 personas와 맞지 않습니다 ✗","bastantes: '꽤 많은' 복수형 → 정답 ✓"]},{"id":"G12","q":"Espero ____ tengáis un buen fin de semana.","o":["para que","de que","a que","que"],"a":3,"k":"esperar que","t":"너희가 좋은 주말 보내길 바라.","e":"esperar(바라다) 뒤에 다른 사람에 대한 바람을 말할 때는 'esperar que + 접속법(바람·의심·감정을 나타낼 때 쓰는 동사 형태)'을 씁니다. tengáis는 tener의 vosotros 접속법 현재형입니다. 중남미에서는 vosotros 대신 ustedes를 써서 'Espero que tengan...'이라고 합니다.","x":["para que: '~하도록'이란 목적 표현으로 esperar 뒤에 쓰지 않습니다 ✗","de que: esperar는 de 없이 바로 que를 씁니다 ✗","a que: esperar a que는 '~할 때까지 기다리다'라는 다른 뜻입니다 ✗","que: esperar que + 접속법 '~하기를 바라다' → 정답 ✓"]},{"id":"G13","q":"El zumo de piña está ____ la nevera.","o":["entre","a","de","en"],"a":3,"k":"장소 전치사 en","t":"파인애플 주스는 냉장고 안에 있다.","e":"'~안에, ~에'처럼 물건이 있는 장소를 나타낼 때는 전치사 en을 씁니다. estar en + 장소는 '~에 있다'라는 가장 기본적인 위치 표현입니다. 참고로 '주스'는 스페인에서 zumo, 중남미에서는 jugo라고 합니다.","x":["entre: '~사이에'라 두 개 이상의 대상이 필요합니다 ✗","a: 방향·도착점을 나타내며 위치를 말할 때는 쓰지 않습니다 ✗","de: '~의/~에서부터'라는 뜻이라 위치를 나타내지 못합니다 ✗","en: '~안에/~에' 위치 표현 → 정답 ✓"]},{"id":"G14","q":"¿Vives con ____ familia? —Sí, vivo con mis padres y mi hermano.","o":["su","tu","tus","vuestra"],"a":1,"k":"소유형용사 tu","t":"너는 가족이랑 같이 사니? — 응, 부모님이랑 남동생이랑 같이 살아.","e":"vives는 tú(너)에 대한 활용이므로 '너의'라는 소유형용사 tu를 씁니다. 소유형용사는 소유하는 대상(familia, 단수)의 수에 맞추므로 단수 tu가 됩니다. 악센트 없는 tu는 '너의', 악센트 있는 tú는 '너는'이니 구별하세요.","x":["su: '그/그녀/당신의'라 tú로 말하는 문장과 맞지 않습니다 ✗","tu: '너의' 단수형 → 정답 ✓","tus: 복수형이라 단수 명사 familia와 맞지 않습니다 ✗","vuestra: '너희의'라 단수 tú를 상대로 하는 질문과 맞지 않습니다 ✗"]},{"id":"G15","q":"Esa mujer es una de ____ mejores cantaoras del mundo del flamenco.","o":["las","la","los","ellas"],"a":0,"k":"최상급 정관사","t":"그 여자는 플라멩코 계에서 가장 뛰어난 칸타오라(여성 플라멩코 가수) 중 한 명이다.","e":"최상급 '가장 ~한'은 '정관사 + mejor(es) + 명사'로 만듭니다. 'una de(~중 하나)' 뒤에는 복수 명사가 오고, cantaoras는 여성 복수이므로 정관사 las가 맞습니다. 예: Es uno de los mejores libros.(그것은 최고의 책들 중 하나다.)","x":["las: 여성 복수 정관사로 cantaoras와 일치 → 정답 ✓","la: 단수형이라 복수 명사 cantaoras와 맞지 않습니다 ✗","los: 남성 복수형이라 여성 명사 cantaoras와 맞지 않습니다 ✗","ellas: 인칭대명사 '그녀들'이라 관사 자리에 올 수 없습니다 ✗"]},{"id":"G16","q":"Nunca le pongo demasiada sal ____ la comida.","o":["por","a","ø","de"],"a":1,"k":"poner 전치사 a","t":"나는 음식에 소금을 절대 너무 많이 넣지 않는다.","e":"'poner(넣다/놓다) + 물건 + a + 대상'은 '~에 …을 넣다'라는 구조입니다. 앞의 le는 la comida를 가리키는 간접목적격 대명사로, 'a la comida'와 함께 쓰이는 중복 표현입니다. 예: Le pongo azúcar al café.(나는 커피에 설탕을 넣는다.)","x":["por: '~때문에/~을 통해'라 넣는 대상을 나타내지 못합니다 ✗","a: 간접목적어(~에게/~에)를 나타냄 → 정답 ✓","ø: 간접목적어 앞에는 전치사 a가 필요합니다 ✗","de: '~의'라 소금이 음식의 것이라는 이상한 뜻이 됩니다 ✗"]},{"id":"G17","q":"Marcelo es más alto ____ Jorge.","o":["como","que","tanto","de"],"a":1,"k":"비교급 más...que","t":"마르셀로는 호르헤보다 키가 크다.","e":"우등 비교 '~보다 더 …하다'는 'más + 형용사 + que + 비교 대상'으로 만듭니다. 비교 대상(Jorge) 앞에는 que를 씁니다. 예: Mi casa es más grande que la tuya.(우리 집은 너희 집보다 크다.)","x":["como: tan ... como(…만큼)의 동등 비교에 씁니다 ✗","que: más ... que '~보다 더' → 정답 ✓","tanto: 동등 비교 tanto ... como에 쓰는 말입니다 ✗","de: más de는 숫자 앞에서 '~이상'일 때 씁니다 ✗"]},{"id":"G18","q":"Mi ____ amigo es médico de cabecera.","o":["el mejor","mucho mejor","mejores","mejor"],"a":3,"k":"mejor + 명사","t":"내 가장 친한 친구는 가정의(동네 주치의)다.","e":"소유형용사 mi 다음에는 정관사를 함께 쓸 수 없으므로 'mi mejor amigo(내 가장 친한 친구)'가 됩니다. mejor는 명사 앞에 와서 '최고의/가장 좋은'이라는 뜻을 나타내고, 단수 amigo에 맞춰 단수형을 씁니다. 'médico de cabecera'는 '가정의, 주치의'라는 뜻입니다.","x":["el mejor: 소유형용사 mi와 정관사 el은 함께 쓰지 않습니다 ✗","mucho mejor: '훨씬 더 좋은'이라는 비교 표현으로 이 자리에 어색합니다 ✗","mejores: 복수형이라 단수 amigo와 맞지 않습니다 ✗","mejor: 'mi mejor amigo(가장 친한 친구)' → 정답 ✓"]},{"id":"G19","q":"Mis padres compraron su casa ____ 1992.","o":["la","en","el","al"],"a":1,"k":"연도 전치사 en","t":"우리 부모님은 1992년에 집을 샀다.","e":"'~년에'라고 연도를 말할 때는 전치사 en을 쓰고 관사를 붙이지 않습니다. 월(en mayo), 계절(en verano)도 en을 씁니다. 반면 날짜(el 5 de mayo)나 요일(el lunes)에는 정관사를 씁니다.","x":["la: 관사만으로는 연도를 표현할 수 없습니다 ✗","en: 연도 앞에 쓰는 전치사 → 정답 ✓","el: 날짜·요일 앞에 쓰며 연도 앞에는 쓰지 않습니다 ✗","al: a + el 축약형으로 연도 표현에 쓰지 않습니다 ✗"]},{"id":"G20","q":"Hoy me siento ____ que ayer, así que voy a pedir una cita médica.","o":["tan mal","más peor","peor","más mal"],"a":2,"k":"불규칙 비교급 peor","t":"오늘은 어제보다 몸이 더 안 좋아서 병원 예약을 할 거야.","e":"mal(나쁘게)의 비교급은 'más mal'이 아니라 불규칙형 peor(더 나쁘게)입니다. 뒤에 'que ayer(어제보다)'가 있으므로 비교급이 필요합니다. peor 자체에 '더'라는 뜻이 있어서 más를 또 붙이면 틀립니다.","x":["tan mal: 동등 비교로 tan ... como와 쓰여야 하며 que와 맞지 않습니다 ✗","más peor: peor에 이미 '더'가 들어 있어 más를 겹쳐 쓰면 틀립니다 ✗","peor: mal의 불규칙 비교급 '더 나쁘게' → 정답 ✓","más mal: 일반적으로 peor를 쓰며 표준적이지 않습니다 ✗"]},{"id":"G21","q":"A ti no ____ interesa este tema, ¿no?","o":["te","se","le","os"],"a":0,"k":"interesar 구문","t":"너는 이 주제에 관심 없지, 그렇지?","e":"interesar(~의 관심을 끌다)는 gustar처럼 '관심 있는 사람'을 간접목적격 대명사로 나타냅니다. 'A ti(너에게)'가 있으므로 2인칭 단수 te를 씁니다. 'a ti'는 강조를 위한 것이고 te는 생략할 수 없습니다.","x":["te: 2인칭 단수 간접목적격(너에게) → 정답 ✓","se: 재귀·무인칭 대명사로 이 구조에 맞지 않습니다 ✗","le: 3인칭 단수용이라 a ti와 맞지 않습니다 ✗","os: '너희에게'라 단수 ti와 맞지 않습니다 ✗"]},{"id":"G22","q":"Emilio busca a ____ para practicar inglés.","o":["algún","alguien","algo","algunos"],"a":1,"k":"부정어 alguien","t":"에밀리오는 영어 연습할 사람을 찾고 있다.","e":"alguien은 '누군가'라는 뜻의 부정대명사(특정하지 않은 대상을 가리키는 말)로 사람을 가리킵니다. 사람이 직접목적어일 때는 앞에 전치사 a를 붙이므로 'busca a alguien'이 됩니다. algo는 '무언가(사물)'입니다.","x":["algún: 형용사라 뒤에 명사가 와야 합니다(algún amigo) ✗","alguien: '누군가(사람)' → 정답 ✓","algo: '무언가'로 사물을 가리키며 사람 앞의 a와 맞지 않습니다 ✗","algunos: 형용사·대명사 '몇몇'으로 문맥상 어색합니다 ✗"]},{"id":"G23","q":"Elvira prefiere ir a la playa ____ la mañana.","o":["de","por","con","para"],"a":1,"k":"por la mañana","t":"엘비라는 아침에 해변에 가는 것을 더 좋아한다.","e":"하루 중 시간대를 말할 때는 'por la mañana(아침/오전에)', 'por la tarde(오후에)', 'por la noche(밤에)'처럼 por를 씁니다. 중남미 일부 지역에서는 'en la mañana'라고도 합니다. 정확한 시각과 함께 쓸 때는 'a las diez de la mañana(오전 10시에)'처럼 de를 씁니다.","x":["de: 정확한 시각 뒤에 쓰는 형태(las diez de la mañana)라 여기서는 맞지 않습니다 ✗","por: 'por la mañana(아침에)' → 정답 ✓","con: '~와 함께'라 시간대를 나타내지 못합니다 ✗","para: '~을 위해/~까지'라 시간대 표현이 아닙니다 ✗"]},{"id":"G24","q":"Me duelen ____ oídos.","o":["los","las","ø","unos"],"a":0,"k":"doler + 정관사","t":"나는 귀가 아프다.","e":"doler(아프다)는 gustar처럼 아픈 부위가 주어가 됩니다. 신체 부위 앞에는 소유형용사 대신 정관사를 씁니다. oído(귀 안쪽, 청각 기관)는 남성 명사이고 복수이므로 los oídos가 됩니다.","x":["los: 남성 복수 정관사로 oídos와 일치 → 정답 ✓","las: 여성 복수형이라 남성 명사 oídos와 맞지 않습니다 ✗","ø: 주어가 되는 신체 부위 앞에는 관사가 필요합니다 ✗","unos: 부정관사 '몇몇의'라 내 몸의 특정 부위를 가리키기에 어색합니다 ✗"]},{"id":"G25","q":"¡Me encanta el ciclismo! — ____ no, me aburre muchísimo.","o":["Me","A mí","Yo","Mi"],"a":1,"k":"A mí no (반대 의견)","t":"나는 사이클 경기가 정말 좋아! — 나는 아니야, 너무 지루해.","e":"gustar·encantar 같은 동사에 대해 '나는 (그렇지 않아)'라고 반응할 때는 'A mí sí / A mí no / A mí también / A mí tampoco'를 씁니다. 상대가 좋다고 했는데 나는 싫으니 'A mí no'가 됩니다. 일반 동사에 반응할 때처럼 yo를 쓰지 않는 것이 핵심입니다.","x":["Me: 대명사 me만으로는 반응 표현을 만들 수 없습니다 ✗","A mí: 'A mí no(나는 아니야)' → 정답 ✓","Yo: gustar 류 동사에 대한 반응에는 yo가 아니라 a mí를 씁니다 ✗","Mi: 소유형용사 '나의'라 맞지 않습니다 ✗"]},{"id":"G26","q":"____ Mónica no le gusta vivir en una casa tan pequeña.","o":["Para","ø","La","A"],"a":3,"k":"a + 사람 (gustar)","t":"모니카는 그렇게 작은 집에 사는 것을 좋아하지 않는다.","e":"gustar 구문에서 '좋아하는 사람'을 명사로 말할 때는 앞에 전치사 a를 붙입니다. 뒤에 나오는 le가 바로 'a Mónica'를 가리키는 간접목적격 대명사입니다. 예: A Pedro le gusta el fútbol.(페드로는 축구를 좋아한다.)","x":["Para: '~를 위해'라 gustar 구문의 사람 표시에 쓰지 않습니다 ✗","ø: 전치사 a가 없으면 Mónica가 주어처럼 되어 틀립니다 ✗","La: 사람 이름 앞에 관사는 표준어에서 쓰지 않으며 문법 구조도 맞지 않습니다 ✗","A: gustar 구문의 'a + 사람' → 정답 ✓"]},{"id":"G27","q":"Ismael siempre llega a casa después ____ mediodía.","o":["el","la","del","de la"],"a":2,"k":"después de + el","t":"이스마엘은 항상 정오가 지나서 집에 도착한다.","e":"después(~후에)는 명사 앞에서 'después de'로 씁니다. mediodía(정오)는 남성 명사이므로 'de + el mediodía'가 되고, de와 el이 만나면 반드시 del로 합쳐집니다. 예: después del trabajo(일이 끝난 후에)","x":["el: de가 빠져서 después와 연결되지 않습니다 ✗","la: de가 없고 mediodía는 남성 명사라 맞지 않습니다 ✗","del: de + el 축약형 → 정답 ✓","de la: mediodía는 남성 명사라 여성 관사 la를 쓰지 않습니다 ✗"]},{"id":"G28","q":"Juana no quiere hablar ____.","o":["con te","con ti","con tú","contigo"],"a":3,"k":"contigo","t":"후아나는 너와 이야기하고 싶어 하지 않는다.","e":"전치사 con(~와 함께) 뒤에 '나'와 '너'가 오면 특별한 형태 conmigo(나와 함께), contigo(너와 함께)를 씁니다. 다른 전치사 뒤에서는 mí, ti를 쓰지만(para ti), con과는 반드시 한 단어로 합쳐집니다.","x":["con te: te는 목적격 대명사라 전치사 뒤에 올 수 없습니다 ✗","con ti: con + ti는 반드시 contigo로 합쳐야 합니다 ✗","con tú: 주격 tú는 전치사 뒤에 쓰지 않습니다 ✗","contigo: '너와 함께' → 정답 ✓"]},{"id":"G29","q":"¿Para qué quieres ____ copas?","o":["tanta","tanto","tantas","tantos"],"a":2,"k":"tanto 일치","t":"그렇게 많은 잔을 뭐 하려고?","e":"tanto(그렇게 많은)가 명사 앞에서 형용사로 쓰일 때는 명사의 성·수에 맞춰 tanto/tanta/tantos/tantas로 변합니다. copas(잔)는 여성 복수이므로 tantas가 됩니다. 예: tantos libros(그렇게 많은 책)","x":["tanta: 여성 단수형이라 복수 copas와 맞지 않습니다 ✗","tanto: 남성 단수형이라 맞지 않습니다 ✗","tantas: 여성 복수형으로 copas와 일치 → 정답 ✓","tantos: 남성 복수형이라 여성 명사 copas와 맞지 않습니다 ✗"]},{"id":"G30","q":"¿____ quieres tomar de postre?","o":["Cuándo","Qué","De qué","Cómo"],"a":1,"k":"의문사 qué","t":"디저트로 뭐 먹을래?","e":"'무엇'을 물을 때는 의문사 qué를 씁니다. tomar는 여기서 '먹다/마시다'라는 뜻이고, 'de postre'는 '디저트로'입니다. 의문사에는 항상 악센트가 붙습니다(qué, cuándo, cómo).","x":["Cuándo: '언제'라 무엇을 먹을지 묻는 문장과 맞지 않습니다 ✗","Qué: '무엇' → 정답 ✓","De qué: '무엇에 대해/무엇으로 만든'이라 tomar와 맞지 않습니다 ✗","Cómo: '어떻게'라 문맥에 맞지 않습니다 ✗"]},{"id":"G31","q":"Desde ____ murió su abuela, está muy triste.","o":["ø","que","como","cuando"],"a":1,"k":"desde que","t":"할머니가 돌아가신 이후로 그는 몹시 슬퍼한다.","e":"'desde que + 문장'은 '~한 이후로'라는 뜻으로, 어떤 일이 시작된 시점을 나타냅니다. desde 뒤에 명사가 오면 바로 쓰지만(desde el lunes), 동사가 있는 문장이 오면 que가 필요합니다. 예: Desde que vivo aquí, estoy feliz.(여기 산 이후로 행복하다.)","x":["ø: desde 뒤에 문장이 오려면 que가 필요합니다 ✗","que: 'desde que(~한 이후로)' → 정답 ✓","como: desde como라는 표현은 없습니다 ✗","cuando: 'desde cuando'는 의문문(¿Desde cuándo?)에서나 쓰며 이 문장에 맞지 않습니다 ✗"]},{"id":"G32","q":"Tener una buena alimentación es importantísimo para ____ salud.","o":["el","ø","lo","la"],"a":3,"k":"추상명사 정관사","t":"좋은 식생활은 건강에 아주 중요하다.","e":"스페인어에서는 salud(건강)처럼 일반적인 개념을 말하는 추상명사 앞에 보통 정관사를 붙입니다. salud는 -d로 끝나는 여성 명사이므로 la salud가 됩니다. -dad, -tud, -ud로 끝나는 명사는 대부분 여성입니다.","x":["el: salud는 여성 명사라 남성 관사가 맞지 않습니다 ✗","ø: 일반 개념으로서의 '건강' 앞에는 관사를 붙이는 것이 자연스럽습니다 ✗","lo: 중성 관사로 형용사 앞(lo bueno)에 쓰며 명사 앞에 쓰지 않습니다 ✗","la: 여성 정관사로 salud와 일치 → 정답 ✓"]},{"id":"G33","q":"____ carpetas están vacías.","o":["Estos","Aquella","Esas","Aquel"],"a":2,"k":"지시형용사 일치","t":"그 서류철들은 비어 있다.","e":"지시형용사는 명사의 성·수에 맞춰야 합니다. carpetas(서류철·폴더)는 여성 복수이고 동사 están과 형용사 vacías도 복수이므로 여성 복수형 esas가 맞습니다. 참고로 '폴더'는 스페인에서 carpeta, 중남미에서는 fólder라고도 합니다.","x":["Estos: 남성 복수형이라 여성 명사와 맞지 않습니다 ✗","Aquella: 여성 단수형이라 복수 carpetas와 맞지 않습니다 ✗","Esas: 여성 복수 '그' → 정답 ✓","Aquel: 남성 단수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G34","q":"Ahora los chicos ____ haciendo los deberes de la escuela.","o":["estáis","está","estás","están"],"a":3,"k":"estar + 현재분사","t":"지금 아이들은 학교 숙제를 하고 있다.","e":"'estar + 현재분사(-ando/-iendo)'는 '~하고 있다'라는 진행 중인 동작을 나타냅니다. 주어 los chicos(아이들)는 3인칭 복수이므로 están을 씁니다. 예: Estoy comiendo.(나는 먹고 있다.)","x":["estáis: vosotros(너희) 형태라 3인칭 주어와 맞지 않습니다 ✗","está: 3인칭 단수형이라 복수 주어와 맞지 않습니다 ✗","estás: tú(너) 형태라 맞지 않습니다 ✗","están: 3인칭 복수 → 정답 ✓"]},{"id":"G35","q":"¿____ ha hecho este dibujo tan bonito?","o":["Quiénes","Quién","Qué","De quién"],"a":1,"k":"의문사 quién","t":"이렇게 예쁜 그림은 누가 그렸어?","e":"'누가'를 물을 때는 quién을 씁니다. 동사 ha hecho가 단수형이므로 단수 quién이 맞습니다. 여러 사람을 예상할 때는 quiénes를 쓰고 동사도 복수(han hecho)가 됩니다.","x":["Quiénes: 복수형인데 동사 ha hecho가 단수라 맞지 않습니다 ✗","Quién: '누가' 단수 → 정답 ✓","Qué: '무엇'이라 그림을 그린 사람을 묻지 못합니다 ✗","De quién: '누구의 것'이라 소유자를 묻는 표현입니다 ✗"]},{"id":"G36","q":"Mi color favorito es ____ azul.","o":["lo","el","ø","la"],"a":1,"k":"색 이름 정관사","t":"내가 좋아하는 색은 파란색이다.","e":"색 이름이 명사로 쓰일 때는 남성 명사로 취급하여 정관사 el을 붙입니다. 따라서 'el azul(파란색)', 'el rojo(빨간색)'처럼 씁니다. color 자체도 남성 명사입니다.","x":["lo: 중성 관사로 'lo + 형용사(~한 것)'에 쓰며 색 이름에는 쓰지 않습니다 ✗","el: 색 이름은 남성 명사 → 정답 ✓","ø: ser 뒤에서 특정한 색을 말할 때는 관사를 붙이는 것이 자연스럽습니다 ✗","la: 색 이름은 남성이므로 여성 관사를 쓰지 않습니다 ✗"]},{"id":"G37","q":"Badajoz es ____ ciudad de España.","o":["la","el","un","una"],"a":3,"k":"부정관사 una","t":"바다호스는 스페인의 한 도시이다.","e":"여러 도시 중 '하나'를 소개할 때는 부정관사(하나의, 어떤)를 씁니다. ciudad(도시)는 여성 명사이므로 una가 맞습니다. 'la ciudad de España'라고 하면 스페인에 도시가 하나뿐인 것처럼 들립니다.","x":["la: 정관사라 스페인의 유일한 도시라는 이상한 뜻이 됩니다 ✗","el: 남성 정관사라 여성 명사 ciudad와 맞지 않습니다 ✗","un: 남성 부정관사라 맞지 않습니다 ✗","una: 여성 부정관사 '하나의' → 정답 ✓"]},{"id":"G38","q":"¿Quieres ____ copa de vino?","o":["otra","otras","una otra","otro"],"a":0,"k":"otro 용법","t":"와인 한 잔 더 할래?","e":"otro/otra(또 다른, 하나 더)는 앞에 부정관사 un/una를 붙이지 않습니다. copa(잔)는 여성 단수이므로 otra를 씁니다. 영어 'another'를 생각해 'una otra'로 쓰는 실수를 자주 하니 주의하세요.","x":["otra: 여성 단수 '하나 더' → 정답 ✓","otras: 복수형이라 단수 copa와 맞지 않습니다 ✗","una otra: otro 앞에는 부정관사를 쓰지 않습니다 ✗","otro: 남성형이라 여성 명사 copa와 맞지 않습니다 ✗"]},{"id":"G39","q":"¿Qué haces normalmente ____ la tarde?","o":["para","de","ø","por"],"a":3,"k":"por la tarde","t":"너는 보통 오후에 뭐 하니?","e":"하루의 시간대는 'por la mañana / por la tarde / por la noche'처럼 por로 나타냅니다. 'a las cinco de la tarde(오후 5시에)'처럼 정확한 시각이 있을 때만 de를 씁니다. 중남미에서는 'en la tarde'도 자주 씁니다.","x":["para: '~을 위해/~까지'라 시간대 표현이 아닙니다 ✗","de: 정확한 시각 뒤에서만 씁니다(a las cinco de la tarde) ✗","ø: 시간대 앞에는 전치사가 필요합니다 ✗","por: 'por la tarde(오후에)' → 정답 ✓"]},{"id":"G40","q":"¿____ se deletrea su apellido?","o":["Qué","Por qué","Quién","Cómo"],"a":3,"k":"의문사 cómo","t":"당신의 성은 철자가 어떻게 되나요?","e":"'어떻게'를 물을 때는 cómo를 씁니다. deletrearse는 '철자를 하나씩 말하다'라는 뜻이고, se가 붙어 '(철자가) ~게 쓰이다'라는 수동적인 의미가 됩니다. 이름을 물을 때도 '¿Cómo te llamas?'처럼 cómo를 씁니다.","x":["Qué: '무엇'이라 방법을 묻는 질문에 맞지 않습니다 ✗","Por qué: '왜'라 문맥에 맞지 않습니다 ✗","Quién: '누구'라 철자 방법을 묻지 못합니다 ✗","Cómo: '어떻게' → 정답 ✓"]},{"id":"G41","q":"Suelo ____ leer las noticias por la noche.","o":["ø","de","a","en"],"a":0,"k":"soler + 동사원형","t":"나는 보통 밤에 뉴스를 읽는다.","e":"soler는 '보통 ~하다, ~하곤 하다'라는 습관을 나타내며, 바로 뒤에 전치사 없이 동사원형이 옵니다. soler는 o → ue로 바뀌는 불규칙동사입니다(suelo, sueles, suele...). 예: Suelo correr los sábados.(나는 토요일마다 달리곤 한다.)","x":["ø: soler + 동사원형, 전치사 없음 → 정답 ✓","de: soler 뒤에 de를 넣지 않습니다 ✗","a: soler 뒤에 a를 넣지 않습니다 ✗","en: soler 뒤에 en을 넣지 않습니다 ✗"]},{"id":"G42","q":"¿____ carne necesitamos para la barbacoa?","o":["Cuánto","Cuándo","Cómo","Cuánta"],"a":3,"k":"cuánto 일치","t":"바비큐 하는 데 고기가 얼마나 필요하지?","e":"cuánto(얼마나 많은)가 명사 앞에 오면 명사의 성·수에 맞춰 변합니다. carne(고기)는 셀 수 없는 여성 단수 명사이므로 cuánta가 됩니다. 예: ¿Cuántos años tienes?(너 몇 살이니?)","x":["Cuánto: 남성형이라 여성 명사 carne와 맞지 않습니다 ✗","Cuándo: '언제'라 양을 묻지 못합니다 ✗","Cómo: '어떻게'라 양을 묻지 못합니다 ✗","Cuánta: 여성 단수 '얼마나 많은' → 정답 ✓"]},{"id":"G43","q":"¿Quieres otra taza ____ té?","o":["de","ø","a","con"],"a":0,"k":"용기 + de + 내용물","t":"차 한 잔 더 할래?","e":"'잔·병·봉지 + de + 내용물'은 '~ 한 잔/한 병'처럼 양을 나타내는 표현입니다. 내용물 앞에는 관사를 붙이지 않고 de만 씁니다. 예: una botella de agua(물 한 병), un vaso de leche(우유 한 잔)","x":["de: 'taza de té(차 한 잔)' → 정답 ✓","ø: 용기와 내용물 사이에 de가 필요합니다 ✗","a: 'taza a té'라는 표현은 없습니다 ✗","con: '차가 곁들여진 잔'처럼 뜻이 달라집니다 ✗"]},{"id":"G44","q":"María Isabel es menor ____.","o":["de mí","que yo","que mí","a mí"],"a":1,"k":"비교 대상 que yo","t":"마리아 이사벨은 나보다 어리다.","e":"menor(더 어린)는 불규칙 비교급으로, 비교 대상 앞에는 que를 씁니다. que 뒤에는 주격 대명사(yo, tú)가 와서 'que yo(나보다)'가 됩니다. 'que mí'처럼 전치사 뒤에 쓰는 형태는 쓰지 않습니다.","x":["de mí: 비교 대상 앞에는 de가 아니라 que를 씁니다 ✗","que yo: que + 주격 대명사 '나보다' → 정답 ✓","que mí: que 뒤에는 mí가 아니라 yo를 씁니다 ✗","a mí: 비교 표현이 아닙니다 ✗"]},{"id":"G45","q":"¿A qué ____ vosotras?","o":["te dedicas","os dedicáis","se dedica","se dedican"],"a":1,"k":"dedicarse 활용","t":"너희는 무슨 일을 하니?","e":"'¿A qué te dedicas?'는 '무슨 일을 하세요?(직업이 뭐예요?)'라는 표현으로, 재귀동사 dedicarse(~에 종사하다)를 씁니다. 주어 vosotras(너희, 여성)에 맞춰 'os dedicáis'가 됩니다. 중남미에서는 vosotros 대신 ustedes를 써서 '¿A qué se dedican ustedes?'라고 합니다.","x":["te dedicas: tú(너) 형태라 복수 vosotras와 맞지 않습니다 ✗","os dedicáis: vosotras 형태 → 정답 ✓","se dedica: 3인칭 단수(그/그녀/당신)형이라 맞지 않습니다 ✗","se dedican: ustedes·ellos 형태라 vosotras와 맞지 않습니다(중남미에서는 '너희'의 뜻으로 이 형태를 씀) ✗"]},{"id":"G46","q":"José Manuel y tú ____ mucho talento.","o":["tenéis","tiene","tienes","tenemos"],"a":0,"k":"복합 주어 활용","t":"호세 마누엘과 너는 재능이 많다.","e":"'José Manuel y tú(호세 마누엘과 너)'는 '너희(vosotros)'와 같으므로 vosotros 형태 tenéis를 씁니다. 3인칭 + tú = vosotros, yo가 포함되면 nosotros가 됩니다. 중남미에서는 이 경우 ustedes 형태 tienen을 씁니다.","x":["tenéis: vosotros 형태 → 정답 ✓","tiene: 3인칭 단수라 복수 주어와 맞지 않습니다 ✗","tienes: tú 단수 형태라 맞지 않습니다 ✗","tenemos: nosotros(우리) 형태라 yo가 포함되어야 합니다 ✗"]},{"id":"G47","q":"En México hay más personas que ____ Cuba.","o":["en la","a la","a","en"],"a":3,"k":"비교 대상 반복 en","t":"멕시코에는 쿠바보다 사람이 더 많다.","e":"비교 대상이 장소일 때는 앞의 전치사를 그대로 반복합니다. 'En México ... que en Cuba(멕시코에서 ... 쿠바에서보다)'처럼 en을 다시 씁니다. 나라 이름 Cuba에는 관사를 붙이지 않습니다.","x":["en la: Cuba 앞에는 관사를 붙이지 않습니다 ✗","a la: 전치사도 맞지 않고 관사도 불필요합니다 ✗","a: 장소를 나타내는 앞의 en과 맞지 않습니다 ✗","en: 앞의 en México에 맞춰 반복 → 정답 ✓"]},{"id":"G48","q":"Enhorabuena, tu redacción está muy ____.","o":["bueno","buena","bien","buen"],"a":2,"k":"bien vs bueno","t":"축하해, 네 작문 아주 잘 썼어.","e":"'estar bien'은 '(상태가) 잘 되어 있다, 괜찮다'라는 뜻입니다. bien은 부사이므로 성·수 변화가 없습니다. 'ser bueno'는 성질이 좋다는 뜻이고, estar 뒤에서 '잘 됐다'는 평가는 bien이 자연스럽습니다.","x":["bueno: 남성형 형용사라 여성 명사 redacción과 맞지 않습니다 ✗","buena: 'estar bueno/a'는 주로 음식이 맛있다는 뜻 등으로 쓰여, 결과물이 잘 됐다는 평가에는 bien이 기본입니다 ✗","bien: 부사 '잘' → 정답 ✓","buen: 명사 앞에서만 쓰는 단축형입니다 ✗"]},{"id":"G49","q":"Esa novela me parece aburridísima. — ____.","o":["A mí sí","A mí también","Yo también","Yo sí"],"a":1,"k":"A mí también","t":"그 소설 정말 지루한 것 같아. — 나도 그래.","e":"parecer(~처럼 보이다)는 gustar처럼 사람을 간접목적격으로 나타내므로, 동의할 때는 yo가 아니라 'a mí'를 씁니다. 긍정 문장에 동의하므로 'A mí también(나도 그래)'입니다. 부정 문장에 동의할 때는 'A mí tampoco'를 씁니다.","x":["A mí sí: 상대의 부정 문장에 반대할 때 씁니다 ✗","A mí también: 긍정 문장에 동의 '나도' → 정답 ✓","Yo también: parecer·gustar 류 동사에는 yo가 아니라 a mí를 씁니다 ✗","Yo sí: 일반 동사의 부정 문장에 반대할 때 씁니다 ✗"]},{"id":"G50","q":"____ ordenadores no funcionan.","o":["Esas","Esos","Ese","Esa"],"a":1,"k":"지시형용사 일치","t":"그 컴퓨터들은 작동하지 않는다.","e":"ordenadores(컴퓨터들)는 남성 복수이므로 지시형용사도 남성 복수 esos를 씁니다. 동사 funcionan도 복수입니다. 참고로 '컴퓨터'는 스페인에서 ordenador, 중남미에서는 computadora라고 합니다.","x":["Esas: 여성 복수형이라 남성 명사와 맞지 않습니다 ✗","Esos: 남성 복수 '그' → 정답 ✓","Ese: 단수형이라 복수 명사와 맞지 않습니다 ✗","Esa: 여성 단수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G51","q":"No hay ____ jabón, tenemos que comprar.","o":["ø","del","el","la"],"a":0,"k":"hay + 무관사 명사","t":"비누가 없어, 사야 해.","e":"hay 뒤에는 정관사(el, la)를 쓰지 않습니다. 특히 jabón(비누)처럼 셀 수 없는 물질명사는 관사 없이 'No hay jabón'이라고 합니다. 예: No hay leche.(우유가 없다.)","x":["ø: hay 뒤 셀 수 없는 명사는 관사 없음 → 정답 ✓","del: 프랑스어식 부분관사 표현은 스페인어에 없습니다 ✗","el: hay 뒤에는 정관사를 쓰지 않습니다 ✗","la: 정관사이고 jabón은 남성 명사라 이중으로 틀립니다 ✗"]},{"id":"G52","q":"En mi clase de salsa nunca hay ____ diez aprendices.","o":["más a","muchos más","más","más de"],"a":3,"k":"más de + 숫자","t":"우리 살사 수업에는 수강생이 열 명을 넘는 일이 없다.","e":"숫자 앞에서 '~이상, ~넘게'라고 할 때는 'más de + 숫자'를 씁니다. 'más que'는 일반 비교(~보다 더)에 씁니다. 예: Tengo más de cien libros.(나는 책이 100권 넘게 있다.)","x":["más a: 'más a'라는 표현은 없습니다 ✗","muchos más: '훨씬 많은'이라 숫자 앞에서 de 없이 쓰지 않습니다 ✗","más: 숫자 앞에는 de가 필요합니다 ✗","más de: 숫자 앞 '~넘게' → 정답 ✓"]},{"id":"G53","q":"José Manuel ____ libros de historia.","o":["lee","leen","lees","le"],"a":0,"k":"leer 현재형","t":"호세 마누엘은 역사책을 읽는다.","e":"주어 José Manuel은 3인칭 단수이므로 leer(읽다)의 3인칭 단수형 lee를 씁니다. -er 동사의 현재형은 leo, lees, lee, leemos, leéis, leen으로 변합니다.","x":["lee: 3인칭 단수 '읽는다' → 정답 ✓","leen: 3인칭 복수형이라 단수 주어와 맞지 않습니다 ✗","lees: tú(너) 형태라 맞지 않습니다 ✗","le: 간접목적격 대명사(그에게)라 동사가 아닙니다 ✗"]},{"id":"G54","q":"Ya no tenemos ____ aceite, voy a comprar una botella esta tarde.","o":["la","el","uno","ø"],"a":3,"k":"tener + 무관사","t":"이제 기름이 없어, 오늘 오후에 한 병 사러 갈게.","e":"tener(가지다)나 hay 뒤에서 aceite(기름)처럼 셀 수 없는 물질명사를 일반적으로 말할 때는 관사를 붙이지 않습니다. 'No tenemos aceite'는 '(우리 집에) 기름이 없다'라는 뜻입니다. 'ya no'는 '이제 더 이상 ~않다'입니다.","x":["la: aceite는 남성 명사이고 여기서는 관사도 필요 없습니다 ✗","el: 특정한 기름이 아니라 일반적으로 '기름'이 없다는 뜻이므로 관사가 필요 없습니다 ✗","uno: 대명사 '하나'로 명사 앞에 쓸 수 없습니다 ✗","ø: 셀 수 없는 명사 앞 무관사 → 정답 ✓"]},{"id":"G55","q":"¿Os ____ bien mi plan?","o":["parece","parecen","pareces","parecéis"],"a":0,"k":"parecer 구문","t":"너희는 내 계획이 괜찮아 보이니?","e":"parecer(~처럼 보이다/생각되다)는 gustar와 같은 구조로, 주어는 판단 대상인 mi plan(단수)입니다. 따라서 동사는 3인칭 단수 parece가 됩니다. os(너희에게)는 의견을 가진 사람을 나타내는 간접목적격 대명사입니다.","x":["parece: 주어 mi plan(단수)에 맞춘 3인칭 단수 → 정답 ✓","parecen: 3인칭 복수형이라 단수 plan과 맞지 않습니다 ✗","pareces: tú 형태라 주어 plan과 맞지 않습니다 ✗","parecéis: vosotros 형태로, os를 주어로 착각한 형태입니다 ✗"]},{"id":"G56","q":"Este verano Juana está ____ camarera en el negocio de sus padres.","o":["por","de","ø","a"],"a":1,"k":"estar de + 직업","t":"이번 여름 후아나는 부모님 가게에서 종업원으로 일하고 있다.","e":"'estar de + 직업'은 '(임시로) ~로 일하고 있다'라는 뜻입니다. 영구적인 직업은 'ser camarera'라고 하지만, 여름 동안만 하는 일처럼 일시적일 때 'estar de'를 씁니다. 참고로 '종업원'은 스페인에서 camarero/a, 중남미에서는 mesero/a라고 합니다.","x":["por: 'estar por'는 '~할 참이다/~에 찬성하다'로 다른 뜻입니다 ✗","de: 'estar de + 직업(임시로 ~로 일하다)' → 정답 ✓","ø: 'está camarera'는 문법적으로 틀립니다 ✗","a: 'estar a'는 이런 뜻으로 쓰지 않습니다 ✗"]},{"id":"G57","q":"Esa es la tienda ____ venden ropa de bebé.","o":["cual","donde","cuando","como"],"a":1,"k":"관계부사 donde","t":"저기가 아기 옷을 파는 가게다.","e":"선행사가 장소(la tienda)이고 '그곳에서'라는 의미일 때 관계부사 donde를 씁니다. 'la tienda donde venden...'은 '…을 파는 가게'라는 뜻입니다. 이때 donde에는 악센트를 붙이지 않습니다(의문사 dónde와 구별).","x":["cual: 단독으로 관계사로 쓰지 않고 el cual 형태로 씁니다 ✗","donde: 장소를 받는 관계부사 '~하는 곳' → 정답 ✓","cuando: 시간을 받는 관계사라 장소와 맞지 않습니다 ✗","como: 방법을 받는 관계사라 맞지 않습니다 ✗"]},{"id":"G58","q":"Lo ____ que deben hacer es escribir su nombre y sus apellidos.","o":["primeros","primer","primera","primero"],"a":3,"k":"lo + 형용사","t":"가장 먼저 해야 할 일은 이름과 성을 쓰는 것이다.","e":"중성 관사 lo + 형용사는 '~한 것'이라는 추상적인 뜻을 만듭니다. 'lo primero'는 '첫 번째 것, 가장 먼저 할 일'이라는 뜻입니다. lo 뒤에는 남성 단수형을 쓰고, primer처럼 줄어든 형태는 명사 앞에서만 씁니다.","x":["primeros: 복수형이라 lo와 함께 쓰지 않습니다 ✗","primer: 남성 명사 앞에서만 쓰는 단축형입니다 ✗","primera: 여성형이라 중성 lo와 맞지 않습니다 ✗","primero: 'lo primero(가장 먼저 할 일)' → 정답 ✓"]},{"id":"G59","q":"No come ____ no tiene hambre.","o":["por","que","porqué","porque"],"a":3,"k":"porque (이유)","t":"그는 배가 고프지 않아서 먹지 않는다.","e":"이유를 나타내는 '왜냐하면, ~이기 때문에'는 한 단어 porque입니다. 'por qué'(띄어 쓰고 악센트)는 '왜?'라는 의문사이고, 'porqué'는 '이유'라는 명사입니다. 예: Estudio porque tengo un examen.(시험이 있어서 공부한다.)","x":["por: 뒤에 동사원형이나 명사가 와야 하며 문장을 이을 수 없습니다 ✗","que: 이유를 분명하게 나타내지 못합니다 ✗","porqué: '이유'라는 명사(el porqué)입니다 ✗","porque: 이유 접속사 '~이기 때문에' → 정답 ✓"]},{"id":"G60","q":"Estos son ____ padres de Luis.","o":["los","la","el","las"],"a":0,"k":"정관사 일치","t":"이분들이 루이스의 부모님이다.","e":"padres(부모님)는 남성 복수 명사이므로 정관사 los를 씁니다. padre의 복수형 padres는 '아버지들' 외에 '부모(아버지와 어머니)'라는 뜻으로도 쓰입니다. 남녀가 섞이면 남성 복수형을 쓰는 규칙 때문입니다.","x":["los: 남성 복수 정관사 → 정답 ✓","la: 여성 단수형이라 맞지 않습니다 ✗","el: 단수형이라 복수 padres와 맞지 않습니다 ✗","las: 여성 복수형이라 남성 명사 padres와 맞지 않습니다 ✗"]},{"id":"G61","q":"Yo no tengo hermanos y mi mejor amiga ____.","o":["tampoco","tampoco no","también","no"],"a":0,"k":"tampoco","t":"나는 형제가 없고, 내 가장 친한 친구도 없다.","e":"부정 문장(No tengo hermanos)에 '~도 역시 아니다'라고 동의할 때는 tampoco를 씁니다. 긍정 문장에 동의할 때는 también을 씁니다. tampoco 자체가 부정의 뜻이라 no를 덧붙이지 않습니다.","x":["tampoco: 부정 문장에 동의 '~도 아니다' → 정답 ✓","tampoco no: tampoco가 동사 앞에 올 때는 no를 함께 쓰지 않습니다 ✗","también: 긍정 문장에 동의할 때 쓰므로 맞지 않습니다 ✗","no: '내 친구는 아니다(있다)'라는 반대 뜻이 되어 어색합니다 ✗"]},{"id":"G62","q":"¿Me pone ____ café con leche?","o":["un","una","a un","uno"],"a":0,"k":"부정관사 un","t":"밀크커피 한 잔 주시겠어요?","e":"가게에서 주문할 때 '¿Me pone + 부정관사 + 음식?'은 '~ 하나 주시겠어요?'라는 스페인식 표현입니다. café(커피)는 남성 명사이므로 un을 씁니다. 중남미에서는 '¿Me da...?'나 '¿Me trae...?'를 더 자주 씁니다.","x":["un: 남성 부정관사 '하나의' → 정답 ✓","una: 여성형이라 남성 명사 café와 맞지 않습니다 ✗","a un: 직접목적어인 사물 앞에 a를 쓰지 않습니다 ✗","uno: 대명사 형태로 명사 앞에서는 un으로 줄여야 합니다 ✗"]},{"id":"G63","q":"____ maletas están ahí.","o":["Vuestros","Las vuestras","Vuestra","Vuestras"],"a":3,"k":"소유형용사 vuestro","t":"너희 여행 가방들은 저기 있어.","e":"명사 앞에 쓰는 소유형용사 vuestro(너희의)는 소유된 명사의 성·수에 맞춥니다. maletas(여행 가방)는 여성 복수이므로 vuestras가 됩니다. 중남미에서는 vosotros를 쓰지 않으므로 'Sus maletas'라고 합니다.","x":["Vuestros: 남성 복수형이라 여성 명사 maletas와 맞지 않습니다 ✗","Las vuestras: '너희의 것들'이라는 대명사 형태로 명사 앞에 쓰지 않습니다 ✗","Vuestra: 단수형이라 복수 maletas와 맞지 않습니다 ✗","Vuestras: 여성 복수 '너희의' → 정답 ✓"]},{"id":"G64","q":"____ película que más me gusta es de Argentina.","o":["Una","La","El","Un"],"a":1,"k":"정관사 (특정)","t":"내가 가장 좋아하는 영화는 아르헨티나 영화다.","e":"'que más me gusta(내가 가장 좋아하는)'로 대상이 하나로 특정되므로 정관사를 씁니다. película(영화)는 여성 명사이므로 la가 맞습니다. 최상급 의미를 가진 관계절 앞에는 보통 정관사가 옵니다.","x":["Una: 부정관사라 '가장 좋아하는 하나'라는 특정 의미와 맞지 않습니다 ✗","La: 여성 정관사 → 정답 ✓","El: 남성형이라 여성 명사 película와 맞지 않습니다 ✗","Un: 남성 부정관사라 성도 뜻도 맞지 않습니다 ✗"]},{"id":"G65","q":"No me gusta ____ color de esa pared.","o":["ø","los","el","la"],"a":2,"k":"gustar + 정관사","t":"나는 저 벽의 색깔이 마음에 들지 않는다.","e":"gustar 구문에서 주어가 되는 명사 앞에는 보통 정관사를 붙입니다. color(색)는 남성 명사이므로 el color가 됩니다. -or로 끝나는 명사는 대부분 남성입니다.","x":["ø: gustar의 주어 명사 앞에는 관사가 필요합니다 ✗","los: 복수형이라 단수 color와 맞지 않습니다 ✗","el: 남성 단수 정관사 → 정답 ✓","la: color는 남성 명사라 맞지 않습니다 ✗"]},{"id":"G66","q":"Esos cuadernos no son ____, son de Alfredo.","o":["mis","míos","mío","de mí"],"a":1,"k":"소유대명사 míos","t":"그 공책들은 내 것이 아니고, 알프레도 것이다.","e":"ser 뒤에서 '내 것'이라고 말할 때는 강세형 소유사 mío/mía/míos/mías를 씁니다. 소유된 대상 cuadernos(공책들)가 남성 복수이므로 míos가 됩니다. mi/mis는 명사 앞에서만 씁니다.","x":["mis: 명사 앞에 쓰는 형태라 단독으로 쓰지 못합니다 ✗","míos: 남성 복수 '내 것' → 정답 ✓","mío: 단수형이라 복수 cuadernos와 맞지 않습니다 ✗","de mí: 스페인어에서는 '내 것'을 de mí로 표현하지 않습니다 ✗"]},{"id":"G67","q":"Luis, ¿quieres ____ taza de café?","o":["una otra","otra","el otra","otra la"],"a":1,"k":"otro 용법","t":"루이스, 커피 한 잔 더 할래?","e":"otro/otra(하나 더, 또 다른)는 부정관사 없이 단독으로 명사 앞에 씁니다. taza(잔)는 여성 단수이므로 otra taza가 됩니다. 영어 'another'처럼 'una otra'라고 하면 틀립니다.","x":["una otra: otro 앞에는 부정관사를 쓰지 않습니다 ✗","otra: 여성 단수 '하나 더' → 정답 ✓","el otra: 관사 el이 남성이라 맞지 않고 뜻도 '나머지 하나'가 됩니다 ✗","otra la: 이런 어순은 없습니다 ✗"]},{"id":"G68","q":"¿Dónde están ____ gafas de sol?","o":["mía","mis","mí","mías"],"a":1,"k":"소유형용사 mis","t":"내 선글라스 어디 있지?","e":"명사 앞에 쓰는 소유형용사는 mi(단수)/mis(복수)입니다. gafas(안경)는 항상 복수로 쓰는 여성 명사이므로 mis gafas가 됩니다. 참고로 '안경'은 스페인에서 gafas, 중남미에서는 lentes나 anteojos라고 합니다.","x":["mía: 강세형이라 명사 뒤에 쓰거나 단독으로 씁니다 ✗","mis: 복수 명사 앞 '나의' → 정답 ✓","mí: 전치사 뒤에 쓰는 대명사(para mí)입니다 ✗","mías: 강세형이라 명사 앞에 오지 않습니다 ✗"]},{"id":"G69","q":"Voy a comprar patatas, leche, pan y ____ paquete de galletas.","o":["un","uno","una","ø"],"a":0,"k":"부정관사 un","t":"나는 감자, 우유, 빵 그리고 과자 한 봉지를 사러 갈 거야.","e":"'과자 한 봉지'처럼 셀 수 있는 대상 하나를 말할 때 부정관사를 씁니다. paquete(봉지, 꾸러미)는 남성 명사이므로 un이 맞습니다. uno는 명사 앞에서 un으로 줄어듭니다.","x":["un: 남성 부정관사 '하나의' → 정답 ✓","uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","una: 여성형이라 남성 명사 paquete와 맞지 않습니다 ✗","ø: 셀 수 있는 단수 명사 하나를 말할 때는 관사가 필요합니다 ✗"]},{"id":"G70","q":"Mi abuelo tiene ____ coche muy antiguo.","o":["el","un","ø","uno"],"a":1,"k":"부정관사 un","t":"우리 할아버지는 아주 오래된 차를 가지고 있다.","e":"처음 언급하는 셀 수 있는 대상을 '하나의, 어떤'으로 소개할 때 부정관사를 씁니다. coche(자동차)는 남성 명사이므로 un coche가 됩니다. 참고로 '자동차'는 스페인에서 coche, 중남미에서는 carro나 auto라고 합니다.","x":["el: 정관사라 처음 소개하는 대상에 어색합니다 ✗","un: 남성 부정관사 → 정답 ✓","ø: 형용사로 꾸며진 셀 수 있는 단수 명사는 관사가 필요합니다 ✗","uno: 명사 앞에서는 un으로 줄여야 합니다 ✗"]},{"id":"G71","q":"Aunque soy despistada, nunca ____ las llaves de mi casa.","o":["pierdo","está perdiendo","pierde","estoy perdiendo"],"a":0,"k":"습관 현재형","t":"나는 덤벙대지만 집 열쇠는 절대 잃어버리지 않는다.","e":"nunca(절대 ~않다)처럼 습관이나 반복을 나타낼 때는 단순 현재형을 씁니다. 주어가 yo(soy despistada)이므로 perder(잃어버리다)의 1인칭 단수 pierdo가 됩니다. perder는 e → ie로 바뀌는 불규칙동사입니다.","x":["pierdo: 1인칭 단수 현재형 '잃어버린다' → 정답 ✓","está perdiendo: 3인칭이고 진행형이라 습관을 나타내기에 맞지 않습니다 ✗","pierde: 3인칭 단수라 주어 yo와 맞지 않습니다 ✗","estoy perdiendo: 진행형은 '지금 ~하고 있다'라 nunca와 어울리지 않습니다 ✗"]},{"id":"G72","q":"No me gusta el fútbol y a mi esposa ____.","o":["tampoco","también","tampoco no","también sí"],"a":0,"k":"A ... tampoco","t":"나는 축구를 좋아하지 않고, 내 아내도 좋아하지 않는다.","e":"부정 문장(No me gusta)에 '~도 역시 아니다'라고 이어 말할 때 'a + 사람 + tampoco'를 씁니다. gustar 구문이라 'a mi esposa'처럼 a를 붙인 것입니다. 긍정 문장이었다면 también을 씁니다.","x":["tampoco: 부정에 대한 동의 '~도 아니다' → 정답 ✓","también: 긍정 문장에 동의할 때 쓰므로 맞지 않습니다 ✗","tampoco no: tampoco와 no를 함께 쓰지 않습니다 ✗","también sí: 이런 표현은 쓰지 않습니다 ✗"]},{"id":"G73","q":"Joana es ____ Portugal.","o":["a","de","en","del"],"a":1,"k":"ser de (출신)","t":"조아나는 포르투갈 출신이다.","e":"'ser de + 장소'는 '~ 출신이다'라는 뜻입니다. Portugal 같은 나라 이름은 보통 관사 없이 쓰므로 de만 씁니다. 예: Soy de Corea.(나는 한국 출신이다.)","x":["a: 방향을 나타내는 전치사로 출신을 나타내지 않습니다 ✗","de: 'ser de(~ 출신이다)' → 정답 ✓","en: '~에(서)'로 위치를 나타내며 ser와 출신에 쓰지 않습니다 ✗","del: de + el인데 Portugal에는 관사를 붙이지 않습니다 ✗"]},{"id":"G74","q":"Los domingos prefiero ____ en casa.","o":["quedarme","quedar me","me quedo","me quedar"],"a":0,"k":"재귀동사 원형","t":"일요일에는 집에 있는 것을 더 좋아한다.","e":"preferir(더 좋아하다) 뒤에는 동사원형이 옵니다. 재귀동사 원형에서는 재귀대명사를 동사원형 끝에 붙여 한 단어로 씁니다(quedarme). quedarse는 '머무르다'라는 뜻입니다.","x":["quedarme: 동사원형 + me를 붙여 쓴 형태 → 정답 ✓","quedar me: 대명사는 동사원형에 붙여 써야 합니다 ✗","me quedo: 이미 prefiero가 활용되어 있어 활용형이 또 올 수 없습니다 ✗","me quedar: 대명사를 동사원형 앞에 떨어뜨려 쓰지 않습니다 ✗"]},{"id":"G75","q":"Para mí, Messi es ____ futbolista de la historia.","o":["el mejor","mejor","un mejor","lo mejor"],"a":0,"k":"최상급","t":"내 생각에 메시는 역사상 최고의 축구 선수다.","e":"최상급 '가장 ~한'은 '정관사 + mejor + 명사 + de + 범위'로 만듭니다. futbolista는 남녀 형태가 같지만 메시는 남성이므로 el mejor가 됩니다. 예: Es la mejor película del año.(올해 최고의 영화다.)","x":["el mejor: 정관사 + mejor 최상급 → 정답 ✓","mejor: 관사가 없으면 최상급이 되지 않습니다 ✗","un mejor: 부정관사로는 '가장 ~한'을 표현하지 못합니다 ✗","lo mejor: '가장 좋은 것'이라는 중성 표현이라 사람 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G76","q":"¿A qué se dedica? —Soy ____ ingeniero.","o":["ø","el","uno","un"],"a":0,"k":"직업 무관사","t":"무슨 일을 하세요? — 저는 엔지니어입니다.","e":"ser 뒤에 직업을 말할 때는 관사를 붙이지 않습니다. 'Soy ingeniero(저는 엔지니어입니다)', 'Es profesora(그녀는 선생님이다)'처럼 씁니다. 다만 형용사가 붙으면 'Es un buen ingeniero(좋은 엔지니어다)'처럼 관사를 씁니다.","x":["ø: ser + 직업은 관사 없음 → 정답 ✓","el: 정관사를 직업 앞에 붙이지 않습니다 ✗","uno: 대명사 형태로 명사 앞에 쓰지 않습니다 ✗","un: 형용사가 없는 직업 앞에는 부정관사를 쓰지 않습니다 ✗"]},{"id":"G77","q":"La profe respondió a ____ preguntas de sus alumnos.","o":["todas","las todas","todas las","toda"],"a":2,"k":"todo + 정관사","t":"선생님은 학생들의 모든 질문에 대답했다.","e":"'모든 ~'은 'todo/toda/todos/todas + 정관사 + 명사' 순서로 씁니다. preguntas(질문들)는 여성 복수이므로 'todas las preguntas'가 됩니다. 관사를 todo 앞에 두면 틀립니다.","x":["todas: 정관사 las가 빠져 불완전합니다 ✗","las todas: 어순이 틀렸습니다(todas las가 맞음) ✗","todas las: todo + 정관사 + 명사 순서 → 정답 ✓","toda: 단수형이고 관사도 없어 맞지 않습니다 ✗"]},{"id":"G78","q":"¿____ te llamas? —Carlota Hernández Figueroa.","o":["Cómo","Qué","Cuánto","Dónde"],"a":0,"k":"¿Cómo te llamas?","t":"이름이 뭐야? — 카를로타 에르난데스 피게로아야.","e":"이름을 물을 때는 '¿Cómo te llamas?'라고 합니다. llamarse는 '~라고 불리다'라는 재귀동사이므로, 직역하면 '너는 어떻게 불리니?'가 됩니다. 한국어나 영어처럼 '무엇'을 생각해 qué를 쓰지 않도록 주의하세요.","x":["Cómo: '¿Cómo te llamas?(이름이 뭐니?)' → 정답 ✓","Qué: llamarse와 함께 이름을 물을 때는 qué를 쓰지 않습니다 ✗","Cuánto: '얼마나'라 이름을 묻지 못합니다 ✗","Dónde: '어디'라 문맥에 맞지 않습니다 ✗"]},{"id":"G79","q":"Perdone, ¿____ cuesta esta camisa?","o":["cómo","cuánto","cuándo","quién"],"a":1,"k":"¿Cuánto cuesta?","t":"실례합니다, 이 셔츠 얼마예요?","e":"가격을 물을 때는 '¿Cuánto cuesta?(얼마예요?)'를 씁니다. costar(값이 ~이다)는 o → ue로 바뀌는 불규칙동사입니다. 여러 개를 물을 때는 '¿Cuánto cuestan?'이라고 합니다.","x":["cómo: '어떻게'라 가격을 묻지 못합니다 ✗","cuánto: '얼마' → 정답 ✓","cuándo: '언제'라 가격과 관계없습니다 ✗","quién: '누구'라 문맥에 맞지 않습니다 ✗"]},{"id":"G80","q":"Los invitados ____ aquí.","o":["estás","son","sois","están"],"a":3,"k":"estar (위치)","t":"손님들은 여기 있다.","e":"사람이나 사물이 '어디에 있다'라고 위치를 말할 때는 estar를 씁니다. 주어 los invitados(손님들)는 3인칭 복수이므로 están이 됩니다. ser는 위치가 아닌 정체·성질을 말할 때 씁니다.","x":["estás: tú 형태라 3인칭 복수 주어와 맞지 않습니다 ✗","son: ser는 사람의 위치를 나타내지 않습니다 ✗","sois: ser의 vosotros 형태라 동사도 인칭도 맞지 않습니다 ✗","están: estar 3인칭 복수 위치 표현 → 정답 ✓"]},{"id":"G81","q":"Esa chica se llama Almudena y ____ chica se llama Esther.","o":["el otra","una otra","otra la","la otra"],"a":3,"k":"la otra","t":"그 여자애 이름은 알무데나이고, 다른 여자애 이름은 에스테르이다.","e":"두 사람 중 '나머지 한 명'을 가리킬 때는 '정관사 + otro/otra'를 씁니다. chica(여자아이)는 여성 명사이므로 'la otra chica'가 됩니다. 정관사는 otro 앞에 올 수 있지만 부정관사 una는 올 수 없습니다.","x":["el otra: 정관사 el이 남성이라 otra·chica와 맞지 않습니다 ✗","una otra: otro 앞에는 부정관사를 쓰지 않습니다 ✗","otra la: 어순이 틀렸습니다 ✗","la otra: '나머지 한 명(의)' → 정답 ✓"]},{"id":"G82","q":"A Julián ____ duele la rodilla derecha.","o":["les","te","le","me"],"a":2,"k":"doler 구문","t":"훌리안은 오른쪽 무릎이 아프다.","e":"doler(아프다)는 gustar처럼 '아픈 사람'을 간접목적격 대명사로 나타냅니다. 'A Julián(훌리안에게)'은 3인칭 단수이므로 le를 씁니다. 아픈 부위 la rodilla(무릎)가 주어라서 동사는 duele(단수)입니다.","x":["les: 3인칭 복수라 한 사람인 Julián과 맞지 않습니다 ✗","te: '너에게'라 맞지 않습니다 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓","me: '나에게'라 맞지 않습니다 ✗"]},{"id":"G83","q":"Voy ____ visitar a mis abuelos este fin de semana.","o":["de","a","por","ø"],"a":1,"k":"ir a + 동사원형","t":"이번 주말에 할아버지 할머니를 뵈러 갈 거야.","e":"'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래나 계획을 나타냅니다. a는 생략할 수 없습니다. 예: Voy a estudiar.(나는 공부할 거야.)","x":["de: ir de는 'ir de vacaciones'처럼 다른 뜻으로 씁니다 ✗","a: 'ir a + 동사원형(~할 것이다)' → 정답 ✓","por: ir por는 '~을 가지러 가다'라는 다른 뜻입니다 ✗","ø: ir 뒤에 동사원형이 오려면 a가 필요합니다 ✗"]},{"id":"G84","q":"Todas las mañanas mi marido ____ a las seis.","o":["levantarse","se levantan","se levanta","levanta"],"a":2,"k":"재귀동사 활용","t":"매일 아침 남편은 6시에 일어난다.","e":"levantarse(일어나다)는 재귀동사이므로 주어에 맞는 재귀대명사를 함께 써야 합니다. 주어 mi marido(내 남편)는 3인칭 단수이므로 se levanta입니다. 'todas las mañanas(매일 아침)'는 습관을 나타냅니다.","x":["levantarse: 동사원형이라 활용이 필요합니다 ✗","se levantan: 3인칭 복수형이라 단수 주어와 맞지 않습니다 ✗","se levanta: 3인칭 단수 재귀동사 → 정답 ✓","levanta: se가 없으면 '(무언가를) 들어 올리다'라는 뜻이 됩니다 ✗"]},{"id":"G85","q":"Los hijos de Maribel son muy ____.","o":["altos","altas","alto","alta"],"a":0,"k":"형용사 성·수 일치","t":"마리벨의 아이들은 키가 아주 크다.","e":"형용사는 꾸미는 명사의 성·수에 맞춥니다. hijos는 남성 복수(아들들 또는 남녀가 섞인 자녀들)이므로 altos를 씁니다. 남녀가 섞인 그룹은 남성 복수형을 쓰는 것이 규칙입니다.","x":["altos: 남성 복수 → 정답 ✓","altas: 여성 복수형이라 hijos와 맞지 않습니다 ✗","alto: 단수형이라 복수 주어와 맞지 않습니다 ✗","alta: 여성 단수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G86","q":"Eloy parece preocupado. ¿Alguien sabe qué ____ pasa?","o":["lo","le","les","se"],"a":1,"k":"pasar 구문 (le)","t":"엘로이가 걱정스러워 보여. 그에게 무슨 일이 있는지 아는 사람 있어?","e":"'¿Qué te pasa?(무슨 일 있어?)'처럼 pasar(일어나다)는 일을 겪는 사람을 간접목적격 대명사로 나타냅니다. Eloy는 3인칭 단수이므로 le가 맞습니다. 예: ¿Qué le pasa a tu madre?(어머니께 무슨 일 있으세요?)","x":["lo: 직접목적격(그를)이라 pasar 구문에 맞지 않습니다 ✗","le: 3인칭 단수 간접목적격 '그에게' → 정답 ✓","les: 복수형이라 한 사람인 Eloy와 맞지 않습니다 ✗","se: 재귀대명사라 이 구조에 맞지 않습니다 ✗"]},{"id":"G87","q":"A doscientos metros de aquí hay ____ parque precioso.","o":["uno","una","el","un"],"a":3,"k":"hay + 부정관사","t":"여기서 200미터 떨어진 곳에 아주 멋진 공원이 있다.","e":"hay(있다) 뒤에서 셀 수 있는 단수 명사를 말할 때는 부정관사를 씁니다. hay 뒤에는 정관사를 쓰지 않습니다. parque(공원)는 남성 명사이므로 un parque가 됩니다.","x":["uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","una: 여성형이라 남성 명사 parque와 맞지 않습니다 ✗","el: hay 뒤에는 정관사를 쓰지 않습니다 ✗","un: hay + 부정관사 → 정답 ✓"]},{"id":"G88","q":"Miguel terminó la carrera en ____ posición.","o":["tercer","terceros","tercero","tercera"],"a":3,"k":"서수 일치","t":"미겔은 경주를 3위로 마쳤다.","e":"서수(첫째, 둘째, 셋째…)는 형용사처럼 명사의 성·수에 맞춥니다. posición(순위)은 여성 명사이므로 tercera가 됩니다. tercer는 남성 단수 명사 앞에서만 쓰는 단축형입니다(el tercer piso). 여기서 carrera는 '경주'라는 뜻입니다.","x":["tercer: 남성 명사 앞에서만 쓰는 단축형입니다 ✗","terceros: 남성 복수형이라 맞지 않습니다 ✗","tercero: 남성형이라 여성 명사 posición과 맞지 않습니다 ✗","tercera: 여성 단수 서수 → 정답 ✓"]},{"id":"G89","q":"Nos vemos el lunes. ¡Que pases ____ buen fin de semana!","o":["el","una","un","la"],"a":2,"k":"부정관사 un","t":"월요일에 봐. 좋은 주말 보내!","e":"'Que pases un buen fin de semana(좋은 주말 보내)'는 인사 표현으로, fin de semana(주말)는 남성 명사라 부정관사 un을 씁니다. 'que + 접속법'은 상대에게 바람을 전할 때 씁니다. bueno는 남성 단수 명사 앞에서 buen이 됩니다.","x":["el: 정관사라 '좋은 주말 보내'라는 인사 표현에 어색합니다 ✗","una: 여성형이라 남성 명사 fin과 맞지 않습니다 ✗","un: 남성 부정관사 → 정답 ✓","la: 여성 정관사라 성도 뜻도 맞지 않습니다 ✗"]},{"id":"G90","q":"La señora Rodríguez está hablando ____ teléfono en este momento.","o":["para","a","por","con"],"a":2,"k":"por teléfono","t":"로드리게스 부인은 지금 전화 통화 중이다.","e":"'hablar por teléfono'는 '전화로 이야기하다'라는 고정 표현입니다. por는 수단·매체(~을 통해)를 나타냅니다. 예: Te lo envío por correo.(우편/이메일로 보낼게.)","x":["para: '~을 위해'라 수단을 나타내지 못합니다 ✗","a: 'hablar a teléfono'라는 표현은 없습니다 ✗","por: 수단 '전화로' → 정답 ✓","con: '전화와 함께'라는 어색한 뜻이 됩니다 ✗"]},{"id":"G91","q":"Tener éxito en esta prueba ____ de ti.","o":["es depende","depende","depender","dependes"],"a":1,"k":"depender de","t":"이 시험에 합격하는 것은 너에게 달려 있다.","e":"'depender de'는 '~에 달려 있다'라는 뜻입니다. 주어는 동사원형 'Tener éxito(성공하는 것)'이고, 동사원형 주어는 3인칭 단수로 취급하므로 depende가 됩니다. 예: Depende del tiempo.(날씨에 달렸다.)","x":["es depende: ser와 depender 두 동사를 겹쳐 쓸 수 없습니다 ✗","depende: 3인칭 단수 '~에 달려 있다' → 정답 ✓","depender: 동사원형이라 활용이 필요합니다 ✗","dependes: tú 형태로, de ti의 ti를 주어로 착각한 형태입니다 ✗"]},{"id":"G92","q":"El chico ____ lleva gafas se llama Alejandro.","o":["el que","quien","al que","que"],"a":3,"k":"관계대명사 que","t":"안경을 쓴 그 남자아이는 이름이 알레한드로다.","e":"선행사 el chico를 꾸미는 관계절에서 chico는 lleva의 주어 역할을 합니다. 이처럼 전치사 없이 이어지는 제한적 관계절에는 que를 씁니다. 예: La chica que canta es mi hermana.(노래하는 여자아이는 내 여동생이다.)","x":["el que: 선행사 바로 뒤 전치사 없는 제한적 관계절에는 쓰지 않습니다 ✗","quien: 제한적 관계절(쉼표 없음)의 주어로 쓰지 않습니다 ✗","al que: '그에게/그를'이라는 뜻으로 주어 역할에 맞지 않습니다 ✗","que: 사람·사물 모두 받는 기본 관계대명사 → 정답 ✓"]},{"id":"G93","q":"¿____ vas, María?","o":["A donde","Adónde","Donde","Adonde"],"a":1,"k":"의문사 adónde","t":"어디 가, 마리아?","e":"ir(가다)처럼 이동 방향을 물을 때는 '어디로'라는 뜻의 adónde(= a dónde)를 씁니다. 의문사이므로 악센트가 반드시 있습니다. 위치를 물을 때는 '¿Dónde estás?(어디 있어?)'처럼 dónde를 씁니다.","x":["A donde: 의문문인데 악센트가 없어 틀립니다(a dónde는 가능) ✗","Adónde: '어디로' 의문사 → 정답 ✓","Donde: 악센트가 없고 방향의 a도 빠졌습니다 ✗","Adonde: 악센트 없는 형태는 관계부사로 의문문에 쓰지 않습니다 ✗"]},{"id":"G94","q":"Miguel Ángel ya ____ dieciséis años.","o":["está","tiene","es","son"],"a":1,"k":"tener + 나이","t":"미겔 앙헬은 벌써 열여섯 살이다.","e":"스페인어에서는 나이를 말할 때 tener(가지다)를 씁니다. 'Tengo veinte años(나는 스무 살이다)'처럼 '~살을 가지고 있다'고 표현합니다. 영어처럼 ser나 estar를 쓰지 않도록 주의하세요.","x":["está: 나이를 estar로 표현하지 않습니다 ✗","tiene: 'tener + 숫자 + años(~살이다)' → 정답 ✓","es: 나이를 ser로 표현하지 않습니다 ✗","son: ser 복수형으로 주어 Miguel Ángel과도 맞지 않습니다 ✗"]},{"id":"G95","q":"Habla bien español ____ lleva seis años en España.","o":["porqué","porque","por qué","por que"],"a":1,"k":"porque (이유)","t":"그는 스페인에서 6년째 살고 있어서 스페인어를 잘한다.","e":"이유를 말하는 접속사 '~이기 때문에'는 한 단어로 악센트 없는 porque입니다. 'llevar + 기간 + en + 장소'는 '~에서 (기간)째 지내고 있다'라는 뜻입니다. 'por qué'는 '왜?'라는 의문사입니다.","x":["porqué: '이유'라는 명사(el porqué)입니다 ✗","porque: 이유 접속사 → 정답 ✓","por qué: '왜'라는 의문사입니다 ✗","por que: 전치사 + 관계사 조합으로 이유를 나타내지 않습니다 ✗"]},{"id":"G96","q":"Alfonso y Amelia tienen ____ cuatro hijos, dos niños y dos niñas.","o":["ø","los","a los","a"],"a":0,"k":"숫자 앞 무관사","t":"알폰소와 아멜리아는 아들 둘, 딸 둘, 이렇게 아이가 넷이다.","e":"tener 뒤에서 '아이가 ~명 있다'처럼 수를 처음 말할 때는 숫자 앞에 관사를 붙이지 않습니다. 사람이라도 tener의 목적어(가족 수)에는 전치사 a를 쓰지 않는 것이 일반적입니다. 예: Tengo dos hermanos.(나는 형제가 둘 있다.)","x":["ø: 숫자 앞 관사 없음 → 정답 ✓","los: '그 네 아이'처럼 이미 언급된 특정 대상이 될 때만 씁니다 ✗","a los: tener 뒤에 a + 관사를 쓰는 것은 이 문맥에 맞지 않습니다 ✗","a: tener의 가족 수를 말할 때는 a를 쓰지 않습니다 ✗"]},{"id":"G97","q":"Me gustaría mucho ir ____ España.","o":["en","en la","a","a la"],"a":2,"k":"ir a + 나라","t":"나는 스페인에 꼭 가 보고 싶다.","e":"ir(가다)는 목적지 앞에 전치사 a를 씁니다. España처럼 대부분의 나라 이름에는 관사를 붙이지 않습니다. 'me gustaría'는 '~하고 싶다'라는 공손한 바람의 표현입니다.","x":["en: 위치 '~에서'를 나타내며 ir와 함께 목적지에 쓰지 않습니다 ✗","en la: 전치사도 틀리고 나라 이름에 관사도 불필요합니다 ✗","a: 목적지를 나타내는 전치사 → 정답 ✓","a la: España 앞에는 관사를 붙이지 않습니다 ✗"]},{"id":"G98","q":"¿Cuánto tiempo necesitas ____ hacer este plato?","o":["en","para","a","por"],"a":1,"k":"para (목적)","t":"이 요리를 만드는 데 시간이 얼마나 필요하니?","e":"'~하기 위해, ~하는 데'라는 목적을 나타낼 때는 'para + 동사원형'을 씁니다. 'necesitar ... para + 동사원형'은 '~하는 데 …가 필요하다'라는 뜻입니다. 예: Necesito gafas para leer.(나는 읽기 위해 안경이 필요하다.)","x":["en: 'en hacer'는 이 문맥에서 목적을 나타내지 않습니다 ✗","para: 목적 '~하는 데' → 정답 ✓","a: necesitar 뒤에 목적을 나타내는 a는 쓰지 않습니다 ✗","por: '~때문에'라는 원인을 나타냅니다 ✗"]},{"id":"G99","q":"Javier Bardem nació ____ Las Palmas de Gran Canaria.","o":["en","a","de","desde"],"a":0,"k":"nacer en","t":"하비에르 바르뎀은 그란 카나리아의 라스팔마스에서 태어났다.","e":"'nacer en + 장소'는 '~에서 태어나다'라는 표현입니다. 태어난 장소는 위치를 나타내는 en으로 씁니다. 출신을 말할 때는 'ser de'를 쓰니 구별하세요(Es de Las Palmas).","x":["en: 태어난 장소 '~에서' → 정답 ✓","a: 방향을 나타내 출생지 표현에 쓰지 않습니다 ✗","de: nacer와 함께 장소를 나타내지 않습니다(출신은 ser de) ✗","desde: '~부터'라 출생지를 나타내지 않습니다 ✗"]},{"id":"G100","q":"Para mí, el peor día de la semana ____ el lunes.","o":["es","están","está","son"],"a":0,"k":"ser (정체)","t":"내게 일주일 중 최악의 날은 월요일이다.","e":"'A는 B이다'처럼 어떤 것이 무엇인지 정의하거나 동일시할 때는 ser를 씁니다. 주어 'el peor día(최악의 날)'는 단수이므로 es가 됩니다. estar는 위치나 일시적 상태에 씁니다.","x":["es: ser 3인칭 단수 '~이다' → 정답 ✓","están: estar 복수형이라 의미도 수도 맞지 않습니다 ✗","está: estar는 정의·동일시에 쓰지 않습니다 ✗","son: 복수형이라 단수 주어와 맞지 않습니다 ✗"]},{"id":"G101","q":"Me gusta fotografiar paisajes ____.","o":["bonitos","bonitas","bonito","bonita"],"a":0,"k":"형용사 성·수 일치","t":"나는 아름다운 풍경을 사진 찍는 것을 좋아한다.","e":"형용사는 명사의 성·수에 맞춥니다. paisajes(풍경들)는 -aje로 끝나는 남성 명사의 복수형이므로 bonitos가 됩니다. -aje로 끝나는 명사(viaje, paisaje, garaje)는 대부분 남성입니다.","x":["bonitos: 남성 복수 → 정답 ✓","bonitas: 여성 복수형이라 남성 명사 paisajes와 맞지 않습니다 ✗","bonito: 단수형이라 복수 명사와 맞지 않습니다 ✗","bonita: 여성 단수형이라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G102","q":"Me interesa ____ cine de Alejandro Amenábar.","o":["ø","el","un","la"],"a":1,"k":"interesar + 정관사","t":"나는 알레한드로 아메나바르의 영화에 관심이 있다.","e":"interesar(관심을 끌다)는 gustar처럼 관심 대상이 주어가 되고, 주어 명사 앞에는 보통 정관사를 붙입니다. cine(영화, 영화 예술)은 남성 명사이므로 el cine가 됩니다. 'el cine de + 감독'은 '~ 감독의 영화 세계'라는 뜻입니다.","x":["ø: interesar의 주어 명사 앞에는 관사가 필요합니다 ✗","el: 남성 정관사 → 정답 ✓","un: 부정관사라 특정 감독의 영화 세계를 가리키기에 어색합니다 ✗","la: cine는 남성 명사라 맞지 않습니다 ✗"]},{"id":"G103","q":"Esa moto no es ____, es mía.","o":["suya","sus","su","de suya"],"a":0,"k":"소유대명사 suya","t":"저 오토바이는 그의 것이 아니라 내 것이다.","e":"ser 뒤에서 '~의 것'이라고 말할 때는 강세형 소유사(mío, tuyo, suyo...)를 씁니다. moto(오토바이)는 여성 명사이므로 suya가 됩니다. 문장 뒤의 mía와 같은 형태라고 생각하면 쉽습니다.","x":["suya: 여성 단수 '그(그녀/당신)의 것' → 정답 ✓","sus: 명사 앞에 쓰는 복수형이라 단독으로 쓰지 않습니다 ✗","su: 명사 앞에만 쓰는 형태입니다 ✗","de suya: 강세형 소유사 앞에 de를 붙이지 않습니다 ✗"]},{"id":"G104","q":"¿Sois mexicanos? —No, somos ____ Guatemala.","o":["a","para","de","en"],"a":2,"k":"ser de (출신)","t":"너희 멕시코 사람이야? — 아니, 우리는 과테말라 출신이야.","e":"'ser de + 나라/도시'는 '~ 출신이다'라는 뜻입니다. somos(우리는 ~이다) 뒤에 de Guatemala를 붙여 출신을 말합니다. 참고로 중남미에서는 '¿Sois...?' 대신 '¿Son mexicanos?'라고 묻습니다.","x":["a: 방향을 나타내 출신 표현에 쓰지 않습니다 ✗","para: '~을 위해/~로 향해'라 출신을 나타내지 않습니다 ✗","de: 'ser de(~ 출신)' → 정답 ✓","en: 위치를 나타내며 ser와 출신에 쓰지 않습니다 ✗"]},{"id":"G105","q":"Necesitamos ____ mapa para la excursión.","o":["unas","un","uno","una"],"a":1,"k":"부정관사 un","t":"소풍 가는 데 지도가 하나 필요하다.","e":"mapa(지도)는 -a로 끝나지만 남성 명사입니다. 따라서 부정관사 un을 씁니다. -ma로 끝나는 그리스어 유래 명사(problema, idioma, tema, mapa 등)는 남성이니 함께 외워 두세요.","x":["unas: 여성 복수형이라 맞지 않습니다 ✗","un: 남성 부정관사 → 정답 ✓","uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","una: mapa는 -a로 끝나지만 남성 명사입니다 ✗"]},{"id":"G106","q":"He llamado ____ Inés varias veces, pero no responde.","o":["por","de","a","ø"],"a":2,"k":"사람 목적어 a","t":"이네스에게 여러 번 전화했는데 받지 않는다.","e":"스페인어에서는 사람이 직접목적어(~을/를)일 때 앞에 전치사 a를 붙입니다(인칭의 a). llamar(전화하다/부르다)의 목적어가 사람 Inés이므로 'llamar a Inés'가 됩니다. 예: Veo a mi madre.(나는 어머니를 본다.)","x":["por: 'llamar por'는 '~을 위해/~때문에 전화하다'로 다른 뜻입니다 ✗","de: llamar 뒤에 사람 목적어를 de로 잇지 않습니다 ✗","a: 사람 직접목적어 앞 '인칭의 a' → 정답 ✓","ø: 사람 목적어 앞에 a가 빠지면 틀립니다 ✗"]},{"id":"G107","q":"Estudio español ____ viajar por Hispanoamérica.","o":["a","sobre","en","para"],"a":3,"k":"para (목적)","t":"나는 중남미를 여행하기 위해 스페인어를 공부한다.","e":"'~하기 위해'라는 목적은 'para + 동사원형'으로 나타냅니다. Hispanoamérica는 '스페인어를 쓰는 아메리카 국가들'을 말합니다. 예: Ahorro para comprar un coche.(차를 사려고 저축한다.)","x":["a: 이 문맥에서 목적을 나타내지 못합니다 ✗","sobre: '~에 대해'라 문맥에 맞지 않습니다 ✗","en: '~에서'라 목적을 나타내지 못합니다 ✗","para: 목적 '~하기 위해' → 정답 ✓"]},{"id":"G108","q":"Este ejercicio ____ mal.","o":["es","está","son","estás"],"a":1,"k":"estar mal","t":"이 연습문제는 틀렸다.","e":"'estar bien/mal'은 '맞다/틀리다, 잘/잘못 되어 있다'라는 상태 평가 표현입니다. bien·mal은 부사라서 ser가 아닌 estar와 함께 씁니다. 주어 este ejercicio는 3인칭 단수이므로 está입니다.","x":["es: bien·mal은 ser와 함께 쓰지 않습니다 ✗","está: 'estar mal(틀렸다)' → 정답 ✓","son: 복수형이고 동사도 맞지 않습니다 ✗","estás: tú 형태라 주어와 맞지 않습니다 ✗"]},{"id":"G109","q":"____ los hispanohablantes es más fácil aprender una lengua romance.","o":["Por","A","De","Para"],"a":3,"k":"para (관점)","t":"스페인어 사용자에게는 로망스어(라틴어 계열 언어)를 배우는 것이 더 쉽다.","e":"'para + 사람'은 '~에게(는), ~ 입장에서'라는 관점이나 기준을 나타냅니다. 'Para mí, ...(내 생각에는)'도 같은 용법입니다. 'es más fácil + 동사원형'은 '~하는 것이 더 쉽다'입니다.","x":["Por: '~때문에/~을 통해'라 관점을 나타내지 않습니다 ✗","A: 이 구조에서는 관점을 나타내지 못합니다 ✗","De: '~의/~로부터'라 문맥에 맞지 않습니다 ✗","Para: 관점 '~에게는' → 정답 ✓"]},{"id":"G110","q":"____ agua de la piscina está fría.","o":["La","El","Un","Una"],"a":1,"k":"el agua","t":"수영장 물이 차갑다.","e":"agua(물)는 여성 명사지만, 강세가 있는 a-/ha-로 시작하는 여성 단수 명사 앞에서는 발음을 위해 정관사 el을 씁니다. 그래도 명사 자체는 여성이라 형용사는 fría(여성형)를 씁니다. 같은 예: el águila(독수리), el hambre(배고픔)","x":["La: 강세 있는 a로 시작하는 여성 명사 앞에서는 la 대신 el을 씁니다 ✗","El: 'el agua(물)' → 정답 ✓","Un: 특정한 수영장 물이므로 정관사가 필요합니다 ✗","Una: 부정관사이고 형태도 맞지 않습니다 ✗"]},{"id":"G111","q":"____ calcetines son nuevos.","o":["Esas","Estas","Estos","Ese"],"a":2,"k":"지시형용사 일치","t":"이 양말들은 새것이다.","e":"calcetines(양말들)는 남성 복수이므로 지시형용사도 남성 복수 estos를 씁니다. 형용사 nuevos도 남성 복수입니다. 참고로 '양말'은 중남미에서 medias라고도 합니다.","x":["Esas: 여성 복수형이라 남성 명사와 맞지 않습니다 ✗","Estas: 여성 복수형이라 맞지 않습니다 ✗","Estos: 남성 복수 '이' → 정답 ✓","Ese: 단수형이라 복수 명사와 맞지 않습니다 ✗"]},{"id":"G112","q":"Afortunadamente, hoy mi hijo se siente ____.","o":["muy mejor","mucho mejor","más mejor","tan mejor"],"a":1,"k":"mucho mejor","t":"다행히 오늘 우리 아들은 훨씬 좋아졌다.","e":"비교급 mejor(더 좋은/더 낫게)를 강조할 때는 mucho를 써서 'mucho mejor(훨씬 더 낫게)'라고 합니다. mejor에 이미 '더'의 뜻이 있어 más를 붙이지 않으며, muy도 비교급을 꾸미지 못합니다.","x":["muy mejor: muy는 비교급을 꾸미지 못합니다 ✗","mucho mejor: '훨씬 더 낫게' → 정답 ✓","más mejor: mejor에 이미 '더'가 들어 있어 틀립니다 ✗","tan mejor: tan은 비교급과 함께 쓰지 않습니다 ✗"]},{"id":"G113","q":"No tengo tanto dinero ____ tú.","o":["que","a que","como","cuanto"],"a":2,"k":"tanto...como","t":"나는 너만큼 돈이 많지 않다.","e":"명사의 양을 같게 비교할 때는 'tanto/tanta/tantos/tantas + 명사 + como'를 씁니다. dinero(돈)는 남성 단수이므로 tanto dinero como가 됩니다. 형용사를 비교할 때는 'tan + 형용사 + como'를 씁니다.","x":["que: más/menos 비교에 쓰며 tanto와는 함께 쓰지 않습니다 ✗","a que: 비교 표현이 아닙니다 ✗","como: 'tanto ... como(~만큼)' → 정답 ✓","cuanto: tanto ... cuanto는 일상 비교에 쓰지 않습니다 ✗"]},{"id":"G114","q":"Tus fotos son muy ____.","o":["bonita","bonitos","bonito","bonitas"],"a":3,"k":"형용사 성·수 일치","t":"네 사진들 정말 예쁘다.","e":"foto(사진)는 fotografía의 줄임말이라 -o로 끝나도 여성 명사입니다. 따라서 복수 fotos에 맞춰 형용사도 여성 복수 bonitas를 씁니다. 같은 예: la moto(오토바이), la mano(손)","x":["bonita: 단수형이라 복수 fotos와 맞지 않습니다 ✗","bonitos: 남성형이라 여성 명사 fotos와 맞지 않습니다 ✗","bonito: 남성 단수형이라 성·수 모두 맞지 않습니다 ✗","bonitas: 여성 복수 → 정답 ✓"]},{"id":"G115","q":"¿Cuánto ____ ese vestido?","o":["cuesta","cuestan","cuesto","cuestas"],"a":0,"k":"costar 활용","t":"그 원피스 얼마예요?","e":"가격을 물을 때 쓰는 costar(값이 ~이다)는 물건이 주어입니다. ese vestido(그 원피스)는 단수이므로 3인칭 단수 cuesta를 씁니다. costar는 o → ue로 바뀌는 불규칙동사입니다.","x":["cuesta: 3인칭 단수 → 정답 ✓","cuestan: 복수형이라 단수 vestido와 맞지 않습니다 ✗","cuesto: 1인칭 '내가 값이 ~이다'라는 뜻이 됩니다 ✗","cuestas: tú 형태라 주어와 맞지 않습니다 ✗"]},{"id":"G116","q":"____ mi opinión, ver series y películas va muy bien para aprender idiomas.","o":["A","De","En","Por"],"a":2,"k":"en mi opinión","t":"내 생각에는 드라마와 영화를 보는 것이 외국어 공부에 아주 좋다.","e":"'en mi opinión'은 '내 의견으로는, 내 생각에는'이라는 고정 표현입니다. 같은 뜻으로 'para mí', 'a mi parecer'도 씁니다. 'ir bien para'는 '~에 좋다, 도움이 되다'입니다.","x":["A: 'a mi opinión'이라고는 하지 않습니다(a mi parecer는 가능) ✗","De: 'de mi opinión'은 고정 표현이 아닙니다 ✗","En: 'en mi opinión(내 생각에는)' → 정답 ✓","Por: 'por mi opinión'은 '내 의견 때문에'라는 다른 뜻입니다 ✗"]},{"id":"G117","q":"¿Has escrito las cartas? —Voy a ____ ahora.","o":["las escribir","escribirlas","escribirla","escribir las"],"a":1,"k":"동사원형 + 목적격","t":"편지 썼니? — 지금 쓰려고.","e":"직접목적격 대명사(~을/를에 해당)는 동사원형 뒤에 붙여 한 단어로 쓸 수 있습니다. 앞에서 말한 las cartas(편지들)는 여성 복수이므로 las를 붙여 escribirlas가 됩니다. 'Las voy a escribir'처럼 활용 동사 앞에 둘 수도 있습니다.","x":["las escribir: 대명사를 동사원형 바로 앞에 따로 둘 수 없습니다 ✗","escribirlas: 동사원형 + las → 정답 ✓","escribirla: 단수형이라 복수 cartas와 맞지 않습니다 ✗","escribir las: 대명사는 동사원형에 붙여 써야 합니다 ✗"]},{"id":"G118","q":"____ ver documentales.","o":["Me aburro","Me aburre","Yo aburro","A mí aburre"],"a":1,"k":"aburrir 구문","t":"나는 다큐멘터리 보는 게 지루하다.","e":"aburrir(지루하게 하다)는 gustar처럼 '지루한 일'이 주어이고 지루함을 느끼는 사람은 간접목적격 대명사로 씁니다. 주어 'ver documentales(다큐 보는 것)'는 동사원형이라 3인칭 단수 aburre가 됩니다. 'Me aburro'는 '나는 지루하다(심심하다)'는 재귀 표현으로 뒤에 동사원형을 직접 잇지 않습니다.","x":["Me aburro: 재귀형 '나는 지루해한다'로 뒤에 동사원형 주어를 받지 않습니다 ✗","Me aburre: '(~하는 것이) 나를 지루하게 한다' → 정답 ✓","Yo aburro: '내가 (누군가를) 지루하게 한다'라는 엉뚱한 뜻입니다 ✗","A mí aburre: 대명사 me가 빠졌습니다(A mí me aburre는 가능) ✗"]},{"id":"G119","q":"Aquí llueve mucho ____ primavera.","o":["a la","en","a","con"],"a":1,"k":"계절 전치사 en","t":"이곳은 봄에 비가 많이 온다.","e":"'~에(계절)'는 전치사 en을 쓰고 보통 관사 없이 'en primavera(봄에)', 'en verano(여름에)'라고 합니다. 월·연도도 en을 씁니다. llover(비가 오다)는 주어 없이 3인칭 단수 llueve로 씁니다.","x":["a la: 계절 앞에 a를 쓰지 않습니다 ✗","en: 계절 앞 전치사 → 정답 ✓","a: 계절 앞에 a를 쓰지 않습니다 ✗","con: '~와 함께'라 시간을 나타내지 않습니다 ✗"]},{"id":"G120","q":"No vivo ____ mis padres, vivo sola.","o":["a","por","en","con"],"a":3,"k":"전치사 con","t":"나는 부모님과 살지 않고 혼자 산다.","e":"'~와 함께'는 전치사 con을 씁니다. 'vivir con + 사람'은 '~와 함께 살다'라는 뜻입니다. sola는 주어가 여성(yo, 여자)임을 보여 주는 형용사로 '혼자'라는 뜻입니다.","x":["a: '~에게/~로'라 함께 사는 사람을 나타내지 못합니다 ✗","por: '~때문에/~을 통해'라 맞지 않습니다 ✗","en: '~에서'라 장소를 나타내며 사람 앞에 어색합니다 ✗","con: '~와 함께' → 정답 ✓"]},{"id":"G121","q":"¿Te gusta mi collar? ____ ha regalado Martín.","o":["Me","Me la","Me lo","A mí"],"a":2,"k":"이중 목적격 대명사","t":"내 목걸이 마음에 들어? 마르틴이 선물해 준 거야.","e":"간접목적격(~에게)과 직접목적격(~을)을 함께 쓸 때는 '간접 + 직접' 순서로 동사 앞에 둡니다. me(나에게) + lo(그것을)인데, lo가 가리키는 collar(목걸이)는 남성 명사이므로 'Me lo ha regalado'가 됩니다. 예: Te la doy.(그것을 너에게 줄게, la = 여성 명사)","x":["Me: 직접목적격 '그것을'이 빠져 불완전합니다 ✗","Me la: la는 여성형이라 남성 명사 collar와 맞지 않습니다 ✗","Me lo: 나에게 + 그것(collar, 남성)을 → 정답 ✓","A mí: 강조 표현만으로는 대명사를 대신할 수 없습니다 ✗"]},{"id":"G122","q":"Está triste ____ ha recibido una mala noticia.","o":["por que","porque","porqué","por qué"],"a":1,"k":"porque (이유)","t":"그녀는 나쁜 소식을 받아서 슬퍼하고 있다.","e":"앞 문장(슬퍼한다)의 이유를 설명할 때는 한 단어 porque(~이기 때문에)를 씁니다. 의문사 '왜?'는 'por qué', 명사 '이유'는 'el porqué'입니다. 'estar triste'는 일시적인 감정 상태라 estar를 씁니다.","x":["por que: 전치사 + 관계사로 이유 접속사가 아닙니다 ✗","porque: 이유 접속사 → 정답 ✓","porqué: '이유'라는 명사입니다 ✗","por qué: '왜'라는 의문사입니다 ✗"]},{"id":"G123","q":"En esta habitación no ____ fumar, está prohibido.","o":["puede se","poderse","se puede","poder"],"a":2,"k":"무인칭 se puede","t":"이 방에서는 담배를 피울 수 없어요, 금지되어 있어요.","e":"'se + 3인칭 동사'는 주어를 특정하지 않고 '(사람들이) ~한다'라는 무인칭 표현을 만듭니다. 'se puede + 동사원형'은 '~할 수 있다(해도 된다)', 부정은 'no se puede(~하면 안 된다)'입니다. 대명사 se는 활용된 동사 앞에 둡니다.","x":["puede se: se는 활용 동사 앞에 와야 합니다 ✗","poderse: 동사원형이라 문장의 동사가 될 수 없습니다 ✗","se puede: 무인칭 '~할 수 있다' → 정답 ✓","poder: 활용되지 않은 동사원형입니다 ✗"]},{"id":"G124","q":"Atenas es una ciudad ____.","o":["gran","grande","grandísimo","grandes"],"a":1,"k":"grande vs gran","t":"아테네는 큰 도시이다.","e":"grande(큰)는 명사 뒤에 올 때 원형 grande를 씁니다. 단수 명사 앞에서는 gran으로 줄어들고 '위대한, 훌륭한'이라는 뜻이 강해집니다(una gran ciudad). 여기서는 명사 ciudad 뒤에 있으므로 grande가 맞습니다.","x":["gran: 명사 앞에서만 쓰는 단축형입니다 ✗","grande: 명사 뒤 '큰' → 정답 ✓","grandísimo: 남성형이라 여성 명사 ciudad와 맞지 않습니다 ✗","grandes: 복수형이라 단수 ciudad와 맞지 않습니다 ✗"]},{"id":"G125","q":"Disculpe, ¿sabe si ____ una farmacia cerca?","o":["está","están","hay","es"],"a":2,"k":"hay vs estar","t":"실례합니다, 근처에 약국이 있는지 아세요?","e":"'(어떤) ~이 있다'라고 불특정한 대상의 존재를 물을 때는 hay를 씁니다. una farmacia처럼 부정관사가 붙은 명사는 hay와 함께 씁니다. 특정한 약국의 위치를 물을 때는 '¿Dónde está la farmacia?'처럼 estar를 씁니다.","x":["está: 부정관사가 붙은 불특정 명사와는 쓰지 않습니다 ✗","están: 복수형이고 용법도 맞지 않습니다 ✗","hay: 불특정한 대상의 존재 '있다' → 정답 ✓","es: ser는 존재를 나타내지 않습니다 ✗"]},{"id":"G126","q":"Debemos ____ acostarnos pronto esta noche.","o":["a","por","en","ø"],"a":3,"k":"deber + 동사원형","t":"오늘 밤에는 일찍 자야 한다.","e":"deber(~해야 한다)는 바로 뒤에 전치사 없이 동사원형이 옵니다. acostarnos는 재귀동사 acostarse(잠자리에 들다)에 nos(우리)를 붙인 형태입니다. 'pronto'는 스페인에서 '일찍'이라는 뜻으로도 쓰입니다(중남미에서는 temprano를 주로 씀).","x":["a: deber 뒤에 a를 넣지 않습니다 ✗","por: deber 뒤에 por를 넣지 않습니다 ✗","en: deber 뒤에 en을 넣지 않습니다 ✗","ø: deber + 동사원형 → 정답 ✓"]},{"id":"G127","q":"Estos ____ los ingredientes que necesitamos para hacer la paella.","o":["son","somos","ser","sois"],"a":0,"k":"ser 활용","t":"이것들이 파에야를 만드는 데 필요한 재료들이다.","e":"'이것들은 ~이다'처럼 무엇인지 정의할 때는 ser를 씁니다. 주어 estos(이것들, 재료를 가리킴)는 3인칭 복수이므로 son이 됩니다. 'Estos son mis padres(이분들이 우리 부모님이에요)'처럼 소개할 때도 같은 구조를 씁니다.","x":["son: ser 3인칭 복수 → 정답 ✓","somos: '우리는 ~이다'라 주어와 맞지 않습니다 ✗","ser: 동사원형이라 활용이 필요합니다 ✗","sois: '너희는 ~이다'라 주어와 맞지 않습니다 ✗"]},{"id":"G128","q":"____ con respeto, por favor.","o":["Hable a mí","Hable me","Hábleme","Me hable"],"a":2,"k":"긍정명령 + 대명사","t":"저에게 예의 있게 말씀해 주세요.","e":"긍정명령문에서는 목적격 대명사를 동사 끝에 붙여 한 단어로 씁니다. usted에 대한 명령형 hable에 me를 붙이면 강세 위치를 지키기 위해 악센트가 생겨 hábleme가 됩니다. 부정명령에서는 'No me hable así'처럼 대명사가 동사 앞에 옵니다.","x":["Hable a mí: 대명사 me가 빠졌고 구조도 틀렸습니다 ✗","Hable me: 대명사를 띄어 쓰면 안 되고 악센트도 빠졌습니다 ✗","Hábleme: 명령형 + me, 악센트 추가 → 정답 ✓","Me hable: 긍정명령에서는 대명사가 동사 앞에 오지 않습니다 ✗"]},{"id":"G129","q":"¿Ya has hablado con Joaquín? —No, ____.","o":["también","tampoco","todavía no","todavía"],"a":2,"k":"todavía no","t":"벌써 호아킨이랑 이야기했어? — 아니, 아직.","e":"'¿Ya ...?(벌써/이미 ~했어?)'라는 질문에 '아직 안 했다'라고 답할 때는 'todavía no'를 씁니다. ya는 '이미', todavía no는 '아직 ~않다'입니다. 같은 뜻으로 'aún no'도 씁니다.","x":["también: '~도 역시'라 질문에 대한 대답으로 맞지 않습니다 ✗","tampoco: 부정 문장에 동의할 때 쓰는 말이라 맞지 않습니다 ✗","todavía no: '아직 안 했다' → 정답 ✓","todavía: '아직도'라 no 없이는 부정 대답이 되지 않습니다 ✗"]},{"id":"G130","q":"Esa peluquería está cerrada ____ los lunes.","o":["por","en","ø","a"],"a":2,"k":"요일 + 정관사","t":"그 미용실은 월요일마다 문을 닫는다.","e":"요일 앞에는 전치사를 쓰지 않고 정관사만 붙입니다. 'los lunes'처럼 복수 정관사를 쓰면 '월요일마다'라는 반복을 뜻합니다. 'el lunes'는 '(이번) 월요일에'라는 뜻입니다.","x":["por: 요일 앞에 por를 쓰지 않습니다 ✗","en: 요일 앞에 en을 쓰지 않습니다 ✗","ø: 요일 앞은 정관사만, 전치사 없음 → 정답 ✓","a: 요일 앞에 a를 쓰지 않습니다 ✗"]},{"id":"G131","q":"____ que dices no es verdad.","o":["Esos","Esa","Ese","Eso"],"a":3,"k":"중성 지시대명사","t":"네가 하는 말은 사실이 아니다.","e":"상대방이 한 말이나 생각처럼 구체적인 명사가 아닌 내용을 가리킬 때는 중성 지시대명사 eso(그것)를 씁니다. 'Eso que dices'는 '네가 말하는 그것'이라는 뜻입니다. 같은 의미로 'Lo que dices'도 자주 씁니다.","x":["Esos: 남성 복수 '그것들'이라 말의 내용을 가리키지 못합니다 ✗","Esa: 여성 단수라 특정 명사가 있어야 합니다 ✗","Ese: 남성 단수라 특정 명사가 있어야 합니다 ✗","Eso: 내용을 가리키는 중성 '그것' → 정답 ✓"]},{"id":"G132","q":"Yo preparo ____ desayuno mientras mis hijos se preparan para ir a la escuela.","o":["ø","uno","el","un"],"a":2,"k":"식사 + 정관사","t":"아이들이 학교 갈 준비를 하는 동안 나는 아침을 준비한다.","e":"desayuno(아침 식사), comida(점심), cena(저녁) 같은 매일 하는 식사는 보통 정관사를 붙여 'preparar el desayuno'라고 합니다. desayuno는 남성 명사이므로 el을 씁니다. 동사로는 desayunar(아침을 먹다)도 씁니다.","x":["ø: 식사 명사 앞에는 정관사를 붙이는 것이 자연스럽습니다 ✗","uno: 대명사라 명사 앞에 쓰지 않습니다 ✗","el: 남성 정관사 'el desayuno' → 정답 ✓","un: '어떤 아침 식사 하나'라는 어색한 뜻이 됩니다 ✗"]},{"id":"G133","q":"Prefiero viajar ____ tren.","o":["en","a","de","sobre"],"a":0,"k":"교통수단 en","t":"나는 기차로 여행하는 것을 더 좋아한다.","e":"교통수단을 나타낼 때는 'en + 교통수단(관사 없음)'을 씁니다. en tren(기차로), en coche(차로), en avión(비행기로)처럼 씁니다. 단, '걸어서'는 'a pie', '말 타고'는 'a caballo'입니다.","x":["en: 교통수단 '~로' → 정답 ✓","a: 'a pie(걸어서)' 같은 경우에만 쓰며 tren에는 쓰지 않습니다 ✗","de: 교통수단을 나타내지 않습니다 ✗","sobre: '~위에'라 기차 지붕 위라는 엉뚱한 뜻이 됩니다 ✗"]},{"id":"G134","q":"Javi empezó ____ jugar al fútbol a los seis años.","o":["a","ø","en","de"],"a":0,"k":"empezar a","t":"하비는 여섯 살 때 축구를 시작했다.","e":"'empezar a + 동사원형'은 '~하기 시작하다'라는 표현으로 a가 꼭 필요합니다. 'a los seis años'는 '여섯 살 때'라는 뜻입니다. 같은 의미로 'comenzar a + 동사원형'도 씁니다.","x":["a: 'empezar a(~하기 시작하다)' → 정답 ✓","ø: empezar 뒤에 동사원형이 오려면 a가 필요합니다 ✗","en: empezar en은 장소·시점 표현이라 동사원형과 맞지 않습니다 ✗","de: empezar 뒤에 de를 쓰지 않습니다 ✗"]},{"id":"G135","q":"José Antonio no come ____ carne. Es vegetariano.","o":["el","ø","la","una"],"a":1,"k":"무관사 (일반 물질)","t":"호세 안토니오는 고기를 먹지 않는다. 채식주의자다.","e":"carne(고기)처럼 셀 수 없는 명사를 일반적으로 '먹다/사다/없다'라고 말할 때는 관사를 붙이지 않습니다. 'No como carne(나는 고기를 안 먹는다)'처럼 씁니다. 특정한 고기를 가리킬 때만 'la carne'를 씁니다.","x":["el: carne는 여성 명사이고 관사도 필요 없습니다 ✗","ø: 일반적인 물질명사 목적어 무관사 → 정답 ✓","la: 특정한 고기를 가리킬 때만 씁니다 ✗","una: 셀 수 없는 명사라 부정관사를 붙이지 않습니다 ✗"]},{"id":"G136","q":"Cerca de mi casa no hay ____ lugares interesantes.","o":["las","algún","los","ø"],"a":3,"k":"hay + 무관사 복수","t":"우리 집 근처에는 흥미로운 곳이 없다.","e":"hay 뒤에 불특정한 복수 명사가 올 때는 관사 없이 씁니다. 'No hay lugares interesantes(흥미로운 장소가 없다)'처럼 씁니다. hay 뒤에는 정관사(los, las)를 쓰지 않습니다.","x":["las: 정관사이고 lugares는 남성 명사라 틀립니다 ✗","algún: 단수형이라 복수 lugares와 맞지 않습니다 ✗","los: hay 뒤에는 정관사를 쓰지 않습니다 ✗","ø: hay + 무관사 복수 명사 → 정답 ✓"]},{"id":"G137","q":"A mis hijos les gusta mucho ____ chocolate.","o":["uno","del","la","el"],"a":3,"k":"gustar + 정관사","t":"우리 아이들은 초콜릿을 정말 좋아한다.","e":"gustar의 주어는 좋아하는 대상인 chocolate이고, 주어 명사 앞에는 정관사를 붙입니다. chocolate는 남성 명사이므로 el chocolate가 됩니다. 'No como chocolate'처럼 일반 동사 목적어일 때와 달리 gustar 구문에서는 관사가 필요합니다.","x":["uno: 대명사라 명사 앞에 쓰지 않습니다 ✗","del: 프랑스어식 부분관사 표현으로 스페인어에서 쓰지 않습니다 ✗","la: chocolate는 남성 명사라 맞지 않습니다 ✗","el: 남성 정관사 → 정답 ✓"]},{"id":"G138","q":"Me gustan los domingos ____ puedo dedicarme a mis aficiones.","o":["porque","aunque","como","por"],"a":0,"k":"porque (이유)","t":"나는 일요일이 좋다, 왜냐하면 내 취미 생활을 할 수 있기 때문이다.","e":"일요일을 좋아하는 이유를 설명하므로 이유 접속사 porque(~이기 때문에)를 씁니다. 'dedicarse a + 명사'는 '~에 시간을 쏟다'라는 뜻이고, afición은 '취미'입니다. aunque는 '~에도 불구하고'라는 양보입니다.","x":["porque: 이유 '~이기 때문에' → 정답 ✓","aunque: '~지만'이라는 양보라 의미가 맞지 않습니다 ✗","como: 이유의 como는 문장 맨 앞에서만 씁니다 ✗","por: 뒤에 활용된 동사를 이을 수 없습니다 ✗"]},{"id":"G139","q":"Tu texto está ____, no tiene errores.","o":["bueno","buena","bien","buen"],"a":2,"k":"estar bien","t":"네 글은 잘 썼어, 틀린 곳이 없어.","e":"'estar bien'은 '(상태가) 잘 되어 있다, 맞다'라는 평가 표현입니다. bien은 부사이므로 명사 texto의 성·수에 따라 변하지 않습니다. 반대는 'estar mal(틀렸다)'입니다.","x":["bueno: 'estar bueno'는 주로 음식이 맛있다는 뜻 등으로 쓰여 '잘 됐다'라는 평가에는 bien이 기본입니다 ✗","buena: 여성형이라 남성 명사 texto와 맞지 않습니다 ✗","bien: 부사 '잘, 제대로' → 정답 ✓","buen: 명사 앞에서만 쓰는 단축형입니다 ✗"]},{"id":"G140","q":"No tengo ____ camiseta blanca.","o":["ninguna","algunas","algún","alguna"],"a":0,"k":"ninguno 부정","t":"나는 흰 티셔츠가 하나도 없다.","e":"부정문(No tengo)에서 '하나도 ~없다'라고 할 때는 ninguno/ninguna를 씁니다. camiseta(티셔츠)는 여성 단수이므로 ninguna가 됩니다. 스페인어는 no와 ninguna처럼 부정어를 겹쳐 써도 부정 의미가 유지됩니다.","x":["ninguna: 여성 단수 '하나도 ~없는' → 정답 ✓","algunas: 복수 '몇몇'이고 부정문의 강조와 맞지 않습니다 ✗","algún: 남성형이라 여성 명사 camiseta와 맞지 않습니다 ✗","alguna: 부정문에서 '하나도'라는 뜻으로는 ninguna를 씁니다 ✗"]},{"id":"G141","q":"Si habláis en voz alta, vais a despertar ____ los niños.","o":["por","ø","a","para"],"a":2,"k":"사람 목적어 a","t":"너희가 큰 소리로 말하면 아이들을 깨우게 될 거야.","e":"despertar(깨우다)의 직접목적어가 사람(los niños)이므로 앞에 '인칭의 a'를 붙입니다. 'a los niños'처럼 a + 정관사 los는 합쳐지지 않습니다(a + el만 al로 합침). 'ir a + 동사원형'으로 미래를 나타낸 문장입니다.","x":["por: '~때문에'라는 뜻이 되어 맞지 않습니다 ✗","ø: 사람 직접목적어 앞에는 a가 필요합니다 ✗","a: 사람 목적어 앞 '인칭의 a' → 정답 ✓","para: '~를 위해'라 목적어를 나타내지 못합니다 ✗"]},{"id":"G142","q":"Los helados que más me gustan son los ____ fresa.","o":["a","con","en","de"],"a":3,"k":"de + 맛·재료","t":"내가 가장 좋아하는 아이스크림은 딸기 아이스크림이다.","e":"'명사 + de + 재료/맛'은 '~로 만든, ~ 맛의'라는 뜻입니다. 'helado de fresa(딸기 아이스크림)', 'zumo de naranja(오렌지 주스)'처럼 씁니다. 여기서 'los de fresa'는 'los helados de fresa'에서 반복되는 명사를 생략한 형태입니다.","x":["a: '~ 맛'을 나타낼 때 a를 쓰지 않습니다 ✗","con: '딸기를 곁들인'이라는 뜻이 되어 맛을 나타내지 못합니다 ✗","en: 재료·맛을 나타내지 않습니다 ✗","de: '~ 맛의' → 정답 ✓"]},{"id":"G143","q":"José María está ____ vacaciones en Tenerife.","o":["por","a","sobre","de"],"a":3,"k":"estar de vacaciones","t":"호세 마리아는 테네리페에서 휴가 중이다.","e":"'estar de vacaciones'는 '휴가 중이다'라는 고정 표현입니다. 'irse de vacaciones(휴가를 떠나다)'처럼 de를 씁니다. 비슷한 표현으로 'estar de viaje(여행 중이다)'도 있습니다.","x":["por: 'estar por vacaciones'라고 하지 않습니다 ✗","a: 'estar a vacaciones'라는 표현은 없습니다 ✗","sobre: '~위에/~에 대해'라 맞지 않습니다 ✗","de: 'estar de vacaciones(휴가 중)' → 정답 ✓"]},{"id":"G144","q":"¿Dónde ____ ahora Ana y Luisa?","o":["vives","vivimos","vive","viven"],"a":3,"k":"vivir 활용","t":"아나와 루이사는 지금 어디에 살고 있니?","e":"주어 'Ana y Luisa'는 두 사람이므로 3인칭 복수(ellas)이고, vivir(살다)의 3인칭 복수형은 viven입니다. 의문문에서는 주어가 동사 뒤로 가는 경우가 많습니다. -ir 동사 현재형: vivo, vives, vive, vivimos, vivís, viven","x":["vives: tú(너) 형태라 맞지 않습니다 ✗","vivimos: nosotros(우리) 형태라 맞지 않습니다 ✗","vive: 3인칭 단수라 두 사람 주어와 맞지 않습니다 ✗","viven: 3인칭 복수 → 정답 ✓"]},{"id":"G145","q":"Este libro es ____ aprender ruso.","o":["por","hasta","a","para"],"a":3,"k":"para (목적·용도)","t":"이 책은 러시아어를 배우기 위한 것이다.","e":"'ser para + 동사원형/명사'는 '~을 위한 것이다'라는 용도나 목적을 나타냅니다. 예: Este regalo es para ti.(이 선물은 너를 위한 거야.) por는 원인·이유에 씁니다.","x":["por: '~때문에'라는 원인을 나타내 용도와 맞지 않습니다 ✗","hasta: '~까지'라 맞지 않습니다 ✗","a: ser와 함께 용도를 나타내지 않습니다 ✗","para: 용도 '~을 위한' → 정답 ✓"]},{"id":"G146","q":"Los niños están jugando ____ jardín.","o":["en la","en el","en","al"],"a":1,"k":"en + 정관사","t":"아이들이 정원에서 놀고 있다.","e":"'~에서'라는 장소는 전치사 en으로 나타내고, 특정한 장소이므로 정관사를 붙입니다. jardín(정원)은 남성 명사이므로 'en el jardín'이 됩니다. en과 el은 합쳐지지 않습니다(a + el, de + el만 축약).","x":["en la: jardín은 남성 명사라 여성 관사를 쓰지 않습니다 ✗","en el: 장소 + 남성 정관사 → 정답 ✓","en: 특정 장소 앞에 관사가 빠졌습니다 ✗","al: 방향을 나타내 '정원으로'라는 뜻이 되어 jugar와 맞지 않습니다 ✗"]},{"id":"G147","q":"¿A ____ hora tenemos la reunión mañana?","o":["cuánta","qué","quién","cuál"],"a":1,"k":"¿A qué hora?","t":"내일 회의는 몇 시에 있어?","e":"'몇 시에?'라고 물을 때는 '¿A qué hora...?'를 씁니다. 명사 앞에서 '어떤, 무슨'이라는 뜻으로는 qué를 씁니다. 대답은 'A las diez(10시에)'처럼 a + 정관사 + 시각으로 합니다.","x":["cuánta: '얼마나 많은'이라 시각을 묻지 못합니다 ✗","qué: '¿A qué hora?(몇 시에?)' → 정답 ✓","quién: '누구'라 맞지 않습니다 ✗","cuál: 스페인 표준에서는 명사 앞에 cuál을 쓰지 않습니다 ✗"]},{"id":"G148","q":"No necesitamos ____ huevos para preparar el bizcocho.","o":["tanto","tantos","tantas","tan"],"a":1,"k":"tanto 일치","t":"스펀지케이크를 만드는 데 그렇게 많은 달걀이 필요하지 않다.","e":"tanto(그렇게 많은)가 명사 앞에 오면 명사의 성·수에 맞춥니다. huevos(달걀들)는 남성 복수이므로 tantos가 됩니다. tan은 형용사·부사 앞에만 씁니다(tan grande).","x":["tanto: 단수형이라 복수 huevos와 맞지 않습니다 ✗","tantos: 남성 복수 → 정답 ✓","tantas: 여성형이라 남성 명사 huevos와 맞지 않습니다 ✗","tan: 형용사·부사 앞에 쓰며 명사 앞에는 쓰지 않습니다 ✗"]},{"id":"G149","q":"Ignacio me ha invitado a ____ fiesta de cumpleaños.","o":["suyas","su","sus","la suya"],"a":1,"k":"소유형용사 su","t":"이그나시오가 나를 자기 생일 파티에 초대했다.","e":"명사 앞에서 '그의/그녀의'는 소유형용사 su(단수)/sus(복수)를 씁니다. fiesta(파티)는 단수이므로 su fiesta가 됩니다. 소유형용사는 소유자(Ignacio)가 아니라 소유된 명사(fiesta)의 수에 맞춥니다.","x":["suyas: 강세형 복수라 명사 앞에 쓰지 않습니다 ✗","su: 단수 명사 앞 '그의' → 정답 ✓","sus: 복수형이라 단수 fiesta와 맞지 않습니다 ✗","la suya: '그의 것'이라는 대명사라 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G150","q":"No veo ____ tele, prefiero navegar por internet.","o":["al","el","la","a la"],"a":2,"k":"ver la tele","t":"나는 TV를 안 보고, 인터넷 서핑을 더 좋아한다.","e":"tele는 televisión(텔레비전)의 줄임말로 여성 명사이므로 'ver la tele(TV를 보다)'라고 합니다. 직접목적어가 사물이므로 전치사 a는 쓰지 않습니다. 'navegar por internet'은 '인터넷 서핑을 하다'라는 표현입니다.","x":["al: 사물 목적어 앞에 a를 쓰지 않고 tele는 여성입니다 ✗","el: tele는 여성 명사라 맞지 않습니다 ✗","la: 여성 정관사 'la tele' → 정답 ✓","a la: 사물 직접목적어 앞에는 a를 쓰지 않습니다 ✗"]},{"id":"G151","q":"¡Qué ____ tengo las manos! Voy a ponerme los guantes.","o":["frías","frío","fría","fríos"],"a":0,"k":"형용사 성·수 일치","t":"손이 정말 차갑네! 장갑을 껴야겠어.","e":"형용사는 꾸미는 명사의 성(남성/여성)과 수(단수/복수)에 맞춰 형태가 바뀝니다. 'las manos(손들)'는 -o로 끝나지만 여성 명사이고 복수이므로 여성 복수형 frías가 맞습니다. '¡Qué + 형용사 + 동사 + 명사!'는 '정말 ~하구나!'라는 감탄문입니다.","x":["frías: 여성 복수형(차가운)으로 las manos와 일치 → 정답 ✓","frío: 남성 단수형이거나 명사 '추위'라서 여성 복수 manos와 맞지 않습니다 ✗","fría: 여성 단수형이라 복수 manos와 수가 맞지 않습니다 ✗","fríos: 남성 복수형이라 여성 명사 manos와 성이 맞지 않습니다 ✗"]},{"id":"G152","q":"Madrid está ____ centro de España.","o":["en el","al","en","en la"],"a":0,"k":"en el centro","t":"마드리드는 스페인 중앙에 있다.","e":"위치를 말할 때 '~에 있다'는 estar en을 씁니다. centro(중심)는 남성 명사이고 '스페인의 그 중심'처럼 특정한 곳이므로 정관사 el이 필요해 en el centro가 됩니다. 예: Vivo en el centro.(나는 시내 중심가에 산다.)","x":["en el: 위치 전치사 en + 남성 정관사 el → 정답 ✓","al: a + el의 축약으로 방향(~로)을 나타내 estar와 함께 위치를 말할 때 쓰지 않습니다 ✗","en: 관사가 빠져 특정한 '그 중심'을 나타내지 못합니다 ✗","en la: la는 여성 관사라 남성 명사 centro와 맞지 않습니다 ✗"]},{"id":"G153","q":"En ese teatro hay ahora ____ personas.","o":["doscientas","las doscientas","dos cientas","doscientos"],"a":0,"k":"숫자 200 성 일치","t":"그 극장에는 지금 200명의 사람이 있다.","e":"200~900의 백 단위 숫자(doscientos, trescientos…)는 뒤의 명사 성에 맞춰 -os/-as로 바뀝니다. personas(사람들)는 여성 명사이므로 doscientas가 맞습니다. 또한 한 단어로 붙여 씁니다. 예: doscientos libros(책 200권).","x":["doscientas: 여성형 200으로 personas와 일치 → 정답 ✓","las doscientas: 정관사 las가 붙어 '그 200명'이 되어 hay(~이 있다) 문장과 어울리지 않습니다 ✗","dos cientas: 띄어 쓰는 것은 틀린 철자입니다 ✗","doscientos: 남성형이라 여성 명사 personas와 맞지 않습니다 ✗"]},{"id":"G154","q":"¿Has visto esa película? —No, todavía no ____ he visto.","o":["lo","el","la","las"],"a":2,"k":"직접목적격 대명사","t":"그 영화 봤어? — 아니, 아직 그것을 못 봤어.","e":"앞에 나온 명사를 '그것을'로 받을 때는 직접목적격 대명사(~을/를에 해당: lo, la, los, las)를 씁니다. película(영화)는 여성 단수이므로 la를 동사 앞에 둡니다. 현재완료(he visto)에서는 대명사가 haber 앞에 옵니다.","x":["lo: 남성 단수 목적격이라 여성 명사 película와 맞지 않습니다 ✗","el: 정관사이지 대명사가 아니므로 이 자리에 올 수 없습니다 ✗","la: 여성 단수 직접목적격(그것을) → 정답 ✓","las: 여성 복수형이라 영화 한 편을 받을 수 없습니다 ✗"]},{"id":"G155","q":"Ese señor de allí es un escritor ____ conocido.","o":["muy","más","mucho","tanto"],"a":0,"k":"muy + 형용사","t":"저기 있는 저 신사는 아주 유명한 작가이다.","e":"형용사(conocido: 알려진, 유명한) 앞에서 '매우'를 나타낼 때는 muy를 씁니다. mucho는 명사 앞이나 동사 뒤에서 '많이'를 뜻하고, 형용사 앞에는 쓰지 않습니다. 예: muy alto(아주 키가 큰) / Trabajo mucho.(나는 일을 많이 한다.)","x":["muy: 형용사 앞의 '매우' → 정답 ✓","más: '더'라는 비교 표현이라 비교 대상(que…)이 없으면 어색합니다 ✗","mucho: 형용사 앞에서는 쓰지 않고 muy를 써야 합니다 ✗","tanto: '그만큼'이란 뜻으로 형용사 앞에서는 tan이 되며 비교 문맥이 필요합니다 ✗"]},{"id":"G156","q":"Tengo ____ ir al dentista, me duele una muela.","o":["que","de","como","a"],"a":0,"k":"tener que","t":"치과에 가야 해, 어금니가 아파.","e":"'tener que + 동사원형'은 '~해야 한다'는 의무를 나타내는 아주 자주 쓰는 표현입니다. Tengo que ir는 '나는 가야 한다'라는 뜻입니다. 예: Tienes que estudiar.(너는 공부해야 해.)","x":["que: tener que + 동사원형(~해야 한다) → 정답 ✓","de: tener de라는 의무 표현은 쓰지 않습니다 ✗","como: '~처럼'이라는 뜻이라 문장이 성립하지 않습니다 ✗","a: tener a + 동사원형이라는 표현은 없습니다 ✗"]},{"id":"G157","q":"____ que estés deprimido.","o":["Entristezco","Me entristezco","Entristecerme","Me entristece"],"a":3,"k":"감정동사 + que 접속법","t":"네가 우울해해서 슬프다.","e":"'Me entristece que + 접속법'은 gustar처럼 쓰는 구문으로, 'que 이하의 일이 나를 슬프게 한다'는 뜻입니다. 주어는 que절 전체이고 '슬퍼하는 사람'은 간접목적격 대명사 me로 나타냅니다. 감정을 나타내는 동사 뒤 que절에는 접속법(바람·의심·감정을 나타낼 때 쓰는 동사 형태) estés가 옵니다.","x":["Entristezco: '내가 (누구를) 슬프게 한다'는 뜻이라 que절과 맞지 않습니다 ✗","Me entristezco: '나는 슬퍼진다'는 재귀형으로, 뒤에 de que가 필요합니다 ✗","Entristecerme: 동사원형이라 문장의 주된 동사가 될 수 없습니다 ✗","Me entristece: 'que절이 나를 슬프게 한다' 구조 → 정답 ✓"]},{"id":"G158","q":"En primavera les ____ viajar por España.","o":["gusta","gustas","gustáis","gustan"],"a":0,"k":"gustar + 동사원형","t":"봄에 그들은 스페인을 여행하는 것을 좋아한다.","e":"gustar 구문에서 동사는 '좋아하는 대상'에 맞춥니다. 대상이 동사원형(viajar: 여행하다)이면 항상 3인칭 단수 gusta를 씁니다. les(그들에게)는 좋아하는 사람을 나타낼 뿐 동사 형태에는 영향을 주지 않습니다.","x":["gusta: 동사원형 viajar가 주어이므로 3인칭 단수 → 정답 ✓","gustas: 2인칭 단수(네가 마음에 든다)라 맞지 않습니다 ✗","gustáis: 2인칭 복수(너희가 마음에 든다)라 맞지 않습니다 ✗","gustan: 복수 명사를 좋아할 때 쓰며 동사원형 앞에서는 쓰지 않습니다 ✗"]},{"id":"G159","q":"¿Es verdad ____ Ana se casa la semana que viene?","o":["como","cuando","que","ø"],"a":2,"k":"es verdad que","t":"아나가 다음 주에 결혼한다는 게 사실이야?","e":"'¿Es verdad que + 문장?'은 '~라는 게 사실이야?'라는 표현입니다. que는 영어의 that처럼 뒤에 오는 문장을 이어 주는 접속사입니다. 스페인어에서는 이 que를 생략하지 않습니다.","x":["como: '~처럼/~하듯이'라는 뜻이라 내용을 연결하지 못합니다 ✗","cuando: '~할 때'라는 뜻이라 의미가 맞지 않습니다 ✗","que: 문장을 이어 주는 접속사(~라는 것) → 정답 ✓","ø: 스페인어에서는 이 자리의 que를 생략할 수 없습니다 ✗"]},{"id":"G160","q":"Los lunes ____ la mañana me levanto con mucha energía.","o":["a","por","entre","para"],"a":1,"k":"por la mañana","t":"월요일 아침에는 나는 아주 활기차게 일어난다.","e":"하루 중 시간대(오전, 오후, 밤)를 말할 때는 por la mañana(아침에), por la tarde(오후에), por la noche(밤에)처럼 전치사 por를 씁니다. 단, 정확한 시각과 함께 쓸 때는 de를 씁니다. 예: a las 8 de la mañana(아침 8시에).","x":["a: a la mañana는 스페인 표준 표현이 아닙니다(아르헨티나 등 일부 중남미에서는 씀) ✗","por: 하루의 시간대를 나타내는 por la mañana → 정답 ✓","entre: '~사이에'라는 뜻이라 맞지 않습니다 ✗","para: '~을 위해/~까지'라는 뜻이라 시간대 표현이 되지 않습니다 ✗"]},{"id":"G161","q":"Son ____ once de la noche y Pablo todavía no ha vuelto.","o":["la","las","ø","los"],"a":1,"k":"시각 표현","t":"밤 11시인데 파블로는 아직 돌아오지 않았다.","e":"시각을 말할 때는 'Es la una(1시)'를 제외하고 'Son las + 숫자'를 씁니다. 시각 앞의 관사는 여성형인데, 생략된 단어 horas(시간, 여성 명사)에 맞추기 때문입니다. 11시는 복수이므로 las once가 됩니다.","x":["la: 단수형으로 1시(la una)에만 씁니다 ✗","las: 2시 이후 시각 앞의 여성 복수 관사 → 정답 ✓","ø: 시각 앞에는 관사가 꼭 필요합니다 ✗","los: 남성형이라 시각 표현에 쓰지 않습니다 ✗"]},{"id":"G162","q":"¿____ usted el papá de Federico?","o":["Eres","Estás","Está","Es"],"a":3,"k":"ser 동사 usted","t":"당신이 페데리코의 아빠이세요?","e":"신분·관계(누구의 아빠인지)를 말할 때는 ser를 씁니다. usted(당신)는 존칭이지만 동사는 3인칭 단수형을 쓰므로 es가 맞습니다. estar는 상태나 위치를 나타낼 때 씁니다.","x":["Eres: ser의 2인칭 단수(tú)형이라 usted와 맞지 않습니다 ✗","Estás: estar의 tú형이며, 신분은 estar로 말하지 않습니다 ✗","Está: usted형이지만 estar는 상태·위치에 쓰므로 맞지 않습니다 ✗","Es: ser의 3인칭 단수, usted에 맞는 형태 → 정답 ✓"]},{"id":"G163","q":"____ edificio es el más alto de la ciudad.","o":["Aquel el","Aquello","Aquel","Aquella"],"a":2,"k":"지시형용사 aquel","t":"저 건물이 도시에서 가장 높다.","e":"aquel(저, 멀리 있는)은 지시형용사로 명사 앞에 바로 붙으며 관사를 함께 쓰지 않습니다. edificio(건물)는 남성 단수라서 aquel이 맞습니다. 여성형은 aquella, 복수형은 aquellos/aquellas입니다.","x":["Aquel el: 지시형용사와 정관사를 함께 쓸 수 없습니다 ✗","Aquello: 중성 대명사(저것)로 명사 앞에 쓰지 않습니다 ✗","Aquel: 남성 단수 지시형용사(저) → 정답 ✓","Aquella: 여성형이라 남성 명사 edificio와 맞지 않습니다 ✗"]},{"id":"G164","q":"El conferenciante no dijo ____ interesante.","o":["nada","ninguno","nadie","ninguna"],"a":0,"k":"부정어 nada","t":"그 강연자는 흥미로운 말을 아무것도 하지 않았다.","e":"사물에 대해 '아무것도 (~않다)'는 nada를 씁니다. 스페인어는 no와 nada를 함께 쓰는 이중 부정이 정상 문법입니다. 'nada + 형용사(interesante)'는 '흥미로운 것은 아무것도'라는 뜻이 됩니다.","x":["nada: 사물에 대한 '아무것도' → 정답 ✓","ninguno: '어느 것도/아무도'라는 뜻으로 특정 명사 집단을 가리킬 때 씁니다 ✗","nadie: 사람에 대한 '아무도'라서 의미가 맞지 않습니다 ✗","ninguna: 여성형으로 특정 여성 명사를 가리킬 때 쓰므로 맞지 않습니다 ✗"]},{"id":"G165","q":"Vamos a ir a Bilbao en tren y vamos a regresar en ____ avión.","o":["lo","una","ø","la"],"a":2,"k":"교통수단 en + 무관사","t":"우리는 빌바오에 기차로 가서 비행기로 돌아올 거야.","e":"교통수단을 나타낼 때는 'en + 교통수단'을 관사 없이 씁니다: en tren(기차로), en avión(비행기로), en coche(차로). 앞부분의 en tren과 같은 형태로 en avión이 됩니다. 단, '걸어서'는 a pie입니다.","x":["lo: 중성 관사/대명사로 명사 avión 앞에 쓰지 않습니다 ✗","una: 여성 부정관사이고, 교통수단 앞에는 관사를 쓰지 않습니다 ✗","ø: en + 교통수단은 관사 없이 씀 → 정답 ✓","la: 여성 관사이며, 교통수단 표현에는 관사를 쓰지 않습니다 ✗"]},{"id":"G166","q":"Tengo un examen importante ____ 2 de octubre.","o":["el","en el","en la","al"],"a":0,"k":"날짜 앞 정관사 el","t":"나는 10월 2일에 중요한 시험이 있다.","e":"스페인어에서 날짜를 말할 때는 '~에'라는 전치사 없이 정관사 el만 씁니다: el 2 de octubre(10월 2일에). 요일도 마찬가지로 el lunes(월요일에)처럼 씁니다. en el 2 de octubre라고 하지 않습니다.","x":["el: 날짜 앞에는 정관사 el만 씀 → 정답 ✓","en el: 날짜 앞에 en을 넣지 않습니다 ✗","en la: 전치사가 불필요하고 la는 여성형이라 맞지 않습니다 ✗","al: a + el 축약형이라 날짜 표현에 쓰지 않습니다 ✗"]},{"id":"G167","q":"No me gusta el verano, por eso ____ el otoño con ganas.","o":["espera","espere","espero","esperas"],"a":2,"k":"현재형 1인칭","t":"나는 여름을 좋아하지 않아. 그래서 가을을 손꼽아 기다려.","e":"주어가 me gusta에서 보이듯 '나(yo)'이므로 esperar(기다리다)의 1인칭 단수 현재형 espero를 씁니다. -ar 동사의 현재형은 -o, -as, -a, -amos, -áis, -an으로 변합니다. 'con ganas'는 '간절히, 열심히'라는 뜻입니다.","x":["espera: 3인칭 단수(그/그녀/당신)형이라 주어 yo와 맞지 않습니다 ✗","espere: 접속법 현재 형태라 평서문에 맞지 않습니다 ✗","espero: 1인칭 단수 현재형(나는 기다린다) → 정답 ✓","esperas: 2인칭 단수(너)형이라 맞지 않습니다 ✗"]},{"id":"G168","q":"Mi padre se ____ muy pronto.","o":["despierta","despertamos","despertar","despierto"],"a":0,"k":"despertarse","t":"우리 아버지는 아주 일찍 잠에서 깬다.","e":"despertarse(잠에서 깨다)는 재귀동사(주어가 자기 자신에게 하는 동작)이며 e→ie로 바뀌는 불규칙 동사입니다. 주어 mi padre는 3인칭 단수이므로 se despierta가 됩니다. 재귀대명사 se가 이미 문장에 있으므로 동사만 맞추면 됩니다.","x":["despierta: 3인칭 단수 현재형(se와 함께 '그는 깬다') → 정답 ✓","despertamos: 1인칭 복수형이라 se, mi padre와 맞지 않습니다 ✗","despertar: 동사원형이라 활용되지 않았습니다 ✗","despierto: 1인칭 단수형이라 주어와 맞지 않습니다 ✗"]},{"id":"G169","q":"Los productos de limpieza están ____ final de ese pasillo.","o":["al","con el","del","para el"],"a":0,"k":"al final de","t":"세제 제품은 그 통로 끝에 있다.","e":"'al final de ~'는 '~의 끝에'라는 위치 표현입니다. al은 a + el의 축약형입니다. 예: al final de la calle(길 끝에).","x":["al: al final de(~의 끝에) → 정답 ✓","con el: '~와 함께'라는 뜻이라 위치 표현이 되지 않습니다 ✗","del: '~의/~로부터'라는 뜻으로 estar del final은 쓰지 않습니다 ✗","para el: '~을 위해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G170","q":"No sé ____ viven en la cuarta planta.","o":["cuál","quién","qué","quiénes"],"a":3,"k":"의문사 quiénes","t":"누가 4층에 사는지 모르겠다.","e":"사람에 대해 '누구'를 물을 때는 quién(단수)/quiénes(복수)를 씁니다. 동사 viven이 3인칭 복수이므로 복수형 quiénes가 맞습니다. 간접의문문(No sé + 의문사)에서도 악센트를 유지합니다.","x":["cuál: '어느 것'이라는 뜻으로 사람 주어와 복수 동사에 맞지 않습니다 ✗","quién: 단수형이라 복수 동사 viven과 맞지 않습니다 ✗","qué: '무엇'이라는 뜻이라 사는 사람을 묻지 못합니다 ✗","quiénes: 복수의 '누구', viven과 일치 → 정답 ✓"]},{"id":"G171","q":"¿____ sois primas?","o":["Vos","Vuestras","Vosotros","Vosotras"],"a":3,"k":"주격 대명사 vosotras","t":"너희는 사촌 자매 사이니?","e":"sois는 ser의 2인칭 복수형으로 주어는 vosotros/vosotras(너희)입니다. primas(여자 사촌들)가 여성 복수이므로 여성형 vosotras가 맞습니다. vosotros 형태는 주로 스페인에서 쓰고, 중남미에서는 ustedes(son)를 씁니다.","x":["Vos: 중남미 일부의 '너(단수)'이며 sois와 맞지 않습니다 ✗","Vuestras: 소유형용사(너희의)라 주어 자리에 올 수 없습니다 ✗","Vosotros: 남성(또는 혼성) 복수라 primas와 성이 맞지 않습니다 ✗","Vosotras: 여성 복수 '너희' → 정답 ✓"]},{"id":"G172","q":"El bar de Mariano está en ____ esquina.","o":["la","ø","las","el"],"a":0,"k":"정관사 la","t":"마리아노의 바는 길모퉁이에 있다.","e":"esquina(길모퉁이)는 여성 단수 명사이므로 정관사 la를 씁니다. 'estar en la esquina'는 '모퉁이에 있다'라는 자주 쓰는 표현입니다.","x":["la: 여성 단수 정관사 → 정답 ✓","ø: 특정한 장소를 말할 때 관사가 필요합니다 ✗","las: 복수형이라 단수 esquina와 맞지 않습니다 ✗","el: 남성형이라 여성 명사 esquina와 맞지 않습니다 ✗"]},{"id":"G173","q":"¡Silencio! La profesora ____.","o":["está hablando","hablando","es hablando","habla"],"a":0,"k":"현재진행형","t":"조용! 선생님이 말씀하고 계셔.","e":"지금 이 순간 진행 중인 동작은 'estar + 현재분사(-ando/-iendo)'로 나타냅니다. 'está hablando'는 '말하고 있다'라는 뜻입니다. ser는 진행형을 만들 수 없습니다.","x":["está hablando: estar + 현재분사로 지금 진행 중인 동작 → 정답 ✓","hablando: estar 없이 현재분사만으로는 문장이 되지 않습니다 ✗","es hablando: 진행형은 ser가 아니라 estar로 만듭니다 ✗","habla: 문법적으로 가능하지만 '지금 말하는 중'을 강조하기엔 진행형이 더 자연스럽습니다 ✗"]},{"id":"G174","q":"Aquí ____ la revista que me pediste.","o":["es","hay","estás","está"],"a":3,"k":"aquí está","t":"여기 네가 부탁한 잡지가 있어.","e":"정해진 특정한 것(la revista: 그 잡지)의 위치를 말할 때는 estar를 씁니다. 'Aquí está ~'는 물건을 건네며 '여기 ~이 있어'라고 할 때 쓰는 표현입니다. hay는 정해지지 않은 것의 존재(un, una 등과 함께)를 말할 때 씁니다.","x":["es: ser는 위치를 나타내지 않습니다 ✗","hay: 정관사가 붙은 특정한 것에는 쓰지 않습니다 ✗","estás: 2인칭(너)형이라 주어 la revista와 맞지 않습니다 ✗","está: 특정한 것의 위치, 3인칭 단수 → 정답 ✓"]},{"id":"G175","q":"¿Cuánto tiempo hace que esperas ____ Luisa?","o":["por","a","de","ø"],"a":1,"k":"사람 목적어 앞 a","t":"루이사를 기다린 지 얼마나 됐어?","e":"동사의 직접목적어가 특정한 사람일 때는 앞에 전치사 a를 붙입니다(사람 목적어 표시 a). esperar(기다리다)는 목적어를 바로 받으므로 'esperar a Luisa'가 됩니다. 예: Veo a mi madre.(나는 어머니를 본다.)","x":["por: esperar por는 일부 중남미 구어에서 쓰지만 표준 표현은 아닙니다 ✗","a: 사람 직접목적어 앞의 a → 정답 ✓","de: esperar de는 '~에게 기대하다'라는 다른 뜻입니다 ✗","ø: 사람 목적어 앞에는 a를 생략하지 않습니다 ✗"]},{"id":"G176","q":"A mi chica y a mí ____ encantan las películas de terror.","o":["os","me","ø","nos"],"a":3,"k":"encantar 구문 nos","t":"내 여자친구와 나는 공포 영화를 아주 좋아한다.","e":"encantar(아주 좋아하다)는 gustar처럼 '좋아하는 사람'을 간접목적격 대명사로 씁니다. 'A mi chica y a mí(내 여자친구와 나에게)'는 '우리'이므로 nos가 맞습니다. 'a + 사람'이 있어도 대명사는 반드시 함께 씁니다.","x":["os: '너희에게'라는 뜻이라 맞지 않습니다 ✗","me: '나에게'만 가리키므로 여자친구가 빠집니다 ✗","ø: gustar류 동사는 간접목적격 대명사를 생략할 수 없습니다 ✗","nos: '우리에게' → 정답 ✓"]},{"id":"G177","q":"Ayer ____ un día fantástico.","o":["voy a tener","tiene","tuve","tengo"],"a":2,"k":"단순과거 tuve","t":"어제 나는 환상적인 하루를 보냈다.","e":"ayer(어제)처럼 끝난 과거 시점의 일은 단순과거(pretérito indefinido)로 씁니다. tener의 1인칭 단수 단순과거형은 불규칙형 tuve입니다. 'tener un día ~'는 '~한 하루를 보내다'라는 뜻입니다.","x":["voy a tener: 미래(~할 것이다)라서 ayer와 맞지 않습니다 ✗","tiene: 3인칭 현재형이라 시제가 맞지 않습니다 ✗","tuve: tener의 1인칭 단순과거 → 정답 ✓","tengo: 현재형이라 ayer와 맞지 않습니다 ✗"]},{"id":"G178","q":"¿Con ____ está hablando tu marido? —Con su hermano.","o":["qué","quién","que","quien"],"a":1,"k":"전치사 + quién","t":"네 남편은 누구랑 통화하고 있어? — 자기 형이랑.","e":"사람에 대해 '누구'를 물을 때는 의문사 quién을 쓰며 의문사에는 악센트가 있습니다. '누구와'는 con quién이 됩니다. 대답 'Con su hermano'에서 사람을 물었다는 것을 알 수 있습니다.","x":["qué: '무엇'이라 사람을 묻지 않습니다 ✗","quién: 사람을 묻는 의문사 → 정답 ✓","que: 악센트 없는 관계사/접속사라 의문문에 쓰지 않습니다 ✗","quien: 악센트 없는 관계대명사라 의문사가 아닙니다 ✗"]},{"id":"G179","q":"Todavía no conozco ____ novio de mi hija.","o":["al","a","ø","el"],"a":0,"k":"사람 목적어 a + el","t":"나는 아직 딸의 남자친구를 모른다.","e":"conocer(알다, 만나 보다)의 목적어가 특정한 사람이면 a를 붙입니다. a + el은 반드시 al로 축약되므로 'al novio'가 됩니다. 예: Conozco al director.(나는 교장 선생님을 안다.)","x":["al: 사람 목적어 표시 a + 정관사 el의 축약 → 정답 ✓","a: 관사 el이 빠져 '그 남자친구'를 나타내지 못합니다 ✗","ø: 사람 목적어 앞의 a가 빠졌습니다 ✗","el: 사람 목적어 표시 a가 빠졌습니다 ✗"]},{"id":"G180","q":"Quiero un helado ____ chocolate.","o":["de","en","por","a"],"a":0,"k":"재료·맛 de","t":"나는 초콜릿 아이스크림을 원해.","e":"맛이나 재료를 나타낼 때는 'de + 명사'를 씁니다: helado de chocolate(초콜릿 아이스크림), zumo de naranja(오렌지 주스). 이때 명사 앞에 관사를 넣지 않습니다.","x":["de: 맛·재료를 나타내는 de → 정답 ✓","en: '~안에'라는 뜻이라 맛을 나타내지 않습니다 ✗","por: '~때문에/~을 통해'라는 뜻이라 맞지 않습니다 ✗","a: helado a chocolate는 쓰지 않습니다(a la… 형식의 요리 이름과 혼동 주의) ✗"]},{"id":"G181","q":"Todavía no conozco ____ marido de Esperanza.","o":["un","al","a un","a"],"a":1,"k":"사람 목적어 al","t":"나는 아직 에스페란사의 남편을 모른다.","e":"conocer의 목적어가 특정한 사람(에스페란사의 남편)이므로 사람 목적어 표시 a가 필요합니다. 특정한 사람이라 정관사 el도 붙어 a + el = al이 됩니다. 'el marido de ~'는 '~의 남편'입니다.","x":["un: a가 빠졌고, 특정한 남편이라 부정관사는 어색합니다 ✗","al: a + el, 특정한 사람 목적어 → 정답 ✓","a un: '어떤 남편'이 되어 한 사람의 정해진 남편과 맞지 않습니다 ✗","a: 관사가 빠져 marido 앞에서 어색합니다 ✗"]},{"id":"G182","q":"¡Qué ____ habla español usted!","o":["bien","buen","buena","bueno"],"a":0,"k":"부사 bien","t":"당신 스페인어를 정말 잘하시네요!","e":"동사(habla: 말하다)를 꾸밀 때는 부사 bien(잘)을 씁니다. bueno/buena/buen은 명사를 꾸미는 형용사(좋은)입니다. '¡Qué bien + 동사!'는 '정말 잘 ~하는구나!'라는 감탄문입니다.","x":["bien: 동사를 꾸미는 부사(잘) → 정답 ✓","buen: 남성 단수 명사 앞의 형용사(좋은)라 동사를 꾸미지 못합니다 ✗","buena: 여성형 형용사라 동사를 꾸미지 못합니다 ✗","bueno: 남성형 형용사라 동사를 꾸미지 못합니다 ✗"]},{"id":"G183","q":"Nunca bebo ____ leche porque tengo intolerancia a la lactosa.","o":["el","ø","un","la"],"a":1,"k":"불가산명사 무관사","t":"나는 유당불내증이 있어서 우유를 절대 마시지 않는다.","e":"우유, 물, 커피처럼 셀 수 없는 물질을 '일반적으로' 먹거나 마신다고 할 때는 관사를 쓰지 않습니다. 'Nunca bebo leche'는 '(어떤) 우유도 마시지 않는다'라는 뜻입니다. 예: Bebo agua.(나는 물을 마신다.)","x":["el: 남성 관사이며 leche는 여성 명사입니다 ✗","ø: 불특정한 물질명사 앞에는 관사를 쓰지 않음 → 정답 ✓","un: 부정관사는 셀 수 있는 명사에 쓰며 leche와 성도 맞지 않습니다 ✗","la: '그 (특정한) 우유'가 되어 일반적인 습관을 말하는 문장과 맞지 않습니다 ✗"]},{"id":"G184","q":"Estas zapatillas de deporte cuestan ____ libras.","o":["doscientas","dos cien","doscientos","dos ciento"],"a":0,"k":"숫자 200 성 일치","t":"이 운동화는 200파운드이다.","e":"200~900의 백 단위 숫자는 뒤에 오는 명사의 성에 맞춥니다. libras(파운드, 여성 명사)이므로 doscientas가 됩니다. 한 단어로 붙여 쓰는 것도 기억하세요.","x":["doscientas: 여성형 200으로 libras와 일치 → 정답 ✓","dos cien: 존재하지 않는 형태입니다 ✗","doscientos: 남성형이라 여성 명사 libras와 맞지 않습니다 ✗","dos ciento: 존재하지 않는 형태입니다 ✗"]},{"id":"G185","q":"Mi bisabuela tiene ____ años.","o":["ciento y dos","cien dos","ciento dos","cien y dos"],"a":2,"k":"숫자 cien/ciento","t":"우리 증조할머니는 102살이시다.","e":"100은 단독으로 쓰거나 명사 바로 앞에서는 cien이지만, 뒤에 다른 숫자가 이어지면 ciento가 됩니다(101 ciento uno, 102 ciento dos). 백의 자리와 일의 자리 사이에는 y를 넣지 않습니다. y는 30 이상의 십의 자리와 일의 자리 사이에만 씁니다(treinta y dos).","x":["ciento y dos: 100과 2 사이에는 y를 넣지 않습니다 ✗","cien dos: 뒤에 숫자가 이어지면 ciento를 써야 합니다 ✗","ciento dos: 102의 올바른 형태 → 정답 ✓","cien y dos: cien 형태도, y도 틀렸습니다 ✗"]},{"id":"G186","q":"El hotel que te recomiendo está en ____ centro de Toledo.","o":["un","los","el","ø"],"a":2,"k":"en el centro","t":"내가 추천하는 호텔은 톨레도 중심가에 있다.","e":"'el centro de + 도시'는 '~의 중심가'라는 특정한 장소이므로 정관사 el을 씁니다. centro는 남성 단수 명사입니다.","x":["un: '어떤 중심'이 되어 하나뿐인 도심과 맞지 않습니다 ✗","los: 복수형이라 단수 centro와 맞지 않습니다 ✗","el: 남성 단수 정관사, 특정한 중심가 → 정답 ✓","ø: 이 경우 관사를 생략하지 않습니다 ✗"]},{"id":"G187","q":"____ tenés una casa muy linda.","o":["Vosotros","Tú","Vos","Ustedes"],"a":2,"k":"voseo 주어 vos","t":"너는 정말 예쁜 집을 가지고 있구나.","e":"tenés는 vos(너)에 쓰는 동사 형태입니다(voseo: 아르헨티나, 우루과이, 중미 일부 등에서 tú 대신 vos를 쓰는 현상). tú라면 tienes가 됩니다. linda(예쁜)도 중남미에서 많이 쓰는 표현입니다.","x":["Vosotros: 스페인의 '너희'이며 동사는 tenéis입니다 ✗","Tú: tú의 동사형은 tienes입니다 ✗","Vos: voseo 동사형 tenés와 일치 → 정답 ✓","Ustedes: '당신들/너희'이며 동사는 tienen입니다 ✗"]},{"id":"G188","q":"Me encantan ____ flores azules.","o":["esos","unos","las","los"],"a":2,"k":"정관사 일반 지칭","t":"나는 파란 꽃을 아주 좋아한다.","e":"gustar·encantar 구문에서 좋아하는 대상을 '그런 종류 전체'로 말할 때는 정관사를 씁니다. flores(꽃들)는 여성 복수이므로 las가 맞습니다. 예: Me gustan los perros.(나는 개를 좋아한다.)","x":["esos: 남성형이라 여성 명사 flores와 맞지 않습니다 ✗","unos: 남성형이며 '몇몇'이라는 뜻이라 일반적인 취향 표현에 맞지 않습니다 ✗","las: 여성 복수 정관사, 종류 전체를 가리킴 → 정답 ✓","los: 남성형이라 flores와 맞지 않습니다 ✗"]},{"id":"G189","q":"No me gusta ____ libro, es aburrido.","o":["esto","estos","el este","este"],"a":3,"k":"지시형용사 este","t":"이 책은 마음에 안 들어, 지루해.","e":"este(이)는 지시형용사로 명사 앞에 바로 오며 관사와 함께 쓰지 않습니다. libro(책)는 남성 단수라서 este가 맞습니다. esto는 중성 대명사(이것)로 명사 앞에 쓰지 않습니다.","x":["esto: 중성 대명사(이것)로 명사를 꾸미지 않습니다 ✗","estos: 복수형이라 단수 libro와 맞지 않습니다 ✗","el este: 관사와 지시형용사를 함께 쓸 수 없습니다 ✗","este: 남성 단수 지시형용사 → 정답 ✓"]},{"id":"G190","q":"No suelo pintarme ____ uñas.","o":["los","ø","mis","las"],"a":3,"k":"신체 부위 정관사","t":"나는 보통 손톱에 매니큐어를 칠하지 않는다.","e":"재귀동사(pintarse: 자기 몸에 칠하다)와 함께 신체 부위를 말할 때는 소유형용사(mis) 대신 정관사를 씁니다. 재귀대명사 me가 이미 '내 몸'임을 알려 주기 때문입니다. uñas(손톱)는 여성 복수이므로 las가 맞습니다.","x":["los: 남성형이라 여성 명사 uñas와 맞지 않습니다 ✗","ø: 신체 부위 앞에는 관사가 필요합니다 ✗","mis: 재귀동사와 함께 신체 부위에 소유형용사를 쓰지 않습니다 ✗","las: 신체 부위 앞 여성 복수 정관사 → 정답 ✓"]},{"id":"G191","q":"Tengo ____ prisa, no puedo hablar ahora.","o":["la","un","ø","una"],"a":2,"k":"tener prisa","t":"나 급해, 지금은 얘기 못 해.","e":"'tener prisa'는 '급하다, 서두르다'라는 관용 표현으로 관사 없이 씁니다. 같은 종류로 tener hambre(배고프다), tener frío(춥다), tener sueño(졸리다)가 있습니다. 강조할 때는 'tener mucha prisa'라고 합니다.","x":["la: 관용 표현 tener prisa에는 관사를 쓰지 않습니다 ✗","un: 관사를 쓰지 않으며 prisa는 여성 명사입니다 ✗","ø: tener prisa(급하다) → 정답 ✓","una: 관용 표현에 부정관사를 넣지 않습니다 ✗"]},{"id":"G192","q":"Vos ____ muy bien italiano.","o":["habla","habláis","hablas","hablás"],"a":3,"k":"voseo 동사형","t":"너는 이탈리아어를 아주 잘하는구나.","e":"vos의 현재형은 동사원형에서 -r를 빼고 마지막 모음에 악센트를 붙인 형태입니다: hablar → hablás, comer → comés, vivir → vivís. 그래서 'Vos hablás'가 맞습니다. 이 voseo는 아르헨티나·우루과이 등에서 씁니다.","x":["habla: 3인칭 단수(él/usted)형입니다 ✗","habláis: vosotros(너희)형입니다 ✗","hablas: tú형이라 vos와 맞지 않습니다 ✗","hablás: vos의 현재형 → 정답 ✓"]},{"id":"G193","q":"Ponte el abrigo antes de salir, ____ mucho frío ahí fuera.","o":["hay","es","hace","está"],"a":2,"k":"날씨 hacer","t":"나가기 전에 외투 입어, 밖은 아주 추워.","e":"날씨를 말할 때는 hacer의 3인칭 단수 hace를 씁니다: hace frío(춥다), hace calor(덥다), hace sol(해가 난다). 'mucho frío'처럼 명사 frío를 꾸밀 때는 mucho를 씁니다.","x":["hay: '~이 있다'라는 뜻으로 hay frío는 표준 날씨 표현이 아닙니다 ✗","es: ser로 날씨를 표현하지 않습니다 ✗","hace: 날씨 표현 hace frío → 정답 ✓","está: está frío는 '(물건이) 차갑다'라는 뜻이라 날씨 표현이 아닙니다 ✗"]},{"id":"G194","q":"La cerveza me gusta menos ____ vino.","o":["que el","que","a que","de que"],"a":0,"k":"비교급 menos que","t":"나는 맥주를 와인보다 덜 좋아한다.","e":"비교급 'más/menos ~ que'에서 비교 대상 앞에는 que를 씁니다. 맥주(la cerveza)와 비교하는 대상도 일반적인 와인 전체이므로 정관사를 붙여 'que el vino'가 됩니다. 예: Me gusta más el té que el café.","x":["que el: 비교의 que + 일반 지칭 정관사 el → 정답 ✓","que: 관사가 빠져 la cerveza와 균형이 맞지 않습니다 ✗","a que: 비교급에 a를 넣지 않습니다 ✗","de que: 비교급 뒤에 de que는 쓰지 않습니다 ✗"]},{"id":"G195","q":"____ año que viene voy a viajar a Egipto.","o":["El","La","Los","Un"],"a":0,"k":"año que viene","t":"내년에 나는 이집트로 여행 갈 거야.","e":"'el año que viene'는 '내년'(직역: 오는 해)이라는 표현입니다. año(해)는 남성 단수 명사이므로 정관사 el을 씁니다. 같은 뜻으로 'el próximo año'도 있습니다.","x":["El: 남성 단수 정관사 → 정답 ✓","La: 여성형이라 남성 명사 año와 맞지 않습니다 ✗","Los: 복수형이라 단수 año와 맞지 않습니다 ✗","Un: '어떤 해'가 되어 '내년'이라는 정해진 때와 맞지 않습니다 ✗"]},{"id":"G196","q":"Carlos es ____ mecánico, tiene un taller cerca de su casa.","o":["un","una","uno","ø"],"a":3,"k":"직업 앞 무관사","t":"카를로스는 정비공이고, 집 근처에 정비소가 있다.","e":"'ser + 직업'으로 누군가의 직업을 말할 때는 관사를 쓰지 않습니다: Es mecánico(그는 정비공이다). 단, 형용사가 붙으면 관사를 씁니다: Es un mecánico excelente.","x":["un: 직업을 소개할 때 부정관사를 쓰지 않습니다 ✗","una: 여성형이며 관사도 불필요합니다 ✗","uno: 대명사(하나)라 명사 앞에 오지 않습니다 ✗","ø: ser + 직업은 관사 없이 → 정답 ✓"]},{"id":"G197","q":"Beatriz quiere aprender ____ bailar bachata.","o":["ø","en","de","a"],"a":3,"k":"aprender a + 동사","t":"베아트리스는 바차타 춤을 배우고 싶어 한다.","e":"aprender(배우다) 뒤에 동사원형이 올 때는 전치사 a를 넣어 'aprender a + 동사원형'으로 씁니다. 예: Aprendo a nadar.(나는 수영을 배운다.) 같은 패턴으로 empezar a(~하기 시작하다), enseñar a(~하는 법을 가르치다)가 있습니다.","x":["ø: aprender 뒤 동사원형 앞에는 a가 필요합니다 ✗","en: aprender en은 장소를 나타낼 때만 씁니다 ✗","de: aprender de는 '~로부터 배우다'라는 뜻입니다 ✗","a: aprender a + 동사원형 → 정답 ✓"]},{"id":"G198","q":"Hoy ____ sábado.","o":["está","es","tiene","hay"],"a":1,"k":"요일 ser","t":"오늘은 토요일이다.","e":"요일이나 날짜를 말할 때는 ser를 씁니다: Hoy es sábado(오늘은 토요일이다). 이때 요일 앞에 관사를 쓰지 않습니다. 참고로 'Estamos a sábado'라는 표현도 있지만 형태가 다릅니다.","x":["está: estar로 요일을 말하지 않습니다 ✗","es: 요일·날짜는 ser → 정답 ✓","tiene: '가지고 있다'라는 뜻이라 맞지 않습니다 ✗","hay: '~이 있다'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G199","q":"En ____ región apenas llueve en verano.","o":["esta","ese","aquel","este"],"a":0,"k":"지시형용사 성 일치","t":"이 지역에는 여름에 비가 거의 오지 않는다.","e":"región(지역)은 -ión으로 끝나는 여성 명사입니다. 그래서 여성형 지시형용사 esta(이)를 씁니다. -ción, -sión, -ión으로 끝나는 명사는 대부분 여성입니다.","x":["esta: 여성 단수 '이' → 정답 ✓","ese: 남성형이라 여성 명사 región과 맞지 않습니다 ✗","aquel: 남성형이라 región과 맞지 않습니다 ✗","este: 남성형이라 región과 맞지 않습니다 ✗"]},{"id":"G200","q":"Tengo ____ problemas. ¡Estoy harto!","o":["bastante","muchos","tantas","demasiado"],"a":1,"k":"수량 형용사 muchos","t":"나는 문제가 많아. 지긋지긋해!","e":"수량을 나타내는 형용사는 명사의 성·수에 맞춥니다. problema는 -a로 끝나지만 남성 명사이므로(el problema) 남성 복수 muchos가 맞습니다. -ma로 끝나는 그리스어 계열 명사(problema, tema, sistema)는 남성이라는 점을 기억하세요.","x":["bastante: 단수형이라 복수 problemas 앞에서는 bastantes가 되어야 합니다 ✗","muchos: 남성 복수 '많은' → 정답 ✓","tantas: 여성형이라 남성 명사 problemas와 맞지 않습니다 ✗","demasiado: 단수형이라 복수 앞에서는 demasiados가 되어야 합니다 ✗"]},{"id":"G201","q":"Mónica está ____ cocinera en un restaurante mexicano.","o":["ø","de","en","a"],"a":1,"k":"estar de + 직업","t":"모니카는 멕시코 식당에서 요리사로 일하고 있다.","e":"'estar de + 직업'은 '(임시로) ~로 일하고 있다'라는 표현입니다. ser cocinera가 직업 자체를 말한다면, estar de cocinera는 현재 맡고 있는 일을 강조합니다. 이때 관사를 쓰지 않습니다.","x":["ø: estar cocinera는 문법적으로 성립하지 않습니다 ✗","de: estar de + 직업(~로 일하는 중) → 정답 ✓","en: estar en은 장소를 나타냅니다 ✗","a: estar a + 직업이라는 표현은 없습니다 ✗"]},{"id":"G202","q":"No me gustan ____ las personas cotillas.","o":["algo","nadie","algunas","nada"],"a":3,"k":"no ~ nada 강조","t":"나는 남의 얘기하기 좋아하는 사람들이 정말 싫다.","e":"'No me gusta(n) nada'는 '전혀 좋아하지 않는다'는 강한 부정입니다. 여기서 nada는 '아무것도'가 아니라 '전혀'라는 부사로 쓰였습니다. cotilla는 '남의 소문을 즐기는 사람'이란 뜻의 스페인 구어입니다.","x":["algo: '조금, 어느 정도'라는 뜻으로 no와 함께 쓰지 않습니다 ✗","nadie: '아무도'라는 대명사라 이 자리에 맞지 않습니다 ✗","algunas: '몇몇의'라는 뜻이라 las와 함께 쓸 수 없습니다 ✗","nada: no와 함께 '전혀' → 정답 ✓"]},{"id":"G203","q":"Jorge ____ por la noche.","o":["me ducho","se duchan","se ducha","ducha"],"a":2,"k":"재귀동사 ducharse","t":"호르헤는 밤에 샤워한다.","e":"ducharse(샤워하다)는 재귀동사(자기 자신에게 하는 동작)라서 재귀대명사가 필요합니다. 주어 Jorge는 3인칭 단수이므로 se ducha가 됩니다. 재귀대명사: me, te, se, nos, os, se.","x":["me ducho: 1인칭(나) 형태라 Jorge와 맞지 않습니다 ✗","se duchan: 3인칭 복수형이라 한 사람인 Jorge와 맞지 않습니다 ✗","se ducha: 3인칭 단수 재귀동사 → 정답 ✓","ducha: 재귀대명사가 없어 '누군가를 씻기다'라는 뜻이 됩니다 ✗"]},{"id":"G204","q":"Ese es ____ gimnasio al que voy actualmente.","o":["lo","el","ø","al"],"a":1,"k":"정관사 + 관계절","t":"그곳이 내가 요즘 다니는 헬스장이다.","e":"관계절(al que voy: 내가 다니는)이 꾸며 주어 특정해진 명사 앞에는 정관사를 씁니다. gimnasio(헬스장)는 남성 단수이므로 el이 맞습니다.","x":["lo: 중성 관사라 남성 명사 앞에 쓰지 않습니다 ✗","el: 남성 단수 정관사, 특정한 헬스장 → 정답 ✓","ø: 특정한 장소를 가리키므로 관사가 필요합니다 ✗","al: a + el로 ser 뒤에 쓰면 문장이 성립하지 않습니다 ✗"]},{"id":"G205","q":"Ayer conocí a una persona ____ 95 años.","o":["desde","de","en","a"],"a":1,"k":"나이 de","t":"어제 나는 95살인 사람을 알게 되었다.","e":"사람이나 사물의 나이·특징을 명사 뒤에서 나타낼 때는 'de + 숫자 + años'를 씁니다: una persona de 95 años(95세인 사람). 예: un niño de cinco años(다섯 살 아이).","x":["desde: '~부터'라는 뜻이라 나이를 나타내지 않습니다 ✗","de: 명사 뒤에서 나이를 나타내는 de → 정답 ✓","en: '~에'라는 뜻이라 나이 표현이 되지 않습니다 ✗","a: '~에게/~로'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G206","q":"Mi familia vive ____ centro de la ciudad.","o":["en el","en","a","al"],"a":0,"k":"en el centro","t":"우리 가족은 시내 중심가에 산다.","e":"vivir en(~에 살다) 뒤에 특정한 장소 'el centro de la ciudad(도시의 중심)'가 오므로 en el centro가 됩니다. centro는 남성 단수 명사입니다.","x":["en el: 장소 전치사 en + 정관사 el → 정답 ✓","en: 관사가 빠져 어색합니다 ✗","a: '~로'라는 방향 전치사라 vivir와 쓰지 않습니다 ✗","al: a + el로 방향을 나타내므로 '사는 곳'에 맞지 않습니다 ✗"]},{"id":"G207","q":"Me considero ____ una persona sana.","o":["de","a","ø","en"],"a":2,"k":"considerarse","t":"나는 스스로 건강한 사람이라고 생각한다.","e":"'considerarse + 명사/형용사'는 '자신을 ~라고 여기다'라는 뜻으로 전치사 없이 바로 씁니다. 예: Me considero feliz.(나는 내가 행복하다고 생각한다.) sano/sana는 '건강한'입니다.","x":["de: considerarse 뒤에 de를 넣지 않습니다 ✗","a: considerarse 뒤에 a를 넣지 않습니다 ✗","ø: 전치사 없이 바로 명사 → 정답 ✓","en: considerarse 뒤에 en을 넣지 않습니다 ✗"]},{"id":"G208","q":"Almudena ____ mucho por trabajo.","o":["viajo","viaje","viaja","viajan"],"a":2,"k":"현재형 3인칭 단수","t":"알무데나는 일 때문에 출장을 많이 다닌다.","e":"주어 Almudena는 한 사람(3인칭 단수)이므로 viajar(여행하다)의 3인칭 단수 현재형 viaja를 씁니다. 'por trabajo'는 '일 때문에'라는 이유를 나타냅니다.","x":["viajo: 1인칭 단수(나)형입니다 ✗","viaje: 접속법 현재형이라 평서문에 맞지 않습니다 ✗","viaja: 3인칭 단수 현재형 → 정답 ✓","viajan: 3인칭 복수형이라 한 사람 주어와 맞지 않습니다 ✗"]},{"id":"G209","q":"En esa librería hay ____ libros de historia muy buenos.","o":["unos","algún","los","algo"],"a":0,"k":"hay + 부정관사","t":"그 서점에는 아주 좋은 역사책들이 있다.","e":"hay(~이 있다)는 처음 소개하는 불특정한 것에 쓰므로 정관사(el, los)와 함께 쓰지 않고 부정관사(un, unos)나 무관사를 씁니다. libros는 남성 복수이므로 unos(몇몇의)가 맞습니다.","x":["unos: 남성 복수 부정관사, hay와 함께 씀 → 정답 ✓","algún: 단수형이라 복수 libros와 맞지 않습니다 ✗","los: 정관사는 hay와 함께 쓰지 않습니다 ✗","algo: '무언가'라는 대명사라 명사 앞에 오지 않습니다 ✗"]},{"id":"G210","q":"Me gustaría ____ a Sudamérica.","o":["ir","de ir","por ir","a ir"],"a":0,"k":"gustaría + 동사원형","t":"나는 남미에 가 보고 싶다.","e":"'Me gustaría + 동사원형'은 '~하고 싶다'라는 공손한 바람 표현입니다. gustar 뒤에는 전치사 없이 바로 동사원형이 옵니다. 'ir a + 장소'에서 a는 이미 Sudamérica 앞에 있습니다.","x":["ir: gustaría 뒤에 바로 동사원형 → 정답 ✓","de ir: gustaría 뒤에 de를 넣지 않습니다 ✗","por ir: por를 넣으면 '가기 때문에'처럼 뜻이 어색해집니다 ✗","a ir: gustaría 뒤에 a를 넣지 않습니다 ✗"]},{"id":"G211","q":"Mis abuelos ____ por todo el mundo.","o":["viajando","han viajado","ha viajado","hemos viajado"],"a":1,"k":"현재완료","t":"우리 조부모님은 전 세계를 여행하셨다.","e":"현재완료는 'haber 현재형 + 과거분사'로 만들며, 지금까지의 경험을 말할 때 씁니다. 주어 mis abuelos(우리 조부모님)는 3인칭 복수이므로 han viajado가 맞습니다. haber 현재형: he, has, ha, hemos, habéis, han.","x":["viajando: 현재분사만으로는 문장의 동사가 될 수 없습니다 ✗","han viajado: 3인칭 복수 현재완료 → 정답 ✓","ha viajado: 3인칭 단수형이라 복수 주어와 맞지 않습니다 ✗","hemos viajado: 1인칭 복수(우리)형이라 맞지 않습니다 ✗"]},{"id":"G212","q":"____ champú es buenísimo para mi pelo.","o":["Esta","Esa","Este","Eso"],"a":2,"k":"지시형용사 este","t":"이 샴푸는 내 머리카락에 아주 좋다.","e":"champú(샴푸)는 남성 단수 명사이므로 남성형 지시형용사 este(이)를 씁니다. eso는 중성 대명사(그것)로 명사 앞에 오지 않습니다. buenísimo는 bueno의 최상급 표현(아주 좋은)입니다.","x":["Esta: 여성형이라 남성 명사 champú와 맞지 않습니다 ✗","Esa: 여성형이라 champú와 맞지 않습니다 ✗","Este: 남성 단수 '이' → 정답 ✓","Eso: 중성 대명사라 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G213","q":"Están contentos porque están ____ vacaciones.","o":["en","por","a","de"],"a":3,"k":"de vacaciones","t":"그들은 휴가 중이라서 기분이 좋다.","e":"'estar de vacaciones'는 '휴가 중이다'라는 고정 표현입니다. 'estar de + 명사'는 일시적인 상황을 나타냅니다: estar de viaje(여행 중이다), estar de buen humor(기분이 좋다). '휴가를 가다'는 'irse de vacaciones'입니다.","x":["en: estar en vacaciones는 일부 중남미에서 들리지만 표준 표현은 아닙니다 ✗","por: estar por vacaciones는 쓰지 않습니다 ✗","a: estar a vacaciones는 쓰지 않습니다 ✗","de: estar de vacaciones(휴가 중) → 정답 ✓"]},{"id":"G214","q":"Son muy amables, gracias por ____.","o":["ayudar me","ayudar a mí","me ayudar","ayudarme"],"a":3,"k":"동사원형 + 대명사","t":"정말 친절하시네요, 도와주셔서 감사합니다.","e":"목적격 대명사는 동사원형 뒤에 올 때 반드시 붙여 씁니다: ayudar + me = ayudarme(나를 돕다). 'gracias por + 동사원형'은 '~해 줘서 고마워'라는 뜻입니다.","x":["ayudar me: 대명사를 동사원형과 띄어 쓰면 틀립니다 ✗","ayudar a mí: 목적어를 대명사 me 없이 a mí만으로 쓰지 않습니다 ✗","me ayudar: 동사원형 앞에 대명사를 둘 수 없습니다 ✗","ayudarme: 동사원형에 대명사를 붙여 씀 → 정답 ✓"]},{"id":"G215","q":"Esperamos que vengas a ____ pronto.","o":["visitar nos","visitas nos","nos visitas","visitarnos"],"a":3,"k":"동사원형 + 대명사","t":"네가 곧 우리를 찾아오길 바라.","e":"전치사(a) 뒤에는 동사원형이 오고, 목적격 대명사 nos(우리를)는 동사원형 끝에 붙입니다: visitarnos. 'venir a + 동사원형'은 '~하러 오다'라는 뜻입니다. Esperamos que vengas에서 vengas는 바람을 나타내는 접속법입니다.","x":["visitar nos: 띄어 쓰면 틀립니다 ✗","visitas nos: 활용된 동사 뒤에 대명사를 붙이지 않으며 전치사 뒤엔 동사원형이 와야 합니다 ✗","nos visitas: 전치사 a 뒤에는 활용된 동사가 올 수 없습니다 ✗","visitarnos: 동사원형 + nos 붙여 씀 → 정답 ✓"]},{"id":"G216","q":"La conferencia va a comenzar ____ una en punto.","o":["a las","a la","al","a"],"a":1,"k":"시각 a la una","t":"강연은 정각 1시에 시작할 것이다.","e":"'~시에'는 'a + 정관사 + 시각'으로 씁니다. 1시는 단수이므로 a la una, 2시 이후는 a las dos처럼 복수입니다. en punto는 '정각'이라는 뜻입니다.","x":["a las: 복수형이라 1시(una)와 맞지 않습니다 ✗","a la: 1시는 단수 a la una → 정답 ✓","al: 남성형이라 시각에 쓰지 않습니다(시각은 여성형) ✗","a: 시각 앞에는 관사가 필요합니다 ✗"]},{"id":"G217","q":"¿____ está Argentina? —En América del Sur.","o":["Cómo","Cuándo","Dónde","Por qué"],"a":2,"k":"의문사 dónde","t":"아르헨티나는 어디에 있어? — 남아메리카에.","e":"장소·위치를 물을 때는 '¿Dónde está ~?(~은 어디에 있니?)'를 씁니다. 대답 'En América del Sur'가 장소이므로 dónde가 맞습니다.","x":["Cómo: '어떻게'라서 위치를 묻지 않습니다 ✗","Cuándo: '언제'라서 맞지 않습니다 ✗","Dónde: '어디' → 정답 ✓","Por qué: '왜'라서 맞지 않습니다 ✗"]},{"id":"G218","q":"____ mucho que estés enferma.","o":["Me siento","Estoy sintiéndome","Te siento","Siento"],"a":3,"k":"sentir que","t":"네가 아프다니 정말 안타까워.","e":"'Siento (mucho) que + 접속법'은 '~해서 (정말) 유감이다/안타깝다'라는 표현입니다. 여기서 sentir는 재귀형이 아닌 '유감으로 생각하다'라는 뜻입니다. 재귀형 sentirse는 '(기분·몸 상태가) ~하다'라는 뜻입니다: Me siento mal.","x":["Me siento: sentirse는 '~한 기분이다'라는 뜻이라 que절과 맞지 않습니다 ✗","Estoy sintiéndome: 진행형 재귀형이라 의미가 맞지 않습니다 ✗","Te siento: '너를 느낀다'라는 뜻이 되어 어색합니다 ✗","Siento: '유감이다'라는 sentir → 정답 ✓"]},{"id":"G219","q":"Isaac está estudiando ____ Comunicación Audiovisual en Madrid.","o":["una","de","ø","la"],"a":2,"k":"학과명 무관사","t":"이삭은 마드리드에서 시청각 커뮤니케이션을 전공하고 있다.","e":"'estudiar + 학과/과목'은 관사 없이 씁니다: estudiar Medicina(의학을 공부하다), estudiar Derecho(법학을 공부하다). 학과 이름은 대문자로 시작하는 경우가 많습니다.","x":["una: 학과명 앞에 부정관사를 쓰지 않습니다 ✗","de: estudiar de는 쓰지 않습니다 ✗","ø: estudiar + 학과명 관사 없이 → 정답 ✓","la: 학과명을 말할 때 정관사를 쓰지 않습니다 ✗"]},{"id":"G220","q":"Todavía no sé ____ me va a acompañar al baile.","o":["quién","qué","quiénes","a quién"],"a":0,"k":"간접의문 quién","t":"누가 나와 함께 무도회에 갈지 아직 모르겠다.","e":"'누가'를 묻는 간접의문문에는 quién을 씁니다. 동사 va가 3인칭 단수이므로 단수형 quién이 맞습니다. me(나를)가 목적어이고 quién이 주어입니다.","x":["quién: 주어 '누가', 단수 동사 va와 일치 → 정답 ✓","qué: '무엇'이라 사람에게 쓰지 않습니다 ✗","quiénes: 복수형이라 단수 동사 va와 맞지 않습니다 ✗","a quién: '누구를'이 되어 주어 자리에 맞지 않습니다 ✗"]},{"id":"G221","q":"Andrés trabaja ____ la noche.","o":["por","de","con","entre"],"a":0,"k":"por la noche","t":"안드레스는 밤에 일한다.","e":"하루의 시간대를 말할 때는 por la noche(밤에), por la mañana(아침에)처럼 por를 씁니다. 관사 없이 'de noche(밤에)'라고도 하지만 'de la noche'는 시각 뒤에만 씁니다(a las 10 de la noche).","x":["por: 시간대 표현 por la noche → 정답 ✓","de: de la noche는 시각과 함께만 씁니다 ✗","con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗","entre: '~사이에'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G222","q":"Usted ____ esperar su turno.","o":["debe","debo","debes","deben"],"a":0,"k":"deber usted형","t":"당신은 차례를 기다려야 합니다.","e":"'deber + 동사원형'은 '~해야 한다'라는 의무 표현입니다. usted(당신)는 3인칭 단수 동사를 쓰므로 debe가 맞습니다.","x":["debe: usted에 맞는 3인칭 단수 → 정답 ✓","debo: 1인칭(나)형입니다 ✗","debes: tú(너)형이라 usted와 맞지 않습니다 ✗","deben: ustedes(당신들)형입니다 ✗"]},{"id":"G223","q":"¿____ te apetece cenar esta noche?","o":["Qué","A qué","En qué","De qué"],"a":0,"k":"apetecer 구문","t":"오늘 밤에 뭐 먹고 싶어?","e":"apetecer(~하고 싶다, 당기다)는 gustar처럼 쓰는 동사로, te는 '원하는 사람'이고 원하는 것이 주어입니다. '무엇을 먹고 싶은지' 묻는 것이므로 qué를 전치사 없이 씁니다. 이 동사는 주로 스페인에서 쓰고, 중남미에서는 '¿Qué quieres cenar?'가 더 흔합니다.","x":["Qué: '무엇을' → 정답 ✓","A qué: '무엇에게/어디에'가 되어 맞지 않습니다 ✗","En qué: '무엇 안에서/무엇에 대해'라는 뜻이라 맞지 않습니다 ✗","De qué: '무엇에 대해/무엇으로'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G224","q":"Debemos lavarnos las manos ____ comer.","o":["antes de","antes","desde antes","de antes"],"a":0,"k":"antes de + 동사","t":"우리는 먹기 전에 손을 씻어야 한다.","e":"'antes de + 동사원형'은 '~하기 전에'라는 뜻입니다. 반대는 'después de + 동사원형(~한 후에)'입니다. de를 빼면 안 됩니다.","x":["antes de: ~하기 전에 → 정답 ✓","antes: 뒤에 동사원형이 올 때는 de가 필요합니다 ✗","desde antes: '전부터'라는 뜻이라 맞지 않습니다 ✗","de antes: '예전의'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G225","q":"¿____ qué supermercado sueles hacer la compra?","o":["En","A","Por","Hasta"],"a":0,"k":"전치사 + qué","t":"너는 보통 어느 슈퍼마켓에서 장을 보니?","e":"'~에서 장을 보다'처럼 장소를 나타낼 때는 en을 쓰므로, 의문문에서는 전치사를 의문사 앞으로 옮겨 '¿En qué supermercado…?'가 됩니다. soler + 동사원형은 '보통 ~하다'라는 뜻입니다.","x":["En: 장소 '~에서', en qué(어느 ~에서) → 정답 ✓","A: '~로'라는 방향이라 장 보는 장소에 맞지 않습니다 ✗","Por: '~을 통해/근처에서'라는 뜻이라 맞지 않습니다 ✗","Hasta: '~까지'라서 맞지 않습니다 ✗"]},{"id":"G226","q":"Estoy cansado de ____ en una gran ciudad.","o":["viviendo","vivo","vivir","vivido"],"a":2,"k":"전치사 + 동사원형","t":"나는 대도시에 사는 게 지겹다.","e":"전치사(de) 뒤에 동사가 올 때는 항상 동사원형을 씁니다. 'estar cansado de + 동사원형'은 '~하는 데 지쳤다/질렸다'라는 뜻입니다. 영어처럼 -ing(현재분사)를 쓰지 않도록 주의하세요.","x":["viviendo: 전치사 뒤에 현재분사를 쓰지 않습니다 ✗","vivo: 활용된 동사는 전치사 뒤에 올 수 없습니다 ✗","vivir: 전치사 뒤 동사원형 → 정답 ✓","vivido: 과거분사라 이 자리에 맞지 않습니다 ✗"]},{"id":"G227","q":"Albert vive en un pueblo ____ Cataluña.","o":["de","a","a la","de la"],"a":0,"k":"소속 de","t":"알베르트는 카탈루냐의 한 마을에 산다.","e":"'un pueblo de + 지역'은 '~의(~에 속한) 마을'이라는 뜻으로 소속을 나타냅니다. Cataluña 같은 지명에는 보통 관사를 붙이지 않으므로 de만 씁니다.","x":["de: 소속을 나타내는 '~의' → 정답 ✓","a: '~로'라는 방향이라 맞지 않습니다 ✗","a la: 방향 전치사이며 지명 앞 관사도 불필요합니다 ✗","de la: Cataluña 앞에는 관사를 붙이지 않습니다 ✗"]},{"id":"G228","q":"Niños, ____ aquí ahora mismo.","o":["ven","venid","viene","vienes"],"a":1,"k":"긍정명령 vosotros","t":"얘들아, 지금 당장 여기로 와.","e":"Niños(얘들아)처럼 여러 명에게 친근하게 명령할 때는 vosotros 긍정명령형을 씁니다. 동사원형의 -r을 -d로 바꾸면 됩니다: venir → venid, hablar → hablad. 중남미에서는 ustedes 명령형 vengan을 씁니다.","x":["ven: tú(너 한 명)에 대한 명령형이라 복수 Niños와 맞지 않습니다 ✗","venid: vosotros 긍정명령형 → 정답 ✓","viene: 3인칭 현재형이라 명령이 아닙니다 ✗","vienes: tú 현재형이라 명령문이 아닙니다 ✗"]},{"id":"G229","q":"Nunca he ____ en Valencia.","o":["estoy","estado","estar","estando"],"a":1,"k":"현재완료 과거분사","t":"나는 발렌시아에 한 번도 가 본 적이 없다.","e":"현재완료는 'haber + 과거분사'로 만듭니다. estar의 과거분사는 estado이므로 'he estado'가 됩니다. 'estar en + 장소'의 현재완료는 '~에 가 본 적이 있다'라는 경험을 나타냅니다.","x":["estoy: 현재형이라 haber 뒤에 올 수 없습니다 ✗","estado: estar의 과거분사 → 정답 ✓","estar: 동사원형이라 haber 뒤에 올 수 없습니다 ✗","estando: 현재분사라 완료형을 만들지 못합니다 ✗"]},{"id":"G230","q":"La estación del año que más me gusta es ____ primavera.","o":["la","uno","una","el"],"a":0,"k":"계절 정관사","t":"내가 가장 좋아하는 계절은 봄이다.","e":"계절 이름 앞에는 보통 정관사를 씁니다: la primavera(봄), el verano(여름), el otoño(가을), el invierno(겨울). primavera는 여성 명사이므로 la입니다.","x":["la: 여성 단수 정관사 → 정답 ✓","uno: 대명사(하나)라 명사 앞에 오지 않습니다 ✗","una: '어떤 봄'이 되어 의미가 맞지 않습니다 ✗","el: 남성형이라 여성 명사 primavera와 맞지 않습니다 ✗"]},{"id":"G231","q":"Quiero comprar una mesa ____ madera para el salón.","o":["a","con","ø","de"],"a":3,"k":"재료 de","t":"나는 거실에 둘 나무 탁자를 사고 싶다.","e":"물건의 재료를 나타낼 때는 'de + 재료'를 관사 없이 씁니다: mesa de madera(나무 탁자), anillo de oro(금반지). 같은 문장의 para el salón은 '거실용으로'라는 목적을 나타냅니다.","x":["a: 재료를 나타내지 않습니다 ✗","con: '~이 달린'이라는 뜻이라 재료 표현이 아닙니다 ✗","ø: 재료 앞에 de가 필요합니다 ✗","de: 재료를 나타내는 de → 정답 ✓"]},{"id":"G232","q":"No puedo abrir la puerta, no encuentro ____ llaves.","o":["el","las","la","los"],"a":1,"k":"정관사 las","t":"문을 열 수가 없어, 열쇠를 못 찾겠어.","e":"llaves(열쇠들)는 여성 복수 명사이므로 정관사 las를 씁니다. 대화하는 사람이 알고 있는 특정한 열쇠라서 정관사가 필요합니다. 단수형은 la llave입니다.","x":["el: 남성 단수형이라 맞지 않습니다 ✗","las: 여성 복수 정관사 → 정답 ✓","la: 단수형이라 복수 llaves와 맞지 않습니다 ✗","los: 남성형이라 여성 명사 llaves와 맞지 않습니다 ✗"]},{"id":"G233","q":"Alfonso ____ rico, tiene muchísimo dinero.","o":["están","es","está","son"],"a":1,"k":"ser vs estar","t":"알폰소는 부자다, 돈이 엄청 많다.","e":"부유함처럼 사람의 특징이나 지속적인 성질을 말할 때는 ser를 씁니다: Es rico(그는 부자다). 'estar rico'는 음식에 대해 '맛있다'라는 다른 뜻이 되니 주의하세요. 주어 Alfonso는 3인칭 단수입니다.","x":["están: 3인칭 복수이며 estar라서 맞지 않습니다 ✗","es: ser 3인칭 단수, 특징을 나타냄 → 정답 ✓","está: estar rico는 '맛있다'라는 뜻이 됩니다 ✗","son: 3인칭 복수형이라 한 사람 주어와 맞지 않습니다 ✗"]},{"id":"G234","q":"Podemos ir a pie al centro comercial. Está aquí ____ lado.","o":["al","a","en","lo"],"a":0,"k":"al lado","t":"쇼핑센터까지 걸어서 갈 수 있어. 바로 옆에 있거든.","e":"'al lado(옆에)'는 위치를 나타내는 표현이며, 'aquí al lado'는 '바로 이 근처에'라는 뜻입니다. '~의 옆에'는 'al lado de ~'로 씁니다. 예: Al lado del banco hay una farmacia.","x":["al: al lado(옆에) → 정답 ✓","a: 관사가 빠져 a lado가 되면 틀린 표현입니다 ✗","en: en lado는 쓰지 않습니다 ✗","lo: lo lado는 존재하지 않는 표현입니다 ✗"]},{"id":"G235","q":"____ no tiene razón.","o":["Usted","Vosotros","Tú","Vos"],"a":0,"k":"주어와 동사 일치","t":"당신은 틀렸습니다.","e":"동사 tiene는 3인칭 단수형이므로 주어는 usted(당신)여야 합니다. 'tener razón'은 '옳다', 'no tener razón'은 '틀렸다'라는 표현입니다.","x":["Usted: 3인칭 단수 동사 tiene와 일치 → 정답 ✓","Vosotros: 동사가 tenéis여야 합니다 ✗","Tú: 동사가 tienes여야 합니다 ✗","Vos: 동사가 tenés여야 합니다(voseo) ✗"]},{"id":"G236","q":"Por la noche prefiero ____ en casa viendo una buena película.","o":["quedo","me quedo","quedarme","quedar"],"a":2,"k":"preferir + 동사원형","t":"밤에는 집에서 좋은 영화를 보며 있는 게 더 좋다.","e":"preferir(~을 더 좋아하다) 뒤에 동사가 오면 동사원형을 씁니다. quedarse(머무르다)는 재귀동사이므로 원형에 대명사를 붙여 quedarme(내가 머무르다)가 됩니다. quedar만 쓰면 '약속하다, 남다'라는 다른 뜻이 됩니다.","x":["quedo: 활용된 동사라 preferir 뒤에 올 수 없습니다 ✗","me quedo: 활용형이라 동사원형 자리에 맞지 않습니다 ✗","quedarme: 재귀동사 원형 + me → 정답 ✓","quedar: 재귀대명사가 없어 '머무르다'라는 뜻이 되지 않습니다 ✗"]},{"id":"G237","q":"Jaime es ____ profesor de química.","o":["uno","ø","un","de"],"a":1,"k":"직업 앞 무관사","t":"하이메는 화학 선생님이다.","e":"'ser + 직업'으로 직업을 소개할 때는 관사를 쓰지 않습니다: Es profesor de química. '화학 선생님'처럼 de로 과목을 밝히는 것은 형용사를 붙이는 것과 달라 여전히 관사가 없습니다.","x":["uno: 대명사(하나)라 명사 앞에 쓰지 않습니다 ✗","ø: ser + 직업은 관사 없이 → 정답 ✓","un: 직업 소개에는 부정관사를 넣지 않습니다 ✗","de: ser de는 출신·소유를 나타내므로 맞지 않습니다 ✗"]},{"id":"G238","q":"____, vamos a llevarnos los paraguas.","o":["Está lluviendo","Está lloviendo","Es lloviendo","Está lluvia"],"a":1,"k":"진행형 lloviendo","t":"비가 오고 있어, 우산 가져가자.","e":"지금 진행 중인 날씨는 'estar + 현재분사'로 말합니다. llover(비가 오다)는 o→ue 불규칙 동사지만 현재분사는 규칙적으로 lloviendo입니다. lluvia는 명사(비)입니다.","x":["Está lluviendo: 현재분사 철자가 틀렸습니다 ✗","Está lloviendo: estar + 현재분사, 비가 오는 중 → 정답 ✓","Es lloviendo: 진행형은 ser로 만들지 않습니다 ✗","Está lluvia: lluvia는 명사라 진행형이 되지 않습니다 ✗"]},{"id":"G239","q":"¿____ es el tequila? —Una bebida mexicana.","o":["Cómo","Cuál","De qué","Qué"],"a":3,"k":"정의 qué es","t":"데킬라가 뭐야? — 멕시코 술이야.","e":"어떤 것의 정의나 정체를 물을 때는 '¿Qué es ~?(~은 무엇이니?)'를 씁니다. cuál은 여러 개 중에서 '어느 것'을 고를 때 씁니다. 대답이 '멕시코 술'이라는 정의이므로 qué가 맞습니다.","x":["Cómo: '어떤'이라는 성질·모습을 물어 정의와 맞지 않습니다 ✗","Cuál: 여러 가지 중 선택할 때 써서 정의 질문에 맞지 않습니다 ✗","De qué: '무엇으로 만든/무엇에 관한'이라는 뜻이라 맞지 않습니다 ✗","Qué: 정의를 묻는 '무엇' → 정답 ✓"]},{"id":"G240","q":"Ese hotel es muy ____.","o":["caro","caros","cara","caras"],"a":0,"k":"형용사 성·수 일치","t":"그 호텔은 아주 비싸다.","e":"형용사는 주어의 성·수에 맞춥니다. hotel(호텔)은 남성 단수 명사이므로 caro(비싼)를 씁니다. -l로 끝나는 hotel이 남성이라는 점을 기억하세요.","x":["caro: 남성 단수형 → 정답 ✓","caros: 복수형이라 단수 hotel과 맞지 않습니다 ✗","cara: 여성형이라 남성 명사 hotel과 맞지 않습니다 ✗","caras: 여성 복수형이라 맞지 않습니다 ✗"]},{"id":"G241","q":"A Felisa y a sus amigas ____ gusta bailar flamenco.","o":["le","les","se","se les"],"a":1,"k":"gustar 구문 les","t":"펠리사와 그녀의 친구들은 플라멩코 추는 것을 좋아한다.","e":"gustar 구문에서 좋아하는 사람은 간접목적격 대명사로 나타냅니다. 'A Felisa y a sus amigas(펠리사와 친구들에게)'는 3인칭 복수이므로 les가 맞습니다. 동사 gusta는 좋아하는 대상인 동사원형 bailar에 맞춘 단수형입니다.","x":["le: 3인칭 단수라 여러 사람에게 쓰지 않습니다 ✗","les: 3인칭 복수 간접목적격 → 정답 ✓","se: 재귀대명사라 gustar 구문에 쓰지 않습니다 ✗","se les: 불필요한 se가 들어가 틀린 형태입니다 ✗"]},{"id":"G242","q":"Nosotros ____ preparados. ¿Y ustedes?","o":["están","estáis","estamos","estás"],"a":2,"k":"estar 1인칭 복수","t":"우리는 준비됐어. 너희는?","e":"주어 nosotros(우리)에 맞는 estar의 현재형은 estamos입니다. 'estar preparado'는 '준비된 상태이다'라는 뜻으로 상태를 나타내 estar를 씁니다. estar 현재형: estoy, estás, está, estamos, estáis, están.","x":["están: 3인칭 복수(ellos/ustedes)형입니다 ✗","estáis: vosotros(너희)형입니다 ✗","estamos: nosotros형 → 정답 ✓","estás: tú(너)형입니다 ✗"]},{"id":"G243","q":"____ hombre es el padre de María José.","o":["Aquello","Aquella","Aquel","Aquellos"],"a":2,"k":"지시형용사 aquel","t":"저 남자가 마리아 호세의 아버지다.","e":"hombre(남자)는 남성 단수 명사이므로 남성 단수 지시형용사 aquel(저)를 씁니다. 참고로 María José는 여성 이름입니다(남성 이름 José가 붙어도 여성).","x":["Aquello: 중성 대명사(저것)라 명사 앞에 쓰지 않습니다 ✗","Aquella: 여성형이라 hombre와 맞지 않습니다 ✗","Aquel: 남성 단수 '저' → 정답 ✓","Aquellos: 복수형이라 단수 hombre와 맞지 않습니다 ✗"]},{"id":"G244","q":"¿Es cierto que ____ Julio le gusta Carla?","o":["para","ø","a","en"],"a":2,"k":"gustar a + 사람","t":"훌리오가 카를라를 좋아한다는 게 사실이야?","e":"gustar 구문에서 좋아하는 사람을 이름으로 밝힐 때는 'a + 사람'으로 쓰고, 대명사 le도 함께 씁니다: A Julio le gusta Carla(훌리오는 카를라를 좋아한다). 여기서 Carla가 문법상 주어입니다.","x":["para: '~을 위해'라는 뜻이라 gustar 구문에 쓰지 않습니다 ✗","ø: 좋아하는 사람 앞에 a가 필요합니다 ✗","a: gustar 구문의 'a + 사람' → 정답 ✓","en: '~에'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G245","q":"¿____ te gusta el té negro?","o":["Ti","A ti","A tú","Tú"],"a":1,"k":"a ti","t":"너는 홍차 좋아해?","e":"gustar 구문에서 강조나 명확히 하기 위해 'a + 전치격 대명사'를 덧붙입니다. 전치사 뒤에서 tú는 ti로 바뀝니다(a mí, a ti, a él…). 'A ti te gusta'에서 te와 a ti는 같은 사람입니다.","x":["Ti: 전치사 a 없이 ti 혼자 쓰지 않습니다 ✗","A ti: 전치사 + 전치격 대명사 → 정답 ✓","A tú: 전치사 뒤에서는 tú가 아니라 ti를 씁니다 ✗","Tú: 주격이라 gustar 구문의 좋아하는 사람 자리에 맞지 않습니다 ✗"]},{"id":"G246","q":"Voy a ____ al niño.","o":["bañar","bañarme","bañando","baño"],"a":0,"k":"bañar/bañarse","t":"나는 아이를 목욕시킬 거야.","e":"'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래 표현입니다. 목적어(al niño: 아이를)가 따로 있으므로 재귀형이 아닌 bañar(목욕시키다)를 씁니다. bañarse는 '(스스로) 목욕하다'라는 뜻입니다.","x":["bañar: 다른 사람을 목욕시키다, 동사원형 → 정답 ✓","bañarme: '내가 목욕하다'라서 al niño와 맞지 않습니다 ✗","bañando: ir a 뒤에는 현재분사가 올 수 없습니다 ✗","baño: 활용형/명사라 ir a 뒤에 올 수 없습니다 ✗"]},{"id":"G247","q":"¿Falta algún plato en la mesa? —Sí, falta ____.","o":["lo","un","el","uno"],"a":3,"k":"대명사 uno","t":"식탁에 접시가 하나 모자라? — 응, 하나 모자라.","e":"un은 명사 앞에서만 쓰고, 명사(plato) 없이 홀로 '하나'를 말할 때는 uno를 씁니다. 앞에서 나온 남성 명사 plato를 대신하는 대명사 역할입니다. 예: ¿Tienes un bolígrafo? —Sí, tengo uno.","x":["lo: 직접목적격 대명사라 falta의 주어가 될 수 없습니다 ✗","un: 뒤에 명사가 있어야 쓸 수 있습니다 ✗","el: 정관사는 명사 없이 홀로 쓰지 않습니다 ✗","uno: 명사를 대신하는 '하나' → 정답 ✓"]},{"id":"G248","q":"¿Te importa ____ esperar cinco minutos?","o":["a","de","ø","con"],"a":2,"k":"importar + 동사원형","t":"5분만 기다려 줄 수 있어?","e":"'¿Te importa + 동사원형?'은 '~해도 괜찮겠어?/~해 줄래?'라는 정중한 부탁 표현입니다. importar(신경 쓰이다)는 gustar처럼 쓰는 동사로 뒤에 바로 동사원형이 옵니다. 전치사를 넣지 않습니다.","x":["a: importar 뒤에 a를 넣지 않습니다 ✗","de: importar 뒤에 de를 넣지 않습니다 ✗","ø: 전치사 없이 동사원형 → 정답 ✓","con: importar 뒤에 con을 넣지 않습니다 ✗"]},{"id":"G249","q":"¿____ veces has estado en Colombia?","o":["Cuánta","Cuántas","Cuántos","Cuánto"],"a":1,"k":"의문사 cuántas","t":"너는 콜롬비아에 몇 번 가 봤어?","e":"'몇 개/얼마나 많은'을 묻는 cuánto는 명사의 성·수에 맞춥니다. veces(번, 횟수)는 vez의 복수이고 여성 명사이므로 cuántas가 됩니다. '¿Cuántas veces…?'는 '몇 번…?'이라는 자주 쓰는 표현입니다.","x":["Cuánta: 단수형이라 복수 veces와 맞지 않습니다 ✗","Cuántas: 여성 복수, veces와 일치 → 정답 ✓","Cuántos: 남성형이라 여성 명사 veces와 맞지 않습니다 ✗","Cuánto: 남성 단수형이라 맞지 않습니다 ✗"]},{"id":"G250","q":"Marcelo está en su tienda ____ las 9 de la mañana hasta las 6 de la tarde.","o":["a","entre","en","desde"],"a":3,"k":"desde ~ hasta","t":"마르셀로는 오전 9시부터 오후 6시까지 자기 가게에 있다.","e":"시간의 범위는 'desde ~ hasta ~(~부터 ~까지)' 또는 'de ~ a ~'로 나타냅니다. 뒤에 hasta가 있으므로 짝이 되는 desde를 씁니다. 'de ~ a ~'와 섞어 쓰지 않습니다.","x":["a: 'de ~ a'의 짝이며 hasta와는 짝이 되지 않습니다 ✗","entre: '~사이에'로 쓸 때는 'entre ~ y ~'가 됩니다 ✗","en: '~에'라는 뜻이라 범위의 시작을 나타내지 않습니다 ✗","desde: hasta와 짝을 이루는 '~부터' → 정답 ✓"]},{"id":"G251","q":"¿____ es lo que te preocupa?","o":["De qué","Quién","A quién","Qué"],"a":3,"k":"qué es lo que","t":"너를 걱정시키는 게 뭐야?","e":"'¿Qué es lo que…?'는 '~하는 것은 무엇이니?'라는 강조 의문문입니다. lo que(~하는 것)는 사물·일을 가리키므로 의문사 qué(무엇)를 씁니다. preocupar(걱정시키다)는 te(너를)를 목적어로 받습니다.","x":["De qué: '무엇에 대해'가 되어 문장 구조와 맞지 않습니다 ✗","Quién: '누구'라서 lo que(~하는 것)와 맞지 않습니다 ✗","A quién: '누구를'이라 맞지 않습니다 ✗","Qué: 일·사물을 묻는 '무엇' → 정답 ✓"]},{"id":"G252","q":"Esa es la casa ____ nació Federico García Lorca.","o":["cuando","donde","cual","como"],"a":1,"k":"관계부사 donde","t":"저것이 페데리코 가르시아 로르카가 태어난 집이다.","e":"장소 명사(la casa: 집)를 꾸미는 관계절에서는 관계부사 donde(~하는 곳)를 씁니다. la casa donde nació는 '그가 태어난 집'입니다. en la que로 바꿔 써도 같은 뜻입니다.","x":["cuando: 시간을 나타내는 관계부사라 장소에 맞지 않습니다 ✗","donde: 장소를 나타내는 관계부사 → 정답 ✓","cual: 관사 없이 단독으로 관계사로 쓰지 않습니다(la cual 형태 필요) ✗","como: 방법을 나타내 장소에 맞지 않습니다 ✗"]},{"id":"G253","q":"____ sos muy amable.","o":["Vos","Vosotros","Usted","Ustedes"],"a":0,"k":"voseo sos","t":"너는 정말 친절하구나.","e":"sos는 vos(너)에 쓰는 ser의 현재형입니다(voseo: 아르헨티나, 우루과이 등). tú라면 eres, usted라면 es가 됩니다.","x":["Vos: voseo의 ser형 sos와 일치 → 정답 ✓","Vosotros: 동사는 sois입니다 ✗","Usted: 동사는 es입니다 ✗","Ustedes: 동사는 son입니다 ✗"]},{"id":"G254","q":"¿____ falda te gusta más? ¿Esta o esta?","o":["De qué","Quiénes","Qué","Cuántas"],"a":2,"k":"qué + 명사","t":"어느 치마가 더 마음에 들어? 이거야, 아니면 이거야?","e":"'qué + 명사'는 '어떤/어느 ~'라는 뜻으로 선택지 중에서 고르게 할 때 씁니다: ¿Qué falda…?(어느 치마?). 스페인어에서는 명사 앞에 cuál을 쓰지 않고 qué를 쓰는 것이 표준입니다.","x":["De qué: '무엇으로 된/무엇에 대한'이라는 뜻이라 맞지 않습니다 ✗","Quiénes: 사람을 묻는 '누구들'이라 맞지 않습니다 ✗","Qué: 명사 앞의 '어느' → 정답 ✓","Cuántas: '몇 개'라는 뜻이라 단수 falda와 의미가 맞지 않습니다 ✗"]},{"id":"G255","q":"Patricia y Cristian se casaron ____ abril del año pasado.","o":["en","de","a","desde"],"a":0,"k":"월 앞 en","t":"파트리시아와 크리스티안은 작년 4월에 결혼했다.","e":"'~월에'는 'en + 월 이름'으로 씁니다: en abril(4월에), en enero(1월에). 월 이름 앞에는 관사를 쓰지 않으며 소문자로 씁니다. 'del año pasado'는 '작년의'라는 뜻입니다.","x":["en: 월 앞의 '~에' → 정답 ✓","de: '~의'라는 뜻이라 시점을 나타내지 않습니다 ✗","a: 월 앞에 a를 쓰지 않습니다 ✗","desde: '~부터'라서 결혼한 시점에 맞지 않습니다 ✗"]},{"id":"G256","q":"No me gustan ____ zapatos.","o":["esta","esto","estos","estas"],"a":2,"k":"지시형용사 estos","t":"나는 이 신발이 마음에 안 든다.","e":"zapatos(신발)는 남성 복수 명사이므로 남성 복수 지시형용사 estos(이)를 씁니다. 동사 gustan이 복수형인 것도 주어 zapatos가 복수이기 때문입니다.","x":["esta: 여성 단수형입니다 ✗","esto: 중성 대명사라 명사 앞에 쓰지 않습니다 ✗","estos: 남성 복수 '이' → 정답 ✓","estas: 여성 복수형이라 남성 명사 zapatos와 맞지 않습니다 ✗"]},{"id":"G257","q":"Noelia y Juan Carlos están ____.","o":["enamorado","enamorada","enamoradas","enamorados"],"a":3,"k":"형용사 성·수 일치","t":"노엘리아와 후안 카를로스는 사랑에 빠져 있다.","e":"남자와 여자가 함께 주어일 때 형용사는 남성 복수형을 씁니다. Noelia(여)와 Juan Carlos(남)가 함께이므로 enamorados가 맞습니다. 'estar enamorado'는 '사랑에 빠져 있다'라는 상태입니다.","x":["enamorado: 남성 단수형이라 두 사람 주어와 맞지 않습니다 ✗","enamorada: 여성 단수형이라 맞지 않습니다 ✗","enamoradas: 여성 복수형으로 남성이 포함되면 쓰지 않습니다 ✗","enamorados: 남녀 혼성 복수 → 정답 ✓"]},{"id":"G258","q":"¡Bienvenidas ____ nuestro hogar!","o":["en","a","hasta","hacia"],"a":1,"k":"bienvenido a","t":"우리 집에 오신 것을 환영해요!","e":"'Bienvenido/a/os/as a + 장소'는 '~에 오신 것을 환영합니다'라는 표현입니다. bienvenido는 환영받는 사람의 성·수에 맞추는데, 여기서는 여성 복수 Bienvenidas입니다. 전치사는 a를 씁니다.","x":["en: bienvenido 뒤에 en을 쓰지 않습니다 ✗","a: bienvenido a + 장소 → 정답 ✓","hasta: '~까지'라는 뜻이라 맞지 않습니다 ✗","hacia: '~쪽으로'라는 뜻이라 환영 표현에 쓰지 않습니다 ✗"]},{"id":"G259","q":"Me gustaría ir a ____ lugares que no conozco.","o":["muy","muchos","muchas","mucho"],"a":1,"k":"mucho 형용사 일치","t":"나는 가 보지 않은 많은 곳에 가고 싶다.","e":"명사 앞의 mucho는 '많은'이라는 형용사로, 명사의 성·수에 맞춥니다. lugares(장소들)는 남성 복수이므로 muchos가 맞습니다. muy는 형용사·부사 앞에서만 씁니다.","x":["muy: 명사 앞에 쓰지 않습니다 ✗","muchos: 남성 복수 '많은' → 정답 ✓","muchas: 여성형이라 남성 명사 lugares와 맞지 않습니다 ✗","mucho: 단수형이라 복수 lugares와 맞지 않습니다 ✗"]},{"id":"G260","q":"____ es el autobús que pasa por la plaza principal.","o":["Esta","Esto","Este","Estos"],"a":2,"k":"지시대명사 este","t":"이것이 중앙 광장을 지나가는 버스야.","e":"지시사를 명사 없이 대명사로 쓸 때도 가리키는 명사의 성·수에 맞춥니다. el autobús(버스)는 남성 단수이므로 este를 씁니다. 지시대명사는 예전에 éste처럼 악센트를 붙였지만, 지금은 붙이지 않는 것이 기본입니다.","x":["Esta: 여성형이라 autobús와 맞지 않습니다 ✗","Esto: 중성으로 정체를 모르는 것을 가리킬 때 써서 el autobús와 맞지 않습니다 ✗","Este: 남성 단수 지시대명사 → 정답 ✓","Estos: 복수형이라 단수 동사 es와 맞지 않습니다 ✗"]},{"id":"G261","q":"Carlitos, no ____ con la boca llena, por favor.","o":["habla","hablando","hables","habléis"],"a":2,"k":"부정명령 tú","t":"카를리토스, 입에 음식 넣고 말하지 마, 제발.","e":"부정명령(~하지 마)은 'no + 접속법 현재'로 만듭니다. tú에게 하는 부정명령이므로 hablar → no hables가 됩니다. 긍정명령 habla(말해)와 형태가 다르니 주의하세요.","x":["habla: tú 긍정명령형이라 no와 함께 쓰지 않습니다 ✗","hablando: 현재분사라 명령이 되지 않습니다 ✗","hables: tú 부정명령(no + 접속법) → 정답 ✓","habléis: vosotros 부정명령이라 한 사람(Carlitos)과 맞지 않습니다 ✗"]},{"id":"G262","q":"¿Quieres venir ____ playa con nosotros?","o":["al","en la","a","a la"],"a":3,"k":"ir a la playa","t":"우리랑 같이 해변에 갈래?","e":"이동 동사 venir/ir와 함께 목적지를 말할 때는 a를 씁니다. playa(해변)는 여성 명사이므로 'a la playa'가 됩니다. 남성 명사라면 al(a + el)이 됩니다: al cine.","x":["al: 남성형 축약이라 여성 명사 playa와 맞지 않습니다 ✗","en la: en은 위치를 나타내므로 이동 동사와 맞지 않습니다 ✗","a: 관사가 빠졌습니다 ✗","a la: 목적지 a + 여성 정관사 → 정답 ✓"]},{"id":"G263","q":"Muchas gracias, Sra. González. —Gracias ____ usted.","o":["de","por","para","a"],"a":3,"k":"gracias a usted","t":"정말 감사합니다, 곤살레스 부인. — 제가 감사하죠.","e":"감사 인사에 '오히려 제가 감사해요'라고 답할 때는 'Gracias a ti/a usted'라고 합니다. '~에게 감사'라는 의미로 전치사 a를 씁니다. 'gracias por'는 감사의 이유(~에 대해)를 말할 때 씁니다.","x":["de: gracias de usted는 쓰지 않습니다 ✗","por: 감사의 이유를 말할 때 쓰므로 사람 앞에 맞지 않습니다 ✗","para: '~을 위해'라는 뜻이라 맞지 않습니다 ✗","a: 감사의 대상 '~에게' → 정답 ✓"]},{"id":"G264","q":"____ jersey que más me gusta es el gris.","o":["Uno","Un","ø","El"],"a":3,"k":"정관사 + 관계절","t":"내가 가장 마음에 드는 스웨터는 회색이다.","e":"'que más me gusta(내가 가장 좋아하는)'라는 관계절로 특정해진 명사 앞에는 정관사를 씁니다. jersey(스웨터)는 남성 단수이므로 El입니다. 뒤의 'el gris'와 같은 관사입니다.","x":["Uno: 대명사라 명사 앞에 쓰지 않습니다 ✗","Un: '어떤 스웨터'가 되어 '가장 좋아하는'이라는 특정함과 맞지 않습니다 ✗","ø: 문장 맨 앞 특정 명사에는 관사가 필요합니다 ✗","El: 남성 단수 정관사 → 정답 ✓"]},{"id":"G265","q":"La biblioteca está ____ final de esta calle.","o":["el","al","a","en"],"a":1,"k":"al final de","t":"도서관은 이 길 끝에 있다.","e":"'al final de ~'는 '~의 끝에'라는 위치 표현입니다. a + el = al로 축약됩니다. 예: El baño está al final del pasillo.(화장실은 복도 끝에 있다.)","x":["el: 전치사가 빠져 위치 표현이 되지 않습니다 ✗","al: al final de(~의 끝에) → 정답 ✓","a: 관사가 빠졌습니다 ✗","en: en final은 관사가 없어 틀립니다(en el final도 덜 자연스러움) ✗"]},{"id":"G266","q":"Dime, María, ¿qué ____ pareció la película?","o":["se","me","te","nos"],"a":2,"k":"parecer 구문 te","t":"말해 봐, 마리아. 영화 어땠어?","e":"'¿Qué te pareció ~?'는 '~ 어땠어? (너에게 어떻게 보였어?)'라는 표현입니다. parecer는 gustar처럼 사람을 간접목적격 대명사로 씁니다. 마리아에게 묻고 있으므로 te(너에게)가 맞습니다.","x":["se: 재귀대명사라 이 구문에 쓰지 않습니다 ✗","me: '나에게'라서 마리아의 의견을 묻는 질문과 맞지 않습니다 ✗","te: '너에게', 마리아에게 묻는 것 → 정답 ✓","nos: '우리에게'라서 맞지 않습니다 ✗"]},{"id":"G267","q":"¿Cómo ____ tus gatos?","o":["te llamas","se llaman","llaman","se llama"],"a":1,"k":"llamarse","t":"네 고양이들 이름이 뭐야?","e":"이름을 말할 때는 재귀동사 llamarse(~라고 불리다)를 씁니다. 주어 tus gatos(너의 고양이들)는 3인칭 복수이므로 se llaman이 맞습니다. 예: ¿Cómo te llamas?(너 이름이 뭐야?)","x":["te llamas: tú(너)의 이름을 묻는 형태입니다 ✗","se llaman: 3인칭 복수 재귀동사 → 정답 ✓","llaman: 재귀대명사가 없어 '그들이 부른다'는 뜻이 됩니다 ✗","se llama: 3인칭 단수라 복수 gatos와 맞지 않습니다 ✗"]},{"id":"G268","q":"____ lunes son muy aburridos.","o":["Los","Las","La","El"],"a":0,"k":"요일 복수 정관사","t":"월요일은 너무 지루하다.","e":"'매주 월요일'처럼 반복되는 요일을 말할 때는 남성 복수 정관사 los를 씁니다: los lunes. 요일은 모두 남성이며, lunes~viernes는 단수·복수 형태가 같습니다.","x":["Los: 남성 복수 정관사, 매주 월요일 → 정답 ✓","Las: 여성형이라 요일에 쓰지 않습니다 ✗","La: 여성 단수형이라 맞지 않습니다 ✗","El: 단수라 복수 동사 son과 맞지 않습니다 ✗"]},{"id":"G269","q":"Mis padres están ____, gracias por preguntar.","o":["buenos","bueno","bien","buena"],"a":2,"k":"estar bien","t":"우리 부모님은 잘 지내셔, 물어봐 줘서 고마워.","e":"안부(건강·상태가 좋다)를 말할 때는 'estar bien'을 씁니다. bien은 부사라서 주어의 성·수에 따라 바뀌지 않습니다. 'estar bueno'는 구어에서 '(사람이) 매력적이다' 등의 다른 뜻이 됩니다.","x":["buenos: 형용사라 안부를 말하는 estar 뒤에 어색합니다 ✗","bueno: 형용사이고 단수형이라 맞지 않습니다 ✗","bien: 상태를 나타내는 부사 → 정답 ✓","buena: 여성 단수 형용사라 맞지 않습니다 ✗"]},{"id":"G270","q":"¿Me ayudáis a buscar ____ papeles del banco?","o":["a mis","las mías","mis","míos"],"a":2,"k":"소유형용사 mis","t":"내 은행 서류 찾는 것 좀 도와줄래?","e":"명사 앞에서 '나의'는 소유형용사 mi/mis를 씁니다. papeles(서류들)가 복수이므로 mis가 맞습니다. buscar(찾다)의 목적어가 사물이므로 a를 넣지 않습니다.","x":["a mis: 사물 목적어 앞에는 a를 붙이지 않습니다 ✗","las mías: 소유대명사(내 것)이고 여성형이라 명사 앞에 맞지 않습니다 ✗","mis: 복수 명사 앞 '나의' → 정답 ✓","míos: 명사 뒤나 단독으로 쓰는 소유형이라 명사 앞에 오지 않습니다 ✗"]},{"id":"G271","q":"____ apartamento es más pequeño que el mío.","o":["Suyo","Su","Sus","El suyo"],"a":1,"k":"소유형용사 su","t":"그의 아파트는 내 것보다 작다.","e":"명사 앞에서 '그의/그녀의/당신의'는 소유형용사 su(단수)/sus(복수)를 씁니다. apartamento가 단수이므로 Su가 맞습니다. el suyo는 '그의 것'이라는 소유대명사로 명사 없이 씁니다.","x":["Suyo: 명사 뒤에 오는 강세형이라 명사 앞에 쓰지 않습니다 ✗","Su: 단수 명사 앞 소유형용사 → 정답 ✓","Sus: 복수형이라 단수 apartamento와 맞지 않습니다 ✗","El suyo: 소유대명사(그의 것)라 뒤에 명사가 올 수 없습니다 ✗"]},{"id":"G272","q":"¿Sabe si hay ____ estanco por aquí cerca?","o":["ningún","el","algún","alguno"],"a":2,"k":"algún","t":"이 근처에 담배 가게가 있는지 아세요?","e":"hay와 함께 '어떤 ~(이라도)'를 물을 때는 algún을 씁니다. alguno는 남성 단수 명사 앞에서 -o가 빠져 algún이 됩니다. estanco는 스페인에서 담배·우표 등을 파는 가게입니다.","x":["ningún: '어떤 ~도 없는'이라는 부정어라 긍정 질문에 맞지 않습니다 ✗","el: 정관사는 hay와 함께 쓰지 않습니다 ✗","algún: 남성 단수 명사 앞 '어떤' → 정답 ✓","alguno: 명사 앞에서는 algún으로 줄여야 합니다 ✗"]},{"id":"G273","q":"Irene y yo ____ buena relación.","o":["tengo","tenemos","tienen","tienes"],"a":1,"k":"주어와 동사 일치","t":"이레네와 나는 사이가 좋다.","e":"'A y yo(A와 나)'는 '우리(nosotros)'이므로 동사는 1인칭 복수 tenemos를 씁니다. 'tener buena relación'은 '사이가 좋다'라는 표현입니다.","x":["tengo: 1인칭 단수(나)형이라 두 사람 주어와 맞지 않습니다 ✗","tenemos: 1인칭 복수(우리) → 정답 ✓","tienen: 3인칭 복수(그들)형입니다 ✗","tienes: 2인칭 단수(너)형입니다 ✗"]},{"id":"G274","q":"Martina ____ regaló a su marido un reloj digital.","o":["ø","lo","le","les"],"a":2,"k":"간접목적격 le","t":"마르티나는 남편에게 디지털 시계를 선물했다.","e":"regalar(선물하다)에서 '~에게'에 해당하는 사람은 간접목적격 대명사로 나타냅니다. a su marido(그녀의 남편에게)는 3인칭 단수이므로 le를 씁니다. 스페인어에서는 'a + 사람'이 있어도 le를 함께 쓰는 것이 자연스럽습니다.","x":["ø: 문법상 가능하지만 간접목적어를 반복하는 le가 자연스러운 표현입니다 ✗","lo: 직접목적격(그를)이라 '~에게' 자리에 맞지 않습니다 ✗","le: 3인칭 단수 간접목적격(그에게) → 정답 ✓","les: 복수형이라 남편 한 명과 맞지 않습니다 ✗"]},{"id":"G275","q":"Si se siente ____, hable con su doctor.","o":["más peor","lo peor","peor","muy peor"],"a":2,"k":"불규칙 비교급 peor","t":"몸이 더 안 좋아지시면 의사와 상담하세요.","e":"malo/mal(나쁜/나쁘게)의 비교급은 불규칙형 peor(더 나쁜)입니다. peor 자체에 '더'라는 뜻이 있으므로 más나 muy를 붙이지 않습니다. 같은 불규칙형: mejor(더 좋은), mayor, menor.","x":["más peor: peor에 이미 '더'가 있어 más를 겹쳐 쓰지 않습니다 ✗","lo peor: '최악의 것'이라는 명사구라 sentirse 뒤에 맞지 않습니다 ✗","peor: 불규칙 비교급(더 나쁜) → 정답 ✓","muy peor: 비교급 앞에는 muy를 쓰지 않습니다 ✗"]},{"id":"G276","q":"____ más me gusta de mi ciudad es la simpatía de la gente.","o":["Lo","Lo que","El que","Que"],"a":1,"k":"lo que","t":"내 도시에서 가장 마음에 드는 것은 사람들의 친절함이다.","e":"'lo que'는 '~하는 것'이라는 뜻으로 정해진 명사 없이 일이나 사물 전체를 가리킵니다. 'Lo que más me gusta es ~'는 '내가 가장 좋아하는 것은 ~이다'라는 자주 쓰는 표현입니다.","x":["Lo: que 없이 lo만으로는 관계절을 이끌 수 없습니다 ✗","Lo que: '~하는 것' → 정답 ✓","El que: 앞에 나온 남성 명사(특정한 것)를 가리킬 때 써서 이 문장엔 어색합니다 ✗","Que: 선행사 없이 que만으로는 '~하는 것'이 되지 않습니다 ✗"]},{"id":"G277","q":"¿Podría pagar con tarjeta o tiene que ser ____ efectivo?","o":["por","en","desde","de"],"a":1,"k":"en efectivo","t":"카드로 결제할 수 있나요, 아니면 현금이어야 하나요?","e":"'en efectivo'는 '현금으로'라는 고정 표현입니다. 카드는 'con tarjeta(카드로)'처럼 con을 씁니다. 중남미에서는 'en efectivo' 외에 'al contado'라는 표현도 씁니다.","x":["por: por efectivo는 쓰지 않습니다 ✗","en: en efectivo(현금으로) → 정답 ✓","desde: '~부터'라서 맞지 않습니다 ✗","de: de efectivo는 쓰지 않습니다 ✗"]},{"id":"G278","q":"Normalmente, voy a la escuela de baile dos días ____ semana.","o":["a","a la","al","la"],"a":1,"k":"빈도 a la semana","t":"보통 나는 일주일에 이틀 댄스 학원에 간다.","e":"'일주일에/한 달에 몇 번'은 'a la semana', 'al mes', 'al año'처럼 a + 정관사로 표현합니다. semana는 여성 명사이므로 a la semana입니다. 'por semana'도 같은 뜻으로 씁니다.","x":["a: 관사가 빠졌습니다 ✗","a la: 빈도를 나타내는 a la semana → 정답 ✓","al: 남성형 축약이라 여성 명사 semana와 맞지 않습니다 ✗","la: 전치사 a가 빠졌습니다 ✗"]},{"id":"G279","q":"Leonor vive en casa de ____ abuelos maternos.","o":["sus","su","los suyos","suyos"],"a":0,"k":"소유형용사 sus","t":"레오노르는 외조부모님 댁에 산다.","e":"명사 앞의 소유형용사는 소유되는 명사의 수에 맞춥니다. abuelos(조부모)가 복수이므로 sus가 맞습니다. maternos는 '어머니 쪽의'라는 뜻입니다.","x":["sus: 복수 명사 앞 '그녀의' → 정답 ✓","su: 단수형이라 복수 abuelos와 맞지 않습니다 ✗","los suyos: 소유대명사(그녀의 것들)라 명사 앞에 쓰지 않습니다 ✗","suyos: 명사 뒤에 오는 강세형이라 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G280","q":"¿____ estudias japonés?","o":["Porque","Por que","Por qué","Porqué"],"a":2,"k":"por qué/porque","t":"너는 왜 일본어를 공부해?","e":"'왜?'라고 물을 때는 띄어 쓰고 악센트를 붙인 por qué를 씁니다. porque(붙여 쓰고 악센트 없음)는 '왜냐하면'이라는 대답용 접속사입니다. porqué는 '이유'라는 명사입니다(el porqué).","x":["Porque: '왜냐하면'이라는 대답용 접속사입니다 ✗","Por que: 악센트가 없어 의문사가 아닙니다 ✗","Por qué: 의문사 '왜' → 정답 ✓","Porqué: '이유'라는 명사입니다 ✗"]},{"id":"G281","q":"No hablan ____ italiano.","o":["alguno de","algún de","nadie de","nada de"],"a":3,"k":"nada de","t":"그들은 이탈리아어를 전혀 못한다.","e":"'no ~ nada de + 명사'는 '~을 전혀 (않다)'라는 강한 부정 표현입니다. No hablan nada de italiano는 '이탈리아어를 조금도 못한다'라는 뜻입니다. 스페인어는 no와 nada를 함께 쓰는 이중 부정이 정상입니다.","x":["alguno de: '~중 어떤 것'이라는 뜻이라 언어 앞에 맞지 않습니다 ✗","algún de: algún은 명사 앞에만 오며 de와 함께 쓰지 않습니다 ✗","nadie de: '아무도'라는 사람 부정어라 맞지 않습니다 ✗","nada de: no와 함께 '전혀 ~않다' → 정답 ✓"]},{"id":"G282","q":"No son colombianos, ____ venezolanos.","o":["pero","sino","entonces","aunque"],"a":1,"k":"no ~ sino","t":"그들은 콜롬비아 사람이 아니라 베네수엘라 사람이다.","e":"앞 내용을 부정하고 '~가 아니라 …이다'라고 바로잡을 때는 sino를 씁니다(no A sino B). pero는 '하지만'이라는 단순 대조로, 앞 내용을 바로잡지 않습니다. 예: No es caro, pero no lo compro.(비싸진 않지만 안 산다.)","x":["pero: '하지만'으로 앞 내용을 바로잡는 뜻이 없습니다 ✗","sino: no A sino B(A가 아니라 B) → 정답 ✓","entonces: '그러면/그래서'라는 뜻이라 맞지 않습니다 ✗","aunque: '비록 ~이지만'이라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G283","q":"¿A qué hora vuelves ____ casa del trabajo?","o":["en","ø","a","de"],"a":2,"k":"volver a casa","t":"너는 몇 시에 퇴근해서 집에 돌아오니?","e":"이동 동사(volver: 돌아가다/오다, ir, llegar 등)와 함께 '집으로'는 'a casa'라고 합니다. 자기 집을 말할 때는 casa 앞에 관사를 쓰지 않습니다. 'del trabajo'는 '직장에서(출발)'를 나타냅니다.","x":["en: 위치를 나타내 이동 동사 volver와 맞지 않습니다 ✗","ø: 목적지 앞의 a가 필요합니다 ✗","a: 목적지 '~로' → 정답 ✓","de: '~에서(출발)'라서 집으로 돌아오는 뜻이 되지 않습니다 ✗"]},{"id":"G284","q":"____ he comido en ese restaurante.","o":["Ni","Nadie","Nunca","Ninguno"],"a":2,"k":"부정어 nunca","t":"나는 그 식당에서 한 번도 먹어 본 적이 없다.","e":"nunca(결코, 한 번도 ~않다)가 동사 앞에 오면 no 없이 홀로 부정문을 만듭니다. 현재완료와 함께 쓰면 '~해 본 적이 없다'라는 경험의 부정이 됩니다. 동사 뒤에 쓰면 'No he comido nunca'처럼 no가 필요합니다.","x":["Ni: '~조차/~도 아닌'이라는 뜻으로 이 자리에서 혼자 쓰지 않습니다 ✗","Nadie: '아무도'라는 3인칭 주어라 1인칭 동사 he와 맞지 않습니다 ✗","Nunca: '한 번도 ~않다' → 정답 ✓","Ninguno: '아무도/어느 것도'라는 3인칭 대명사라 he와 맞지 않습니다 ✗"]},{"id":"G285","q":"Estos ejercicios no son ____.","o":["fácilmente","fáciles","fácil","facil"],"a":1,"k":"형용사 복수형","t":"이 연습 문제들은 쉽지 않다.","e":"형용사는 주어 ejercicios(연습 문제들, 남성 복수)에 맞춰 복수형을 씁니다. 자음으로 끝나는 형용사는 -es를 붙여 복수를 만듭니다: fácil → fáciles. 악센트도 그대로 유지합니다.","x":["fácilmente: '쉽게'라는 부사라 ser 뒤 주어 설명에 맞지 않습니다 ✗","fáciles: 복수형 형용사 → 정답 ✓","fácil: 단수형이라 복수 주어와 맞지 않습니다 ✗","facil: 단수형이며 악센트도 빠졌습니다 ✗"]},{"id":"G286","q":"Este fin de semana vamos a ir ____ excursión a la montaña.","o":["de","en","por","a"],"a":0,"k":"ir de excursión","t":"이번 주말에 우리는 산으로 소풍을 갈 것이다.","e":"'ir de + 명사'는 '~하러 가다'라는 고정 표현입니다: ir de excursión(소풍 가다), ir de compras(쇼핑 가다), ir de vacaciones(휴가 가다). 목적지는 'a la montaña'처럼 a로 나타냅니다.","x":["de: ir de excursión(소풍 가다) → 정답 ✓","en: ir en은 교통수단을 나타냅니다 ✗","por: ir por excursión은 쓰지 않습니다 ✗","a: ir a excursión은 쓰지 않습니다 ✗"]},{"id":"G287","q":"Vamos a ____ una vuelta por el puerto. ¿Te vienes?","o":["dar","dan","damos","doy"],"a":0,"k":"dar una vuelta","t":"항구 쪽으로 한 바퀴 산책하자. 같이 갈래?","e":"'dar una vuelta'는 '한 바퀴 돌다, 산책하다'라는 관용 표현입니다. 'vamos a + 동사원형'은 '~하자/~할 것이다'라는 뜻이므로 동사원형 dar가 와야 합니다.","x":["dar: ir a 뒤 동사원형 → 정답 ✓","dan: 활용된 동사는 a 뒤에 올 수 없습니다 ✗","damos: 활용된 동사는 a 뒤에 올 수 없습니다 ✗","doy: 활용된 동사는 a 뒤에 올 수 없습니다 ✗"]},{"id":"G288","q":"Mi despacho está en el ____ piso de ese bloque.","o":["tres","tercero","tercer","tercera"],"a":2,"k":"서수 tercer","t":"내 사무실은 그 건물 3층에 있다.","e":"서수 primero(첫 번째)와 tercero(세 번째)는 남성 단수 명사 앞에서 -o가 빠져 primer, tercer가 됩니다. piso(층)는 남성 단수 명사이므로 el tercer piso입니다. 명사 뒤에 오거나 여성 명사 앞에서는 줄이지 않습니다(la tercera planta).","x":["tres: 기수(셋)라 '세 번째 층'이 되지 않습니다 ✗","tercero: 남성 단수 명사 앞에서는 tercer로 줄입니다 ✗","tercer: 남성 단수 명사 앞 서수 축약형 → 정답 ✓","tercera: 여성형이라 남성 명사 piso와 맞지 않습니다 ✗"]},{"id":"G289","q":"¿Qué van a hacer ____ fin de semana?","o":["estas","esta","esto","este"],"a":3,"k":"지시형용사 este","t":"이번 주말에 무엇을 하실 건가요?","e":"fin de semana(주말)의 중심 명사 fin은 남성 단수이므로 남성형 지시형용사 este를 씁니다. 'este fin de semana'는 '이번 주말'이라는 자주 쓰는 표현입니다. semana에 이끌려 esta를 쓰지 않도록 주의하세요.","x":["estas: 여성 복수형입니다 ✗","esta: 여성형으로, 중심 명사 fin은 남성입니다 ✗","esto: 중성 대명사라 명사 앞에 쓰지 않습니다 ✗","este: 남성 단수 '이' → 정답 ✓"]},{"id":"G290","q":"Mi hijo Roberto nació ____ año 2002.","o":["al","a","en","en el"],"a":3,"k":"en el año + 연도","t":"내 아들 로베르토는 2002년에 태어났다.","e":"연도를 말할 때는 'en + 연도(en 2002)'로 쓰거나, año를 넣으면 'en el año 2002'처럼 관사가 필요합니다. 이 문장에는 año가 있으므로 en el이 맞습니다.","x":["al: 연도 앞에 a를 쓰지 않습니다 ✗","a: 연도 앞에 a를 쓰지 않습니다 ✗","en: año 앞에는 관사 el이 필요합니다 ✗","en el: en el año + 연도 → 정답 ✓"]},{"id":"G291","q":"Hoy mi maestra está ____ mal humor.","o":["a","en","con","de"],"a":3,"k":"de mal humor","t":"오늘 우리 선생님은 기분이 안 좋으시다.","e":"'estar de buen/mal humor'는 '기분이 좋다/나쁘다'라는 고정 표현입니다. 일시적인 기분 상태라서 estar와 de를 함께 씁니다. maestra는 주로 초등학교 선생님을 가리킵니다.","x":["a: estar a mal humor는 쓰지 않습니다 ✗","en: estar en mal humor는 표준 표현이 아닙니다 ✗","con: '~을 가지고'라는 뜻이라 기분 표현에 쓰지 않습니다 ✗","de: estar de mal humor(기분이 나쁘다) → 정답 ✓"]},{"id":"G292","q":"No ____ el nombre de ese chico.","o":["recuerdo","me recuerdo","me lo recuerdo","estoy recordando"],"a":0,"k":"recordar","t":"나는 그 남자아이의 이름이 기억나지 않는다.","e":"recordar(기억하다)는 재귀형 없이 목적어를 바로 받습니다: recuerdo el nombre(그 이름을 기억한다). 재귀형으로 쓰고 싶다면 'acordarse de'를 씁니다: No me acuerdo del nombre. recordar는 o→ue 불규칙 동사입니다.","x":["recuerdo: 1인칭 현재형, 목적어를 바로 받음 → 정답 ✓","me recuerdo: recordar는 이 뜻으로 재귀형을 쓰지 않습니다(acordarse와 혼동) ✗","me lo recuerdo: 대명사가 불필요하게 겹쳐 틀립니다 ✗","estoy recordando: '지금 떠올리는 중'이라 기억하지 못한다는 뜻에 어색합니다 ✗"]},{"id":"G293","q":"Si tanto te gusta ese vestido, ¿por qué no te ____ compras?","o":["le","lo","los","la"],"a":1,"k":"재귀 + 직접목적격","t":"그 원피스가 그렇게 마음에 들면, 사지 그래?","e":"앞의 ese vestido(그 원피스, 남성 단수)를 '그것을'로 받으므로 직접목적격 lo를 씁니다. te(너 자신에게)와 함께 쓸 때는 'te lo'처럼 간접 → 직접 순서로 놓습니다. 'comprarse algo'는 '(자기 것으로) ~을 사다'라는 뜻입니다.","x":["le: 간접목적격이라 '그것을' 자리에 맞지 않습니다 ✗","lo: 남성 단수 직접목적격(그것을) → 정답 ✓","los: 복수형이라 한 벌의 원피스와 맞지 않습니다 ✗","la: 여성형이라 남성 명사 vestido와 맞지 않습니다 ✗"]},{"id":"G294","q":"Estoy preocupado ____ mi hija.","o":["para","en","por","a"],"a":2,"k":"preocupado por","t":"나는 딸이 걱정된다.","e":"'estar preocupado por ~'는 '~이 걱정된다'라는 표현으로, 걱정의 원인·대상 앞에 por를 씁니다. 예: Estoy preocupada por el examen.(나는 시험이 걱정된다.)","x":["para: '~을 위해'라는 뜻이라 걱정의 대상에 쓰지 않습니다 ✗","en: preocupado en은 쓰지 않습니다 ✗","por: 걱정의 원인·대상 → 정답 ✓","a: preocupado a는 쓰지 않습니다 ✗"]},{"id":"G295","q":"Esteban es ____ guapo que Ignacio.","o":["más","tanto","mucho","tan"],"a":0,"k":"비교급 más que","t":"에스테반은 이그나시오보다 잘생겼다.","e":"'más + 형용사 + que'는 '~보다 더 …하다'라는 우등 비교입니다. 동등 비교는 'tan + 형용사 + como'로 que가 아닌 como와 짝을 이룹니다. 뒤에 que가 있으므로 más가 맞습니다.","x":["más: más ~ que(~보다 더) → 정답 ✓","tanto: 형용사 앞에서는 tan이 되고 como와 짝입니다 ✗","mucho: 형용사 앞에 쓰지 않으며 비교를 만들지 않습니다 ✗","tan: 동등 비교로 como와 짝이라 que와 맞지 않습니다 ✗"]},{"id":"G296","q":"Ernesto tiene ____ 30 años.","o":["uno","unos","unas","un"],"a":1,"k":"unos + 숫자(약)","t":"에르네스토는 30살쯤 되었다.","e":"숫자 앞에 unos/unas를 쓰면 '대략, 약'이라는 뜻이 됩니다. años(년, 살)는 남성 복수이므로 unos를 씁니다. 예: Hay unas 20 personas.(20명쯤 있다.)","x":["uno: 단수 대명사라 숫자 앞에 쓰지 않습니다 ✗","unos: 남성 복수, '약 ~' → 정답 ✓","unas: 여성형이라 남성 명사 años와 맞지 않습니다 ✗","un: 단수형이라 복수 años와 맞지 않습니다 ✗"]},{"id":"G297","q":"No sé ____ hacer este ejercicio.","o":["cómo","qué","cuánto","cuál"],"a":0,"k":"cómo + 동사원형","t":"나는 이 연습 문제를 어떻게 하는지 모르겠다.","e":"'saber + 의문사 + 동사원형'은 '~해야 할지 알다'라는 뜻입니다. 방법을 말하므로 cómo(어떻게)를 씁니다: No sé cómo hacer…(어떻게 해야 할지 모르겠다). 이미 este ejercicio라는 목적어가 있어 qué는 들어갈 수 없습니다.","x":["cómo: 방법을 나타내는 '어떻게' → 정답 ✓","qué: '무엇을'인데 목적어 este ejercicio가 이미 있어 맞지 않습니다 ✗","cuánto: '얼마나'라는 양을 나타내 맞지 않습니다 ✗","cuál: '어느 것'이라는 선택을 나타내 맞지 않습니다 ✗"]},{"id":"G298","q":"No me gusta ____ la música de este grupo. ¡Qué horror!","o":["poco","nada","algo","bastante"],"a":1,"k":"no ~ nada 강조","t":"나는 이 그룹의 음악이 전혀 마음에 안 들어. 끔찍해!","e":"'no me gusta nada'는 '전혀 마음에 들지 않는다'라는 강한 부정입니다. 뒤의 '¡Qué horror!(끔찍해!)'로 보아 아주 싫어한다는 뜻이므로 nada가 맞습니다. 이 nada는 '전혀'라는 부사로 쓰였습니다.","x":["poco: '별로'라는 약한 뜻이라 '끔찍해'와 어울리지 않습니다 ✗","nada: no와 함께 '전혀' → 정답 ✓","algo: '조금'이라는 뜻으로 부정문에 맞지 않습니다 ✗","bastante: '꽤'라는 뜻이라 강한 거부와 맞지 않습니다 ✗"]},{"id":"G299","q":"El vecino ____ tercer piso es médico.","o":["desde","desde el","de","del"],"a":3,"k":"de + el = del","t":"3층에 사는 이웃은 의사이다.","e":"'~의'라는 소속은 de로 나타내고, 특정한 층(el tercer piso)이므로 정관사 el이 붙어 de + el = del로 축약됩니다. el vecino del tercer piso는 '3층 이웃'이라는 뜻입니다.","x":["desde: '~부터'라서 소속을 나타내지 않습니다 ✗","desde el: '그 층에서부터'가 되어 의미가 맞지 않습니다 ✗","de: 관사가 빠졌고, de el은 del로 축약해야 합니다 ✗","del: de + el 축약, '~층의' → 정답 ✓"]},{"id":"G300","q":"El domingo vamos ____ comer en un restaurante italiano.","o":["por","a","ø","de"],"a":1,"k":"ir a + 동사원형","t":"일요일에 우리는 이탈리아 식당에 밥 먹으러 갈 거야.","e":"'ir a + 동사원형'은 '~할 것이다' 또는 '~하러 가다'라는 뜻입니다. vamos a comer는 '먹으러 갈 거야'입니다. 동사원형 앞에는 반드시 a를 넣습니다.","x":["por: ir por는 '~을 가지러 가다' 등의 뜻이라 맞지 않습니다 ✗","a: ir a + 동사원형 → 정답 ✓","ø: ir 뒤 동사원형 앞에는 a가 필요합니다 ✗","de: ir de 뒤에는 동사원형이 오지 않습니다 ✗"]},{"id":"G301","q":"Me gustan las ventanas ____.","o":["gran","las grandes","grandes","grande"],"a":2,"k":"형용사 성·수 일치","t":"나는 큰 창문들이 마음에 든다.","e":"스페인어 형용사는 꾸미는 명사의 성(남성/여성)과 수(단수/복수)에 맞춰 형태가 바뀝니다. grande(큰)는 남녀 형태가 같고, 복수 명사 'las ventanas(창문들)'를 꾸미므로 -s를 붙인 grandes가 됩니다. 형용사는 보통 명사 뒤에 옵니다.","x":["gran: grande가 단수 명사 앞에 올 때 줄어든 형태(un gran día)라 복수 명사 뒤에는 못 씁니다 ✗","las grandes: 이미 명사 앞에 관사 las가 있으므로 관사를 또 넣을 수 없습니다 ✗","grandes: 복수 명사 ventanas에 맞춘 복수형 → 정답 ✓","grande: 단수형이라 복수 명사 ventanas와 수가 맞지 않습니다 ✗"]},{"id":"G302","q":"Bebo café ____ mañana.","o":["por el","el","la","por la"],"a":3,"k":"하루 때 표현","t":"나는 아침에 커피를 마신다.","e":"'아침에, 오후에, 밤에'처럼 하루 중 때를 말할 때는 'por la mañana / por la tarde / por la noche'를 씁니다. mañana(아침)는 여성 명사이므로 관사 la가 붙습니다. 참고로 중남미에서는 'en la mañana'도 많이 씁니다.","x":["por el: mañana는 여성 명사라 남성 관사 el과 맞지 않습니다 ✗","el: 전치사 por가 빠졌고 관사의 성도 틀립니다 ✗","la: 전치사 없이 'la mañana'만 쓰면 '아침에'라는 뜻이 되지 않습니다 ✗","por la: 'por la mañana(아침에)'라는 정해진 표현 → 정답 ✓"]},{"id":"G303","q":"¿____ personas hay en esa clase?","o":["Cuánta","Cuántos","Cuánto","Cuántas"],"a":3,"k":"의문사 cuánto","t":"그 반에는 사람이 몇 명 있니?","e":"'몇 개의, 얼마나 많은'을 묻는 cuánto는 뒤에 오는 명사의 성·수에 맞춰 cuánto/cuánta/cuántos/cuántas로 바뀝니다. personas(사람들)는 여성 복수 명사이므로 cuántas가 맞습니다. 의문사이므로 악센트(á)를 꼭 씁니다.","x":["Cuánta: 여성 단수형이라 복수 명사 personas와 맞지 않습니다 ✗","Cuántos: 남성 복수형인데 persona는 여성 명사입니다 ✗","Cuánto: 남성 단수형이라 성·수 모두 맞지 않습니다 ✗","Cuántas: 여성 복수 명사 personas에 맞는 형태 → 정답 ✓"]},{"id":"G304","q":"¿Puedes dejarme ____ móvil? El mío no tiene batería.","o":["tuyo","tu","el tuyo","tú"],"a":1,"k":"소유형용사 tu","t":"네 휴대폰 좀 빌려줄 수 있어? 내 건 배터리가 없어.","e":"명사 앞에 붙어 '너의'라는 뜻을 나타내는 소유형용사는 tu(악센트 없음)입니다. 'tu móvil(네 휴대폰)'처럼 명사와 함께 씁니다. 반면 el tuyo는 명사를 대신하는 '네 것'이라는 뜻이라 명사 앞에 쓸 수 없습니다. móvil은 스페인에서 쓰는 말이고 중남미에서는 celular라고 합니다.","x":["tuyo: '너의 것'이라는 뜻의 강세형으로 명사 뒤나 단독으로 씁니다(un amigo tuyo) ✗","tu: 명사 앞에 오는 소유형용사 '너의' → 정답 ✓","el tuyo: '네 것'이라는 소유대명사라 뒤에 명사가 올 수 없습니다 ✗","tú: 악센트가 있으면 주어 '너'라는 인칭대명사입니다 ✗"]},{"id":"G305","q":"¿____ sabe a qué hora abre esa papelería?","o":["Algunos","Algo","Alguien","Algún"],"a":2,"k":"부정어 alguien","t":"그 문구점이 몇 시에 여는지 아는 사람 있어요?","e":"alguien은 '누군가, 어떤 사람'을 뜻하는 대명사로 사람을 가리킵니다. 동사 sabe(안다)의 주어가 될 사람이 필요하므로 alguien이 알맞습니다. 사물이면 algo(무언가)를 씁니다. 예: ¿Alguien tiene un bolígrafo?(누구 볼펜 있는 사람?)","x":["Algunos: '몇몇'이라는 복수형이라 단수 동사 sabe와 맞지 않습니다 ✗","Algo: '무언가'라는 사물을 가리키는 말이라 '아는 사람'이 될 수 없습니다 ✗","Alguien: '누군가'라는 사람을 가리키는 대명사 → 정답 ✓","Algún: 남성 단수 명사 앞에만 쓰는 형용사 형태입니다(algún día) ✗"]},{"id":"G306","q":"Me encantan ____ galletas de chocolate.","o":["los","la","las","ø"],"a":2,"k":"gustar류 + 정관사","t":"나는 초콜릿 쿠키를 아주 좋아한다.","e":"encantar(아주 좋아하다), gustar 같은 동사 뒤에 오는 명사는 일반적인 대상을 말할 때도 정관사를 붙입니다. galletas(쿠키들)는 여성 복수 명사이므로 las가 맞습니다. 동사도 복수 명사에 맞춰 encantan이 쓰였습니다.","x":["los: 남성 복수 관사인데 galleta는 여성 명사입니다 ✗","la: 여성 단수 관사라 복수 galletas와 맞지 않습니다 ✗","las: 여성 복수 명사 galletas에 맞는 정관사 → 정답 ✓","ø: gustar/encantar 구문의 주어 명사에는 관사를 생략하지 않습니다 ✗"]},{"id":"G307","q":"____ dos semanas que no veo a Ernesto.","o":["Antes de","Desde hace","Hace","Desde"],"a":2,"k":"hace + 기간","t":"에르네스토를 못 본 지 2주가 됐다.","e":"'~한 지 (기간)이 되었다'는 'Hace + 기간 + que + 동사' 구조로 말합니다. 'Hace dos semanas que no veo a Ernesto'는 '에르네스토를 안 본 지 2주 됐다'라는 뜻입니다. 같은 뜻으로 'No veo a Ernesto desde hace dos semanas'처럼 문장 끝에 desde hace를 쓸 수도 있습니다.","x":["Antes de: '~하기 전에'라는 뜻으로 이 구조에 맞지 않습니다 ✗","Desde hace: 문장 뒤쪽에 올 때 쓰며, 'que'와 함께 문장 맨 앞에는 쓰지 않습니다 ✗","Hace: 'Hace + 기간 + que ...(~한 지 ~ 되다)' 구조 → 정답 ✓","Desde: '~부터'라는 뜻으로 시점(desde lunes) 앞에 쓰며 기간 앞에는 맞지 않습니다 ✗"]},{"id":"G308","q":"¿Puedes darme ____ libro que está ahí?","o":["este","eso","esto","ese"],"a":3,"k":"지시형용사 ese","t":"거기 있는 그 책 좀 줄 수 있니?","e":"지시형용사는 거리에 따라 este(이, 말하는 사람 가까이), ese(그, 듣는 사람 가까이), aquel(저, 둘 다에게서 멀리)로 나뉩니다. 'ahí(거기)'에 있는 책이므로 ese를 씁니다. libro(책)는 남성 단수이므로 ese가 맞습니다.","x":["este: '이'라는 뜻으로 말하는 사람 가까이(aquí) 있는 것에 씁니다 ✗","eso: 중성 대명사 '그것'이라 명사 libro 앞에 쓸 수 없습니다 ✗","esto: 중성 대명사 '이것'이라 명사 앞에 쓸 수 없습니다 ✗","ese: '그(거기 있는)'라는 남성 단수 지시형용사 → 정답 ✓"]},{"id":"G309","q":"Estoy impaciente por conocer ____ novio de mi hija.","o":["el","ø","a","al"],"a":3,"k":"사람 목적어 앞 a","t":"내 딸의 남자친구를 빨리 만나고 싶어 안달이 난다.","e":"직접목적어(~을/를)가 특정한 사람일 때는 앞에 전치사 a를 붙입니다. 여기서는 'a + el novio'가 되는데, a와 el이 만나면 반드시 al로 합쳐집니다. 그래서 'conocer al novio(남자친구를 알게 되다/만나다)'가 됩니다.","x":["el: 사람 목적어 앞에 필요한 전치사 a가 빠졌습니다 ✗","ø: 관사와 전치사가 모두 빠져 문법적으로 틀립니다 ✗","a: 'a el'은 반드시 al로 줄여 써야 하고, 관사도 필요합니다 ✗","al: 'a + el'의 축약형으로 사람 목적어를 표시 → 정답 ✓"]},{"id":"G310","q":"Los bebés ____ llorando.","o":["está","estáis","están","estás"],"a":2,"k":"현재진행 estar","t":"아기들이 울고 있다.","e":"'~하고 있다'는 현재진행형은 'estar + 현재분사(-ando/-iendo)'로 만듭니다. 주어 'Los bebés(아기들)'는 3인칭 복수이므로 estar는 están이 됩니다. 예: Los niños están jugando.(아이들이 놀고 있다.)","x":["está: 3인칭 단수형(그/그녀가)이라 복수 주어와 맞지 않습니다 ✗","estáis: vosotros(너희들) 형태입니다 ✗","están: 3인칭 복수 주어 los bebés에 맞는 형태 → 정답 ✓","estás: tú(너) 형태입니다 ✗"]},{"id":"G311","q":"____ sofá es comodísimo.","o":["Estos","Este","Esta","Esto"],"a":1,"k":"지시형용사 este","t":"이 소파는 정말 편하다.","e":"지시형용사 este(이)는 명사의 성·수에 따라 este/esta/estos/estas로 바뀝니다. sofá는 -á로 끝나지만 남성 명사이고 단수이므로 este를 씁니다. comodísimo는 cómodo(편한)에 -ísimo를 붙여 '아주 편한'이라는 뜻입니다.","x":["Estos: 남성 복수형이라 단수 sofá와 맞지 않습니다 ✗","Este: 남성 단수 명사 sofá에 맞는 형태 → 정답 ✓","Esta: 여성형인데 sofá는 남성 명사입니다 ✗","Esto: 중성 대명사 '이것'으로 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G312","q":"Mi vida actual es menos estresante ____ antes.","o":["a","de","que","de que"],"a":2,"k":"비교급 menos...que","t":"지금 내 삶은 예전보다 스트레스가 덜하다.","e":"'~보다 덜 …하다'는 'menos + 형용사 + que + 비교 대상'으로 표현합니다. 비교 대상이 antes(예전)라는 부사여도 que를 그대로 씁니다. 반대로 '더 …하다'는 'más ... que'입니다.","x":["a: 비교 구문에서 '~보다'로 쓰이지 않습니다 ✗","de: 'más de/menos de'는 숫자 앞(más de diez)에서만 씁니다 ✗","que: 비교급 'menos ... que(~보다 덜)' → 정답 ✓","de que: 비교 구문에 이런 형태는 쓰지 않습니다 ✗"]},{"id":"G313","q":"El curso de japonés empezó hace ____ semanas.","o":["dos","a dos","desde dos","las dos"],"a":0,"k":"hace + 기간(과거)","t":"일본어 수업은 2주 전에 시작했다.","e":"과거 시제 동사와 함께 'hace + 기간'을 쓰면 '(기간) 전에'라는 뜻이 됩니다. 'hace dos semanas'는 '2주 전에'입니다. 기간 앞에는 전치사나 관사를 붙이지 않습니다. 예: Llegué hace una hora.(한 시간 전에 도착했다.)","x":["dos: 'hace dos semanas(2주 전에)' → 정답 ✓","a dos: hace 뒤에 전치사 a는 쓰지 않습니다 ✗","desde dos: hace와 desde를 이런 순서로 함께 쓰지 않습니다 ✗","las dos: 관사를 붙이면 '두 시' 같은 시각의 의미가 되어 맞지 않습니다 ✗"]},{"id":"G314","q":"¿____ vale este cuadro?","o":["Cuánto","Cuándo","Cómo","Cuál"],"a":0,"k":"가격 묻기 cuánto","t":"이 그림은 얼마예요?","e":"가격을 물을 때는 '¿Cuánto vale ...?' 또는 '¿Cuánto cuesta ...?'를 씁니다. 여기서 cuánto는 명사 없이 '얼마'라는 뜻으로 쓰여 형태가 바뀌지 않습니다. valer(가치가 있다, 값이 나가다)는 costar(비용이 들다)와 비슷한 뜻입니다.","x":["Cuánto: '얼마'라는 뜻으로 가격을 묻는 의문사 → 정답 ✓","Cuándo: '언제'라는 뜻으로 가격과 관계없습니다 ✗","Cómo: '어떻게'라는 뜻이라 맞지 않습니다 ✗","Cuál: '어느 것'이라는 뜻이라 가격 질문에 쓰지 않습니다 ✗"]},{"id":"G315","q":"De lunes a viernes siempre ____ a la misma hora.","o":["acostarme","acuesto","me acuesto","yo acuesto"],"a":2,"k":"재귀동사 acostarse","t":"월요일부터 금요일까지 나는 항상 같은 시간에 잠자리에 든다.","e":"acostarse(잠자리에 들다)는 재귀동사(자기 자신에게 동작이 돌아가는 동사)라 주어에 맞는 재귀대명사(me, te, se...)를 동사 앞에 씁니다. 또 o가 ue로 바뀌는 불규칙 동사여서 yo 형태는 'me acuesto'가 됩니다.","x":["acostarme: 동사원형이라 활용된 동사가 필요한 자리에 쓸 수 없습니다 ✗","acuesto: 재귀대명사 me가 빠져 '(누군가를) 재우다'라는 뜻이 됩니다 ✗","me acuesto: 재귀대명사 + yo 활용형 → 정답 ✓","yo acuesto: 주어 yo는 있지만 재귀대명사 me가 없습니다 ✗"]},{"id":"G316","q":"Carmen ____ llega tarde a su trabajo.","o":["nunca no","ni nunca","nunca","no nunca"],"a":2,"k":"부정어 nunca","t":"카르멘은 절대 직장에 지각하지 않는다.","e":"nunca(결코 ~않다)가 동사 앞에 오면 no 없이 혼자 씁니다. 'Carmen nunca llega tarde.' 반대로 nunca가 동사 뒤에 오면 동사 앞에 no를 넣어 'Carmen no llega tarde nunca'처럼 씁니다.","x":["nunca no: 동사 앞에서 nunca와 no를 연달아 쓰지 않습니다 ✗","ni nunca: ni(~도 아니다)는 이 문장 구조에 맞지 않습니다 ✗","nunca: 동사 앞에서 혼자 부정을 나타냄 → 정답 ✓","no nunca: 이런 순서로는 쓰지 않습니다(no llega nunca가 맞음) ✗"]},{"id":"G317","q":"Mi prima tiene ____ pelo castaño y muy largo.","o":["las","los","el","la"],"a":2,"k":"정관사 el","t":"내 사촌(여)은 갈색의 아주 긴 머리를 가지고 있다.","e":"머리카락, 눈 같은 신체 특징을 말할 때는 'tener el pelo + 형용사'처럼 정관사를 씁니다. pelo(머리카락)는 남성 단수 명사이므로 el이 맞습니다. 예: Tiene los ojos azules.(그는 눈이 파랗다.)","x":["las: 여성 복수 관사라 pelo와 맞지 않습니다 ✗","los: 남성 복수 관사인데 pelo는 단수로 씁니다 ✗","el: 남성 단수 명사 pelo에 맞는 정관사 → 정답 ✓","la: 여성 관사인데 pelo는 남성 명사입니다 ✗"]},{"id":"G318","q":"En ____ calle hay muchas tiendas de ropa.","o":["esto","esta","ese","eso"],"a":1,"k":"지시형용사 esta","t":"이 거리에는 옷가게가 많다.","e":"calle(거리)는 여성 단수 명사이므로 지시형용사도 여성 단수형 esta(이)를 씁니다. esto, eso는 중성 대명사라 명사 앞에 붙일 수 없다는 점을 기억하세요.","x":["esto: 중성 대명사 '이것'으로 명사 앞에 쓰지 않습니다 ✗","esta: 여성 단수 명사 calle에 맞는 '이' → 정답 ✓","ese: 남성형인데 calle는 여성 명사입니다 ✗","eso: 중성 대명사 '그것'으로 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G319","q":"Esas mujeres son ____.","o":["españoles","españolas","español","española"],"a":1,"k":"국적 형용사 일치","t":"그 여자들은 스페인 사람이다.","e":"국적 형용사도 주어의 성·수에 맞춥니다. español(스페인의, 남성 단수)은 여성형 española, 남성 복수 españoles, 여성 복수 españolas가 됩니다. 'Esas mujeres(그 여자들)'는 여성 복수이므로 españolas입니다. 스페인어에서는 국적을 소문자로 씁니다.","x":["españoles: 남성 복수형이라 여성 주어 mujeres와 맞지 않습니다 ✗","españolas: 여성 복수형 → 정답 ✓","español: 남성 단수형입니다 ✗","española: 여성 단수형이라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G320","q":"Anabel está casada ____ un futbolista famoso.","o":["de","a","con","para"],"a":2,"k":"casado con","t":"아나벨은 유명한 축구 선수와 결혼했다.","e":"'~와 결혼하다/결혼한 상태이다'는 전치사 con(~와 함께)을 씁니다. 'estar casado/a con alguien(누구와 결혼한 상태이다)', 'casarse con alguien(누구와 결혼하다)'처럼 씁니다. 한국어 '~와'에 해당한다고 생각하면 쉽습니다.","x":["de: '~의, ~로부터'라는 뜻으로 결혼 상대 앞에 쓰지 않습니다 ✗","a: '~에게, ~로'라는 뜻으로 맞지 않습니다 ✗","con: 'casada con(~와 결혼한)' → 정답 ✓","para: '~을 위해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G321","q":"¿____ te gusta más? ¿El bolso negro o el marrón?","o":["Cuánto","Cuántos","Cuál","Cuáles"],"a":2,"k":"의문사 cuál","t":"어느 게 더 마음에 들어? 검은 가방이야, 갈색 가방이야?","e":"정해진 몇 가지 중에서 '어느 것'을 고르라고 물을 때는 cuál을 씁니다. 여기서는 가방 하나(el bolso)를 고르는 것이므로 단수 cuál입니다. 복수 대상 중에서 고를 때는 cuáles를 씁니다.","x":["Cuánto: '얼마나'라는 뜻으로 선택을 묻지 않습니다 ✗","Cuántos: '몇 개'라는 뜻이라 맞지 않습니다 ✗","Cuál: 둘 중 '어느 것(단수)'을 묻는 의문사 → 정답 ✓","Cuáles: 복수형이라 단수 동사 gusta, 단수 bolso와 맞지 않습니다 ✗"]},{"id":"G322","q":"Esos cantantes son muy ____.","o":["famosas","famosos","famoso","famosa"],"a":1,"k":"형용사 성·수 일치","t":"그 가수들은 매우 유명하다.","e":"'Esos cantantes'에서 지시형용사 esos가 남성 복수이므로 이 가수들은 남성(또는 남녀 섞인) 복수입니다. 따라서 famoso(유명한)도 남성 복수 famosos가 됩니다. cantante(가수)는 남녀 형태가 같아서 앞의 관사·지시사로 성을 판단합니다.","x":["famosas: 여성 복수형이라 남성 esos와 맞지 않습니다 ✗","famosos: 남성 복수형 → 정답 ✓","famoso: 단수형이라 복수 주어와 맞지 않습니다 ✗","famosa: 여성 단수형입니다 ✗"]},{"id":"G323","q":"Prefiero ____ té al café.","o":["lo","al","el","del"],"a":2,"k":"preferir A a B","t":"나는 커피보다 차가 더 좋다.","e":"'B보다 A를 더 좋아하다'는 'preferir A a B'로 씁니다. 일반적인 대상을 말할 때도 명사 앞에 정관사를 붙이므로 'el té al café(a + el café = al café)'가 됩니다.","x":["lo: 중성 관사로 명사 té 앞에 쓰지 않습니다 ✗","al: 'a + el'이라 preferir 바로 뒤의 목적어에는 맞지 않습니다 ✗","el: 남성 명사 té 앞의 정관사 → 정답 ✓","del: 'de + el'로 '~의'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G324","q":"¿____ te pasa? ¿Te sientes mal?","o":["Cómo","Cuál","Qué","Quién"],"a":2,"k":"¿Qué te pasa?","t":"무슨 일 있어? 몸이 안 좋아?","e":"'¿Qué te pasa?'는 '너 무슨 일 있어? / 왜 그래?'라는 뜻의 자주 쓰는 표현입니다. qué(무엇)가 동사 pasar(일어나다)의 주어 역할을 하고, te는 '너에게'입니다. 직역하면 '무엇이 너에게 일어나니?'입니다.","x":["Cómo: '어떻게'라는 뜻이라 '무슨 일'을 묻지 못합니다 ✗","Cuál: '어느 것'이라는 선택 의문사라 맞지 않습니다 ✗","Qué: '무엇(무슨 일)' → 정답 ✓","Quién: '누구'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G325","q":"Mi hijo está a punto de cumplir ____ años.","o":["dieci ocho","diez y ocho","dieciocho","diez ocho"],"a":2,"k":"숫자 16~19","t":"내 아들은 곧 열여덟 살이 된다.","e":"16부터 19까지의 숫자는 한 단어로 붙여 씁니다: dieciséis, diecisiete, dieciocho, diecinueve. 'diez y ocho'처럼 떼어 쓰는 것은 옛 표기라 지금은 쓰지 않습니다. 'estar a punto de + 동사원형'은 '막 ~하려는 참이다'라는 뜻입니다.","x":["dieci ocho: 띄어 쓰지 않고 한 단어로 씁니다 ✗","diez y ocho: 현대 스페인어에서는 쓰지 않는 표기입니다 ✗","dieciocho: 18의 올바른 표기 → 정답 ✓","diez ocho: y도 없고 띄어 써서 틀립니다 ✗"]},{"id":"G326","q":"¿Quieres cenar con ____?","o":["nuestras","nuestros","nos","nosotros"],"a":3,"k":"전치사 뒤 대명사","t":"우리랑 같이 저녁 먹을래?","e":"con(~와 함께) 같은 전치사 뒤에는 전치격 대명사를 씁니다. '우리'는 nosotros(남성 또는 혼성) / nosotras(여성만)입니다. 여기서는 nosotros가 맞습니다. 단, '나와 함께'는 conmigo, '너와 함께'는 contigo라는 특별한 형태를 씁니다.","x":["nuestras: '우리의(여성 복수)'라는 소유형용사입니다 ✗","nuestros: '우리의(남성 복수)'라는 소유형용사라 명사가 뒤에 와야 합니다 ✗","nos: 목적격 대명사(우리를/우리에게)라 전치사 뒤에 못 씁니다 ✗","nosotros: 전치사 con 뒤에 오는 '우리' → 정답 ✓"]},{"id":"G327","q":"Pablo y Mariana son ____.","o":["chilenos","chileno","en Chile","a Chile"],"a":0,"k":"국적 형용사","t":"파블로와 마리아나는 칠레 사람이다.","e":"'ser + 국적 형용사'로 어느 나라 사람인지 말합니다. 주어가 남자와 여자가 섞인 복수이면 남성 복수형을 쓰므로 chilenos가 됩니다. 출신지를 나라 이름으로 말하려면 'son de Chile'처럼 de를 씁니다.","x":["chilenos: 남녀 혼성 복수에 쓰는 남성 복수형 → 정답 ✓","chileno: 단수형이라 두 사람 주어와 맞지 않습니다 ✗","en Chile: 'ser en Chile'는 출신을 나타내지 못합니다(있는 곳은 estar en) ✗","a Chile: '칠레로'라는 방향 표현이라 맞지 않습니다 ✗"]},{"id":"G328","q":"En mi tiempo ____ paseo con mi perro o hago deporte.","o":["libra","libres","libre","libro"],"a":2,"k":"tiempo libre","t":"여가 시간에 나는 개와 산책을 하거나 운동을 한다.","e":"'tiempo libre'는 '자유 시간, 여가 시간'이라는 자주 쓰는 표현입니다. libre(자유로운)는 남녀 형태가 같고, tiempo가 단수이므로 libre를 씁니다. pasear con el perro는 '개와 산책하다'입니다.","x":["libra: '파운드(무게·화폐 단위)'라는 명사입니다 ✗","libres: 복수형이라 단수 tiempo와 맞지 않습니다 ✗","libre: '자유로운' 단수형, 'tiempo libre(여가 시간)' → 정답 ✓","libro: '책'이라는 명사입니다 ✗"]},{"id":"G329","q":"Nosotras ____ colombianas.","o":["somos","son","soy","sois"],"a":0,"k":"ser 현재 활용","t":"우리(여자들)는 콜롬비아 사람이다.","e":"국적은 변하지 않는 특징이라 동사 ser로 말합니다. 주어 nosotras(우리, 여성)는 1인칭 복수이므로 ser의 형태는 somos입니다. ser 현재: soy, eres, es, somos, sois, son.","x":["somos: nosotros/nosotras(우리) 형태 → 정답 ✓","son: ellos/ustedes(그들/여러분) 형태입니다 ✗","soy: yo(나) 형태입니다 ✗","sois: vosotros(너희들) 형태입니다 ✗"]},{"id":"G330","q":"¿Cuál es ____ desierto más grande del mundo?","o":["uno","el","un","ø"],"a":1,"k":"최상급 el más","t":"세계에서 가장 큰 사막은 어디야?","e":"'가장 ~한'이라는 최상급은 '정관사 + 명사 + más + 형용사 (+ de ...)'로 만듭니다. desierto(사막)는 남성 단수이므로 'el desierto más grande del mundo(세계에서 가장 큰 사막)'가 됩니다. 비교 범위는 de(~ 중에서)로 나타냅니다.","x":["uno: 숫자/대명사 '하나'로 명사 앞에 쓰지 않습니다(un이 됨) ✗","el: 최상급에 필요한 정관사 → 정답 ✓","un: 부정관사를 쓰면 '가장 ~한' 뜻이 되지 않습니다 ✗","ø: 최상급에서는 정관사를 생략할 수 없습니다 ✗"]},{"id":"G331","q":"Siempre me ducho ____ desayunar.","o":["antes que","desde antes","antes","antes de"],"a":3,"k":"antes de + 동사원형","t":"나는 항상 아침을 먹기 전에 샤워를 한다.","e":"'~하기 전에'는 'antes de + 동사원형'으로 씁니다. 'antes de desayunar(아침 먹기 전에)'처럼 de가 꼭 필요합니다. 반대로 '~한 후에'는 'después de + 동사원형'입니다.","x":["antes que: 주로 비교(~보다 먼저)나 뒤에 문장이 올 때 쓰며 동사원형 앞에는 de를 씁니다 ✗","desde antes: '그 전부터'라는 뜻으로 맞지 않습니다 ✗","antes: 전치사 de가 빠져 동사원형과 연결되지 않습니다 ✗","antes de: '~하기 전에' + 동사원형 → 정답 ✓"]},{"id":"G332","q":"Don Esteban está esperando ____ su esposa.","o":["ø","por","en","a"],"a":3,"k":"esperar a + 사람","t":"에스테반 씨는 부인을 기다리고 있다.","e":"esperar(기다리다)의 목적어가 특정한 사람이면 앞에 전치사 a를 붙입니다. 'esperar a su esposa(부인을 기다리다)'. 한국어의 '~을/를'처럼 생각하면 되며, 사물이면 a 없이 'esperar el autobús'라고 합니다. 중남미 일부에서는 'esperar por'도 들리지만 표준형은 a입니다.","x":["ø: 사람 목적어 앞에 필요한 a가 빠졌습니다 ✗","por: 일부 지역 구어 외에는 쓰지 않는 표현입니다 ✗","en: '~에서'라는 장소 전치사라 맞지 않습니다 ✗","a: 사람 직접목적어 앞에 붙는 a → 정답 ✓"]},{"id":"G333","q":"Hoy ____ nublado, no se ve el sol.","o":["está","es","están","estamos"],"a":0,"k":"날씨 estar nublado","t":"오늘은 날이 흐려서 해가 안 보인다.","e":"'흐리다'는 날씨 상태이므로 'estar nublado'로 말합니다. 주어는 따로 없고 3인칭 단수형 está를 씁니다. 다른 날씨 표현은 hacer(hace calor/frío/sol)를 많이 씁니다.","x":["está: 'estar nublado(흐리다)'의 3인칭 단수 → 정답 ✓","es: ser는 날씨의 일시적 상태에 쓰지 않습니다 ✗","están: 복수형이라 주어 없는 날씨 표현과 맞지 않습니다 ✗","estamos: '우리가'라는 주어가 되어 뜻이 맞지 않습니다 ✗"]},{"id":"G334","q":"Ese niño está llorando. ¿____ ves?","o":["A él","Lo","La","Él"],"a":1,"k":"직접목적격 lo","t":"저 아이가 울고 있어. 그 애 보여?","e":"'그를/그것을'처럼 '~을/를'에 해당하는 직접목적격 대명사는 lo(남성 단수), la(여성 단수), los, las입니다. ese niño(그 남자아이)는 남성 단수이므로 lo를 쓰며, 활용된 동사 ves 앞에 둡니다.","x":["A él: 강조용으로 쓸 수는 있지만 대명사 lo 없이 혼자는 쓸 수 없습니다 ✗","Lo: 남성 단수 직접목적격 '그를' → 정답 ✓","La: 여성 단수형이라 niño와 맞지 않습니다 ✗","Él: 주격 '그는'이라 목적어 자리에 못 씁니다 ✗"]},{"id":"G335","q":"¿____ te ha parecido la película?","o":["Quién","Qué","Cuál","De qué"],"a":1,"k":"¿Qué te ha parecido?","t":"영화 어땠어?","e":"의견이나 인상을 물을 때는 '¿Qué te parece...?' 또는 '¿Qué te ha parecido...?'를 씁니다. 직역하면 '그 영화가 너에게 무엇처럼 보였니?'로, 한국어 '어땠어?'에 해당합니다. 'Cómo'를 쓰는 사람도 있지만 이 표현에서는 qué가 기본입니다.","x":["Quién: '누구'라는 뜻이라 의견을 묻지 못합니다 ✗","Qué: '¿Qué te ha parecido?(어땠어?)' → 정답 ✓","Cuál: '어느 것'이라는 선택 의문사라 맞지 않습니다 ✗","De qué: '무엇에 대해/무엇으로'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G336","q":"Borja no quiere ir a la playa y su novia ____.","o":["tampoco no","tampoco","no","también"],"a":1,"k":"tampoco","t":"보르하는 해변에 가고 싶어 하지 않고, 그의 여자친구도 마찬가지다.","e":"앞 문장이 부정문일 때 '~도 역시 아니다'는 tampoco를 씁니다. 긍정문에 동의할 때는 también(~도 역시)을 씁니다. tampoco 자체에 부정의 뜻이 있으므로 no를 붙이지 않습니다.","x":["tampoco no: tampoco에 이미 부정 뜻이 있어 no를 겹쳐 쓰지 않습니다 ✗","tampoco: 부정문에 '~도 아니다'로 동의 → 정답 ✓","no: 혼자 쓰면 '아니다'일 뿐 '~도 역시'라는 뜻이 없습니다 ✗","también: 긍정문에 동의할 때 씁니다 ✗"]},{"id":"G337","q":"Voy al gimnasio tres veces ____ semana.","o":["de","por","para","a"],"a":1,"k":"빈도 por semana","t":"나는 일주일에 세 번 헬스장에 간다.","e":"'일주일에 ~번'은 '~ veces por semana' 또는 '~ veces a la semana'라고 합니다. 보기 중에는 관사 없이 쓸 수 있는 por가 맞습니다. 예: dos veces por día / al día(하루에 두 번).","x":["de: 빈도 표현에 de는 쓰지 않습니다 ✗","por: 'tres veces por semana(일주일에 세 번)' → 정답 ✓","para: '~을 위해'라는 뜻이라 맞지 않습니다 ✗","a: a를 쓰려면 관사가 필요합니다(a la semana) ✗"]},{"id":"G338","q":"En mi tiempo libre me gusta escuchar ____ música.","o":["de la","ø","la","a la"],"a":1,"k":"관사 생략","t":"여가 시간에 나는 음악 듣는 것을 좋아한다.","e":"escuchar(듣다)는 전치사 없이 바로 목적어를 받습니다. 그리고 특정한 음악이 아니라 '음악'이라는 막연한 대상일 때는 관사 없이 'escuchar música'라고 하는 것이 가장 자연스럽습니다.","x":["de la: escuchar 뒤에 de는 쓰지 않습니다 ✗","ø: 막연한 대상 '음악을 듣다' → 정답 ✓","la: 'la música'라고 하면 특정한 음악을 가리키는 느낌이 됩니다 ✗","a la: escuchar는 사물 목적어 앞에 a를 쓰지 않습니다 ✗"]},{"id":"G339","q":"¿____ qué barrio os gustaría vivir?","o":["A","Desde","Con","En"],"a":3,"k":"vivir en","t":"너희는 어느 동네에 살고 싶니?","e":"'~에 살다'는 'vivir en + 장소'입니다. 의문문으로 만들면 전치사가 의문사 앞으로 와서 '¿En qué barrio...?(어느 동네에?)'가 됩니다. os gustaría는 '너희는 ~하고 싶니?'라는 공손한 표현이며, vosotros는 스페인에서만 쓰입니다(중남미는 les gustaría).","x":["A: '~로(방향)'라는 뜻이라 사는 장소에 쓰지 않습니다 ✗","Desde: '~부터'라는 뜻이라 맞지 않습니다 ✗","Con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗","En: 'vivir en(~에 살다)'의 장소 전치사 → 정답 ✓"]},{"id":"G340","q":"¿Tienes alguna pregunta? —No, no tengo ____.","o":["algún","ninguna","ningún","alguna"],"a":1,"k":"부정어 ninguna","t":"질문 있니? —아니, 하나도 없어.","e":"부정문에서 '하나도 ~없다'는 ninguno/ninguna를 씁니다. 여기서는 생략된 명사 pregunta(질문)가 여성이므로 ninguna입니다. 질문의 alguna가 긍정, 대답의 ninguna가 부정 짝이라고 기억하세요.","x":["algún: 긍정 표현이고 남성 명사 앞에만 씁니다 ✗","ninguna: 여성 명사 pregunta를 대신하는 부정어 → 정답 ✓","ningún: 남성 명사 바로 앞에서만 쓰는 형태입니다 ✗","alguna: '어떤 것'이라는 긍정이라 no와 함께 쓰지 않습니다 ✗"]},{"id":"G341","q":"No soporto la comida picante. — ____ tampoco.","o":["Yo","Me","Mí","A mí"],"a":0,"k":"yo tampoco","t":"나는 매운 음식을 못 참아. —나도 그래.","e":"soportar(참다, 견디다)는 일반 동사라 주어는 yo입니다. 그래서 '나도 아니야'는 'Yo tampoco'가 됩니다. 만약 앞 문장이 'No me gusta...'처럼 gustar 구문이었다면 'A mí tampoco'라고 답합니다.","x":["Yo: 일반 동사 soportar의 주어 '나' → 정답 ✓","Me: 목적격 대명사라 혼자 대답에 쓸 수 없습니다 ✗","Mí: 전치사 없이는 쓰지 않는 형태입니다 ✗","A mí: gustar류 동사에 답할 때 쓰는 형태입니다 ✗"]},{"id":"G342","q":"¡Qué calor ____ hoy!","o":["hago","hacen","haces","hace"],"a":3,"k":"날씨 hacer","t":"오늘 정말 덥다!","e":"덥다, 춥다 같은 날씨는 동사 hacer의 3인칭 단수 hace로 말합니다: hace calor(덥다), hace frío(춥다), hace sol(해가 난다). '¡Qué calor hace!'는 '정말 덥다!'라는 감탄문입니다.","x":["hago: yo(나) 형태라 날씨 표현에 쓰지 않습니다 ✗","hacen: 3인칭 복수형이라 맞지 않습니다 ✗","haces: tú(너) 형태입니다 ✗","hace: 날씨를 나타내는 3인칭 단수 → 정답 ✓"]},{"id":"G343","q":"Disculpe, ¿sabe si el ayuntamiento ____ muy lejos de aquí?","o":["tiene","está","es","hay"],"a":1,"k":"위치 estar","t":"실례합니다, 시청이 여기서 많이 먼지 아세요?","e":"사람이나 사물이 어디에 있는지(위치)를 말할 때는 estar를 씁니다. 'estar lejos/cerca(멀다/가깝다)'도 위치 표현입니다. 특정한 대상(el ayuntamiento)의 위치이므로 hay가 아닌 está입니다.","x":["tiene: '가지고 있다'라는 뜻이라 맞지 않습니다 ✗","está: 특정 장소의 위치를 나타내는 estar → 정답 ✓","es: ser는 사물의 위치에 쓰지 않습니다 ✗","hay: '~이 있다'는 존재 표현으로 정관사 붙은 특정 대상에는 쓰지 않습니다 ✗"]},{"id":"G344","q":"El sábado pasado mi padre ____ un pastel delicioso.","o":["hace","hacen","hizo","hice"],"a":2,"k":"hacer 단순과거","t":"지난 토요일에 아버지가 맛있는 케이크를 만들었다.","e":"'el sábado pasado(지난 토요일)'는 끝난 과거이므로 단순과거(부정과거)를 씁니다. hacer의 단순과거는 불규칙으로 hice, hiciste, hizo...이며, 주어 mi padre는 3인칭 단수라 hizo입니다.","x":["hace: 현재형이라 지난 토요일과 맞지 않습니다 ✗","hacen: 현재 3인칭 복수형입니다 ✗","hizo: hacer 단순과거 3인칭 단수 → 정답 ✓","hice: 단순과거 yo(나) 형태입니다 ✗"]},{"id":"G345","q":"No tienes ____ repetirlo, ya te he escuchado.","o":["de","por","que","a"],"a":2,"k":"tener que","t":"다시 말할 필요 없어, 이미 들었어.","e":"'~해야 한다'는 'tener que + 동사원형'입니다. 부정문 'no tener que + 동사원형'은 '~할 필요가 없다'라는 뜻이 됩니다. repetirlo는 repetir(반복하다)에 lo(그것을)가 붙은 형태입니다.","x":["de: 'tener de'는 현대 스페인어에서 이 뜻으로 쓰지 않습니다 ✗","por: 이 구조에 por는 쓰지 않습니다 ✗","que: 'tener que(~해야 하다)' → 정답 ✓","a: 이 구조에 a는 쓰지 않습니다 ✗"]},{"id":"G346","q":"¿Qué os pasa? ¿Por qué ____ tristes?","o":["estáis","estás","están","estamos"],"a":0,"k":"estar + 감정","t":"너희 무슨 일이야? 왜 슬퍼해?","e":"슬프다, 기쁘다 같은 일시적인 감정·상태는 estar로 말합니다. 앞 문장 '¿Qué os pasa?'의 os가 vosotros(너희)이므로 동사도 vosotros 형태인 estáis가 맞습니다. 중남미에서는 ustedes를 써서 '¿Qué les pasa? ¿Por qué están tristes?'라고 합니다.","x":["estáis: vosotros(너희) 형태 → 정답 ✓","estás: tú(너) 단수 형태입니다 ✗","están: ellos/ustedes 형태로 앞의 os와 맞지 않습니다 ✗","estamos: '우리' 형태입니다 ✗"]},{"id":"G347","q":"Tengo fiebre y dolor ____ garganta.","o":["de","por","a","para"],"a":0,"k":"dolor de","t":"나는 열이 나고 목이 아프다.","e":"'~의 통증, ~가 아픔'은 'dolor de + 신체 부위'로 씁니다: dolor de garganta(목 통증), dolor de cabeza(두통), dolor de estómago(복통). 이때 신체 부위 앞에 관사를 붙이지 않습니다.","x":["de: 'dolor de garganta(인후통)' → 정답 ✓","por: '~ 때문에'라는 뜻이라 맞지 않습니다 ✗","a: 이 표현에 a는 쓰지 않습니다 ✗","para: '~을 위해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G348","q":"En ese jardín hay ____ flores de muchos tipos.","o":["las","los","ø","el"],"a":2,"k":"hay + 관사 없음","t":"그 정원에는 여러 종류의 꽃이 있다.","e":"hay(~이 있다)는 처음 소개하는 막연한 대상에 쓰므로 뒤에 정관사(el, la, los, las)를 붙이지 않습니다. 복수 명사는 관사 없이 'hay flores(꽃들이 있다)'라고 합니다. 단수는 'hay un/una ...'처럼 부정관사를 씁니다.","x":["las: hay 뒤에 정관사는 쓰지 않습니다 ✗","los: 정관사이고 성도 맞지 않습니다 ✗","ø: hay + 관사 없는 복수 명사 → 정답 ✓","el: 정관사이고 성·수도 맞지 않습니다 ✗"]},{"id":"G349","q":"Si tenéis alguna duda, ____.","o":["dímelo","decidlo a mí","decídmelo","díganlo"],"a":2,"k":"vosotros 명령+대명사","t":"너희가 궁금한 게 있으면 나한테 말해.","e":"앞 문장의 tenéis로 보아 상대는 vosotros(너희)입니다. decir의 vosotros 긍정 명령은 decid인데, 대명사 me(나에게)와 lo(그것을)를 붙이면 끝의 d는 유지되어 decídmelo가 되고 악센트가 붙습니다. 긍정 명령에서는 대명사를 '간접(me) → 직접(lo)' 순서로 동사 끝에 붙입니다.","x":["dímelo: tú(너) 명령형이라 vosotros와 맞지 않습니다 ✗","decidlo a mí: 'a mí'만 쓰고 대명사 me를 빼면 틀립니다 ✗","decídmelo: vosotros 명령 + me + lo → 정답 ✓","díganlo: ustedes 명령형이고 me도 빠졌습니다 ✗"]},{"id":"G350","q":"____ vaso no es de vidrio, es de plástico.","o":["Esto","Aquella","Eso","Este"],"a":3,"k":"지시형용사 este","t":"이 컵은 유리가 아니라 플라스틱이다.","e":"vaso(컵)는 남성 단수 명사이므로 지시형용사는 este(이)나 ese(그)를 써야 합니다. 보기 중 남성 단수 지시형용사는 Este뿐입니다. 'ser de + 재료'는 '~로 만들어졌다'라는 뜻입니다.","x":["Esto: 중성 대명사 '이것'이라 명사 앞에 쓰지 않습니다 ✗","Aquella: 여성형인데 vaso는 남성 명사입니다 ✗","Eso: 중성 대명사 '그것'이라 명사 앞에 쓰지 않습니다 ✗","Este: 남성 단수 명사 vaso 앞의 '이' → 정답 ✓"]},{"id":"G351","q":"Esa bicicleta no es ____, es de Carlos.","o":["mías","de mí","mí","mía"],"a":3,"k":"소유대명사 mía","t":"그 자전거는 내 것이 아니라 카를로스 것이다.","e":"'내 것'은 ser 뒤에 소유형용사 강세형 mío/mía/míos/mías를 씁니다. bicicleta(자전거)가 여성 단수이므로 mía가 됩니다. 'de mí'는 '나의'라는 뜻으로 쓰지 않습니다.","x":["mías: 여성 복수형이라 단수 bicicleta와 맞지 않습니다 ✗","de mí: 소유를 나타낼 때 이렇게 쓰지 않습니다 ✗","mí: 전치사 뒤에 쓰는 '나'라서 소유를 나타내지 못합니다 ✗","mía: 여성 단수 '내 것' → 정답 ✓"]},{"id":"G352","q":"¿Es verdad que ____ regalo es para mí?","o":["esta","este","esto","estos"],"a":1,"k":"지시형용사 este","t":"이 선물이 나를 위한 거라는 게 정말이야?","e":"regalo(선물)는 남성 단수 명사이므로 지시형용사 este(이)를 씁니다. 'para mí'는 '나를 위한'이라는 뜻이고, 전치사 뒤의 mí에는 악센트가 있습니다.","x":["esta: 여성형인데 regalo는 남성 명사입니다 ✗","este: 남성 단수 '이' → 정답 ✓","esto: 중성 대명사라 명사 앞에 쓰지 않습니다 ✗","estos: 복수형이라 단수 regalo와 맞지 않습니다 ✗"]},{"id":"G353","q":"Los niños están viendo ____ la tele ahora.","o":["en","a","de","ø"],"a":3,"k":"ver la tele","t":"아이들은 지금 텔레비전을 보고 있다.","e":"ver(보다)는 사물 목적어를 전치사 없이 바로 받습니다. 그래서 'ver la tele(텔레비전을 보다)'가 됩니다. tele는 televisión의 줄임말입니다. 한국어 '텔레비전에서'에 이끌려 en을 넣지 않도록 주의하세요.","x":["en: ver 뒤에 en은 필요 없습니다 ✗","a: 사물 목적어 앞에 a는 쓰지 않습니다 ✗","de: '~의'라는 뜻이라 맞지 않습니다 ✗","ø: 전치사 없이 'ver la tele' → 정답 ✓"]},{"id":"G354","q":"En este momento, Juana ____ presentando su nuevo libro.","o":["está","estoy","están","estás"],"a":0,"k":"현재진행 estar","t":"지금 후아나는 자신의 새 책을 소개하고 있다.","e":"'En este momento(지금 이 순간)'에 진행 중인 동작은 'estar + 현재분사'로 말합니다. 주어 Juana는 3인칭 단수이므로 está presentando가 됩니다.","x":["está: 3인칭 단수 Juana에 맞는 형태 → 정답 ✓","estoy: yo(나) 형태입니다 ✗","están: 3인칭 복수형입니다 ✗","estás: tú(너) 형태입니다 ✗"]},{"id":"G355","q":"No me gustan estas gafas, prefiero ____ que están allí.","o":["ø","la","los","las"],"a":3,"k":"관사의 명사 대용","t":"이 안경은 마음에 안 들어, 저기 있는 것들이 더 좋아.","e":"앞에 나온 명사를 반복하지 않고 '정관사 + que ...'로 '~한 것'을 나타낼 수 있습니다. gafas(안경)는 항상 여성 복수로 쓰므로 'las que están allí(저기 있는 것들)'가 됩니다. 중남미에서는 안경을 lentes, anteojos라고도 합니다.","x":["ø: que 앞에 관사가 없으면 '~한 것'이라는 뜻이 되지 않습니다 ✗","la: 단수형이라 복수 gafas와 맞지 않습니다 ✗","los: 남성형인데 gafas는 여성 명사입니다 ✗","las: 여성 복수 gafas를 대신하는 관사 → 정답 ✓"]},{"id":"G356","q":"¿Con ____ estabas hablando antes?","o":["quién","dónde","cómo","cuánto"],"a":0,"k":"con quién","t":"아까 누구랑 이야기하고 있었어?","e":"'누구와'는 전치사 con + 의문사 quién으로 '¿Con quién...?'이라고 합니다. 스페인어에서는 전치사가 의문사 앞에 와야 합니다. estabas hablando는 과거진행(~하고 있었다)입니다.","x":["quién: '누구' → 'con quién(누구와)' → 정답 ✓","dónde: '어디'라는 뜻이라 con 뒤에 맞지 않습니다 ✗","cómo: '어떻게'라는 뜻이라 맞지 않습니다 ✗","cuánto: '얼마나'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G357","q":"¿Qué sueles hacer ____ sábados?","o":["el","los","a","a los"],"a":1,"k":"요일 + 관사 los","t":"토요일마다 보통 뭐 해?","e":"'매주 토요일에, 토요일마다'는 전치사 없이 복수 정관사를 붙여 'los sábados'라고 합니다. 단수 'el sábado'는 '(이번) 토요일에'라는 뜻입니다. soler + 동사원형은 '보통 ~하다'라는 뜻입니다.","x":["el: 단수라 특정한 한 토요일을 뜻해 '보통 하는 일'과 맞지 않습니다 ✗","los: 'los sábados(토요일마다)' → 정답 ✓","a: 요일 앞에 a는 쓰지 않습니다 ✗","a los: 요일 앞에는 전치사 없이 관사만 씁니다 ✗"]},{"id":"G358","q":"____ día de mi cumpleaños siempre celebro una fiesta en mi casa.","o":["Un","Una","El","La"],"a":2,"k":"정관사 el día","t":"내 생일날에는 항상 집에서 파티를 연다.","e":"'내 생일날'은 특정한 날이므로 정관사를 씁니다. día는 -a로 끝나지만 남성 명사라 el día가 됩니다. 날짜·요일처럼 '~날에'라는 시간 표현은 전치사 없이 'el día ...'로 말합니다.","x":["Un: '어느 하루'라는 막연한 뜻이 되어 맞지 않습니다 ✗","Una: 여성형인데 día는 남성 명사입니다 ✗","El: 남성 명사 día 앞 정관사 → 정답 ✓","La: día는 남성 명사라 la를 쓰지 않습니다 ✗"]},{"id":"G359","q":"¿____ dónde son tus amigos?","o":["En","A","De","Desde"],"a":2,"k":"ser de (출신)","t":"네 친구들은 어디 출신이야?","e":"출신지를 말할 때는 'ser de + 장소'를 씁니다. 물을 때는 전치사 de가 의문사 앞으로 가서 '¿De dónde son...?(어디 출신이야?)'가 됩니다. 대답 예: Son de Perú.(페루 출신이야.)","x":["En: 'ser en'은 출신을 나타내지 않습니다 ✗","A: '~로'라는 방향이라 맞지 않습니다 ✗","De: 'ser de(~ 출신이다)' → 정답 ✓","Desde: '~부터'라는 출발점 표현이라 출신과 맞지 않습니다 ✗"]},{"id":"G360","q":"Somos ____ amigos de Teresa.","o":["mejores","mejor","los mejores","las mejores"],"a":2,"k":"최상급 los mejores","t":"우리는 테레사의 가장 친한 친구들이다.","e":"'가장 좋은, 최고의'는 '정관사 + mejor(es)'로 나타냅니다. amigos가 남성(또는 혼성) 복수이므로 'los mejores amigos(가장 친한 친구들)'가 됩니다. 관사가 없으면 '더 좋은'이라는 비교급이 됩니다.","x":["mejores: 관사가 없어 '가장'이라는 최상급 뜻이 되지 않습니다 ✗","mejor: 단수형이고 관사도 없습니다 ✗","los mejores: 남성 복수 최상급 → 정답 ✓","las mejores: 여성형이라 amigos와 맞지 않습니다 ✗"]},{"id":"G361","q":"Mira, ahí ____ Alfonso.","o":["es","está","hay","están"],"a":1,"k":"위치 estar","t":"봐, 저기 알폰소가 있어.","e":"이름이 있는 특정한 사람이나 사물이 어디에 있는지 말할 때는 estar를 씁니다. 'Ahí está Alfonso(저기 알폰소가 있다)'. hay는 막연한 존재(~이 있다)에만 쓰고 고유명사와는 쓰지 않습니다.","x":["es: ser는 위치를 나타내지 않습니다 ✗","está: 특정 인물의 위치를 나타내는 3인칭 단수 → 정답 ✓","hay: 특정 인물(고유명사)에는 쓰지 않습니다 ✗","están: 복수형이라 한 사람 Alfonso와 맞지 않습니다 ✗"]},{"id":"G362","q":"Disculpe, ¿me ____ la hora, por favor?","o":["diga","dices","dice","digo"],"a":2,"k":"usted 활용","t":"실례합니다, 지금 몇 시인지 알려 주시겠어요?","e":"'Disculpe(실례합니다)'는 usted(당신)에게 쓰는 형태이므로 상대는 usted입니다. usted는 3인칭 단수 동사를 쓰므로 decir의 현재형 dice가 맞습니다. '¿Me dice la hora?'는 직역하면 '저에게 시간을 말해 주시나요?'로, 공손하게 시각을 묻는 표현입니다.","x":["diga: 접속법/명령형이라 의문문에서 이렇게 쓰지 않습니다 ✗","dices: tú(너) 형태라 Disculpe(usted)와 맞지 않습니다 ✗","dice: usted에 맞는 3인칭 단수 현재형 → 정답 ✓","digo: yo(나) 형태입니다 ✗"]},{"id":"G363","q":"El cumpleaños de Marina es el 13 ____ marzo.","o":["de","en","a","por"],"a":0,"k":"날짜 표현 de","t":"마리나의 생일은 3월 13일이다.","e":"날짜는 'el + 숫자 + de + 월'로 말합니다. 'el 13 de marzo(3월 13일)'. 월 이름은 소문자로 씁니다. 연도까지 말하면 'el 13 de marzo de 2025'처럼 de를 한 번 더 씁니다.","x":["de: 'el 13 de marzo' → 정답 ✓","en: 날짜 사이에는 en을 쓰지 않습니다 ✗","a: 날짜 표현에 a는 쓰지 않습니다 ✗","por: 날짜 표현에 por는 쓰지 않습니다 ✗"]},{"id":"G364","q":"Es verdad que Ana saca mejores notas ____ Manuel.","o":["que","a que","de","de que"],"a":0,"k":"비교급 mejor que","t":"아나가 마누엘보다 성적이 더 좋은 건 사실이다.","e":"mejor(더 좋은)는 bueno의 불규칙 비교급이고, '~보다'는 que로 나타냅니다. 'mejores notas que Manuel(마누엘보다 더 좋은 성적)'. sacar notas는 '성적을 받다'라는 뜻입니다.","x":["que: 비교 대상 앞의 '~보다' → 정답 ✓","a que: 비교에 쓰지 않는 형태입니다 ✗","de: 숫자 앞이 아니므로 비교 대상 앞에 쓰지 않습니다 ✗","de que: 비교에 쓰지 않는 형태입니다 ✗"]},{"id":"G365","q":"¿____ puede ayudarme a llevar estas cajas?","o":["De quién","A quién","Quién","Quiénes"],"a":2,"k":"의문사 quién","t":"누가 이 상자들 옮기는 것 좀 도와줄 수 있어요?","e":"동사 puede(할 수 있다)의 주어가 '누구'인지 묻고 있으므로 quién을 씁니다. 동사가 단수(puede)이므로 단수형 quién이 맞습니다. 주어를 물을 때는 앞에 전치사가 붙지 않습니다.","x":["De quién: '누구의'라는 소유를 묻는 표현입니다 ✗","A quién: '누구를/누구에게'라는 목적어 질문입니다 ✗","Quién: 단수 주어 '누가' → 정답 ✓","Quiénes: 복수형이라 단수 동사 puede와 맞지 않습니다 ✗"]},{"id":"G366","q":"No tengo ningún problema con ____ de mis compañeros.","o":["ningunos","ninguna","ningún","ninguno"],"a":3,"k":"부정어 ninguno","t":"나는 동료 중 누구와도 문제가 없다.","e":"'~ 중 아무도/하나도 ~않다'는 'ninguno/ninguna de + 복수 명사'로 씁니다. compañeros가 남성 복수이므로 ninguno가 됩니다. 명사 바로 앞이 아니라 de 앞에 오므로 줄인 형태 ningún이 아닌 ninguno를 씁니다.","x":["ningunos: 복수형은 거의 쓰지 않으며 여기서는 틀립니다 ✗","ninguna: 여성형이라 남성 compañeros와 맞지 않습니다 ✗","ningún: 남성 단수 명사 바로 앞에만 쓰는 형태입니다 ✗","ninguno: 'ninguno de(~ 중 아무도)' → 정답 ✓"]},{"id":"G367","q":"Ayer tuve ____ día complicado.","o":["una","uno","la","un"],"a":3,"k":"부정관사 un","t":"어제는 복잡한(힘든) 하루였다.","e":"처음 언급하는 막연한 대상 '어떤 하루'에는 부정관사를 씁니다. día는 -a로 끝나도 남성 명사이므로 un día가 됩니다. uno는 명사 앞에서 반드시 un으로 줄여 씁니다.","x":["una: 여성형인데 día는 남성 명사입니다 ✗","uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","la: 여성 정관사라 성이 맞지 않습니다 ✗","un: 남성 단수 부정관사 → 정답 ✓"]},{"id":"G368","q":"____ a Lucía que me llame por teléfono, por favor.","o":["Dilo","Di le","Dile","Dila"],"a":2,"k":"명령형 + le","t":"루시아에게 나한테 전화하라고 말해 줘.","e":"decir의 tú 긍정 명령은 불규칙형 di입니다. '그녀에게'라는 간접목적격 대명사 le를 명령형 끝에 붙여 한 단어 dile가 됩니다. 'a Lucía'가 있어도 le를 함께 쓰는 것이 자연스럽습니다.","x":["Dilo: lo는 직접목적격(그것을)이라 '루시아에게'와 맞지 않습니다 ✗","Di le: 긍정 명령에서는 대명사를 붙여 한 단어로 씁니다 ✗","Dile: di + le(그녀에게) → 정답 ✓","Dila: la는 직접목적격(그녀를)이라 decir의 '~에게'와 맞지 않습니다 ✗"]},{"id":"G369","q":"Gracias, ya no quiero comer ____ más, estoy lleno.","o":["nada","algún","nadie","algo"],"a":0,"k":"부정어 nada","t":"고마워, 이제 아무것도 더 먹고 싶지 않아, 배불러.","e":"no가 있는 부정문에서 '아무것도'는 nada를 씁니다. 스페인어는 부정어를 겹쳐 쓰는 언어라 'no quiero nada(아무것도 원하지 않는다)'가 맞습니다. 'nada más'는 '더 이상 아무것도'라는 뜻입니다.","x":["nada: 부정문의 '아무것도' → 정답 ✓","algún: '어떤'이라는 긍정 형용사로 명사가 필요합니다 ✗","nadie: '아무도'라는 사람을 가리키는 말입니다 ✗","algo: '무언가'라는 긍정어라 no와 함께 쓰지 않습니다 ✗"]},{"id":"G370","q":"Mis sobrinos son muy ____.","o":["gracioso","graciosos","graciosas","graciosa"],"a":1,"k":"형용사 성·수 일치","t":"내 조카들은 아주 재미있다.","e":"sobrinos(조카들)는 남성 또는 남녀 혼성 복수이므로 형용사도 남성 복수형을 씁니다. gracioso(재미있는, 웃긴)의 남성 복수형은 graciosos입니다.","x":["gracioso: 단수형이라 복수 sobrinos와 맞지 않습니다 ✗","graciosos: 남성 복수형 → 정답 ✓","graciosas: 여성 복수형이라 sobrinos와 맞지 않습니다 ✗","graciosa: 여성 단수형입니다 ✗"]},{"id":"G371","q":"Vivo ____ 50 kilómetros de aquí.","o":["a","para","de","en"],"a":0,"k":"거리 표현 a","t":"나는 여기서 50킬로미터 떨어진 곳에 산다.","e":"'~만큼 떨어진 곳에'라는 거리는 전치사 a로 나타냅니다. 'a 50 kilómetros de aquí(여기서 50km 거리에)'. 시간 거리도 같아서 'a diez minutos(10분 거리에)'라고 합니다.","x":["a: 거리를 나타내는 전치사 → 정답 ✓","para: '~을 위해/~로 향해'라는 뜻이라 맞지 않습니다 ✗","de: 출발점(de aquí)에 쓰지만 거리 앞에는 쓰지 않습니다 ✗","en: '50km 안에'라는 뜻이 되어 맞지 않습니다 ✗"]},{"id":"G372","q":"Mi abuela Ana murió a los ____ años.","o":["noventa nueve","noventas y nueve","noventa y nueve","noventainueve"],"a":2,"k":"숫자 31~99","t":"우리 할머니 아나는 아흔아홉 살에 돌아가셨다.","e":"31부터 99까지는 '십의 자리 + y + 일의 자리'로 띄어 씁니다: treinta y uno, noventa y nueve. 한 단어로 붙여 쓰는 것은 16~29까지입니다(veintinueve). 'a los ~ años'는 '~살 때'입니다.","x":["noventa nueve: 가운데 y가 빠졌습니다 ✗","noventas y nueve: 숫자 noventa는 복수형을 쓰지 않습니다 ✗","noventa y nueve: 99의 올바른 표기 → 정답 ✓","noventainueve: 30 이상은 붙여 쓰지 않습니다 ✗"]},{"id":"G373","q":"¿Dónde vais a pasar ____ luna de miel?","o":["vuestros","vuestras","vuestro","vuestra"],"a":3,"k":"소유형용사 vuestra","t":"너희는 신혼여행을 어디로 갈 거야?","e":"동사 vais로 보아 '너희(vosotros)'에게 묻고 있으므로 소유형용사 '너희의'는 vuestro/vuestra/vuestros/vuestras 중에서 고릅니다. 'luna de miel(신혼여행)'의 luna가 여성 단수이므로 vuestra가 맞습니다. 중남미에서는 vosotros 대신 ustedes를 써서 'su luna de miel'이라고 합니다.","x":["vuestros: 남성 복수형입니다 ✗","vuestras: 여성 복수형이라 단수 luna와 맞지 않습니다 ✗","vuestro: 남성형인데 luna는 여성 명사입니다 ✗","vuestra: 여성 단수 luna에 맞는 '너희의' → 정답 ✓"]},{"id":"G374","q":"Ayer ____ al mercado para comprar fruta y verdura.","o":["voy","fui","iba","ir"],"a":1,"k":"ir 단순과거","t":"어제 나는 과일과 채소를 사러 시장에 갔다.","e":"'Ayer(어제)'에 일어나고 끝난 한 번의 행동은 단순과거로 씁니다. ir(가다)의 단순과거는 fui, fuiste, fue...로 불규칙이며, yo는 fui입니다. 참고로 ser의 단순과거도 같은 형태입니다.","x":["voy: 현재형이라 ayer와 맞지 않습니다 ✗","fui: ir 단순과거 yo 형태 → 정답 ✓","iba: 불완료과거로 과거의 습관·배경에 써서 한 번 간 일에는 어울리지 않습니다 ✗","ir: 동사원형이라 활용형이 필요합니다 ✗"]},{"id":"G375","q":"Miguel Ángel está viendo ____ su programa de televisión preferido.","o":["el","ø","a","al"],"a":1,"k":"사물 목적어 ø","t":"미겔 앙헬은 자기가 제일 좋아하는 TV 프로그램을 보고 있다.","e":"목적어 'su programa'는 사람이 아니라 사물이므로 전치사 a가 필요 없습니다. 또 이미 소유형용사 su(그의)가 있어서 관사를 겹쳐 쓸 수 없습니다. 그래서 아무것도 넣지 않는 것이 맞습니다.","x":["el: 소유형용사 su 앞에 관사를 붙이지 않습니다 ✗","ø: 사물 목적어 + 소유형용사, 추가 요소 없음 → 정답 ✓","a: 사물 목적어 앞에는 a를 쓰지 않습니다 ✗","al: 'a + el'로 둘 다 필요 없습니다 ✗"]},{"id":"G376","q":"No encuentro ____ Juan. ¿Sabes dónde está?","o":["el","ø","a","al"],"a":2,"k":"사람 목적어 앞 a","t":"후안을 못 찾겠어. 어디 있는지 알아?","e":"encontrar(찾다)의 직접목적어가 사람(Juan)이므로 앞에 전치사 a를 붙입니다. 사람 이름 앞에는 관사를 쓰지 않으므로 al이 아닌 a입니다. 비교: No encuentro las llaves.(열쇠를 못 찾겠다 – 사물이라 a 없음)","x":["el: 사람 이름 앞에 관사를 쓰지 않고 a도 빠졌습니다 ✗","ø: 사람 목적어 앞에 필요한 a가 빠졌습니다 ✗","a: 사람 직접목적어 표시 → 정답 ✓","al: 'a + el'이라 이름 앞에 관사가 들어가 틀립니다 ✗"]},{"id":"G377","q":"No entiendo ____ esta pregunta.","o":["por","ø","de","a"],"a":1,"k":"entender + 목적어","t":"나는 이 질문을 이해하지 못하겠다.","e":"entender(이해하다)는 목적어를 전치사 없이 바로 받는 타동사입니다. 목적어 'esta pregunta'는 사물이므로 a도 필요 없습니다. 예: No entiendo esta palabra.(이 단어를 이해 못 하겠다.)","x":["por: entender 뒤에 por는 쓰지 않습니다 ✗","ø: 전치사 없이 바로 목적어 → 정답 ✓","de: entender de는 '~에 대해 잘 안다'라는 다른 뜻입니다 ✗","a: 사물 목적어 앞에는 a를 쓰지 않습니다 ✗"]},{"id":"G378","q":"No sabe ____ de inglés, nunca lo aprendió.","o":["alguien","nada","alguno","algo"],"a":1,"k":"no ... nada","t":"그는 영어를 전혀 모른다, 한 번도 배운 적이 없다.","e":"no가 있는 부정문에서 '아무것도/전혀'는 nada를 씁니다. 'no saber nada de + 분야'는 '~에 대해 전혀 모르다'라는 자주 쓰는 표현입니다. 스페인어에서는 부정어를 겹쳐 써도 부정의 의미가 유지됩니다.","x":["alguien: '누군가'라는 사람이라 맞지 않습니다 ✗","nada: 부정문의 '아무것도, 전혀' → 정답 ✓","alguno: '어떤 것/누군가'라는 긍정어라 no와 맞지 않습니다 ✗","algo: '무언가'라는 긍정어라 no와 함께 쓰지 않습니다 ✗"]},{"id":"G379","q":"Leo el periódico cada mañana. ____ hago mientras desayuno.","o":["Le","La","Lo","Los"],"a":2,"k":"직접목적격 lo","t":"나는 매일 아침 신문을 읽는다. 아침을 먹으면서 그걸 읽는다.","e":"앞 문장의 el periódico(신문, 남성 단수)를 대신하는 직접목적격 대명사는 lo입니다. 'Lo hago'는 '그것을 한다'로, 여기서 hacer가 앞의 '읽는 일'을 받습니다. 직접목적격: lo, la, los, las.","x":["Le: 간접목적격(~에게)이라 '~을'에 쓰지 않습니다 ✗","La: 여성형이라 남성 periódico와 맞지 않습니다 ✗","Lo: 남성 단수 직접목적격 '그것을' → 정답 ✓","Los: 복수형이라 단수 periódico와 맞지 않습니다 ✗"]},{"id":"G380","q":"Usted ____ una vida muy interesante.","o":["tenéis","tiene","ten","tienes"],"a":1,"k":"usted 활용","t":"당신은 아주 흥미로운 삶을 살고 계시네요.","e":"usted(당신)는 존칭이지만 동사는 3인칭 단수형을 씁니다. tener(가지다)의 3인칭 단수 현재형은 tiene입니다. 'tener una vida ...'는 '~한 삶을 살다'라는 뜻입니다.","x":["tenéis: vosotros(너희) 형태입니다 ✗","tiene: usted에 맞는 3인칭 단수 → 정답 ✓","ten: tú에게 하는 명령형입니다 ✗","tienes: tú(너) 형태라 usted와 맞지 않습니다 ✗"]},{"id":"G381","q":"Esta tarde voy a ____ en casa.","o":["me quedo","quedarme","quedar","quedo"],"a":1,"k":"ir a + 동사원형","t":"오늘 오후에 나는 집에 있을 거야.","e":"가까운 미래 '~할 것이다'는 'ir a + 동사원형'으로 말합니다. quedarse(머무르다)는 재귀동사이므로 원형 끝에 주어에 맞는 대명사를 붙여 quedarme(내가 머무르다)가 됩니다. 'voy a me quedar'처럼 쓰지 않도록 주의하세요.","x":["me quedo: 활용형이라 a 뒤 동사원형 자리에 맞지 않습니다 ✗","quedarme: 동사원형 + me → 정답 ✓","quedar: 재귀대명사가 빠지면 '약속하다/남다' 등 다른 뜻이 됩니다 ✗","quedo: 활용형이고 재귀대명사도 없습니다 ✗"]},{"id":"G382","q":"La farmacia más cercana está ____ unos quince minutos de aquí a pie.","o":["desde","en","de","a"],"a":3,"k":"거리 표현 a","t":"가장 가까운 약국은 여기서 걸어서 15분 정도 거리에 있다.","e":"'~분 거리에 있다'처럼 거리를 시간이나 길이로 말할 때는 전치사 a를 씁니다. 'estar a quince minutos de aquí(여기서 15분 거리에 있다)'. a pie는 '걸어서'라는 뜻입니다.","x":["desde: '~부터'라는 출발점 표현이라 맞지 않습니다 ✗","en: '15분 안에'라는 뜻이 되어 거리 표현이 아닙니다 ✗","de: 거리 앞에 쓰지 않습니다 ✗","a: 거리 표현 'estar a ~' → 정답 ✓"]},{"id":"G383","q":"Te llamo ____ pedirte un consejo.","o":["para","por","sobre","a"],"a":0,"k":"para + 목적","t":"너한테 조언을 구하려고 전화하는 거야.","e":"'~하기 위해'라는 목적은 'para + 동사원형'으로 나타냅니다. 'para pedirte un consejo(너에게 조언을 구하기 위해)'. por는 원인·이유(~때문에)에 주로 씁니다.","x":["para: 목적 '~하기 위해' → 정답 ✓","por: 이유·원인을 나타내며 목적에는 para를 씁니다 ✗","sobre: '~에 대해'라는 뜻이라 맞지 않습니다 ✗","a: 'llamar a'는 사람 앞에 쓰고 목적에는 맞지 않습니다 ✗"]},{"id":"G384","q":"¿____ yogures hay en el frigorífico?","o":["Cuánta","Cuántas","Cuantos","Cuántos"],"a":3,"k":"의문사 cuántos","t":"냉장고에 요구르트가 몇 개 있어?","e":"yogur(요구르트)는 남성 명사이고 여기서는 복수 yogures이므로 cuántos를 씁니다. 의문사에는 반드시 악센트(á)가 들어가야 합니다. frigorífico는 스페인식이고 중남미에서는 refrigerador, heladera, nevera 등을 씁니다.","x":["Cuánta: 여성 단수형입니다 ✗","Cuántas: 여성 복수형인데 yogur는 남성 명사입니다 ✗","Cuantos: 악센트가 없어 의문사가 아닙니다 ✗","Cuántos: 남성 복수 의문사 → 정답 ✓"]},{"id":"G385","q":"Tus perros son más tranquilos que ____ míos.","o":["unos","las","los","ø"],"a":2,"k":"소유대명사 los míos","t":"네 개들이 내 개들보다 더 얌전하다.","e":"'내 것(들)'을 명사 없이 말할 때는 '정관사 + mío/mía/míos/mías'를 씁니다. 여기서는 perros(개들, 남성 복수)를 대신하므로 'los míos(내 개들)'가 됩니다.","x":["unos: 부정관사라 소유대명사와 함께 쓰지 않습니다 ✗","las: 여성형이라 perros와 맞지 않습니다 ✗","los: 남성 복수 정관사 + míos → 정답 ✓","ø: 비교 대상 자리에서 소유대명사는 관사가 필요합니다 ✗"]},{"id":"G386","q":"¿Quién se ha comido todas ____ manzanas?","o":["ø","los","las","la"],"a":2,"k":"todos + 관사","t":"누가 사과를 전부 먹었어?","e":"'모든 ~'는 'todo/toda/todos/todas + 정관사 + 명사'로 씁니다. manzanas(사과들)는 여성 복수이므로 'todas las manzanas'가 됩니다. todas 뒤에 관사를 빼지 않도록 주의하세요.","x":["ø: todas 뒤에는 정관사가 필요합니다 ✗","los: 남성형이라 manzanas와 맞지 않습니다 ✗","las: 여성 복수 정관사 → 정답 ✓","la: 단수형이라 복수 manzanas와 맞지 않습니다 ✗"]},{"id":"G387","q":"No puedo contestar al teléfono ahora, ____ cocinando.","o":["están","estás","estoy","está"],"a":2,"k":"현재진행 estar","t":"지금은 전화를 받을 수 없어, 요리하는 중이야.","e":"'요리하고 있다'는 현재진행형 'estar + cocinando'입니다. 앞 문장 'No puedo(나는 할 수 없다)'로 보아 주어가 yo이므로 estoy가 맞습니다.","x":["están: 3인칭 복수형입니다 ✗","estás: tú(너) 형태입니다 ✗","estoy: yo(나) 형태 → 정답 ✓","está: 3인칭 단수형입니다 ✗"]},{"id":"G388","q":"Estamos haciendo ____ curso de informática.","o":["a un","uno","un","ø"],"a":2,"k":"부정관사 un","t":"우리는 컴퓨터 강좌를 듣고 있다.","e":"처음 소개하는 '어떤 강좌'이므로 부정관사를 씁니다. curso(강좌)는 남성 단수 명사이고, uno는 명사 앞에서 un으로 줄어듭니다. 'hacer un curso'는 '강좌를 듣다'라는 뜻입니다.","x":["a un: 사물 목적어 앞에 a를 쓰지 않습니다 ✗","uno: 명사 앞에서는 un으로 줄여 씁니다 ✗","un: 남성 단수 부정관사 → 정답 ✓","ø: 단수 가산 명사 curso 앞에는 관사가 필요합니다 ✗"]},{"id":"G389","q":"A mi amiga Elena le ____ las películas de esa directora.","o":["encantas","encantan","encanta","encantáis"],"a":1,"k":"encantar 구문","t":"내 친구 엘레나는 그 감독의 영화를 정말 좋아한다.","e":"encantar(아주 좋아하다)는 gustar처럼 '좋아하는 대상'이 문법적 주어입니다. 대상 'las películas(영화들)'가 복수이므로 동사는 3인칭 복수 encantan이 됩니다. le는 '엘레나에게'를 나타냅니다.","x":["encantas: tú 형태라 '네가 그녀 마음에 든다'는 뜻이 됩니다 ✗","encantan: 복수 대상 películas에 맞춘 형태 → 정답 ✓","encanta: 단수형이라 복수 películas와 맞지 않습니다 ✗","encantáis: vosotros 형태입니다 ✗"]},{"id":"G390","q":"Estas botas cuestan ____ dólares.","o":["ciento treinta y cuatro","ciento treinta cuatro","cien treinta y cuatro","cien y treinta y cuatro"],"a":0,"k":"숫자 100 이상","t":"이 부츠는 134달러이다.","e":"100은 단독으로는 cien이지만 뒤에 다른 숫자가 이어지면 ciento가 됩니다(101 = ciento uno). 그리고 y는 십의 자리와 일의 자리 사이에만 넣습니다. 그래서 134는 ciento treinta y cuatro입니다.","x":["ciento treinta y cuatro: 134의 올바른 표기 → 정답 ✓","ciento treinta cuatro: 30과 4 사이의 y가 빠졌습니다 ✗","cien treinta y cuatro: 뒤에 숫자가 이어지면 ciento를 써야 합니다 ✗","cien y treinta y cuatro: 100 뒤에는 y를 넣지 않습니다 ✗"]},{"id":"G391","q":"Agustín trabaja ____ una marisquería.","o":["a","por","de","en"],"a":3,"k":"trabajar en","t":"아구스틴은 해산물 식당에서 일한다.","e":"'~에서 일하다'처럼 일하는 장소를 말할 때는 'trabajar en + 장소'를 씁니다. marisquería는 해산물(marisco) 전문 식당입니다. 'trabajar de + 직업'은 '~로 일하다'라는 뜻이라 구별하세요(trabaja de camarero 웨이터로 일한다).","x":["a: '~로(방향)'라는 뜻이라 일하는 장소에 쓰지 않습니다 ✗","por: '~ 근처/~을 통해'라는 뜻이라 맞지 않습니다 ✗","de: 'trabajar de'는 직업 앞에 씁니다 ✗","en: 일하는 장소 '~에서' → 정답 ✓"]},{"id":"G392","q":"¿____ dice la verdad? ¿Jaime o Cristóbal?","o":["Cuándo","Quién","Qué","Cómo"],"a":1,"k":"의문사 quién","t":"누가 진실을 말하고 있는 거야? 하이메야, 크리스토발이야?","e":"뒤에 사람 이름(Jaime, Cristóbal)이 선택지로 나오므로 '누가'를 묻는 quién이 알맞습니다. quién이 동사 dice(말하다)의 주어입니다. 'decir la verdad'는 '진실을 말하다'입니다.","x":["Cuándo: '언제'라는 뜻이라 사람을 묻지 못합니다 ✗","Quién: '누가' → 정답 ✓","Qué: '무엇'이라는 뜻이라 사람 선택과 맞지 않습니다 ✗","Cómo: '어떻게'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G393","q":"Mira, ____ niños están haciendo un castillo de arena.","o":["estas","esos","aquel","ese"],"a":1,"k":"지시형용사 esos","t":"봐, 저 아이들이 모래성을 만들고 있어.","e":"niños(아이들)는 남성 복수 명사이므로 지시형용사도 남성 복수형을 써야 합니다. 보기 중 남성 복수는 esos(그/저 ~들)뿐입니다. 'castillo de arena'는 '모래성'입니다.","x":["estas: 여성 복수형이라 niños와 맞지 않습니다 ✗","esos: 남성 복수 지시형용사 → 정답 ✓","aquel: 단수형이라 복수 niños와 맞지 않습니다 ✗","ese: 단수형입니다 ✗"]},{"id":"G394","q":"¿Dónde ____ tus compañeros de clase?","o":["tienen","son","están","hay"],"a":2,"k":"위치 estar","t":"네 반 친구들은 어디에 있어?","e":"특정한 사람들(tus compañeros)이 어디에 있는지 묻는 위치 표현이므로 estar를 씁니다. 주어가 3인칭 복수라서 están이 됩니다. 출신을 물을 때는 '¿De dónde son?'처럼 ser를 쓰니 구별하세요.","x":["tienen: '가지고 있다'라는 뜻이라 맞지 않습니다 ✗","son: ser는 위치에 쓰지 않습니다(출신은 de dónde son) ✗","están: 특정 인물들의 위치 → 정답 ✓","hay: 소유형용사가 붙은 특정 대상에는 쓰지 않습니다 ✗"]},{"id":"G395","q":"Hoy vamos a comer ____ pasta.","o":["la","las","ø","los"],"a":2,"k":"관사 생략","t":"오늘 우리는 파스타를 먹을 거야.","e":"셀 수 없는 음식을 막연하게 '조금, 어느 정도' 먹는다고 할 때는 관사 없이 씁니다. 'comer pasta(파스타를 먹다)', 'beber agua(물을 마시다)'처럼요. 'la pasta'라고 하면 이미 정해진 특정 파스타를 가리킵니다.","x":["la: 특정한 파스타를 가리키게 되어 어색합니다 ✗","las: 복수형이라 맞지 않습니다 ✗","ø: 막연한 음식 '파스타를 먹다' → 정답 ✓","los: 남성 복수형이라 맞지 않습니다 ✗"]},{"id":"G396","q":"¿____ estáis haciendo aquí?","o":["Qué","Por qué","A qué","De qué"],"a":0,"k":"의문사 qué","t":"너희 여기서 뭐 하고 있어?","e":"'무엇을' 하고 있는지 묻고 있으므로 qué를 씁니다. 'estar haciendo'는 '하고 있다'라는 현재진행형이고, qué는 hacer의 목적어입니다. estáis는 vosotros(너희) 형태로 스페인에서 씁니다(중남미: ¿Qué están haciendo?).","x":["Qué: '무엇을' → 정답 ✓","Por qué: '왜'라는 뜻이라 hacer의 목적어가 될 수 없습니다 ✗","A qué: '무엇에/무엇하러'라는 뜻이라 맞지 않습니다 ✗","De qué: '무엇에 대해'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G397","q":"Prefiero ____ invierno porque en verano hace demasiado calor.","o":["a","de","el","al"],"a":2,"k":"preferir + 관사","t":"여름은 너무 더워서 나는 겨울이 더 좋다.","e":"preferir(더 좋아하다)는 목적어를 전치사 없이 바로 받습니다. 계절 같은 일반적인 대상도 정관사를 붙여 'el invierno(겨울)'라고 합니다. 예: Prefiero la playa.(나는 해변이 더 좋다.)","x":["a: preferir 바로 뒤 목적어 앞에 a는 쓰지 않습니다 ✗","de: '~의'라는 뜻이라 맞지 않습니다 ✗","el: 남성 명사 invierno 앞 정관사 → 정답 ✓","al: 'a + el'이라 전치사가 불필요하게 들어갑니다 ✗"]},{"id":"G398","q":"El examen de matemáticas es hoy ____ mediodía.","o":["a la","al","en la","en el"],"a":1,"k":"al mediodía","t":"수학 시험은 오늘 정오에 있다.","e":"'정오에'는 'al mediodía'라는 정해진 표현을 씁니다(a + el = al). 시각 앞에 a를 쓰는 것과 같은 원리입니다: a las tres(3시에). mediodía는 남성 명사입니다.","x":["a la: mediodía는 남성 명사라 la를 쓰지 않습니다 ✗","al: 'al mediodía(정오에)' → 정답 ✓","en la: 시각 표현에 en을 쓰지 않고 성도 틀립니다 ✗","en el: 이 시간 표현에는 en 대신 a를 씁니다 ✗"]},{"id":"G399","q":"No ____ pan, voy a ir a la panadería.","o":["está","es","ha","hay"],"a":3,"k":"hay (존재)","t":"빵이 없어서 빵집에 갈 거야.","e":"'~이 있다/없다'처럼 무언가의 존재를 말할 때는 hay를 씁니다. 관사 없는 막연한 명사 pan(빵) 앞이므로 hay가 알맞습니다. 'No hay pan'은 '빵이 없다'라는 뜻입니다.","x":["está: 특정 대상의 위치를 말할 때 써서 막연한 pan과 맞지 않습니다 ✗","es: '~이다'라는 뜻이라 존재를 나타내지 못합니다 ✗","ha: haber의 조동사형으로 과거분사가 필요합니다 ✗","hay: 존재를 나타내는 '있다' → 정답 ✓"]},{"id":"G400","q":"Marta sabe ____ inglés.","o":["la","el","lo","ø"],"a":3,"k":"언어 + 관사 생략","t":"마르타는 영어를 할 줄 안다.","e":"saber, hablar, estudiar 같은 동사 바로 뒤에 언어 이름이 오면 보통 관사를 붙이지 않습니다. 'Marta sabe inglés(마르타는 영어를 안다)'. 단, 주어로 쓸 때는 'El inglés es difícil'처럼 관사를 씁니다.","x":["la: 여성형이고, 언어 앞 관사는 이 경우 생략합니다 ✗","el: 동사 saber 바로 뒤 언어에는 관사를 생략합니다 ✗","lo: 중성 관사로 명사 앞에 쓰지 않습니다 ✗","ø: 'saber inglés'로 관사 없음 → 정답 ✓"]},{"id":"G401","q":"Hoy los alumnos se han portado muy ____ en clase.","o":["bien","buenos","bueno","buena"],"a":0,"k":"부사 bien","t":"오늘 학생들이 수업 시간에 아주 얌전하게 행동했다.","e":"portarse(행동하다)처럼 동사를 꾸밀 때는 형용사가 아니라 부사를 씁니다. bien(잘)은 부사로 형태가 변하지 않습니다. 'portarse bien/mal'은 '얌전하게/버릇없이 행동하다'라는 자주 쓰는 표현입니다.","x":["bien: 동사를 꾸미는 부사 '잘' → 정답 ✓","buenos: 형용사라 동사를 꾸미지 못합니다 ✗","bueno: 형용사 단수형입니다 ✗","buena: 형용사 여성 단수형입니다 ✗"]},{"id":"G402","q":"Dicen que ____ padres de Juan se han divorciado.","o":["ø","unos","el","los"],"a":3,"k":"정관사 los","t":"후안의 부모님이 이혼했다고들 한다.","e":"'후안의 부모님'은 정해진 특정한 사람들이므로 정관사를 씁니다. padres(부모)는 남성 복수이므로 'los padres de Juan'이 됩니다. 'Dicen que...'는 '~라고들 한다'라는 표현입니다.","x":["ø: 주어 자리의 특정 명사 앞에는 관사가 필요합니다 ✗","unos: '어떤 부모들'이라는 막연한 뜻이 되어 맞지 않습니다 ✗","el: 단수형이라 복수 padres와 맞지 않습니다 ✗","los: 남성 복수 정관사 → 정답 ✓"]},{"id":"G403","q":"____ programas de este canal de televisión son interesantísimos.","o":["Los","Las","El","La"],"a":0,"k":"정관사 los","t":"이 TV 채널의 프로그램들은 아주 재미있다.","e":"programa는 -a로 끝나지만 남성 명사입니다(el problema, el tema처럼 -ma로 끝나는 그리스어 계열 단어). 복수 programas 앞에는 los를 씁니다. interesantísimos는 '매우 흥미로운'입니다.","x":["Los: 남성 복수 명사 programas 앞 정관사 → 정답 ✓","Las: programa는 남성 명사라 las를 쓰지 않습니다 ✗","El: 단수형이라 복수 programas와 맞지 않습니다 ✗","La: 여성 단수형입니다 ✗"]},{"id":"G404","q":"____ fines de semana tengo que ir a la oficina.","o":["Las","Algún","Algunos","Algunas"],"a":2,"k":"부정형용사 algunos","t":"몇몇 주말에는 사무실에 나가야 한다.","e":"'몇몇의, 어떤'은 alguno의 형태 중 명사의 성·수에 맞는 것을 고릅니다. 'fines de semana(주말들)'의 fin은 남성 명사이고 복수이므로 algunos가 됩니다. 단수 남성 명사 앞에서는 algún으로 줄어듭니다.","x":["Las: 여성 관사인데 fines는 남성 명사입니다 ✗","Algún: 단수형이라 복수 fines와 맞지 않습니다 ✗","Algunos: 남성 복수 '몇몇의' → 정답 ✓","Algunas: 여성형이라 fines와 맞지 않습니다 ✗"]},{"id":"G405","q":"A Belén le interesa el atletismo y a su novio ____.","o":["sí","también","tampoco","además"],"a":1,"k":"también","t":"벨렌은 육상에 관심이 있고, 그녀의 남자친구도 그렇다.","e":"앞 문장이 긍정문일 때 '~도 역시 그렇다'는 también을 씁니다. interesar는 gustar처럼 'a + 사람' 구조를 쓰므로 'a su novio también'이 됩니다. 부정문에 동의할 때는 tampoco를 씁니다.","x":["sí: 부정에 반대할 때(a mí sí 나는 그래) 쓰는 말이라 맞지 않습니다 ✗","también: 긍정문에 '~도 역시' → 정답 ✓","tampoco: 부정문에 동의할 때 씁니다 ✗","además: '게다가'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G406","q":"¿Qué estáis ____ aquí?","o":["haciendo","a hacer","hecho","hacer"],"a":0,"k":"현재분사 haciendo","t":"너희 여기서 뭐 하고 있어?","e":"estar 뒤에 동작이 오면 '~하고 있다'라는 현재진행형이 되며, 동사는 현재분사(-ando/-iendo) 형태여야 합니다. hacer(하다)의 현재분사는 haciendo입니다.","x":["haciendo: estar + 현재분사(하고 있다) → 정답 ✓","a hacer: estar 뒤에는 이런 형태가 오지 않습니다(ir a hacer와 혼동) ✗","hecho: 과거분사(된, 만든)라 진행형이 되지 않습니다 ✗","hacer: 동사원형은 estar 뒤에 쓰지 않습니다 ✗"]},{"id":"G407","q":"María está más alegre desde ____ vive en Sevilla.","o":["cuando","que","ø","entonces"],"a":1,"k":"desde que","t":"마리아는 세비야에 살게 된 후로 더 밝아졌다.","e":"'~한 이후로, ~한 때부터'는 'desde que + 문장'으로 말합니다. 'desde que vive en Sevilla(세비야에 산 이후로)'. 뒤에 명사가 오면 que 없이 'desde marzo(3월부터)'처럼 씁니다.","x":["cuando: 'desde cuando'는 의문문(desde cuándo) 외에는 이렇게 쓰지 않습니다 ✗","que: 'desde que(~한 이후로)' → 정답 ✓","ø: desde 뒤에 문장을 바로 이어 쓸 수 없습니다 ✗","entonces: 'desde entonces(그때부터)'는 뒤에 문장을 받지 않습니다 ✗"]},{"id":"G408","q":"Mi hermano Álex es más alto que ____.","o":["mí","yo","me","yo soy"],"a":1,"k":"비교급 que yo","t":"내 형 알렉스는 나보다 키가 크다.","e":"비교 구문에서 que(~보다) 뒤에는 주격 대명사(yo, tú)를 씁니다. 'más alto que yo(나보다 키가 큰)'. que는 전치사가 아니라서 mí를 쓰지 않습니다. 동사를 반복하지 않는 것이 자연스럽습니다.","x":["mí: 전치사 뒤에 쓰는 형태인데 que는 전치사가 아닙니다 ✗","yo: que 뒤 주격 대명사 → 정답 ✓","me: 목적격 대명사라 비교 대상에 쓰지 않습니다 ✗","yo soy: 문법적으로 가능은 하지만 동사를 반복해 부자연스럽습니다 ✗"]},{"id":"G409","q":"Creo que ____ moto de María Isabel está en el garaje.","o":["la","los","el","ø"],"a":0,"k":"정관사 la","t":"마리아 이사벨의 오토바이는 차고에 있는 것 같다.","e":"moto(오토바이)는 -o로 끝나지만 motocicleta를 줄인 말이라 여성 명사입니다. 그래서 정관사 la를 씁니다. 같은 예로 la foto(사진, fotografía), la radio(라디오)가 있습니다.","x":["la: 여성 명사 moto 앞 정관사 → 정답 ✓","los: 남성 복수형입니다 ✗","el: moto는 여성 명사라 el을 쓰지 않습니다 ✗","ø: 주어 자리의 특정 명사에는 관사가 필요합니다 ✗"]},{"id":"G410","q":"¿Nos ____ la cuenta, por favor?","o":["trae","traed","traemos","traigo"],"a":0,"k":"usted 공손 요청","t":"계산서 좀 가져다주시겠어요?","e":"식당에서 종업원(usted)에게 공손하게 부탁할 때 의문문 현재형 '¿Nos trae ...?(우리에게 ~ 가져다주시겠어요?)'를 씁니다. usted는 3인칭 단수 동사이므로 trae가 맞습니다. nos는 '우리에게'입니다.","x":["trae: usted에 맞는 3인칭 단수 현재형 → 정답 ✓","traed: vosotros 명령형이라 의문문·nos 앞에 쓰지 않습니다 ✗","traemos: '우리가 가져온다'는 뜻이라 맞지 않습니다 ✗","traigo: '내가 가져온다'는 뜻이라 맞지 않습니다 ✗"]},{"id":"G411","q":"¿De quién es ____ lápiz?","o":["estos","estas","esta","este"],"a":3,"k":"지시형용사 este","t":"이 연필은 누구 거야?","e":"lápiz(연필)는 남성 단수 명사이므로 지시형용사 este(이)를 씁니다. '¿De quién es ...?'는 '~은 누구 것이니?'라는 소유를 묻는 표현입니다. 복수는 lápices입니다.","x":["estos: 복수형이라 단수 lápiz와 맞지 않습니다 ✗","estas: 여성 복수형입니다 ✗","esta: 여성형인데 lápiz는 남성 명사입니다 ✗","este: 남성 단수 '이' → 정답 ✓"]},{"id":"G412","q":"Para muchas personas, ____ más importante en la vida es la salud.","o":["la","ø","el","lo"],"a":3,"k":"중성 lo + 형용사","t":"많은 사람들에게 인생에서 가장 중요한 것은 건강이다.","e":"'lo + 형용사'는 '~한 것'이라는 추상적인 뜻을 만듭니다. 'lo más importante'는 '가장 중요한 것'이라는 자주 쓰는 표현입니다. 특정 명사를 가리키지 않으므로 남성·여성 관사 대신 중성 lo를 씁니다.","x":["la: 여성 명사를 가리킬 때만 쓰므로 맞지 않습니다 ✗","ø: 관사가 없으면 '가장 중요한 것'이라는 뜻이 되지 않습니다 ✗","el: 남성 명사를 가리킬 때 쓰며 추상적인 '것'에는 lo를 씁니다 ✗","lo: 'lo más importante(가장 중요한 것)' → 정답 ✓"]},{"id":"G413","q":"No ____ comer fuera de casa.","o":["nos gusta","gusta a nosotros","gustamos","nos gustamos"],"a":0,"k":"gustar 구문","t":"우리는 외식하는 것을 좋아하지 않는다.","e":"gustar 뒤에 동사원형(comer fuera)이 오면 동사는 항상 3인칭 단수 gusta를 씁니다. 좋아하는 사람 '우리'는 간접목적격 nos로 나타내며 동사 앞에 둡니다. 'comer fuera'는 '외식하다'입니다.","x":["nos gusta: nos(우리에게) + gusta(동사원형 대상) → 정답 ✓","gusta a nosotros: 대명사 nos 없이 'a nosotros'만 쓰는 것은 틀립니다 ✗","gustamos: '우리가 (누군가의) 마음에 든다'는 뜻이 됩니다 ✗","nos gustamos: '우리가 서로 좋아한다'라는 뜻이 됩니다 ✗"]},{"id":"G414","q":"Hay ____ personas en ese bar. Vamos a otro, ¿vale?","o":["mucha","mucho","muchos","muchas"],"a":3,"k":"mucho 일치","t":"그 바에는 사람이 너무 많아. 다른 데로 가자, 응?","e":"mucho가 명사 앞에서 '많은'이라는 형용사로 쓰이면 명사의 성·수에 맞춥니다. personas(사람들)는 여성 복수이므로 muchas가 됩니다. ¿vale?는 스페인에서 '알았지?/좋아?'라는 뜻으로 자주 씁니다.","x":["mucha: 단수형이라 복수 personas와 맞지 않습니다 ✗","mucho: 남성 단수형입니다 ✗","muchos: 남성 복수형인데 persona는 여성 명사입니다 ✗","muchas: 여성 복수 '많은' → 정답 ✓"]},{"id":"G415","q":"¿Pueden guardar silencio? ____ molestando.","o":["Está","Estáis","Están","Estás"],"a":2,"k":"ustedes 활용","t":"조용히 해 주시겠어요? 방해가 되고 있어요.","e":"'¿Pueden...?'으로 보아 상대는 ustedes(여러분)입니다. ustedes는 3인칭 복수 동사를 쓰므로 estar는 están이 되고, 'están molestando'는 '방해하고 있다'라는 현재진행형입니다.","x":["Está: 3인칭 단수형이라 pueden과 맞지 않습니다 ✗","Estáis: vosotros 형태라 ustedes와 맞지 않습니다 ✗","Están: ustedes에 맞는 3인칭 복수 → 정답 ✓","Estás: tú 형태입니다 ✗"]},{"id":"G416","q":"¡Qué contento ____ Alejandro!","o":["está","están","sois","es"],"a":0,"k":"estar + 감정","t":"알레한드로가 정말 기뻐하네!","e":"contento(기쁜, 만족한)는 지금의 감정 상태를 나타내므로 estar와 함께 씁니다. 주어 Alejandro는 3인칭 단수라 está가 됩니다. '¡Qué + 형용사 + 동사 + 주어!'는 '정말 ~하구나!'라는 감탄문입니다.","x":["está: 감정 상태를 나타내는 estar 3인칭 단수 → 정답 ✓","están: 복수형입니다 ✗","sois: ser의 vosotros 형태입니다 ✗","es: contento는 항상 estar와 함께 씁니다 ✗"]},{"id":"G417","q":"¿____ bailar salsa?","o":["Te gustan","Te gustas","Gustas","Te gusta"],"a":3,"k":"gustar + 동사원형","t":"살사 춤추는 거 좋아해?","e":"gustar 뒤에 동사원형(bailar)이 오면 동사는 3인칭 단수 gusta를 씁니다. '너'는 간접목적격 te로 나타냅니다. 그래서 '¿Te gusta bailar salsa?'가 됩니다.","x":["Te gustan: 복수형은 복수 명사 앞에 씁니다 ✗","Te gustas: '네가 너 자신의 마음에 든다'는 뜻이 됩니다 ✗","Gustas: '네가 (누군가의) 마음에 든다'는 뜻이 됩니다 ✗","Te gusta: te + 단수형(동사원형 대상) → 정답 ✓"]},{"id":"G418","q":"Marina no es tan habladora ____ su hermana.","o":["como","cuando","cual","que"],"a":0,"k":"동등비교 tan...como","t":"마리나는 자기 언니(여동생)만큼 수다스럽지 않다.","e":"'~만큼 …하다'는 'tan + 형용사 + como'로 나타냅니다. 'tan habladora como su hermana(그녀의 자매만큼 수다스러운)'. tan과 짝이 되는 말은 que가 아니라 como입니다.","x":["como: 'tan ... como(~만큼)' → 정답 ✓","cuando: '~할 때'라는 뜻이라 맞지 않습니다 ✗","cual: 비교 구문에 쓰지 않습니다 ✗","que: más/menos와 짝이 되며 tan과는 쓰지 않습니다 ✗"]},{"id":"G419","q":"Esta chaqueta no es ____.","o":["a mí","mí","mía","de mí"],"a":2,"k":"소유대명사 mía","t":"이 재킷은 내 것이 아니다.","e":"'내 것'은 ser 뒤에 mío/mía/míos/mías를 씁니다. chaqueta(재킷)는 여성 단수 명사이므로 mía가 됩니다. 'de mí'는 소유를 나타내지 않습니다.","x":["a mí: '나에게'라는 뜻이라 소유를 나타내지 않습니다 ✗","mí: 전치사 뒤 대명사라 단독으로 쓰지 않습니다 ✗","mía: 여성 단수 '내 것' → 정답 ✓","de mí: 소유 표현으로 쓰지 않습니다 ✗"]},{"id":"G420","q":"Necesito hablar ____.","o":["contigo","con ti","con tú","a ti"],"a":0,"k":"contigo","t":"너랑 얘기할 필요가 있어.","e":"'너와 함께'는 con + ti가 아니라 특별한 한 단어 contigo를 씁니다. 마찬가지로 '나와 함께'는 conmigo입니다. 다른 사람은 그대로 con él, con ella, con usted처럼 씁니다.","x":["contigo: '너와 함께'의 특별한 형태 → 정답 ✓","con ti: 이렇게 쓰지 않고 contigo로 합쳐야 합니다 ✗","con tú: 전치사 뒤에 주격 tú는 쓰지 않습니다 ✗","a ti: '너에게'라는 뜻이라 'hablar con(~와 이야기하다)'에 맞지 않습니다 ✗"]},{"id":"G421","q":"¿____ viven tus primos?","o":["Qué","Dónde","Quién","Cuándo"],"a":1,"k":"의문사 dónde","t":"네 사촌들은 어디에 살아?","e":"사는 장소를 물을 때는 '어디'라는 dónde를 씁니다. vivir(살다)는 장소와 함께 쓰는 동사이므로 '¿Dónde viven...?'이 됩니다. 대답 예: Viven en Madrid.(마드리드에 살아.)","x":["Qué: '무엇'이라는 뜻이라 장소를 묻지 않습니다 ✗","Dónde: '어디' → 정답 ✓","Quién: '누구'라는 뜻이고 주어 tus primos가 이미 있습니다 ✗","Cuándo: '언제'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G422","q":"____ la ventana de la cocina veo un parque.","o":["Desde","De","Entre","A"],"a":0,"k":"전치사 desde","t":"부엌 창문에서 공원이 보인다.","e":"'~에서(보다)'처럼 바라보는 위치·출발점을 나타낼 때는 desde를 씁니다. 'desde la ventana(창문에서)'. desde는 '~부터'라는 뜻으로 장소와 시간 모두에 쓸 수 있습니다.","x":["Desde: 바라보는 출발점 '~에서' → 정답 ✓","De: 출처를 나타내지만 '어디에서 보다'에는 desde가 자연스럽습니다 ✗","Entre: '~ 사이에'라는 뜻이라 맞지 않습니다 ✗","A: '~로'라는 방향이라 맞지 않습니다 ✗"]},{"id":"G423","q":"____ gente me sorprende cada día.","o":["El","La","Las","Los"],"a":1,"k":"la gente","t":"사람들은 매일 나를 놀라게 한다.","e":"gente(사람들)는 뜻은 복수지만 문법적으로는 여성 단수 명사입니다. 그래서 관사는 la, 동사는 3인칭 단수(sorprende)를 씁니다. 'la gente son'처럼 복수 동사를 쓰지 않도록 주의하세요.","x":["El: gente는 여성 명사입니다 ✗","La: 여성 단수 명사 gente 앞 정관사 → 정답 ✓","Las: gente는 단수 명사로 씁니다 ✗","Los: 남성 복수형이라 맞지 않습니다 ✗"]},{"id":"G424","q":"Perdone, ¿____ cuestan esos bolsos?","o":["cuánto","cuánta","cuántas","cuántos"],"a":0,"k":"가격 묻기 cuánto","t":"실례지만, 그 가방들 얼마예요?","e":"가격을 물을 때 '¿Cuánto cuesta(n)...?'의 cuánto는 '얼마'라는 뜻의 부사라서 형태가 바뀌지 않습니다. 주어 bolsos가 복수라서 동사만 cuestan으로 복수가 됩니다. cuántos는 '몇 개'라는 뜻이 됩니다.","x":["cuánto: 가격을 묻는 '얼마', 형태 불변 → 정답 ✓","cuánta: 여성 단수 명사 앞 '얼마나 많은'입니다 ✗","cuántas: 여성 복수 '몇 개의'라 가격 질문이 아닙니다 ✗","cuántos: '몇 개'라는 뜻이 되어 가격 질문과 맞지 않습니다 ✗"]},{"id":"G425","q":"¿Cómo ____, señora Pérez? —Muy bien, gracias, ¿y usted?","o":["es","está","eres","estás"],"a":1,"k":"¿Cómo está?","t":"어떻게 지내세요, 페레스 부인? —아주 잘 지내요, 고마워요. 당신은요?","e":"안부를 묻는 '어떻게 지내세요?'는 estar를 써서 '¿Cómo está?'라고 합니다. 'señora Pérez'에게 존칭 usted을 쓰므로 3인칭 단수 está입니다. 친한 사이라면 '¿Cómo estás?'라고 합니다.","x":["es: '¿Cómo es?'는 성격이나 외모(어떤 사람이에요?)를 묻습니다 ✗","está: usted에게 안부를 묻는 형태 → 정답 ✓","eres: ser의 tú 형태라 안부와 존칭 모두 맞지 않습니다 ✗","estás: tú 형태라 존칭 usted와 맞지 않습니다 ✗"]},{"id":"G426","q":"En mi país ____ muy bien.","o":["te comes","nos comemos","se come","se comen"],"a":2,"k":"무인칭 se","t":"우리나라에서는 음식이 아주 맛있다(잘 먹는다).","e":"'se + 3인칭 단수 동사'는 특정한 주어 없이 '(사람들이) 일반적으로 ~한다'라는 무인칭 표현입니다. 'se come muy bien'은 '(그곳에서는) 음식을 아주 잘 먹는다, 음식이 맛있다'라는 뜻입니다. 목적어가 없으므로 단수 come를 씁니다.","x":["te comes: '네가 (다) 먹어 버린다'라는 특정 주어 표현입니다 ✗","nos comemos: '우리가 (다) 먹어 치운다'라는 뜻이라 일반 표현이 아닙니다 ✗","se come: 무인칭 '일반적으로 먹는다' → 정답 ✓","se comen: 복수 주어가 필요한데 복수 명사가 없습니다 ✗"]},{"id":"G427","q":"Mis perritos ____ llaman Coco y Perla.","o":["se","le","les","los"],"a":0,"k":"llamarse","t":"우리 강아지들은 이름이 코코와 페를라다.","e":"이름을 말할 때는 재귀동사 llamarse(~라고 불리다)를 씁니다. 주어 mis perritos가 3인칭 복수이므로 재귀대명사는 se, 동사는 llaman입니다. 예: Me llamo Ana.(내 이름은 아나야.)","x":["se: 3인칭 재귀대명사 'se llaman(이름이 ~이다)' → 정답 ✓","le: 간접목적격이라 '그에게 전화한다'는 뜻이 됩니다 ✗","les: 간접목적격 복수라 맞지 않습니다 ✗","los: 직접목적격이라 '그들을 부른다'는 뜻이 됩니다 ✗"]},{"id":"G428","q":"En ____ ciudad hay varios museos de arte moderno.","o":["mi","la mía","mía","mí"],"a":0,"k":"소유형용사 mi","t":"우리 도시에는 현대 미술관이 여러 개 있다.","e":"명사 앞에서 '나의'는 소유형용사 mi를 씁니다(악센트 없음). 'mi ciudad(내 도시)'. la mía는 '내 것'이라는 소유대명사라 명사 앞에 쓰지 않고, mí는 전치사 뒤에 쓰는 '나'입니다.","x":["mi: 명사 앞 소유형용사 '나의' → 정답 ✓","la mía: '내 것'이라 뒤에 명사가 올 수 없습니다 ✗","mía: 명사 뒤나 ser 뒤에 쓰는 형태입니다 ✗","mí: 악센트가 있으면 전치사 뒤 대명사(para mí)입니다 ✗"]},{"id":"G429","q":"Para mí, ____ clima de esta región es perfecto.","o":["la","lo","ø","el"],"a":3,"k":"정관사 el clima","t":"내 생각에 이 지역의 기후는 완벽하다.","e":"clima(기후)는 -a로 끝나지만 남성 명사입니다(el problema, el tema와 같은 -ma 계열). 그래서 정관사 el을 씁니다. 'Para mí'는 '내 생각에는'이라는 뜻입니다.","x":["la: clima는 남성 명사라 la를 쓰지 않습니다 ✗","lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗","ø: 주어 자리의 특정 명사에는 관사가 필요합니다 ✗","el: 남성 명사 clima 앞 정관사 → 정답 ✓"]},{"id":"G430","q":"María Isabel está saliendo con Moisés; ____ vi el otro día de la mano.","o":["le","los","se los","lo"],"a":1,"k":"직접목적격 los","t":"마리아 이사벨은 모이세스와 사귀고 있어. 며칠 전에 둘이 손잡고 있는 걸 봤어.","e":"'그 둘을 보았다'에서 '그들을'은 직접목적격 대명사입니다. 남녀가 섞인 복수(María Isabel과 Moisés)는 남성 복수형 los를 씁니다. 'de la mano'는 '손을 잡고'라는 뜻입니다.","x":["le: 간접목적격 단수(~에게)라 맞지 않습니다 ✗","los: 남녀 혼성 복수 직접목적격 '그들을' → 정답 ✓","se los: se는 간접목적격 대용인데 ver에는 '~에게'가 필요 없습니다 ✗","lo: 단수형이라 두 사람을 가리킬 수 없습니다 ✗"]},{"id":"G431","q":"¿____ qué banco trabaja Mario?","o":["Sobre","A","En","De"],"a":2,"k":"trabajar en","t":"마리오는 어느 은행에서 일해?","e":"'~에서 일하다'는 'trabajar en + 장소'입니다. 의문문에서는 전치사가 의문사 앞으로 와서 '¿En qué banco...?(어느 은행에서?)'가 됩니다. 스페인어는 문장 끝에 전치사를 남기지 않습니다.","x":["Sobre: '~ 위에/~에 대해'라는 뜻이라 맞지 않습니다 ✗","A: '~로'라는 방향이라 일하는 곳에 쓰지 않습니다 ✗","En: 'trabajar en(~에서 일하다)' → 정답 ✓","De: 'trabajar de'는 직업 앞에 씁니다 ✗"]},{"id":"G432","q":"Mis padres nunca ____ la siesta.","o":["dormimos","dormir","duermo","duermen"],"a":3,"k":"dormir 현재 활용","t":"우리 부모님은 절대 낮잠을 자지 않는다.","e":"dormir(자다)는 현재형에서 o가 ue로 바뀌는 불규칙 동사입니다(duermo, duermes, duerme, dormimos, dormís, duermen). 주어 mis padres는 3인칭 복수이므로 duermen입니다. 'dormir la siesta'는 '낮잠을 자다'입니다.","x":["dormimos: nosotros(우리) 형태입니다 ✗","dormir: 동사원형이라 활용형이 필요합니다 ✗","duermo: yo(나) 형태입니다 ✗","duermen: 3인칭 복수 → 정답 ✓"]},{"id":"G433","q":"Podemos descansar; ya hemos hecho ____ trabajo.","o":["bastantes","bastante","muchas","muchos"],"a":1,"k":"bastante","t":"쉬어도 돼. 이미 일을 꽤 했어.","e":"bastante(충분한, 꽤 많은)는 남녀 형태가 같고 수만 바뀝니다(bastante/bastantes). trabajo(일)는 단수 명사이므로 bastante가 맞습니다. 예: Tengo bastante tiempo.(시간이 충분히 있다.)","x":["bastantes: 복수형이라 단수 trabajo와 맞지 않습니다 ✗","bastante: 단수 명사 trabajo 앞 '충분한' → 정답 ✓","muchas: 여성 복수형이라 trabajo와 맞지 않습니다 ✗","muchos: 복수형이라 단수 trabajo와 맞지 않습니다 ✗"]},{"id":"G434","q":"¿Podrías mandarme la información ____ correo electrónico?","o":["a","en","para","por"],"a":3,"k":"por + 수단","t":"그 정보를 이메일로 보내 줄 수 있어?","e":"'~로, ~을 통해서'처럼 전달 수단을 말할 때는 por를 씁니다: por correo electrónico(이메일로), por teléfono(전화로), por correo(우편으로). Podrías는 '~해 줄 수 있겠니?'라는 공손한 표현입니다.","x":["a: '~에게/~로(방향)'라는 뜻이라 수단에 쓰지 않습니다 ✗","en: 이 표현에서는 수단을 나타내지 못합니다 ✗","para: '~을 위해'라는 목적이라 맞지 않습니다 ✗","por: 전달 수단 '~로' → 정답 ✓"]},{"id":"G435","q":"Anabel ha cantado ____ canción preciosa.","o":["un","a una","una","ø"],"a":2,"k":"부정관사 una","t":"아나벨이 아름다운 노래를 한 곡 불렀다.","e":"처음 언급하는 '어떤 노래 한 곡'이므로 부정관사를 씁니다. canción(노래)은 -ción으로 끝나는 여성 명사이므로 una가 맞습니다. -ción, -sión으로 끝나는 명사는 대부분 여성입니다.","x":["un: 남성형인데 canción은 여성 명사입니다 ✗","a una: 사물 목적어 앞에는 a를 쓰지 않습니다 ✗","una: 여성 단수 부정관사 → 정답 ✓","ø: 단수 명사 canción 앞에는 관사가 필요합니다 ✗"]},{"id":"G436","q":"El agua ____ tomo del tiempo, ni fría ni caliente.","o":["le","la","las","lo"],"a":1,"k":"목적어 반복 la","t":"물은 너무 차지도 뜨겁지도 않은 상온으로 마신다.","e":"목적어(El agua)를 문장 앞에 두면 동사 앞에 직접목적격 대명사로 한 번 더 받아야 합니다. agua는 단수 앞에서 el을 쓰지만 실제로는 여성 명사이므로 대명사는 la입니다. 'del tiempo'는 '실온의, 상온의'라는 뜻입니다.","x":["le: 간접목적격(~에게)이라 '~을'에 쓰지 않습니다 ✗","la: 여성 명사 agua를 받는 직접목적격 → 정답 ✓","las: 복수형이라 단수 agua와 맞지 않습니다 ✗","lo: 남성형인데 agua는 여성 명사입니다(관사 el에 속지 마세요) ✗"]},{"id":"G437","q":"Alberto y ____ mujer van a mudarse a otra ciudad.","o":["sus","suya","la suya","su"],"a":3,"k":"소유형용사 su","t":"알베르토와 그의 아내는 다른 도시로 이사할 예정이다.","e":"'그의 아내'처럼 명사 앞에 오는 3인칭 소유형용사는 su(단수)/sus(복수)입니다. mujer(아내)가 단수이므로 su를 씁니다. 여기서 mujer는 '여자'가 아니라 '아내'라는 뜻입니다.","x":["sus: 복수형이라 단수 mujer와 맞지 않습니다 ✗","suya: 명사 뒤에 쓰는 강세형입니다 ✗","la suya: '그의 것'이라 뒤에 명사가 올 수 없습니다 ✗","su: 단수 명사 앞 '그의' → 정답 ✓"]},{"id":"G438","q":"Me duele mucho ____ cabeza.","o":["mía","la mía","mi","la"],"a":3,"k":"신체 부위 + 관사","t":"나는 머리가 너무 아프다.","e":"신체 부위를 말할 때 스페인어는 소유형용사(mi) 대신 정관사(la)를 씁니다. 누구의 머리인지는 이미 me(나에게)로 알 수 있기 때문입니다. 'Me duele la cabeza(머리가 아프다)', 'Me duelen los pies(발이 아프다)'.","x":["mía: 명사 앞에 쓰지 않는 형태입니다 ✗","la mía: '내 것'이라 뒤에 명사가 올 수 없습니다 ✗","mi: 신체 부위에는 보통 소유형용사 대신 관사를 씁니다 ✗","la: 신체 부위 앞 정관사 → 정답 ✓"]},{"id":"G439","q":"Me gustaría ____ más, pero no tengo suficiente dinero.","o":["viajo","viajando","viajaría","viajar"],"a":3,"k":"gustaría + 동사원형","t":"여행을 더 다니고 싶지만 돈이 충분하지 않다.","e":"'Me gustaría + 동사원형'은 '~하고 싶다'라는 공손하고 부드러운 소망 표현입니다. gustar 뒤에 오는 동사는 항상 원형을 씁니다. 예: Me gustaría aprender a nadar.(수영을 배우고 싶다.)","x":["viajo: 활용형이라 gustaría 뒤에 쓸 수 없습니다 ✗","viajando: 현재분사라 gustaría 뒤에 쓰지 않습니다 ✗","viajaría: 조건법 활용형이라 동사가 겹칩니다 ✗","viajar: gustaría + 동사원형 → 정답 ✓"]},{"id":"G440","q":"Mis amigas no son de Francia, ____ de Bélgica.","o":["o","si no","no","sino"],"a":3,"k":"no A sino B","t":"내 친구들은 프랑스가 아니라 벨기에 출신이다.","e":"'A가 아니라 B다'라고 앞의 부정을 바로잡을 때는 'no ... sino ...'를 씁니다. sino는 한 단어이며, 'si no(만약 ~하지 않으면)'와 다르니 주의하세요.","x":["o: '또는'이라는 뜻이라 맞지 않습니다 ✗","si no: '만약 ~이 아니면'이라는 조건 표현입니다 ✗","no: 부정어 하나만으로는 '~이 아니라'를 연결하지 못합니다 ✗","sino: 'no A sino B(A가 아니라 B)' → 정답 ✓"]},{"id":"G441","q":"____ problemas que tienes no son tan importantes como piensas.","o":["La","Las","Los","El"],"a":2,"k":"정관사 los problemas","t":"네가 가진 문제들은 네 생각만큼 중요하지 않다.","e":"problema(문제)는 -a로 끝나지만 남성 명사입니다. 복수 problemas 앞에는 남성 복수 정관사 los를 씁니다. 'tan + 형용사 + como'는 '~만큼 …한'이라는 동등비교입니다.","x":["La: 여성 단수형이라 맞지 않습니다 ✗","Las: problema는 남성 명사라 las를 쓰지 않습니다 ✗","Los: 남성 복수 정관사 → 정답 ✓","El: 단수형이라 복수 problemas와 맞지 않습니다 ✗"]},{"id":"G442","q":"Todos los padres ____ preocupan por sus hijos.","o":["los","le","les","se"],"a":3,"k":"재귀동사 preocuparse","t":"모든 부모는 자기 자녀를 걱정한다.","e":"'~을 걱정하다'는 재귀동사 'preocuparse por + 대상'입니다. 주어 'Todos los padres'가 3인칭 복수이므로 재귀대명사 se를 쓰고 동사는 preocupan이 됩니다.","x":["los: 직접목적격이라 '그들을 걱정시키다'라는 뜻이 됩니다 ✗","le: 간접목적격 단수라 맞지 않습니다 ✗","les: 간접목적격 복수라 재귀동사 자리에 맞지 않습니다 ✗","se: 3인칭 재귀대명사 'se preocupan' → 정답 ✓"]},{"id":"G443","q":"A Dolores ____ encanta escuchar música clásica.","o":["les","la","las","le"],"a":3,"k":"encantar + le","t":"돌로레스는 클래식 음악 듣는 것을 아주 좋아한다.","e":"encantar(아주 좋아하다)는 gustar처럼 '좋아하는 사람'을 간접목적격 대명사로 나타냅니다. 'A Dolores(돌로레스에게)'는 3인칭 단수이므로 le를 씁니다. 'a + 사람'이 있어도 le를 꼭 함께 씁니다.","x":["les: 3인칭 복수형이라 한 사람 Dolores와 맞지 않습니다 ✗","la: 직접목적격(그녀를)이라 encantar 구문에 쓰지 않습니다 ✗","las: 직접목적격 복수형입니다 ✗","le: 3인칭 단수 간접목적격 '그녀에게' → 정답 ✓"]},{"id":"G444","q":"Manuela tiene ____ talento como su madre.","o":["menos","tanto","más","tan"],"a":1,"k":"동등비교 tanto","t":"마누엘라는 엄마만큼 재능이 있다.","e":"명사를 가지고 '~만큼 많은 …'이라고 비교할 때는 'tanto/tanta/tantos/tantas + 명사 + como'를 씁니다. talento(재능)는 남성 단수이므로 tanto가 됩니다. 형용사·부사 앞에서는 tan을 씁니다(tan alta como).","x":["menos: 'menos ... que'와 짝이라 como와 함께 쓰지 않습니다 ✗","tanto: 명사 앞 동등비교 'tanto ... como' → 정답 ✓","más: 'más ... que'와 짝이라 como와 맞지 않습니다 ✗","tan: 형용사·부사 앞에 쓰며 명사 앞에는 tanto를 씁니다 ✗"]},{"id":"G445","q":"¿Cómo ____ vuestros apellidos?","o":["escribirse","escriben se","se escribe","se escriben"],"a":3,"k":"수동의 se","t":"너희 성은 어떻게 쓰니?","e":"'se + 3인칭 동사'는 '(일반적으로) ~되다'라는 수동/무인칭 표현입니다. 주어 'vuestros apellidos(너희 성들)'가 복수이므로 동사도 복수 escriben이 되어 'se escriben'입니다. 철자를 물을 때 자주 쓰는 표현입니다: ¿Cómo se escribe tu nombre?","x":["escribirse: 동사원형이라 활용형이 필요합니다 ✗","escriben se: 활용된 동사 뒤에 se를 띄어 쓰지 않습니다 ✗","se escribe: 단수형이라 복수 주어 apellidos와 맞지 않습니다 ✗","se escriben: 복수 주어에 맞춘 수동의 se → 정답 ✓"]},{"id":"G446","q":"Esos chicos ____ varios idiomas.","o":["hablas","hablan","habláis","hablamos"],"a":1,"k":"hablar 현재 활용","t":"그 남자애들은 여러 언어를 한다.","e":"주어 'Esos chicos(그 남자애들)'는 3인칭 복수입니다. -ar 동사 hablar의 3인칭 복수 현재형은 hablan입니다. hablar 현재: hablo, hablas, habla, hablamos, habláis, hablan.","x":["hablas: tú(너) 형태입니다 ✗","hablan: 3인칭 복수 → 정답 ✓","habláis: vosotros(너희) 형태입니다 ✗","hablamos: nosotros(우리) 형태입니다 ✗"]},{"id":"G447","q":"Esta habitación ____ sucia, vamos a limpiarla.","o":["estamos","son","es","está"],"a":3,"k":"estar + 상태","t":"이 방은 지저분해, 청소하자.","e":"'더럽다, 깨끗하다'처럼 지금의 상태(변할 수 있는 것)는 estar로 말합니다. 주어 'Esta habitación'은 3인칭 단수이므로 está입니다. 청소하면 limpia(깨끗한) 상태로 바뀌니까 estar가 어울린다고 기억하세요.","x":["estamos: '우리' 형태입니다 ✗","son: ser의 3인칭 복수형이라 수와 용법 모두 틀립니다 ✗","es: ser는 일시적인 상태에 쓰지 않습니다 ✗","está: 상태를 나타내는 estar 3인칭 단수 → 정답 ✓"]},{"id":"G448","q":"No veo mis zapatos marrones. ¿Sabes ____ están?","o":["dónde","desde dónde","adónde","de dónde"],"a":0,"k":"의문사 dónde","t":"내 갈색 신발이 안 보여. 어디 있는지 알아?","e":"'어디에 있는지'처럼 위치를 물을 때는 dónde를 씁니다. 간접의문문(문장 속 질문)에서도 의문사의 악센트는 그대로 유지합니다. adónde는 '어디로', de dónde는 '어디에서/어디 출신'입니다.","x":["dónde: 위치 '어디에' → 정답 ✓","desde dónde: '어디서부터'라는 뜻이라 맞지 않습니다 ✗","adónde: '어디로'라는 방향이라 estar와 맞지 않습니다 ✗","de dónde: '어디에서(출신)'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G449","q":"Tenéis ____ preparar bien vuestro espectáculo.","o":["ø","de","que","a"],"a":2,"k":"tener que","t":"너희는 공연을 잘 준비해야 한다.","e":"의무 '~해야 한다'는 'tener que + 동사원형'입니다. 주어가 vosotros(너희)라서 tenéis가 쓰였습니다. 중남미에서는 ustedes를 써서 'Tienen que preparar...'라고 합니다.","x":["ø: que가 없으면 '~해야 한다'라는 뜻이 되지 않습니다 ✗","de: 'tener de'는 이 뜻으로 쓰지 않습니다 ✗","que: 'tener que(~해야 하다)' → 정답 ✓","a: 이 구조에 a는 쓰지 않습니다 ✗"]},{"id":"G450","q":"Bienvenidos ____ nuestra casa.","o":["en","hasta","a","hacia"],"a":2,"k":"bienvenido a","t":"우리 집에 오신 것을 환영합니다.","e":"'~에 오신 것을 환영합니다'는 'Bienvenido(s) a + 장소'로 씁니다. 도착하는 방향을 나타내므로 a를 씁니다. bienvenido는 형용사라 상대에 따라 bienvenida, bienvenidos, bienvenidas로 바뀝니다.","x":["en: 이 표현에서는 en을 쓰지 않습니다 ✗","hasta: '~까지'라는 뜻이라 맞지 않습니다 ✗","a: 'Bienvenidos a(~에 오신 것을 환영)' → 정답 ✓","hacia: '~ 쪽으로'라는 뜻이라 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"G451","q":"Ana ____ Pérez, no Ortiz.","o":["apellida","se apellida","su apellido","es apellido"],"a":1,"k":"apellidarse","t":"아나의 성은 오르티스가 아니라 페레스이다.","e":"'성이 ~이다'는 재귀동사 apellidarse(성이 ~이다)를 써서 표현합니다. 재귀동사는 se 같은 재귀대명사(자기 자신을 가리키는 대명사)와 함께 쓰므로 3인칭 단수 Ana에는 se apellida가 됩니다. llamarse(이름이 ~이다)와 같은 구조예요. 예: Me apellido García.(제 성은 가르시아입니다.)","x":["apellida: 재귀대명사 se가 빠져 있어 '성이 ~이다'라는 뜻이 되지 않습니다 ✗","se apellida: apellidarse의 3인칭 단수 형태 → 정답 ✓","su apellido: '그녀의 성'이라는 명사구라 동사가 없어 문장이 성립하지 않습니다 ✗","es apellido: 'Su apellido es Pérez'처럼 써야 하며 이 형태는 틀린 표현입니다 ✗"]},{"id":"G452","q":"Tengo una moto nueva, ¿quieres ____?","o":["verlo","ver la","verla","la ver"],"a":2,"k":"직접목적격 대명사","t":"새 오토바이가 있는데, 볼래?","e":"una moto(오토바이)는 여성 단수 명사이므로 직접목적격 대명사(~을/를에 해당) la로 받습니다. 동사원형 뒤에서는 대명사를 붙여 한 단어로 써서 verla가 됩니다. 'la quieres ver'처럼 활용된 동사 앞에 둘 수도 있어요.","x":["verlo: lo는 남성 단수를 받으므로 여성 명사 moto와 맞지 않습니다 ✗","ver la: 동사원형 뒤의 대명사는 띄어 쓰지 않고 붙여 씁니다 ✗","verla: 동사원형 + 여성 단수 직접목적격 la → 정답 ✓","la ver: 대명사는 동사원형 앞에 올 수 없습니다 ✗"]},{"id":"G453","q":"Hoy voy a quedarme en casa ____ estoy enferma.","o":["por","para","para que","porque"],"a":3,"k":"porque (이유)","t":"오늘은 아파서 집에 있을 거예요.","e":"빈칸 뒤에 'estoy enferma(나는 아프다)'라는 주어+동사가 있는 완전한 문장이 오고, 집에 있는 '이유'를 말하므로 접속사 porque(왜냐하면, ~때문에)가 맞습니다. por는 전치사라 뒤에 명사나 동사원형이 옵니다. 예: por la lluvia(비 때문에).","x":["por: 전치사라 뒤에 활용된 동사 문장을 바로 이을 수 없습니다 ✗","para: '~을 위해'라는 목적의 전치사입니다 ✗","para que: '~하도록'이라는 목적을 나타내며 뒤에 접속법이 옵니다 ✗","porque: '~때문에'라는 이유의 접속사 → 정답 ✓"]},{"id":"G454","q":"¿Es usted ____ señora Martínez?","o":["la","ø","una","el"],"a":0,"k":"정관사 + 호칭","t":"당신이 마르티네스 부인이신가요?","e":"señor, señora 같은 호칭으로 어떤 사람을 '가리켜 말할 때'는 정관사를 붙입니다. señora는 여성 단수이므로 la를 씁니다. 단, 그 사람을 직접 부를 때는 관사 없이 'Buenos días, señora Martínez'라고 합니다.","x":["la: 호칭 señora 앞의 여성 단수 정관사 → 정답 ✓","ø: 직접 부르는 말이 아니라 사람을 지칭하므로 관사가 필요합니다 ✗","una: 부정관사는 '어떤 한 부인'이라는 뜻이 되어 특정인 지칭에 맞지 않습니다 ✗","el: 남성 정관사라 señora와 성이 맞지 않습니다 ✗"]},{"id":"G455","q":"En este pueblo solo ____ una panadería.","o":["está","es","hay","son"],"a":2,"k":"hay (존재)","t":"이 마을에는 빵집이 딱 하나 있다.","e":"'~이 있다'고 무언가의 존재를 처음 알릴 때는 haber의 무인칭 형태 hay를 씁니다. 특히 부정관사(un, una)나 숫자와 함께 쓰일 때 hay가 자연스럽습니다. 반면 특정한 것이 '어디에 있는지' 말할 때는 estar를 씁니다. 예: La panadería está en la plaza.(그 빵집은 광장에 있다.)","x":["está: 정해진 대상의 위치를 말할 때 쓰며 una panadería와는 어울리지 않습니다 ✗","es: ser는 성질·정체를 나타내므로 존재 표현이 아닙니다 ✗","hay: 존재를 나타내는 무인칭 형태 → 정답 ✓","son: ser의 3인칭 복수로 의미와 수가 모두 맞지 않습니다 ✗"]},{"id":"G456","q":"Me gustaría hablar ____.","o":["a ti","con ti","contigo","con tu"],"a":2,"k":"con + 대명사","t":"너와 이야기하고 싶어.","e":"전치사 con(~와 함께) 뒤에 1·2인칭 단수 대명사가 오면 특별한 형태 conmigo(나와), contigo(너와)를 씁니다. 'con ti', 'con mí'라고 하지 않으니 통째로 외워 두세요. 3인칭은 con él, con ella처럼 평범하게 씁니다.","x":["a ti: '너에게'라는 뜻이라 hablar con(~와 이야기하다)의 의미와 맞지 않습니다 ✗","con ti: con + ti는 contigo로 바뀌므로 틀린 형태입니다 ✗","contigo: '너와 함께'의 특수 형태 → 정답 ✓","con tu: tu는 소유형용사(너의)라 뒤에 명사가 필요합니다 ✗"]},{"id":"G457","q":"La panadería está ____ el banco y el estanco.","o":["en","por","con","entre"],"a":3,"k":"위치 전치사 entre","t":"빵집은 은행과 담배 가게 사이에 있다.","e":"'A와 B 사이에'는 entre A y B로 표현합니다. 문장에 'el banco y el estanco' 두 장소가 나와 있으므로 entre가 맞습니다. estanco는 스페인의 담배·우표 판매점이에요.","x":["en: '~안에/~에'라는 뜻으로 두 장소 사이를 나타낼 수 없습니다 ✗","por: '~쯤에, ~을 지나서'라는 뜻이라 맞지 않습니다 ✗","con: '~와 함께'라는 뜻이라 위치 표현이 아닙니다 ✗","entre: 'A와 B 사이에' → 정답 ✓"]},{"id":"G458","q":"Odio ____ tan temprano.","o":["levantar","levantar me","me levanto","levantarme"],"a":3,"k":"재귀동사 원형","t":"나는 이렇게 일찍 일어나는 게 너무 싫다.","e":"odiar(몹시 싫어하다) 뒤에 동사가 오면 동사원형을 씁니다. levantarse(일어나다)는 재귀동사이므로 주어 yo에 맞춰 재귀대명사 me를 원형 끝에 붙여 levantarme가 됩니다. 예: Me gusta ducharme por la noche.(나는 밤에 샤워하는 걸 좋아한다.)","x":["levantar: 재귀대명사가 없으면 '(무언가를) 들어 올리다'라는 뜻이 됩니다 ✗","levantar me: 대명사는 원형에 붙여 써야 합니다 ✗","me levanto: 활용된 동사라 odio 바로 뒤에 올 수 없습니다 ✗","levantarme: 원형 + me를 붙인 형태 → 정답 ✓"]},{"id":"G459","q":"No quiero otro tenedor, gracias, ya tengo ____.","o":["una","un","uno","lo"],"a":2,"k":"부정대명사 uno","t":"포크 하나 더는 필요 없어요, 고마워요. 이미 하나 있어요.","e":"앞에 나온 남성 명사(tenedor, 포크)를 '하나'라고 대신 받을 때는 명사 없이 uno를 씁니다. un은 뒤에 명사가 있을 때만 쓰는 형태예요(un tenedor). 여성 명사라면 una를 씁니다.","x":["una: 여성형이라 남성 명사 tenedor를 받을 수 없습니다 ✗","un: 뒤에 명사가 와야 하는 형태입니다 ✗","uno: 명사 없이 남성 명사를 대신하는 '하나' → 정답 ✓","lo: '그것을'이라는 특정 대상을 가리켜 '이미 하나 있다'는 뜻이 되지 않습니다 ✗"]},{"id":"G460","q":"¿Cómo ____ el clima en vuestra ciudad?","o":["es","tiene","existe","hay"],"a":0,"k":"ser (성질 묘사)","t":"너희 도시의 기후는 어때?","e":"기후(el clima)가 어떤 성질을 가졌는지 물을 때는 '¿Cómo es...?'를 씁니다. ser는 사람·사물의 본질적인 특징을 나타내요. vuestra는 스페인에서 쓰는 vosotros(너희)의 소유형으로, 중남미에서는 'su ciudad (de ustedes)'라고 합니다.","x":["es: 기후의 특징을 묻는 ser → 정답 ✓","tiene: '가지고 있다'라는 뜻이라 '기후가 어떤가'를 물을 수 없습니다 ✗","existe: '존재하다'라는 뜻이라 의미가 맞지 않습니다 ✗","hay: 존재를 나타내며 정관사가 붙은 el clima와 쓰지 않습니다 ✗"]},{"id":"G461","q":"Últimamente tengo ____ tiempo libre.","o":["poco","un poco","pocos","poca"],"a":0,"k":"poco vs un poco","t":"요즘 나는 자유 시간이 별로 없다.","e":"tiempo(시간)는 남성 단수 명사이므로 poco(적은)를 씁니다. poco는 '거의 없다'는 부정적인 느낌, un poco de는 '조금 있다'는 긍정적인 느낌이에요. 'un poco tiempo'가 아니라 'un poco de tiempo'로 써야 합니다.","x":["poco: 남성 단수 명사 앞 '별로 없는' → 정답 ✓","un poco: 명사 앞에서는 un poco de 형태로 써야 합니다 ✗","pocos: 남성 복수형이라 단수 명사 tiempo와 맞지 않습니다 ✗","poca: 여성형이라 남성 명사 tiempo와 맞지 않습니다 ✗"]},{"id":"G462","q":"¿Dónde ____ más estudiantes? ¿En esta clase o en la otra?","o":["hay","están","estás","han"],"a":0,"k":"hay (존재)","t":"어디에 학생이 더 많아? 이 반이야, 아니면 다른 반이야?","e":"'학생이 더 많이 있다'는 정해지지 않은 사람 수의 존재를 묻는 것이므로 hay를 씁니다. hay는 뒤의 명사가 복수여도 형태가 변하지 않아요. 예: Hay muchos coches.(차가 많이 있다.)","x":["hay: 수량 표현(más estudiantes)과 함께 존재를 묻는 형태 → 정답 ✓","están: 정해진 대상(los estudiantes)의 위치에 쓰며 más와 함께 쓰지 않습니다 ✗","estás: 2인칭 단수(너는 ~에 있다)라 주어와 맞지 않습니다 ✗","han: haber의 완료 시제 조동사로 홀로 '있다'는 뜻이 되지 않습니다 ✗"]},{"id":"G463","q":"No quiero melón ____ sandía, prefiero otra fruta.","o":["no","ni","o","y"],"a":1,"k":"ni (부정 연결)","t":"멜론도 수박도 싫어요, 다른 과일이 좋아요.","e":"부정문에서 'A도 B도 아니다'라고 할 때는 y 대신 ni를 씁니다. 'No quiero A ni B'는 둘 다 원하지 않는다는 뜻이에요. 예: No bebo café ni té.(나는 커피도 차도 마시지 않는다.)","x":["no: 접속사 역할을 하지 못하므로 두 명사를 이을 수 없습니다 ✗","ni: 부정문에서 '~도 (아니다)' → 정답 ✓","o: '또는'이라 '멜론이나 수박 중 하나를 원하지 않는다'는 어색한 뜻이 됩니다 ✗","y: 부정문에서 두 대상을 모두 부정할 때는 y 대신 ni를 씁니다 ✗"]},{"id":"G464","q":"Llevamos media hora ____ en la parada de autobús.","o":["esperamos","esperar","a esperar","esperando"],"a":3,"k":"llevar + 현재분사","t":"우리는 버스 정류장에서 30분째 기다리고 있다.","e":"'llevar + 시간 + 현재분사(-ando/-iendo)'는 '~동안 계속 ~하고 있다'는 뜻으로, 어떤 행동이 얼마나 오래 지속되었는지를 나타냅니다. esperar(기다리다)의 현재분사는 esperando예요. 예: Llevo dos años estudiando español.(나는 2년째 스페인어를 공부하고 있다.)","x":["esperamos: 활용된 동사라 llevar 구문에 들어갈 수 없습니다 ✗","esperar: 이 구문에는 동사원형이 아니라 현재분사를 씁니다 ✗","a esperar: 'llevar ... a + 원형' 구조는 존재하지 않습니다 ✗","esperando: llevar + 시간 + 현재분사 → 정답 ✓"]},{"id":"G465","q":"Lo primero que hago al levantarme es darles la comida ____ mis gatos.","o":["a las","al","a","a los"],"a":2,"k":"간접목적어 a","t":"일어나서 제일 먼저 하는 일은 우리 고양이들에게 밥을 주는 것이다.","e":"dar(주다)는 '누구에게' 주는지를 전치사 a로 나타냅니다. 빈칸 뒤에 소유형용사 mis가 있으므로 관사 없이 a만 씁니다. darles의 les는 'a mis gatos'를 미리 받는 간접목적격 대명사(~에게)예요.","x":["a las: 소유형용사 mis 앞에는 관사를 쓰지 않습니다 ✗","al: a + el의 축약형으로 mis와 함께 쓸 수 없습니다 ✗","a: '~에게'를 나타내는 전치사 → 정답 ✓","a los: mis가 있어 관사 los가 중복됩니다 ✗"]},{"id":"G466","q":"Nunca bebo ____ café, no me gusta.","o":["lo","la","ø","el"],"a":2,"k":"무관사 명사","t":"나는 절대 커피를 마시지 않아, 좋아하지 않거든.","e":"음식·음료를 일반적으로 '마시다/먹다'라고 할 때, 특히 부정문에서는 셀 수 없는 명사 앞에 관사를 붙이지 않습니다. 'No bebo café'처럼 씁니다. 반면 gustar 구문에서는 'Me gusta el café'처럼 정관사가 필요해요.","x":["lo: 대명사라 명사 café 앞에 올 수 없습니다 ✗","la: 여성 관사이며 café는 남성 명사입니다 ✗","ø: 일반적인 음료를 말할 때 관사 없이 씀 → 정답 ✓","el: 특정한 커피를 가리키는 것이 아니므로 관사가 필요 없습니다 ✗"]},{"id":"G467","q":"Por favor, Pablito, ____ tu cama antes de salir de casa.","o":["haz","hacer","hace","haced"],"a":0,"k":"tú 긍정 명령 haz","t":"파블리토, 집에서 나가기 전에 네 침대를 정리하렴.","e":"Pablito 한 명에게 tu(너의)로 말하므로 tú에 대한 긍정 명령형을 씁니다. hacer(하다, 만들다)의 tú 명령형은 불규칙형 haz예요. 'hacer la cama'는 '침대를 정돈하다'라는 관용 표현입니다.","x":["haz: hacer의 tú 긍정 명령 불규칙형 → 정답 ✓","hacer: 동사원형이라 명령문이 되지 않습니다 ✗","hace: 3인칭 단수 현재형(그가 한다)입니다 ✗","haced: vosotros(너희)에 대한 명령형이라 한 사람에게 쓰지 않습니다 ✗"]},{"id":"G468","q":"Siempre ____ a casa al mediodía.","o":["volve","volver","vuelvo","volvo"],"a":2,"k":"어간변화 o→ue","t":"나는 늘 정오에 집으로 돌아간다.","e":"volver(돌아가다/돌아오다)는 현재형에서 어간의 o가 ue로 바뀌는 어간변화 동사입니다. 주어 yo는 vuelvo가 되죠. nosotros/vosotros에서는 바뀌지 않아요(volvemos, volvéis).","x":["volve: 존재하지 않는 형태입니다 ✗","volver: 동사원형이라 주어에 맞게 활용해야 합니다 ✗","vuelvo: o→ue 변화를 한 1인칭 단수 → 정답 ✓","volvo: 어간변화를 하지 않은 틀린 형태입니다 ✗"]},{"id":"G469","q":"¿Hay buenos restaurantes en esta calle? —Sí, en esa esquina hay ____.","o":["una","unas","un","uno"],"a":3,"k":"부정대명사 uno","t":"이 거리에 좋은 식당이 있나요? —네, 저 모퉁이에 하나 있어요.","e":"앞에 나온 restaurante(식당, 남성 명사)를 명사 없이 '하나'로 받을 때는 uno를 씁니다. un은 'un restaurante'처럼 명사 바로 앞에서만 써요.","x":["una: 여성형이라 남성 명사 restaurante를 받을 수 없습니다 ✗","unas: 여성 복수라 성과 수가 모두 맞지 않습니다 ✗","un: 뒤에 명사가 와야 하는 형태입니다 ✗","uno: 남성 명사를 대신하는 '하나' → 정답 ✓"]},{"id":"G470","q":"Estudiamos coreano ____ tres años.","o":["desde que","desde hace","de","desde"],"a":1,"k":"desde hace (기간)","t":"우리는 3년 전부터 한국어를 공부하고 있다.","e":"현재까지 계속되는 일의 '기간'을 말할 때는 'desde hace + 기간'을 씁니다. 반면 시작 '시점'(날짜, 연도)을 말할 때는 desde만 씁니다. 예: desde 2020(2020년부터), desde hace tres años(3년 전부터).","x":["desde que: 뒤에 주어+동사 문장이 와야 합니다 ✗","desde hace: '~ 전부터(기간)' → 정답 ✓","de: '~의/~에서'라는 뜻으로 기간을 나타내지 못합니다 ✗","desde: 시점 앞에 쓰며 tres años 같은 기간 앞에는 hace가 필요합니다 ✗"]},{"id":"G471","q":"Muchas gracias ____ su generosidad.","o":["por","sobre","para","hacia"],"a":0,"k":"gracias por","t":"당신의 너그러움에 정말 감사드립니다.","e":"감사의 '이유'를 말할 때는 항상 gracias por를 씁니다. por 뒤에는 명사나 동사원형이 올 수 있어요. 예: Gracias por venir.(와 줘서 고마워요.)","x":["por: 감사의 이유를 나타냄 → 정답 ✓","sobre: '~에 관하여, ~위에'라는 뜻입니다 ✗","para: 목적·대상을 나타내며 gracias와 함께 이유를 말하지 않습니다 ✗","hacia: '~을 향해'라는 방향을 나타냅니다 ✗"]},{"id":"G472","q":"No puedo comprar esa moto; es ____ cara para mí.","o":["poco","más","demasiado","mucho"],"a":2,"k":"demasiado","t":"그 오토바이는 살 수 없어. 나한테는 너무 비싸.","e":"demasiado는 '지나치게, 너무'라는 뜻으로 형용사 앞에 쓰여 정도가 넘친다는 의미를 줍니다. 그래서 '살 수 없다'는 이유와 잘 어울립니다. 형용사 앞에서 '매우'는 mucho가 아니라 muy를 써요.","x":["poco: '별로 ~하지 않은'이라 살 수 없다는 내용과 반대입니다 ✗","más: 비교 대상(que ...)이 없어 문장이 불완전합니다 ✗","demasiado: '너무 (지나치게)' → 정답 ✓","mucho: 형용사 앞에서는 mucho가 아니라 muy를 씁니다 ✗"]},{"id":"G473","q":"¿Cómo ____ tu madre?","o":["se llaman","te llaman","se llama","te llamas"],"a":2,"k":"llamarse","t":"너희 어머니 성함이 어떻게 되시니?","e":"이름을 물을 때는 재귀동사 llamarse(이름이 ~이다)를 씁니다. 주어는 tu madre(너의 어머니), 즉 3인칭 단수이므로 se llama가 맞습니다. 예: Mi madre se llama Ana.(우리 어머니 이름은 아나야.)","x":["se llaman: 3인칭 복수라 주어 한 명과 맞지 않습니다 ✗","te llaman: '사람들이 너를 부른다'라는 뜻이 됩니다 ✗","se llama: 3인칭 단수 llamarse → 정답 ✓","te llamas: '너의 이름'을 묻는 형태입니다 ✗"]},{"id":"G474","q":"Sé conducir, pero no tengo ____ coche.","o":["un","uno","algún","ø"],"a":3,"k":"tener + 무관사","t":"나는 운전할 줄 알지만 차가 없다.","e":"tener(가지다)의 부정문에서 하나만 갖는 것이 일반적인 물건(차, 집, 휴대폰 등)은 보통 관사 없이 씁니다. 'No tengo coche'가 가장 자연스러운 표현이에요. 'no tengo ningún coche'는 '차가 한 대도 없다'는 강조 표현입니다.","x":["un: 부정문에서 un을 쓰면 '차 한 대'를 강조하는 어색한 느낌이 됩니다 ✗","uno: 명사 앞에서는 uno를 쓰지 않습니다 ✗","algún: 부정문에서는 algún 대신 ningún을 씁니다 ✗","ø: 부정문 tener + 무관사 명사 → 정답 ✓"]},{"id":"G475","q":"Esta foto es ____ mi viaje a Grecia.","o":["de","del","de un","de la"],"a":0,"k":"전치사 de (소유)","t":"이 사진은 내 그리스 여행 사진이야.","e":"'~의'라는 관계를 나타낼 때는 de를 씁니다. 뒤에 소유형용사 mi(나의)가 있으므로 관사를 쓰지 않아요. 따라서 'de mi viaje'가 됩니다.","x":["de: '~의'를 나타내는 전치사 → 정답 ✓","del: de + el인데 mi 앞에 관사를 둘 수 없습니다 ✗","de un: 부정관사와 소유형용사 mi를 함께 쓸 수 없습니다 ✗","de la: 관사가 중복되고 viaje는 남성 명사입니다 ✗"]},{"id":"G476","q":"¿Por qué ____ llorando?","o":["estando","estás","estés","estado"],"a":1,"k":"estar + 현재분사","t":"너 왜 울고 있어?","e":"지금 진행 중인 동작은 'estar + 현재분사'로 표현합니다. 주어가 tú(너)이므로 estás llorando이 됩니다. 예: Estoy comiendo.(나는 먹고 있다.)","x":["estando: 현재분사라 활용된 동사가 필요한 자리에 올 수 없습니다 ✗","estás: estar의 tú 현재형 → 정답 ✓","estés: 접속법(바람·의심 등을 나타내는 형태)으로 일반 의문문에 쓰지 않습니다 ✗","estado: 과거분사라 haber와 함께 써야 합니다 ✗"]},{"id":"G477","q":"Gracias a todos por ____ atención.","o":["su","tu","sus","tus"],"a":0,"k":"소유형용사 su","t":"여러분 모두의 관심에 감사드립니다.","e":"todos(여러분 모두)에게 공손하게 말하는 상황으로, ustedes(여러분)의 소유형용사는 su입니다. atención(관심)은 단수 명사이므로 복수형 sus가 아닌 su를 써요. 스페인에서 친한 사이라면 'vuestra atención'도 가능합니다.","x":["su: ustedes의 소유형, 단수 명사 앞 → 정답 ✓","tu: 한 명(너)에게 쓰는 소유형이라 todos와 맞지 않습니다 ✗","sus: 복수형이라 단수 명사 atención과 맞지 않습니다 ✗","tus: 2인칭 단수의 복수형으로 인칭과 수가 맞지 않습니다 ✗"]},{"id":"G478","q":"Espero ____ tengas suerte en tu examen.","o":["como","que","ø","de que"],"a":1,"k":"esperar que","t":"네가 시험에서 운이 좋기를 바라.","e":"'~하기를 바라다'는 'esperar que + 접속법(바람·의심·감정을 나타내는 동사 형태)'으로 말합니다. tengas는 tener의 접속법 현재 tú 형태예요. 두 문장을 잇는 접속사 que는 생략할 수 없습니다.","x":["como: '~처럼'이라는 뜻이라 문장을 연결하지 못합니다 ✗","que: 명사절을 이끄는 접속사 → 정답 ✓","ø: 스페인어에서는 이 que를 생략하지 않습니다 ✗","de que: esperar는 de를 필요로 하지 않습니다 ✗"]},{"id":"G479","q":"Nuestra profesora ya está en ____ aula.","o":["el","la","las","los"],"a":0,"k":"el + 여성명사 a-","t":"우리 선생님은 이미 교실에 계셔.","e":"aula(교실)는 여성 명사이지만 강세가 있는 a로 시작하므로 발음 편의를 위해 단수에서 정관사 el을 씁니다(el agua, el águila도 같아요). 형용사는 여전히 여성형을 씁니다: el aula nueva. 복수는 las aulas예요.","x":["el: 강세 있는 a로 시작하는 여성 단수 명사 앞 → 정답 ✓","la: 강세 있는 a- 여성 명사 앞에서는 단수에서 la를 쓰지 않습니다 ✗","las: 복수 관사라 단수 aula와 맞지 않습니다 ✗","los: 남성 복수 관사로 수가 맞지 않습니다 ✗"]},{"id":"G480","q":"La farmacia ____ cerrada en este momento.","o":["es","tiene","está","hay"],"a":2,"k":"estar + 상태","t":"약국은 지금 문을 닫은 상태이다.","e":"'문이 닫혀 있다'는 일시적인 상태를 나타내므로 estar를 씁니다. cerrada는 과거분사가 형용사처럼 쓰인 것으로 주어 la farmacia(여성 단수)에 맞춰 -a로 끝납니다. 'en este momento(지금 이 순간)'도 일시적 상태라는 힌트예요.","x":["es: ser는 본질·성질에 쓰며 일시적 상태에는 맞지 않습니다 ✗","tiene: '가지다'라는 뜻이라 cerrada와 연결되지 않습니다 ✗","está: 일시적인 상태를 나타내는 estar → 정답 ✓","hay: 존재를 나타내며 정관사가 붙은 주어와 쓰지 않습니다 ✗"]},{"id":"G481","q":"Chicos, ¿qué ____ aquí?","o":["estáis haciendo","estás haciendo","estar haciendo","haciendo"],"a":0,"k":"현재진행 vosotros","t":"얘들아, 여기서 뭐 하고 있니?","e":"Chicos(얘들아)는 여러 명에게 말하는 것이므로 스페인에서는 vosotros 형태를 씁니다. 진행 중인 동작은 'estar + 현재분사'이므로 estáis haciendo가 됩니다. 중남미에서는 ustedes를 써서 '¿qué están haciendo?'라고 해요.","x":["estáis haciendo: vosotros의 현재진행형 → 정답 ✓","estás haciendo: tú(한 명) 형태라 Chicos와 맞지 않습니다 ✗","estar haciendo: estar가 활용되지 않아 문장이 되지 않습니다 ✗","haciendo: 현재분사만으로는 동사 역할을 하지 못합니다 ✗"]},{"id":"G482","q":"Son las once ____ punto.","o":["sobre","de","en","a"],"a":2,"k":"en punto (정각)","t":"11시 정각이다.","e":"'정각'은 en punto라는 고정 표현으로 말합니다. 'Son las once en punto'는 '11시 정각이에요'라는 뜻이에요. 비슷하게 'y media(30분)', 'y cuarto(15분)', 'menos cuarto(15분 전)'도 함께 외워 두세요.","x":["sobre: '대략'이라는 뜻으로 sobre las once처럼 쓰며 punto와 결합하지 않습니다 ✗","de: de punto라는 표현은 없습니다 ✗","en: en punto '정각' → 정답 ✓","a: a punto는 '막 ~하려는'이라는 다른 표현입니다 ✗"]},{"id":"G483","q":"Este es mi café y ese es ____.","o":["el tuyo","tu","la tuya","tuya"],"a":0,"k":"소유대명사","t":"이건 내 커피고, 저건 네 거야.","e":"명사 없이 '네 것'이라고 할 때는 소유대명사(관사 + 소유형)를 씁니다. 앞에 나온 café는 남성 단수이므로 el tuyo가 맞습니다. 여성 명사라면 la tuya가 돼요. 예: Esta es mi taza y esa es la tuya.","x":["el tuyo: 남성 단수 소유대명사 '네 것' → 정답 ✓","tu: 소유형용사라 뒤에 명사가 필요합니다 ✗","la tuya: 여성형이라 남성 명사 café와 맞지 않습니다 ✗","tuya: 여성형이며 관사도 빠져 있습니다 ✗"]},{"id":"G484","q":"¿____ lenguas oficiales hay en España?","o":["Cuánto","Cuánta","Cuántas","Cuántos"],"a":2,"k":"의문사 cuántos/as","t":"스페인에는 공용어가 몇 개 있나요?","e":"'몇 개'를 물을 때 cuánto는 뒤의 명사에 성·수를 맞춥니다. lenguas(언어들)는 여성 복수이므로 Cuántas가 됩니다. 의문사는 항상 악센트가 있어요(cuántas).","x":["Cuánto: 남성 단수라 lenguas와 맞지 않습니다 ✗","Cuánta: 여성 단수라 복수 명사와 맞지 않습니다 ✗","Cuántas: 여성 복수 → 정답 ✓","Cuántos: 남성 복수라 여성 명사 lenguas와 맞지 않습니다 ✗"]},{"id":"G485","q":"Mario habla español e inglés y ____.","o":["a mí también","yo tampoco","yo sí","yo también"],"a":3,"k":"también/tampoco","t":"마리오는 스페인어와 영어를 하고, 나도 그래.","e":"앞 문장이 긍정(habla)이고 '나도 마찬가지'라고 동의할 때는 'yo también'을 씁니다. 앞 문장이 부정이면 'yo tampoco(나도 아니야)'를 써요. gustar 같은 동사에서는 'a mí también'이 됩니다.","x":["a mí también: gustar류 동사에 동의할 때 쓰는 형태입니다 ✗","yo tampoco: 부정문에 동의할 때 쓰는 표현입니다 ✗","yo sí: 앞이 부정문일 때 '나는 해'라고 반대할 때 씁니다 ✗","yo también: 긍정문에 대한 '나도' → 정답 ✓"]},{"id":"G486","q":"Ese escritor tiene ____ novelas interesantes.","o":["alguna","algunos","algún","algunas"],"a":3,"k":"algunos/as","t":"그 작가는 재미있는 소설이 몇 편 있다.","e":"'몇몇의'는 alguno를 쓰며 뒤의 명사에 성·수를 맞춥니다. novelas(소설들)는 여성 복수이므로 algunas가 됩니다. 남성 단수 명사 앞에서는 algún으로 줄어들어요(algún libro).","x":["alguna: 여성 단수라 복수 명사 novelas와 맞지 않습니다 ✗","algunos: 남성 복수라 여성 명사와 맞지 않습니다 ✗","algún: 남성 단수 명사 앞에 쓰는 형태입니다 ✗","algunas: 여성 복수 '몇몇의' → 정답 ✓"]},{"id":"G487","q":"Elvira habla rumano ____.","o":["muy bien","muy buena","mucho bien","muy bueno"],"a":0,"k":"bien vs bueno","t":"엘비라는 루마니아어를 아주 잘한다.","e":"동사(habla)를 꾸며 '잘'이라고 할 때는 부사 bien을 씁니다. bueno/buena는 명사를 꾸미는 형용사예요. 부사를 강조할 때는 mucho가 아니라 muy를 써서 muy bien이 됩니다.","x":["muy bien: 동사를 꾸미는 부사 '아주 잘' → 정답 ✓","muy buena: 형용사라 동사를 꾸밀 수 없습니다 ✗","mucho bien: 부사 앞의 강조는 muy를 씁니다 ✗","muy bueno: 형용사라 동사 habla를 수식하지 못합니다 ✗"]},{"id":"G488","q":"Elena llama a su hija ____ días.","o":["todas","todos los","todas las","todos"],"a":1,"k":"todos los días","t":"엘레나는 매일 딸에게 전화한다.","e":"'매일'은 'todos los días'라는 고정 표현입니다. día는 -a로 끝나지만 남성 명사라서 todos los를 씁니다. 같은 방식으로 todas las semanas(매주), todos los años(매년)라고 해요.","x":["todas: 여성형이며 관사도 빠져 있습니다 ✗","todos los: 남성 복수 명사 días 앞 → 정답 ✓","todas las: día는 남성 명사라 여성형을 쓰지 않습니다 ✗","todos: '매일'이라는 뜻에는 정관사 los가 필요합니다 ✗"]},{"id":"G489","q":"Me gusta ____ música pop desde pequeña.","o":["a la","por la","la","el"],"a":2,"k":"gustar + 정관사","t":"나는 어릴 때부터 팝 음악을 좋아한다.","e":"gustar 구문에서 좋아하는 대상(주어)이 일반적인 명사일 때는 정관사를 붙입니다. música는 여성 명사이므로 la música가 됩니다. 이 명사는 문장의 주어라서 앞에 a를 붙이지 않아요.","x":["a la: música는 gustar의 주어이므로 전치사 a를 쓰지 않습니다 ✗","por la: por는 이 문장에서 필요 없는 전치사입니다 ✗","la: 여성 단수 정관사 → 정답 ✓","el: 남성 관사라 여성 명사 música와 맞지 않습니다 ✗"]},{"id":"G490","q":"¿____ cuándo estudias chino?","o":["En","De","Desde","A"],"a":2,"k":"desde cuándo","t":"너 언제부터 중국어를 공부하고 있어?","e":"어떤 일이 '언제부터' 시작되었는지 물을 때는 '¿Desde cuándo...?'를 씁니다. 대답은 'Desde 2022(2022년부터)'나 'Desde hace dos años(2년 전부터)'처럼 할 수 있어요.","x":["En: ¿En cuándo?라는 표현은 쓰지 않습니다 ✗","De: ¿De cuándo?는 '언제 것인지(시기)'를 묻는 뜻입니다 ✗","Desde: '언제부터' → 정답 ✓","A: ¿A cuándo?는 쓰지 않는 표현입니다 ✗"]},{"id":"G491","q":"Ismael ____ el novio de Alicia.","o":["es","está","estoy","soy"],"a":0,"k":"ser (관계)","t":"이스마엘은 알리시아의 남자친구이다.","e":"사람의 정체나 관계(친구, 가족, 연인 등)를 말할 때는 ser를 씁니다. 주어 Ismael은 3인칭 단수이므로 es가 됩니다. 예: Ana es mi hermana.(아나는 내 여동생이다.)","x":["es: 관계를 나타내는 ser 3인칭 단수 → 정답 ✓","está: estar는 상태·위치를 나타내므로 관계에 쓰지 않습니다 ✗","estoy: 1인칭(나는)이라 주어와 맞지 않습니다 ✗","soy: 1인칭(나는)이라 주어와 맞지 않습니다 ✗"]},{"id":"G492","q":"Tengo una cita médica mañana a las ocho ____ la mañana.","o":["por","a","de","con"],"a":2,"k":"de la mañana","t":"내일 아침 8시에 병원 예약이 있다.","e":"정확한 시각 뒤에 '오전/오후/밤'을 덧붙일 때는 전치사 de를 써서 de la mañana(오전), de la tarde(오후), de la noche(밤)라고 합니다. 시각 없이 '아침에'라고 할 때는 por la mañana를 써요.","x":["por: 시각 없이 '아침에'라고 할 때 씁니다 ✗","a: a la mañana는 일부 중남미 지역 외에는 쓰지 않으며 시각 뒤에는 맞지 않습니다 ✗","de: 시각 뒤 '오전의' → 정답 ✓","con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G493","q":"No sé dónde ____ mis gafas.","o":["es","están","son","está"],"a":1,"k":"estar 복수 (위치)","t":"내 안경이 어디 있는지 모르겠다.","e":"정해진 물건이 '어디에 있는지' 말할 때는 estar를 씁니다. gafas(안경)는 항상 복수로 쓰는 명사이므로 3인칭 복수 están이 맞습니다. 중남미에서는 안경을 lentes나 anteojos라고도 해요.","x":["es: ser는 위치에 쓰지 않으며 수도 맞지 않습니다 ✗","están: 위치를 나타내는 estar 3인칭 복수 → 정답 ✓","son: ser는 물건의 위치를 나타내지 않습니다 ✗","está: 단수형이라 복수 명사 gafas와 맞지 않습니다 ✗"]},{"id":"G494","q":"Vengo ____ supermercado.","o":["de el","de la","del","de"],"a":2,"k":"축약 del","t":"나는 슈퍼마켓에서 오는 길이야.","e":"전치사 de와 남성 정관사 el이 만나면 반드시 del로 줄여 씁니다. supermercado는 남성 명사이므로 'del supermercado'가 됩니다. a + el도 al로 줄어들어요.","x":["de el: 반드시 del로 축약해야 합니다 ✗","de la: 여성 관사라 남성 명사와 맞지 않습니다 ✗","del: de + el의 축약형 → 정답 ✓","de: 특정 장소이므로 관사가 필요합니다 ✗"]},{"id":"G495","q":"¿Por qué te ____ tanto este tema?","o":["interesan","interesa","interesáis","interesas"],"a":1,"k":"interesar 구문","t":"너는 왜 이 주제에 그렇게 관심이 많아?","e":"interesar(~에게 흥미를 주다)는 gustar처럼 관심의 대상이 주어가 되는 동사입니다. 주어는 este tema(이 주제, 단수)이므로 3인칭 단수 interesa를 씁니다. te는 '너에게'를 뜻해요.","x":["interesan: 3인칭 복수라 단수 주어 este tema와 맞지 않습니다 ✗","interesa: 주어 este tema에 맞춘 3인칭 단수 → 정답 ✓","interesáis: vosotros 형태라 주어와 맞지 않습니다 ✗","interesas: '너가 (남에게) 흥미롭다'라는 뜻이 됩니다 ✗"]},{"id":"G496","q":"Por favor, ____ la ventana, tengo frío.","o":["no cierra","no cierres","cierras","cierra"],"a":3,"k":"tú 긍정 명령","t":"창문 좀 닫아 줘, 추워.","e":"춥다고 하니 창문을 '닫으라'는 긍정 명령이 필요합니다. cerrar(닫다)는 e→ie 어간변화 동사로, tú 긍정 명령형은 3인칭 단수 현재형과 같은 cierra예요. 부정 명령은 'no cierres'로 접속법 형태를 씁니다.","x":["no cierra: 부정 명령은 접속법 형태를 쓰며 의미도 반대입니다 ✗","no cierres: '닫지 마'라는 부정 명령이라 의미가 반대입니다 ✗","cierras: 현재형(너는 닫는다)이라 명령이 되지 않습니다 ✗","cierra: cerrar의 tú 긍정 명령형 → 정답 ✓"]},{"id":"G497","q":"Para ____, estudiar idiomas es divertido.","o":["mí","mi","me","yo"],"a":0,"k":"전치사 + mí","t":"내게 있어 외국어 공부는 재미있다.","e":"전치사(para, a, de 등) 뒤에서 '나'는 mí를 씁니다. 소유형용사 mi(나의)와 구별하기 위해 악센트가 붙어요. 'Para mí'는 '내 생각에는, 나에게는'이라는 뜻입니다.","x":["mí: 전치사 뒤 1인칭 대명사 → 정답 ✓","mi: 악센트가 없는 mi는 '나의'라는 소유형용사입니다 ✗","me: 목적격 대명사라 전치사 뒤에 쓰지 않습니다 ✗","yo: 주격이라 전치사 뒤에 쓰지 않습니다(entre tú y yo 등 예외 제외) ✗"]},{"id":"G498","q":"Podemos ir ____ pie al centro comercial, está cerca.","o":["a","con","en","de"],"a":0,"k":"a pie","t":"쇼핑센터까지 걸어서 갈 수 있어, 가깝거든.","e":"'걸어서'는 a pie라는 고정 표현을 씁니다. 교통수단은 보통 en을 써서 en coche(차로), en metro(지하철로)라고 하지만 걷기와 말 타기는 a pie, a caballo로 말해요.","x":["a: a pie '걸어서' → 정답 ✓","con: con pie라는 표현은 없습니다 ✗","en: 교통수단에 쓰지만 pie와는 쓰지 않습니다 ✗","de: de pie는 '서서, 선 채로'라는 다른 뜻입니다 ✗"]},{"id":"G499","q":"____ pocas personas hablan cinco lenguas.","o":["Mucha","Muy","Muchos","Muchas"],"a":1,"k":"muy + 형용사","t":"다섯 개 언어를 하는 사람은 아주 드물다.","e":"pocas(적은)는 형용사이고, 형용사를 강조할 때는 muy(매우)를 씁니다. muy는 부사라서 형태가 변하지 않아요. mucho는 명사나 동사를 꾸밀 때 씁니다.","x":["Mucha: 형용사 pocas 앞에서는 강조어로 쓸 수 없습니다 ✗","Muy: 형용사를 강조하는 부사 '아주' → 정답 ✓","Muchos: 형용사 앞에 쓸 수 없으며 성도 맞지 않습니다 ✗","Muchas: 'muchas pocas'는 모순된 표현입니다 ✗"]},{"id":"G500","q":"Y tú, Eugenio, ¿dónde ____ comprar la fruta y la verdura?","o":["sueles","suelo","suele","soléis"],"a":0,"k":"soler + 원형","t":"그런데 너, 에우헤니오, 너는 보통 과일과 채소를 어디서 사?","e":"soler(보통 ~하다, ~하곤 하다)는 뒤에 동사원형이 와서 습관을 나타냅니다. o→ue 어간변화 동사이며 tú(Eugenio에게 말함)의 형태는 sueles예요. 예: Suelo correr por la mañana.(나는 보통 아침에 달린다.)","x":["sueles: soler의 tú 현재형 → 정답 ✓","suelo: 1인칭(나는)이라 tú와 맞지 않습니다 ✗","suele: 3인칭/usted 형태라 tú와 맞지 않습니다 ✗","soléis: vosotros(너희) 형태입니다 ✗"]},{"id":"G501","q":"Nos encanta ____ comida china.","o":["la","el","las","ø"],"a":0,"k":"encantar + 정관사","t":"우리는 중국 음식을 정말 좋아한다.","e":"encantar(아주 좋아하다)는 gustar와 같은 구조라서 좋아하는 대상 앞에 정관사를 붙입니다. comida(음식)는 여성 단수이므로 la comida china가 됩니다.","x":["la: 여성 단수 정관사 → 정답 ✓","el: 남성 관사라 comida와 맞지 않습니다 ✗","las: 복수 관사라 단수 명사와 맞지 않습니다 ✗","ø: gustar류 동사의 주어에는 보통 관사가 필요합니다 ✗"]},{"id":"G502","q":"Van ____ construir un nuevo edificio en esta calle.","o":["en","por","a","ø"],"a":2,"k":"ir a + 원형","t":"이 거리에 새 건물을 지을 예정이다.","e":"'ir a + 동사원형'은 가까운 미래나 계획(~할 것이다)을 나타냅니다. 여기서는 주어가 정해지지 않은 3인칭 복수 van으로 '사람들이 ~할 것이다'라는 무인칭 의미예요. 예: Voy a estudiar.(나는 공부할 거야.)","x":["en: ir 뒤 미래 표현에 en을 쓰지 않습니다 ✗","por: 'ir por'는 '가지러 가다'라는 다른 뜻입니다 ✗","a: ir a + 원형 미래 표현 → 정답 ✓","ø: ir와 원형 사이에 a가 반드시 필요합니다 ✗"]},{"id":"G503","q":"¿Has puesto la mesa? —Sí, ya ____ he puesto.","o":["la","ø","lo","los"],"a":0,"k":"직접목적격 la","t":"식탁 차렸어? —응, 벌써 차렸어.","e":"앞에 나온 la mesa(식탁, 여성 단수)를 받는 직접목적격 대명사는 la입니다. 활용된 동사(he puesto) 앞에 위치해요. 'poner la mesa'는 '식탁을 차리다'라는 관용 표현입니다.","x":["la: 여성 단수 직접목적격 → 정답 ✓","ø: 스페인어에서는 이미 언급된 목적어를 대명사로 받아 줘야 합니다 ✗","lo: 남성 단수라 mesa와 맞지 않습니다 ✗","los: 남성 복수라 성과 수가 모두 맞지 않습니다 ✗"]},{"id":"G504","q":"La moneda de Cuba ____ el peso cubano.","o":["es","tiene","está","hay"],"a":0,"k":"ser (정체)","t":"쿠바의 화폐는 쿠바 페소이다.","e":"'A는 B이다'처럼 무엇인지 정체를 밝힐 때는 ser를 씁니다. 주어 la moneda(화폐)는 3인칭 단수라 es가 됩니다.","x":["es: 정체를 나타내는 ser → 정답 ✓","tiene: '가지다'라는 뜻이라 'A=B' 관계를 나타내지 못합니다 ✗","está: 상태·위치에 쓰는 동사입니다 ✗","hay: 존재를 나타내는 무인칭 표현이라 주어와 함께 쓰지 않습니다 ✗"]},{"id":"G505","q":"Fernando siempre ____ la verdad.","o":["digo","dice","decís","dices"],"a":1,"k":"decir 현재형","t":"페르난도는 언제나 진실을 말한다.","e":"decir(말하다)는 불규칙 동사로 현재형이 digo, dices, dice, decimos, decís, dicen입니다. 주어 Fernando는 3인칭 단수이므로 dice가 맞습니다.","x":["digo: 1인칭(나는)이라 주어와 맞지 않습니다 ✗","dice: 3인칭 단수 → 정답 ✓","decís: vosotros(너희) 형태입니다 ✗","dices: tú(너는) 형태입니다 ✗"]},{"id":"G506","q":"Manuel trabaja ____.","o":["muchos","mucha","muy","mucho"],"a":3,"k":"부사 mucho","t":"마누엘은 일을 많이 한다.","e":"동사(trabaja)를 꾸며 '많이'라고 할 때는 부사 mucho를 씁니다. 부사로 쓰일 때 mucho는 형태가 변하지 않아요. muy는 형용사나 부사 앞에서만 씁니다.","x":["muchos: 복수 형용사형이라 동사를 꾸밀 수 없습니다 ✗","mucha: 여성 형용사형이라 동사를 꾸밀 수 없습니다 ✗","muy: 형용사·부사 앞에만 쓰고 동사 뒤에 홀로 쓰지 않습니다 ✗","mucho: 동사를 꾸미는 부사 '많이' → 정답 ✓"]},{"id":"G507","q":"Hoy hace ____ calor.","o":["muy","muchos","tan","mucho"],"a":3,"k":"mucho calor","t":"오늘은 아주 덥다.","e":"날씨는 'hace + 명사(calor 더위, frío 추위)'로 표현합니다. calor는 남성 명사이므로 '많은'은 mucho를 써서 'hace mucho calor'가 돼요. calor가 명사라서 muy는 쓸 수 없습니다.","x":["muy: 명사 calor 앞에서는 쓸 수 없습니다 ✗","muchos: 복수형이라 단수 명사 calor와 맞지 않습니다 ✗","tan: 비교 대상 없이 '그렇게'라는 뜻이며 명사 앞에는 tanto를 씁니다 ✗","mucho: 남성 단수 명사 앞 '많은' → 정답 ✓"]},{"id":"G508","q":"Marina es ____ linda como su mamá.","o":["tanto","tanta","tantas","tan"],"a":3,"k":"tan ... como","t":"마리나는 엄마만큼 예쁘다.","e":"형용사의 동등 비교는 'tan + 형용사 + como(~만큼 ~한)'로 표현합니다. linda(예쁜)는 형용사이므로 tan을 씁니다. 명사의 동등 비교는 tanto/a/os/as를 써요. linda는 중남미에서 특히 많이 쓰는 표현이고 스페인에서는 guapa를 더 씁니다.","x":["tanto: 명사나 동사 비교에 쓰며 형용사 앞에는 tan을 씁니다 ✗","tanta: 여성 명사 앞에 쓰는 형태입니다 ✗","tantas: 여성 복수 명사 앞에 쓰는 형태입니다 ✗","tan: 형용사 동등 비교 → 정답 ✓"]},{"id":"G509","q":"¿Alguien sabe ____ está Juliana?","o":["adonde","dónde","donde","adónde"],"a":1,"k":"간접의문 dónde","t":"훌리아나가 어디 있는지 아는 사람 있어?","e":"saber(알다) 뒤에서 '어디에 있는지'를 묻는 간접의문문은 의문사에 악센트를 그대로 붙여 dónde를 씁니다. estar(있다)는 위치를 나타내므로 '어디로'의 adónde가 아니라 '어디에'의 dónde가 맞아요.","x":["adonde: 악센트 없는 관계사 '~로 가는 곳'이며 의문의 뜻이 없습니다 ✗","dónde: 간접의문 '어디에' → 정답 ✓","donde: 악센트가 없으면 관계부사가 되어 의문의 뜻이 없습니다 ✗","adónde: '어디로'라는 방향을 물을 때 ir 같은 이동 동사와 씁니다 ✗"]},{"id":"G510","q":"¿____ algo más, señores?","o":["Deseáis","Desean","Desea","Deseas"],"a":1,"k":"ustedes 존칭","t":"손님들, 더 필요하신 것 있으세요?","e":"señores(손님들, 신사분들)에게 공손하게 말할 때는 ustedes를 쓰고, 동사는 3인칭 복수로 활용합니다. 따라서 desear(원하다)는 desean이 됩니다. 식당이나 가게에서 자주 듣는 표현이에요.","x":["Deseáis: vosotros(친한 너희) 형태라 공손한 상황에 맞지 않습니다 ✗","Desean: ustedes(여러분) 3인칭 복수 → 정답 ✓","Desea: usted(당신, 한 명) 형태라 señores와 수가 맞지 않습니다 ✗","Deseas: tú(너) 형태라 공손하지도 복수도 아닙니다 ✗"]},{"id":"G511","q":"¿Cómo ____ el apellido de José María?","o":["se escribe","se escriben","escribirse","te escribes"],"a":0,"k":"수동의 se","t":"호세 마리아의 성은 어떻게 쓰나요?","e":"'~은 어떻게 쓰나요?'처럼 행위자를 밝히지 않을 때는 se + 3인칭 동사(수동의 se)를 씁니다. 주어는 el apellido(성, 단수)이므로 se escribe가 됩니다. 예: ¿Cómo se dice 'hola' en coreano?(한국어로 'hola'는 어떻게 말해요?)","x":["se escribe: 단수 주어에 맞춘 수동의 se → 정답 ✓","se escriben: 복수형이라 단수 주어 el apellido와 맞지 않습니다 ✗","escribirse: 동사원형이라 활용이 필요합니다 ✗","te escribes: '너는 (자신을) 쓰니?'라는 엉뚱한 뜻입니다 ✗"]},{"id":"G512","q":"Este regalo es ____ ti, Ignacio.","o":["por","en","para","a"],"a":2,"k":"para (받는 사람)","t":"이 선물은 너를 위한 거야, 이그나시오.","e":"선물·편지 등을 '누구에게 주는 것인지' 받는 사람을 나타낼 때는 para를 씁니다. 'para ti'는 '너를 위한, 너에게 주는'이라는 뜻이에요. ti에는 악센트가 없다는 점도 기억하세요.","x":["por: 이유·원인을 나타내 '너 때문에'라는 뜻이 됩니다 ✗","en: '~안에'라는 뜻으로 맞지 않습니다 ✗","para: 받는 사람 '~을 위한' → 정답 ✓","a: ser와 함께 받는 사람을 나타낼 때는 para를 씁니다 ✗"]},{"id":"G513","q":"En ____ lugar, quiero darles las gracias por venir.","o":["primer","primera","primeros","primero"],"a":0,"k":"primer 어미탈락","t":"우선, 와 주신 것에 감사드리고 싶습니다.","e":"primero(첫 번째)는 남성 단수 명사 앞에서 -o가 떨어져 primer가 됩니다. lugar(장소, 자리)는 남성 명사이므로 'en primer lugar(첫째로, 우선)'라는 고정 표현이 돼요. tercero → tercer도 같은 규칙입니다.","x":["primer: 남성 단수 명사 앞 어미탈락형 → 정답 ✓","primera: 여성형이라 남성 명사 lugar와 맞지 않습니다 ✗","primeros: 복수형이라 단수 명사와 맞지 않습니다 ✗","primero: 남성 단수 명사 바로 앞에서는 -o가 탈락해야 합니다 ✗"]},{"id":"G514","q":"¿____ qué material está hecho este mantel?","o":["Desde","De","A","Para"],"a":1,"k":"de (재료)","t":"이 식탁보는 어떤 소재로 만들어졌나요?","e":"재료나 소재는 전치사 de로 나타냅니다. 'estar hecho de ~'는 '~로 만들어져 있다'는 뜻이에요. 의문문에서는 전치사가 의문사 앞으로 나와 '¿De qué...?'가 됩니다. 예: Es de algodón.(면으로 되어 있어요.)","x":["Desde: '~부터'라는 시작점을 나타냅니다 ✗","De: 재료를 나타내는 전치사 → 정답 ✓","A: '~에, ~로'라는 방향을 나타냅니다 ✗","Para: '~을 위해'라는 목적을 나타냅니다 ✗"]},{"id":"G515","q":"Mi abuelo siempre ____ sienta en la misma silla.","o":["a él","se","ø","él"],"a":1,"k":"재귀동사 sentarse","t":"우리 할아버지는 항상 같은 의자에 앉으신다.","e":"sentarse(앉다)는 재귀동사로, 주어가 3인칭 단수이면 재귀대명사 se를 활용된 동사 앞에 둡니다. sienta는 e→ie 어간변화 형태예요. se 없이 sentar만 쓰면 '(다른 사람을) 앉히다'라는 뜻이 됩니다.","x":["a él: 강조 표현이며 재귀대명사 se 없이는 문장이 성립하지 않습니다 ✗","se: 3인칭 재귀대명사 → 정답 ✓","ø: 재귀대명사가 없으면 '앉히다'라는 뜻이 됩니다 ✗","él: 주격 대명사라 이 자리에 올 수 없습니다 ✗"]},{"id":"G516","q":"María Isabel vive ____ lejos de la facultad.","o":["mucho","muchos","mucha","muy"],"a":3,"k":"muy + 부사","t":"마리아 이사벨은 학교(단과대학)에서 아주 멀리 산다.","e":"lejos(멀리)는 부사이므로 강조할 때 muy를 씁니다. 'muy lejos de ~'는 '~에서 아주 멀리'라는 뜻이에요. 반대말은 cerca(가까이)입니다.","x":["mucho: 부사 앞의 강조는 muy를 씁니다 ✗","muchos: 형용사 복수형이라 부사를 꾸밀 수 없습니다 ✗","mucha: 형용사 여성형이라 부사를 꾸밀 수 없습니다 ✗","muy: 부사 lejos를 강조 → 정답 ✓"]},{"id":"G517","q":"Odio la verdura ____ era pequeño.","o":["cuando","de que","desde","desde que"],"a":3,"k":"desde que","t":"나는 어렸을 때부터 채소를 싫어한다.","e":"'~한 때부터'처럼 뒤에 주어+동사가 있는 문장이 올 때는 desde que를 씁니다. 빈칸 뒤 'era pequeño(나는 어렸다)'가 문장이므로 desde que가 맞아요. 명사나 시점 앞에는 desde만 씁니다(desde 2010).","x":["cuando: '~할 때'라는 뜻이라 지금까지 계속된다는 의미가 없습니다 ✗","de que: 이 문장에서 쓰이지 않는 연결어입니다 ✗","desde: 뒤에 문장이 올 때는 que가 필요합니다 ✗","desde que: 문장 앞 '~한 때부터' → 정답 ✓"]},{"id":"G518","q":"¿Es verdad que en España ____ come mucho pescado?","o":["ellos","los","se","lo"],"a":2,"k":"무인칭 se","t":"스페인에서는 생선을 많이 먹는다는 게 사실이야?","e":"'사람들이 일반적으로 ~한다'고 말할 때는 se + 3인칭 동사(무인칭 se)를 씁니다. 'se come mucho pescado'는 특정 주어 없이 '생선을 많이 먹는다'는 뜻이에요. 예: Aquí se habla español.(여기서는 스페인어를 씁니다.)","x":["ellos: '그들이'라는 주어가 되어 3인칭 복수 동사가 필요합니다 ✗","los: 직접목적격 대명사로 의미가 맞지 않습니다 ✗","se: 일반적인 사실을 나타내는 무인칭 se → 정답 ✓","lo: '그것을'이라는 목적격 대명사입니다 ✗"]},{"id":"G519","q":"____ azúcar en exceso es malo para la salud.","o":["Comer","Comen","Comiendo","Si comer"],"a":0,"k":"동사원형 주어","t":"설탕을 지나치게 먹는 것은 건강에 나쁘다.","e":"스페인어에서는 동사원형이 명사처럼 주어가 될 수 있습니다. 'Comer azúcar'는 '설탕을 먹는 것'이라는 뜻이에요. 한국어로 '~하는 것'에 해당하며, 영어의 -ing처럼 현재분사를 쓰지 않는다는 점에 주의하세요.","x":["Comer: 주어 역할을 하는 동사원형 → 정답 ✓","Comen: 활용된 동사라 주어 자리에 올 수 없습니다 ✗","Comiendo: 스페인어에서 현재분사는 주어로 쓰지 않습니다 ✗","Si comer: si 뒤에는 활용된 동사가 와야 합니다 ✗"]},{"id":"G520","q":"¿____ es la lechuga? —Una planta.","o":["Cómo","Qué","Cuánto","Cuál"],"a":1,"k":"qué (정의)","t":"양상추는 뭐야? —식물이야.","e":"어떤 것의 정의나 종류(무엇인지)를 물을 때는 '¿Qué es...?'를 씁니다. 대답이 '식물'이라는 분류이므로 qué가 맞아요. cuál은 여러 개 중 '어느 것'을 고를 때 씁니다.","x":["Cómo: '어떻게, 어떤'이라는 모양·상태를 묻습니다 ✗","Qué: 정의·정체를 묻는 '무엇' → 정답 ✓","Cuánto: '얼마나'라는 양을 묻습니다 ✗","Cuál: 선택지 중 '어느 것'을 물을 때 씁니다 ✗"]},{"id":"G521","q":"¿Cuál es ____ lugar de nacimiento?","o":["vuestro","vuestros","vuestra","vuestras"],"a":0,"k":"소유형 vuestro","t":"너희의 출생지는 어디야?","e":"vuestro(너희의)는 소유되는 명사의 성·수에 맞춰 변합니다. lugar(장소)는 남성 단수이므로 vuestro가 됩니다. vosotros는 스페인에서만 쓰고, 중남미에서는 'su lugar de nacimiento'라고 해요.","x":["vuestro: 남성 단수 명사 lugar 앞 → 정답 ✓","vuestros: 복수형이라 단수 명사와 맞지 않습니다 ✗","vuestra: 여성형이라 남성 명사 lugar와 맞지 않습니다 ✗","vuestras: 여성 복수형이라 성·수가 모두 맞지 않습니다 ✗"]},{"id":"G522","q":"Los platos y los cubiertos ya están ____ la mesa, faltan los vasos.","o":["de","desde","en","a"],"a":2,"k":"en (위치)","t":"접시와 식기는 이미 식탁 위에 있고, 컵이 빠져 있다.","e":"사물이 '어디에(위에/안에)' 있는지 말할 때는 en을 씁니다. 'en la mesa'는 '식탁 위에'라는 뜻이에요. 더 정확히 '위에'를 강조하려면 'sobre la mesa'도 쓸 수 있습니다.","x":["de: '~의, ~에서'라는 뜻이라 위치를 나타내지 못합니다 ✗","desde: '~부터'라는 출발점을 나타냅니다 ✗","en: 위치 '~에/~위에' → 정답 ✓","a: '~로'라는 방향을 나타내며 estar 위치 표현에 맞지 않습니다 ✗"]},{"id":"G523","q":"¿Por qué crees ____ Marta está mintiendo?","o":["como","quien","que","ø"],"a":2,"k":"creer que","t":"너는 왜 마르타가 거짓말하고 있다고 생각해?","e":"'~라고 생각하다'는 'creer que + 문장'으로 표현합니다. que는 두 문장을 잇는 접속사로, 스페인어에서는 생략하지 않아요. 예: Creo que va a llover.(비가 올 것 같아.)","x":["como: '~처럼'이라는 뜻이라 생각의 내용을 이끌지 못합니다 ✗","quien: '~하는 사람'이라는 관계사입니다 ✗","que: 명사절을 이끄는 접속사 → 정답 ✓","ø: 스페인어에서는 이 que를 생략할 수 없습니다 ✗"]},{"id":"G524","q":"En mi barrio no hay ____ lavandería.","o":["alguna","una","nada","ninguna"],"a":3,"k":"ninguna","t":"우리 동네에는 빨래방이 하나도 없다.","e":"부정문에서 '하나도 ~ 없다'는 ninguno를 씁니다. lavandería(세탁소)는 여성 단수 명사이므로 ninguna가 됩니다. 남성 단수 명사 앞에서는 ningún으로 줄어들어요(ningún banco).","x":["alguna: 긍정 표현이라 부정문에서는 ninguna로 바꿔야 합니다 ✗","una: 부정문의 'no hay una'는 어색하며 '하나도 없다'는 ninguna로 표현합니다 ✗","nada: '아무것도'라는 대명사라 명사 앞에 쓰지 않습니다 ✗","ninguna: 여성 단수 '하나도 (없는)' → 정답 ✓"]},{"id":"G525","q":"¿De dónde ____ usted?","o":["es","eres","sois","son"],"a":0,"k":"ser de (출신)","t":"당신은 어디 출신이세요?","e":"출신은 'ser de + 장소'로 표현합니다. usted(당신)는 존칭이지만 동사는 3인칭 단수로 활용하므로 es가 됩니다. 예: Soy de Corea.(저는 한국 출신이에요.)","x":["es: usted에 맞춘 3인칭 단수 → 정답 ✓","eres: tú(너) 형태라 usted와 맞지 않습니다 ✗","sois: vosotros(너희) 형태입니다 ✗","son: ustedes/그들 복수 형태입니다 ✗"]},{"id":"G526","q":"Luego voy a ir ____ jardín para regar las flores.","o":["en el","al","a la","en la"],"a":1,"k":"축약 al","t":"이따가 꽃에 물을 주러 정원에 갈 거야.","e":"ir(가다)처럼 이동을 나타내는 동사는 목적지 앞에 a를 씁니다. jardín(정원)은 남성 명사이므로 a + el이 축약되어 al이 됩니다. de + el → del도 함께 기억하세요.","x":["en el: 이동 동사 ir는 목적지에 en이 아니라 a를 씁니다 ✗","al: a + el의 축약형 → 정답 ✓","a la: 여성 관사라 남성 명사 jardín과 맞지 않습니다 ✗","en la: 전치사와 관사가 모두 맞지 않습니다 ✗"]},{"id":"G527","q":"El gazpacho ____ un plato típico de Andalucía.","o":["está","hay","es","son"],"a":2,"k":"ser (정체)","t":"가스파초는 안달루시아의 전통 요리이다.","e":"'A는 ~이다'라고 정체나 분류를 설명할 때는 ser를 씁니다. 주어 el gazpacho는 3인칭 단수이므로 es가 됩니다. 가스파초는 토마토로 만드는 차가운 수프예요.","x":["está: 상태나 위치를 나타낼 때 씁니다 ✗","hay: 존재를 나타내며 정관사가 붙은 주어와 쓰지 않습니다 ✗","es: 정체·분류를 나타내는 ser → 정답 ✓","son: 복수형이라 단수 주어와 맞지 않습니다 ✗"]},{"id":"G528","q":"No sé cuándo ____ el cumpleaños de Federico. ¿Tú lo sabes?","o":["es","son","hay","está"],"a":0,"k":"ser (행사 시기)","t":"페데리코의 생일이 언제인지 모르겠어. 너는 알아?","e":"생일, 파티, 회의 같은 행사가 '언제/어디서 열리는지' 말할 때는 estar가 아니라 ser를 씁니다. el cumpleaños(생일)는 -s로 끝나지만 단수 명사라 es가 맞아요. 예: La fiesta es en mi casa.(파티는 우리 집에서 해.)","x":["es: 행사의 시기를 나타내는 ser 단수 → 정답 ✓","son: cumpleaños는 여기서 단수이므로 son이 아닙니다 ✗","hay: 정관사가 붙은 특정 행사와는 쓰지 않습니다 ✗","está: 행사의 시간·장소에는 estar를 쓰지 않습니다 ✗"]},{"id":"G529","q":"Aquí tiene su café. ____ dos euros.","o":["Somos","Eres","Están","Son"],"a":3,"k":"가격 ser","t":"여기 커피 나왔습니다. 2유로입니다.","e":"계산할 때 '합계 ~입니다'는 ser를 씁니다. dos euros는 복수이므로 3인칭 복수 son을 써요. 'Son dos euros'는 가게에서 자주 듣는 표현입니다. 단가를 말할 때는 'cuesta(값이 ~이다)'도 씁니다.","x":["Somos: 1인칭 복수(우리는)라 맞지 않습니다 ✗","Eres: 2인칭 단수(너는)라 맞지 않습니다 ✗","Están: estar는 가격 합계를 말할 때 쓰지 않습니다 ✗","Son: 금액(복수)을 나타내는 ser → 정답 ✓"]},{"id":"G530","q":"Este sofá cuesta ____ euros.","o":["el mil","miles","un mil","mil"],"a":3,"k":"숫자 mil","t":"이 소파는 1,000유로이다.","e":"'천(1,000)'은 un 없이 그냥 mil이라고 합니다. 영어 one thousand와 달리 'un mil'이라고 하지 않아요. 2,000은 dos mil입니다. 반면 '백만'은 un millón이라고 un을 씁니다.","x":["el mil: 숫자 앞에 정관사를 붙이지 않습니다 ✗","miles: '수천'이라는 뜻으로 정확한 가격이 아닙니다 ✗","un mil: 1,000은 un 없이 mil이라고 합니다 ✗","mil: '천' → 정답 ✓"]},{"id":"G531","q":"La facultad está a un cuarto de hora ____ metro.","o":["en","de","a","con"],"a":0,"k":"en (교통수단)","t":"대학은 지하철로 15분 거리에 있다.","e":"교통수단은 전치사 en으로 나타냅니다: en metro(지하철로), en autobús(버스로), en coche(차로). 'estar a + 시간/거리'는 '~ 거리에 있다'는 표현이에요. 걸어서는 예외로 a pie입니다.","x":["en: 교통수단 '~로' → 정답 ✓","de: 'de metro'는 교통수단을 나타내지 않습니다 ✗","a: 교통수단 앞에 a는 쓰지 않습니다 ✗","con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G532","q":"Los zapatos que más me pongo son los ____.","o":["en marrón","marrones","de marrón","marrón"],"a":1,"k":"색 형용사 일치","t":"내가 제일 자주 신는 신발은 갈색 신발이다.","e":"marrón(갈색의)은 형용사이므로 명사 zapatos(신발, 남성 복수)에 맞춰 복수형 marrones가 됩니다. 자음으로 끝나는 형용사는 -es를 붙이고, 악센트는 사라져요. 'los marrones'는 '갈색인 것들'이라는 뜻입니다.","x":["en marrón: 'en + 색'은 그런 색으로 나온다는 뜻으로 이 문장에 어색합니다 ✗","marrones: 복수 명사에 맞춘 복수형 → 정답 ✓","de marrón: 이런 형태로는 쓰지 않습니다 ✗","marrón: 단수형이라 복수 명사 zapatos와 맞지 않습니다 ✗"]},{"id":"G533","q":"Trabajo en esta empresa ____ 1999.","o":["de","por","a","desde"],"a":3,"k":"desde (시점)","t":"나는 1999년부터 이 회사에서 일하고 있다.","e":"현재까지 계속되는 일의 시작 '시점'(연도, 날짜)은 desde로 나타냅니다. 기간을 말할 때는 desde hace를 써요. 예: desde hace 25 años(25년 전부터).","x":["de: 'de 1999'는 '1999년의'라는 뜻이 됩니다 ✗","por: '~ 즈음에, ~ 때문에'라는 뜻이라 맞지 않습니다 ✗","a: '~까지/~에'라는 뜻이라 시작점을 나타내지 못합니다 ✗","desde: 시작 시점 '~부터' → 정답 ✓"]},{"id":"G534","q":"Mi abuelo no ____ bien.","o":["oiga","oye","oyen","oigo"],"a":1,"k":"oír 현재형","t":"우리 할아버지는 귀가 잘 안 들리신다.","e":"oír(듣다)는 불규칙 동사로 현재형이 oigo, oyes, oye, oímos, oís, oyen입니다. 주어 mi abuelo(3인칭 단수)에는 oye를 씁니다.","x":["oiga: 접속법이나 usted 명령형('저기요')입니다 ✗","oye: 3인칭 단수 현재형 → 정답 ✓","oyen: 3인칭 복수라 주어와 맞지 않습니다 ✗","oigo: 1인칭(나는)이라 주어와 맞지 않습니다 ✗"]},{"id":"G535","q":"¿Has preparado la merienda? —No, ____ no.","o":["ahora","todavía","después","ya"],"a":1,"k":"todavía no","t":"간식 준비했어? —아니, 아직 안 했어.","e":"'아직 ~하지 않았다'는 'todavía no'로 표현합니다. 'ya(이미)'의 반대 의미예요. 'aún no'도 같은 뜻으로 쓸 수 있습니다. merienda는 오후에 먹는 간식이에요.","x":["ahora: '지금'이라는 뜻으로 '아니, 지금 안 해'라는 어색한 대답이 됩니다 ✗","todavía: todavía no '아직 안' → 정답 ✓","después: '나중에'라는 뜻으로 no와 함께 의미가 어색합니다 ✗","ya: ya no는 '더 이상 ~않다'라는 뜻이 됩니다 ✗"]},{"id":"G536","q":"¿____ vez has visto una ballena?","o":["Algunas","Algunos","Algún","Alguna"],"a":3,"k":"alguna vez","t":"너 고래를 본 적 있어?","e":"'~한 적이 있니?'라고 경험을 물을 때는 'alguna vez(언젠가 한 번)'를 씁니다. vez(번, 회)는 여성 명사라서 alguna가 됩니다. 대답 예: Sí, una vez.(응, 한 번.) / No, nunca.(아니, 한 번도.)","x":["Algunas: 복수형이라 단수 vez와 맞지 않습니다 ✗","Algunos: 남성 복수라 성·수 모두 맞지 않습니다 ✗","Algún: 남성 단수형이라 여성 명사 vez와 맞지 않습니다 ✗","Alguna: 여성 단수 '언젠가 한 번' → 정답 ✓"]},{"id":"G537","q":"¿Sabes ____ es el país más pequeño de África?","o":["cuáles","cuántos","qué","cuál"],"a":3,"k":"cuál (선택)","t":"아프리카에서 가장 작은 나라가 어디인지 알아?","e":"여러 대상 중 하나를 특정할 때 'ser' 앞에서는 cuál을 씁니다. '가장 작은 나라'는 여러 나라 중 하나를 고르는 것이라 cuál이 맞아요. 'qué es'는 정의를 물을 때 씁니다.","x":["cuáles: 복수형이라 단수 동사 es와 맞지 않습니다 ✗","cuántos: '몇 개'라는 수를 묻습니다 ✗","qué: ser 앞에서는 정의를 묻는 뜻이 되어 맞지 않습니다 ✗","cuál: 여러 개 중 하나 '어느 것' → 정답 ✓"]},{"id":"G538","q":"Isabel y ____ esposo viajan mucho.","o":["el suyo","el su","su","suyo"],"a":2,"k":"소유형용사 su","t":"이사벨과 그녀의 남편은 여행을 많이 다닌다.","e":"명사 앞에서 '그녀의'는 소유형용사 su를 씁니다. esposo(남편)가 단수이므로 su가 되고 관사는 붙이지 않아요. el suyo는 명사 없이 '그녀의 것'이라고 할 때 씁니다.","x":["el suyo: 소유대명사라 뒤에 명사를 둘 수 없습니다 ✗","el su: 관사와 소유형용사는 함께 쓰지 않습니다 ✗","su: 명사 앞 소유형용사 '그녀의' → 정답 ✓","suyo: 명사 뒤에 쓰는 형태(un amigo suyo)입니다 ✗"]},{"id":"G539","q":"Hay que apagar las ____ antes de salir de la oficina.","o":["luce","luces","luz","luzes"],"a":1,"k":"복수형 z→ces","t":"사무실을 나서기 전에 불을 꺼야 한다.","e":"-z로 끝나는 명사는 복수형에서 z가 c로 바뀌고 -es가 붙습니다. luz(빛, 불)는 luces가 돼요. lápiz → lápices, vez → veces도 같은 규칙입니다. 'hay que + 원형'은 '~해야 한다'는 뜻이에요.","x":["luce: 동사 lucir(빛나다)의 형태라 명사가 아닙니다 ✗","luces: luz의 복수형 → 정답 ✓","luz: 단수형이라 복수 관사 las와 맞지 않습니다 ✗","luzes: z는 복수에서 c로 바꿔야 합니다 ✗"]},{"id":"G540","q":"¿En ____ países has estado?","o":["cuántos","cuánta","cuántas","cuánto"],"a":0,"k":"의문사 cuántos","t":"너는 몇 개 나라에 가 봤어?","e":"'몇 개'를 묻는 cuánto는 뒤의 명사에 성·수를 맞춥니다. países(나라들)는 남성 복수이므로 cuántos가 됩니다. 전치사 en은 의문사 앞에 와서 '¿En cuántos...?'가 돼요.","x":["cuántos: 남성 복수 명사 países 앞 → 정답 ✓","cuánta: 여성 단수라 맞지 않습니다 ✗","cuántas: 여성 복수라 남성 명사 países와 맞지 않습니다 ✗","cuánto: 단수형이라 복수 명사와 맞지 않습니다 ✗"]},{"id":"G541","q":"El zumo no ____ en el frigorífico.","o":["hay","está","tiene","es"],"a":1,"k":"estar (위치)","t":"주스는 냉장고에 없다.","e":"정관사가 붙은 특정한 것(el zumo, 그 주스)의 위치는 estar로 말합니다. hay는 정해지지 않은 것의 존재에 써요(No hay zumo en el frigorífico). zumo는 스페인어, 중남미에서는 jugo라고 합니다.","x":["hay: 정관사가 붙은 특정 주어와는 쓰지 않습니다 ✗","está: 특정한 것의 위치를 나타내는 estar → 정답 ✓","tiene: '가지다'라는 뜻이라 위치를 나타내지 못합니다 ✗","es: ser는 사물의 위치에 쓰지 않습니다 ✗"]},{"id":"G542","q":"El atleta de Canadá llegó en ____ lugar.","o":["tercer","tercero","terceros","tercera"],"a":0,"k":"tercer 어미탈락","t":"캐나다 선수가 3등으로 들어왔다.","e":"tercero(세 번째)는 primero처럼 남성 단수 명사 앞에서 -o가 떨어져 tercer가 됩니다. lugar(자리)는 남성 명사라 'en tercer lugar(3위로)'가 돼요. 여성 명사 앞에서는 tercera를 씁니다(la tercera vez).","x":["tercer: 남성 단수 명사 앞 어미탈락형 → 정답 ✓","tercero: 명사 바로 앞에서는 -o를 빼야 합니다 ✗","terceros: 복수형이라 단수 lugar와 맞지 않습니다 ✗","tercera: 여성형이라 남성 명사 lugar와 맞지 않습니다 ✗"]},{"id":"G543","q":"Este libro ____ alemán es muy barato.","o":["desde","de","a","con"],"a":1,"k":"de (내용·과목)","t":"이 독일어 책은 아주 싸다.","e":"'무엇에 관한, 무슨 종류의' 책인지 나타낼 때는 de를 씁니다. 'libro de alemán'은 '독일어(학습) 책'이라는 뜻이에요. 예: profesor de español(스페인어 선생님), clase de música(음악 수업).","x":["desde: '~부터'라는 출발점을 나타냅니다 ✗","de: 종류·내용을 나타내는 de → 정답 ✓","a: '~로/~에'라는 뜻이라 맞지 않습니다 ✗","con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G544","q":"Vamos a ir ____ París la semana que viene.","o":["en","al","a","a la"],"a":2,"k":"a + 도시명","t":"우리는 다음 주에 파리에 갈 거야.","e":"이동 동사 ir의 목적지는 a로 나타냅니다. 도시나 나라 이름은 보통 관사 없이 쓰므로 'a París'가 됩니다. 'ir a + 원형(~할 것이다)'과 'ir a + 장소(~에 가다)'가 한 문장에 함께 쓰였어요.","x":["en: 이동의 목적지에는 en이 아니라 a를 씁니다 ✗","al: 도시명에는 관사 el을 붙이지 않습니다 ✗","a: 목적지 '~로' → 정답 ✓","a la: 도시명에는 관사를 쓰지 않습니다 ✗"]},{"id":"G545","q":"No conozco a ____ que hable cinco idiomas.","o":["algún","alguien","nadie","ningún"],"a":2,"k":"nadie (부정)","t":"나는 다섯 개 언어를 하는 사람을 아무도 모른다.","e":"부정문에서 '아무도 ~않다'는 nadie를 씁니다. 사람이 목적어이므로 앞에 전치사 a가 붙었어요(a nadie). 스페인어는 'No conozco a nadie'처럼 no와 nadie를 함께 쓰는 이중 부정이 정상입니다. hable는 접속법으로, 존재하지 않는 사람을 묘사하기 때문이에요.","x":["algún: 명사 앞에 쓰는 형용사이며 부정문에서는 ningún을 씁니다 ✗","alguien: '누군가'라는 긍정어라 부정문에서는 nadie로 바꿉니다 ✗","nadie: 부정문 '아무도' → 정답 ✓","ningún: 형용사라 뒤에 명사가 필요합니다 ✗"]},{"id":"G546","q":"Antes leía el periódico en papel, ahora ____ leo en línea.","o":["la","las","le","lo"],"a":3,"k":"직접목적격 lo","t":"예전에는 신문을 종이로 읽었는데, 지금은 온라인으로 읽는다.","e":"앞에 나온 el periódico(신문, 남성 단수)를 받는 직접목적격 대명사(~을/를)는 lo입니다. 활용된 동사 leo 앞에 둡니다. 여성 명사라면 la를 써요.","x":["la: 여성 단수라 남성 명사 periódico와 맞지 않습니다 ✗","las: 여성 복수라 성·수가 맞지 않습니다 ✗","le: 간접목적격(~에게)이라 사물 목적어에 쓰지 않습니다 ✗","lo: 남성 단수 직접목적격 → 정답 ✓"]},{"id":"G547","q":"Nos han felicitado ____ nuestro trabajo.","o":["hasta","por","entre","hacia"],"a":1,"k":"por (이유)","t":"우리는 일을 잘했다고 축하를 받았다.","e":"felicitar(축하하다, 칭찬하다)는 '무엇 때문에' 축하하는지 이유를 por로 나타냅니다. 'felicitar por ~'를 한 덩어리로 외워 두세요. gracias por와 같은 이유의 por예요.","x":["hasta: '~까지'라는 뜻이라 맞지 않습니다 ✗","por: 이유를 나타내는 전치사 → 정답 ✓","entre: '~사이에'라는 뜻입니다 ✗","hacia: '~을 향해'라는 방향을 나타냅니다 ✗"]},{"id":"G548","q":"Ignacio es ____ hombre muy guapo y elegante.","o":["una","un","el","uno"],"a":1,"k":"부정관사 un","t":"이그나시오는 아주 잘생기고 멋진 남자이다.","e":"'ser + 명사 + 형용사'로 사람을 묘사할 때는 부정관사를 씁니다. hombre(남자)는 남성 단수이므로 un을 써요. uno는 명사 없이 쓸 때의 형태입니다.","x":["una: 여성형이라 hombre와 맞지 않습니다 ✗","un: 남성 단수 부정관사 → 정답 ✓","el: 정관사는 특정한 '그 남자'를 가리켜 묘사 문장에 어색합니다 ✗","uno: 명사 앞에서는 un으로 줄여 씁니다 ✗"]},{"id":"G549","q":"Suelo escuchar canciones ____.","o":["mexicanos","mexicano","México","mexicanas"],"a":3,"k":"국적 형용사 일치","t":"나는 보통 멕시코 노래를 듣는다.","e":"국적 형용사는 꾸미는 명사의 성·수에 맞춥니다. canciones(노래들)는 여성 복수이므로 mexicanas가 됩니다. 스페인어에서는 국적 형용사를 소문자로 써요.","x":["mexicanos: 남성 복수라 여성 명사 canciones와 맞지 않습니다 ✗","mexicano: 남성 단수라 성·수가 맞지 않습니다 ✗","México: 나라 이름이라 형용사로 쓸 수 없습니다(de México라면 가능) ✗","mexicanas: 여성 복수 형용사 → 정답 ✓"]},{"id":"G550","q":"Estos son los zapatos ____ caros de esta zapatería.","o":["más","tan","muchos","muy"],"a":0,"k":"최상급","t":"이것들이 이 신발 가게에서 가장 비싼 신발이다.","e":"최상급은 '정관사 + (명사) + más + 형용사 + de'로 표현합니다. 'los zapatos más caros de esta zapatería'는 '이 가게에서 가장 비싼 신발'이라는 뜻이에요. 범위를 나타낼 때 de를 쓰는 점에 주의하세요.","x":["más: 정관사와 함께 최상급 '가장' → 정답 ✓","tan: 동등 비교(tan ... como)에 씁니다 ✗","muchos: 형용사 앞에서 정도를 나타내지 못합니다 ✗","muy: '매우'라는 뜻으로 de esta zapatería와 함께 최상급이 되지 않습니다 ✗"]},{"id":"G551","q":"¿____ qué hora empieza la película?","o":["Hasta","A","En","Por"],"a":1,"k":"a qué hora","t":"영화는 몇 시에 시작해?","e":"어떤 일이 '몇 시에' 일어나는지 물을 때는 '¿A qué hora...?'를 씁니다. 대답도 a를 써서 'A las ocho(8시에)'라고 해요. 지금 몇 시인지 물을 때는 '¿Qué hora es?'로 a가 없습니다.","x":["Hasta: '몇 시까지'라는 뜻이 되어 empieza와 어울리지 않습니다 ✗","A: '몇 시에' → 정답 ✓","En: 시각 앞에는 en을 쓰지 않습니다 ✗","Por: 시각을 묻는 데 쓰지 않습니다 ✗"]},{"id":"G552","q":"Voy a tomar un taxi ____ llegar antes al evento.","o":["en","a","para","por"],"a":2,"k":"para + 원형 (목적)","t":"행사에 더 빨리 도착하려고 택시를 탈 거야.","e":"'~하기 위해'라는 목적은 'para + 동사원형'으로 나타냅니다. 택시를 타는 목적이 '빨리 도착하는 것'이므로 para가 맞아요. 예: Estudio para aprobar.(합격하기 위해 공부한다.)","x":["en: 목적을 나타내지 못합니다 ✗","a: 이동 동사 뒤 목적에 쓰이기도 하지만 tomar 뒤에는 para를 씁니다 ✗","para: 목적 '~하기 위해' → 정답 ✓","por: 이유·원인을 나타내 목적의 의미가 아닙니다 ✗"]},{"id":"G553","q":"Voy a mandarle ____ mensaje a Raúl.","o":["las","los","una","un"],"a":3,"k":"부정관사 un","t":"라울에게 메시지를 보낼 거야.","e":"mensaje(메시지)는 -e로 끝나는 남성 명사이므로 부정관사 un을 씁니다. -aje로 끝나는 명사는 대부분 남성이에요(el viaje, el garaje). mandarle의 le는 'a Raúl'을 받는 간접목적격(~에게)입니다.","x":["las: 여성 복수 정관사라 맞지 않습니다 ✗","los: 복수라 단수 명사 mensaje와 맞지 않습니다 ✗","una: 여성형이라 남성 명사 mensaje와 맞지 않습니다 ✗","un: 남성 단수 부정관사 → 정답 ✓"]},{"id":"G554","q":"Soy de Córdoba. Y tú, ¿de dónde ____?","o":["sois","son","es","eres"],"a":3,"k":"ser de (tú)","t":"나는 코르도바 출신이야. 너는 어디 출신이야?","e":"출신은 'ser de'로 묻고 답합니다. 'Y tú'라고 한 명에게 친근하게 묻고 있으므로 tú 형태 eres를 써요. 코르도바는 스페인과 아르헨티나 모두에 있는 도시 이름입니다.","x":["sois: vosotros(너희) 형태입니다 ✗","son: ustedes/그들 형태입니다 ✗","es: usted/그·그녀 형태라 tú와 맞지 않습니다 ✗","eres: tú에 맞춘 ser 현재형 → 정답 ✓"]},{"id":"G555","q":"Hay ____ mujer esperando en la puerta de esa casa.","o":["la","una","ø","un"],"a":1,"k":"hay + 부정관사","t":"저 집 문 앞에서 한 여자가 기다리고 있다.","e":"hay는 정해지지 않은 대상의 존재를 나타내므로 부정관사와 함께 씁니다. mujer(여자)는 여성 단수이니 una가 맞아요. hay 뒤에는 정관사 el/la를 쓰지 않습니다.","x":["la: hay 뒤에는 정관사를 쓰지 않습니다 ✗","una: 여성 단수 부정관사 → 정답 ✓","ø: 셀 수 있는 단수 명사는 관사 없이 hay 뒤에 쓰기 어렵습니다 ✗","un: 남성형이라 mujer와 맞지 않습니다 ✗"]},{"id":"G556","q":"¿____ gente va a ir a la fiesta de Luis?","o":["Cuántas","Cuánta","Cuánto","Cuántos"],"a":1,"k":"gente (단수)","t":"루이스의 파티에 사람이 얼마나 갈 거야?","e":"gente(사람들)는 뜻은 복수지만 문법적으로는 여성 단수 명사입니다. 그래서 cuánta gente를 쓰고 동사도 단수 va를 써요. 'La gente es simpática'처럼 항상 단수로 일치시킵니다.","x":["Cuántas: gente는 단수이므로 복수형을 쓰지 않습니다 ✗","Cuánta: 여성 단수 명사 gente에 맞춘 형태 → 정답 ✓","Cuánto: 남성형이라 여성 명사 gente와 맞지 않습니다 ✗","Cuántos: 남성 복수라 성·수가 맞지 않습니다 ✗"]},{"id":"G557","q":"¿Todavía vives ____ mismo apartamento?","o":["en","a","en el","al"],"a":2,"k":"en el mismo","t":"너 아직 같은 아파트에 살아?","e":"vivir(살다)의 장소는 en으로 나타냅니다. mismo(같은)는 보통 정관사와 함께 'el mismo ~'로 써서 '같은 ~'이라는 뜻이 돼요. 따라서 'en el mismo apartamento'가 맞습니다. 스페인에서는 piso라고도 합니다.","x":["en: mismo 앞에는 정관사 el이 필요합니다 ✗","a: vivir는 장소에 a가 아니라 en을 씁니다 ✗","en el: 장소의 en + 정관사 el → 정답 ✓","al: 이동의 방향을 나타내 vivir와 맞지 않습니다 ✗"]},{"id":"G558","q":"____ artistas son muy famosas en Italia.","o":["Estos","Estas","Esto","Esta"],"a":1,"k":"지시형용사 estas","t":"이 예술가들은 이탈리아에서 아주 유명하다.","e":"artista(예술가)는 남녀 모두 같은 형태로 쓰는 명사라서 성은 다른 단어로 판단합니다. 형용사 famosas가 여성 복수이므로 지시형용사도 estas가 됩니다. 남성이라면 'Estos artistas son famosos'가 돼요.","x":["Estos: 남성 복수라 famosas와 성이 맞지 않습니다 ✗","Estas: 여성 복수 지시형용사 → 정답 ✓","Esto: 중성 대명사라 명사 앞에 쓰지 않습니다 ✗","Esta: 단수형이라 복수 명사와 맞지 않습니다 ✗"]},{"id":"G559","q":"Estoy de acuerdo ____.","o":["con ti","con tú","con te","contigo"],"a":3,"k":"contigo","t":"나는 너와 같은 생각이야.","e":"'estar de acuerdo con ~'은 '~와 동의하다'라는 뜻입니다. con 뒤의 '너'는 특별한 형태 contigo를 써요. '나와'는 conmigo입니다.","x":["con ti: con + ti는 contigo로 바뀌어야 합니다 ✗","con tú: 주격 tú는 전치사 뒤에 쓰지 않습니다 ✗","con te: te는 목적격이라 전치사 뒤에 오지 않습니다 ✗","contigo: '너와' 특수 형태 → 정답 ✓"]},{"id":"G560","q":"____ mujer es la tía de Cristian.","o":["Esas","Ese","Eso","Esa"],"a":3,"k":"지시형용사 esa","t":"저 여자는 크리스티안의 이모(고모)이다.","e":"지시형용사는 명사의 성·수에 맞춥니다. mujer(여자)는 여성 단수이므로 esa가 맞아요. ese는 남성, eso는 명사 없이 쓰는 중성 대명사입니다.","x":["Esas: 복수형이라 단수 명사 mujer와 맞지 않습니다 ✗","Ese: 남성형이라 여성 명사와 맞지 않습니다 ✗","Eso: 중성 대명사라 명사 앞에 쓰지 않습니다 ✗","Esa: 여성 단수 지시형용사 → 정답 ✓"]},{"id":"G561","q":"Nunca he visto una obra ____ teatro.","o":["al","a","de","ø"],"a":2,"k":"명사 + de + 명사","t":"나는 연극 공연을 한 번도 본 적이 없다.","e":"두 명사를 이어 종류를 나타낼 때는 de를 씁니다. 'obra de teatro'는 '연극 작품'이라는 뜻이에요. 비슷한 예: película de terror(공포 영화), libro de cocina(요리책).","x":["al: 방향을 나타내는 a + el이라 맞지 않습니다 ✗","a: 명사의 종류를 나타내지 못합니다 ✗","de: 명사를 잇는 de → 정답 ✓","ø: 스페인어에서는 명사 두 개를 바로 붙여 쓰지 않습니다 ✗"]},{"id":"G562","q":"____ gente que vive cerca del mar es afortunada.","o":["El","Los","Las","La"],"a":3,"k":"la gente","t":"바다 근처에 사는 사람들은 운이 좋다.","e":"gente(사람들)는 여성 단수 명사이므로 정관사 la를 씁니다. 동사 vive와 형용사 afortunada도 여성 단수로 일치되어 있어요. 'los gentes'는 틀린 형태입니다.","x":["El: 남성 관사라 여성 명사 gente와 맞지 않습니다 ✗","Los: 복수 관사라 단수 명사 gente와 맞지 않습니다 ✗","Las: gente는 단수라 복수 관사를 쓰지 않습니다 ✗","La: 여성 단수 정관사 → 정답 ✓"]},{"id":"G563","q":"No quiero ____ más, gracias.","o":["ningún","alguno","nada","algo"],"a":2,"k":"nada (부정)","t":"더는 아무것도 필요 없어요, 고마워요.","e":"부정문에서 '아무것도 ~않다'는 nada를 씁니다. no와 함께 쓰는 이중 부정이 스페인어에서는 정상이에요. 'nada más'는 '더 이상 아무것도'라는 뜻입니다.","x":["ningún: 형용사라 뒤에 남성 명사가 필요합니다 ✗","alguno: 긍정어라 부정문에서 쓰지 않습니다 ✗","nada: 부정문 '아무것도' → 정답 ✓","algo: '무언가'라는 긍정어라 부정문에서는 nada로 바꿉니다 ✗"]},{"id":"G564","q":"En esa piscina siempre hay ____ gente.","o":["muchas","muy","mucha","mucho"],"a":2,"k":"mucha gente","t":"그 수영장에는 항상 사람이 많다.","e":"'많은'은 뒤의 명사에 성·수를 맞춥니다. gente는 여성 단수 명사이므로 mucha gente가 맞아요. 의미상 복수라도 muchas를 쓰지 않습니다.","x":["muchas: gente는 단수라 복수형을 쓰지 않습니다 ✗","muy: 부사라 명사 앞에 쓸 수 없습니다 ✗","mucha: 여성 단수 명사 gente 앞 → 정답 ✓","mucho: 남성형이라 여성 명사 gente와 맞지 않습니다 ✗"]},{"id":"G565","q":"Hay mucho polvo ____ sofá.","o":["debajo del","debajo","debajo de la","bajo del"],"a":0,"k":"debajo de","t":"소파 밑에 먼지가 많다.","e":"'~의 밑에'는 'debajo de'로 표현합니다. sofá는 남성 명사라 de + el이 del로 축약되어 'debajo del sofá'가 돼요. 반대말은 'encima de(~의 위에)'입니다.","x":["debajo del: debajo de + el 축약 → 정답 ✓","debajo: 뒤에 명사를 이으려면 de가 필요합니다 ✗","debajo de la: sofá는 남성 명사라 la를 쓰지 않습니다 ✗","bajo del: bajo는 전치사라 de 없이 'bajo el sofá'로 씁니다 ✗"]},{"id":"G566","q":"Cuando era joven, escuchaba ____ la radio cada mañana.","o":["de","por","ø","a"],"a":2,"k":"직접목적어 (사물)","t":"젊었을 때 나는 매일 아침 라디오를 들었다.","e":"escuchar(듣다)는 목적어를 바로 받는 타동사라 사물 목적어 앞에는 전치사가 필요 없습니다. 'escuchar la radio'처럼 씁니다. 사람이 목적어일 때만 a를 붙여요(escuchar a mi madre). escuchaba는 과거의 습관을 나타내는 불완료과거입니다.","x":["de: escuchar 뒤에 de를 쓰지 않습니다 ✗","por: 'por la radio'는 '라디오를 통해'라는 뜻이 되어 목적어가 없게 됩니다 ✗","ø: 사물 직접목적어 앞에는 전치사가 없음 → 정답 ✓","a: 사람 목적어에만 a를 씁니다 ✗"]},{"id":"G567","q":"____ peces de colores son llamativos.","o":["Los","Este","Esas","Las"],"a":0,"k":"정관사 los","t":"색깔 있는 물고기들(금붕어 등)은 눈에 띈다.","e":"peces(물고기들)는 pez의 복수형으로 남성 명사입니다. 그래서 남성 복수 정관사 los를 씁니다. 형용사 llamativos도 남성 복수로 일치되어 있어요. 'peces de colores'는 관상용 금붕어를 가리키기도 합니다.","x":["Los: 남성 복수 정관사 → 정답 ✓","Este: 단수형이라 복수 명사와 맞지 않습니다 ✗","Esas: 여성형이라 남성 명사 peces와 맞지 않습니다 ✗","Las: 여성 관사라 남성 명사와 맞지 않습니다 ✗"]},{"id":"G568","q":"Este protector solar te protege ____ piel del sol.","o":["un","el","la","una"],"a":2,"k":"신체 + 정관사","t":"이 자외선 차단제가 햇빛으로부터 네 피부를 보호해 준다.","e":"스페인어에서는 신체 부위에 소유형용사 대신 정관사를 씁니다. 누구의 피부인지는 간접목적격 대명사 te(너에게)로 이미 알 수 있어요. piel(피부)은 여성 명사라 la piel입니다. 예: Me duele la cabeza.(나는 머리가 아프다.)","x":["un: 부정관사이며 남성형이라 맞지 않습니다 ✗","el: 남성 관사라 여성 명사 piel과 맞지 않습니다 ✗","la: 신체 부위 앞 여성 정관사 → 정답 ✓","una: 부정관사라 '어떤 피부'라는 어색한 뜻이 됩니다 ✗"]},{"id":"G569","q":"Iremos ____ cine si os portáis bien.","o":["al","a","a lo","a la"],"a":0,"k":"축약 al","t":"너희가 착하게 굴면 영화관에 갈 거야.","e":"목적지 앞의 a와 남성 정관사 el이 만나 al이 됩니다. cine(영화관)은 남성 명사이므로 'al cine'이에요. iremos는 ir의 미래형 nosotros, os portáis는 스페인식 vosotros 형태입니다.","x":["al: a + el 축약 → 정답 ✓","a: 특정 장소인 cine 앞에는 관사가 필요합니다 ✗","a lo: lo는 명사 앞 관사로 쓰지 않습니다 ✗","a la: 여성 관사라 남성 명사 cine와 맞지 않습니다 ✗"]},{"id":"G570","q":"Sólo hablo ____ poco de español.","o":["el","una","uno","un"],"a":3,"k":"un poco de","t":"나는 스페인어를 조금밖에 못 한다.","e":"'조금'은 un poco로 표현하고, 뒤에 명사가 올 때는 un poco de를 씁니다. 'un poco de español'은 '약간의 스페인어'라는 뜻이에요. poco는 남성 단수로 취급하므로 관사는 항상 un입니다.","x":["el: 'el poco'는 쓰지 않는 표현입니다 ✗","una: 여성형이라 poco와 맞지 않습니다 ✗","uno: 명사(poco) 앞에서는 un으로 줄여 씁니다 ✗","un: un poco de '조금의' → 정답 ✓"]},{"id":"G571","q":"No conocía a ____ en esa fiesta, pero me lo pasé muy bien.","o":["nada","nadie","ningún","alguien"],"a":1,"k":"nadie (부정)","t":"그 파티에서 아무도 몰랐지만 아주 즐거웠다.","e":"부정문에서 '아무도'는 nadie입니다. 사람이 목적어이므로 a가 붙어 'a nadie'가 돼요. 'pasárselo bien'은 '즐겁게 보내다'라는 스페인식 표현입니다(중남미에서는 'pasarla bien').","x":["nada: '아무것도'로 사물에 쓰며 사람에는 nadie를 씁니다 ✗","nadie: 부정문 '아무도' → 정답 ✓","ningún: 형용사라 뒤에 명사가 필요합니다 ✗","alguien: '누군가'라는 긍정어라 부정문에서는 nadie로 바꿉니다 ✗"]},{"id":"G572","q":"Si no estás viendo la tele, ____.","o":["apágala","apágalas","apágale","apágalo"],"a":0,"k":"명령형 + 목적격","t":"TV 안 보고 있으면 꺼.","e":"긍정 명령형에서는 목적격 대명사를 동사 뒤에 붙여 씁니다. la tele(텔레비전)는 televisión의 줄임말로 여성 단수이므로 la를 붙여 apágala가 됩니다. 대명사가 붙어도 원래 강세 위치를 지키기 위해 á에 악센트를 표시해요.","x":["apágala: 여성 단수 la tele를 받는 명령형 → 정답 ✓","apágalas: 복수형이라 단수 la tele와 맞지 않습니다 ✗","apágale: le는 간접목적격(~에게)이라 사물에 쓰지 않습니다 ✗","apágalo: 남성형이라 여성 명사 tele와 맞지 않습니다 ✗"]},{"id":"G573","q":"¿Te interesa el fútbol? —Sí, ____ gusta mucho.","o":["yo","me","mí","a mí"],"a":1,"k":"gustar 구문","t":"축구에 관심 있어? —응, 아주 좋아해.","e":"gustar 구문에서 '나에게'는 간접목적격 대명사 me를 동사 앞에 둡니다. 'a mí'는 강조용으로 me와 함께 써야 하며 단독으로는 쓸 수 없어요(A mí me gusta). 주어인 축구(el fútbol)는 생략되었습니다.","x":["yo: 주격이라 gustar 구문에 쓸 수 없습니다 ✗","me: 간접목적격 '나에게' → 정답 ✓","mí: 전치사 a 없이 홀로 쓸 수 없습니다 ✗","a mí: me 없이 'a mí gusta'만으로는 틀린 문장이 됩니다 ✗"]},{"id":"G574","q":"Los alumnos esperan ____ a su maestra.","o":["sentado","sentadas","sentando","sentados"],"a":3,"k":"형용사 일치","t":"학생들은 앉아서 선생님을 기다린다.","e":"sentado(앉아 있는)는 과거분사가 형용사처럼 쓰여 주어에 성·수를 맞춥니다. 주어 los alumnos는 남성 복수이므로 sentados가 돼요. sentando는 현재분사(앉히면서)로 의미가 다릅니다.","x":["sentado: 단수형이라 복수 주어와 맞지 않습니다 ✗","sentadas: 여성형이라 남성 명사 alumnos와 맞지 않습니다 ✗","sentando: 현재분사로 '(누군가를) 앉히면서'라는 뜻입니다 ✗","sentados: 남성 복수 형용사 → 정답 ✓"]},{"id":"G575","q":"¿____ es la capital de Ecuador?","o":["Cuánto","Qué","Quién","Cuál"],"a":3,"k":"cuál (ser 앞)","t":"에콰도르의 수도는 어디야?","e":"수도처럼 여러 후보 중 하나를 특정할 때 ser 앞에서는 cuál을 씁니다. 한국어로는 '어디'라고 하지만 스페인어로는 dónde가 아니라 cuál을 써요. 예: ¿Cuál es tu número de teléfono?(네 전화번호가 뭐야?)","x":["Cuánto: '얼마'라는 양을 묻습니다 ✗","Qué: ser 앞에서는 정의를 묻는 뜻이 됩니다 ✗","Quién: 사람을 묻는 '누구'입니다 ✗","Cuál: 하나를 특정하는 '어느 것' → 정답 ✓"]},{"id":"G576","q":"El próximo lunes va a ser mi ____ día en el nuevo colegio.","o":["primera","primeras","primero","primer"],"a":3,"k":"primer 어미탈락","t":"다음 주 월요일은 새 학교에서의 내 첫날이 될 거야.","e":"primero(첫 번째)는 남성 단수 명사 앞에서 primer로 줄어듭니다. día(날)는 -a로 끝나지만 남성 명사이므로 'mi primer día'가 돼요. 소유형용사 mi가 있어도 같은 규칙입니다.","x":["primera: día는 남성 명사라 여성형을 쓰지 않습니다 ✗","primeras: 여성 복수라 성·수가 맞지 않습니다 ✗","primero: 명사 앞에서는 -o를 빼야 합니다 ✗","primer: 남성 단수 명사 앞 어미탈락형 → 정답 ✓"]},{"id":"G577","q":"Alba le dio dos besos a Carolina cuando ____ vio.","o":["la","lo","le","las"],"a":0,"k":"직접목적격 la","t":"알바는 카롤리나를 보자 볼에 두 번 키스를 했다.","e":"ver(보다)는 직접목적어를 받는 동사이고, 본 대상은 Carolina(여성 단수)이므로 la를 씁니다. 볼 키스 두 번(dos besos)은 스페인식 인사예요. 앞의 le는 dar의 간접목적격(카롤리나에게)입니다.","x":["la: 여성 단수 직접목적격 → 정답 ✓","lo: 남성형이라 Carolina와 맞지 않습니다 ✗","le: 간접목적격이라 ver의 목적어로는 맞지 않습니다(스페인 일부 지역 남성에게만 허용) ✗","las: 복수형이라 한 사람에 맞지 않습니다 ✗"]},{"id":"G578","q":"¿Cuánto ____ estas blusas?","o":["cuestan","costan","cuestas","cuesta"],"a":0,"k":"costar o→ue","t":"이 블라우스들은 얼마예요?","e":"costar(값이 ~이다)는 o→ue 어간변화 동사입니다. 주어 estas blusas(이 블라우스들)가 복수이므로 3인칭 복수 cuestan을 씁니다. 하나라면 '¿Cuánto cuesta esta blusa?'예요.","x":["cuestan: 복수 주어에 맞춘 3인칭 복수 → 정답 ✓","costan: 어간변화(o→ue)를 하지 않은 틀린 형태입니다 ✗","cuestas: 2인칭 단수(너는) 형태입니다 ✗","cuesta: 단수형이라 복수 주어 blusas와 맞지 않습니다 ✗"]},{"id":"G579","q":"Olivia ____ mal porque no encuentra trabajo.","o":["está","eres","es","estás"],"a":0,"k":"estar mal (상태)","t":"올리비아는 일자리를 구하지 못해서 기분이 좋지 않다.","e":"bien(좋은), mal(나쁜)은 상태를 나타내는 부사라 estar와 함께 씁니다. 'estar mal'은 '기분·상태가 안 좋다'는 뜻이에요. 주어 Olivia는 3인칭 단수이므로 está가 됩니다.","x":["está: 상태를 나타내는 estar 3인칭 단수 → 정답 ✓","eres: ser의 tú 형태라 인칭도 의미도 맞지 않습니다 ✗","es: ser는 bien/mal과 함께 상태를 나타내지 않습니다 ✗","estás: tú(너) 형태라 주어 Olivia와 맞지 않습니다 ✗"]},{"id":"G580","q":"¿Es cierto que a Rosario ____ Paco?","o":["le guste","guste","le gusta","la gusta"],"a":2,"k":"gustar (사람)","t":"로사리오가 파코를 좋아한다는 게 사실이야?","e":"gustar 구문에서 '로사리오에게'는 간접목적격 le로 받고, 좋아하는 대상 Paco가 주어라 3인칭 단수 gusta를 씁니다. 'Es cierto que'는 사실을 확인하는 표현이라 접속법이 아닌 직설법을 써요. 사람에게 gustar를 쓰면 '이성으로 좋아하다'라는 뉘앙스가 있습니다.","x":["le guste: 접속법이라 'es cierto que' 뒤에 쓰지 않습니다 ✗","guste: 대명사 le가 없고 접속법입니다 ✗","le gusta: 간접목적격 le + 직설법 → 정답 ✓","la gusta: gustar는 직접목적격 la가 아니라 le를 씁니다 ✗"]},{"id":"G581","q":"____ es el bar de Juan.","o":["Esta","Esa","Ese","Estos"],"a":2,"k":"지시사 ese","t":"저것이 후안의 바야.","e":"지시사는 가리키는 명사의 성·수에 맞춥니다. 여기서 가리키는 것은 el bar(바, 남성 단수)이므로 ese가 맞아요. ser 문장에서 지시사는 보어 명사의 성을 따릅니다.","x":["Esta: 여성형이라 남성 명사 bar와 맞지 않습니다 ✗","Esa: 여성형이라 남성 명사 bar와 맞지 않습니다 ✗","Ese: 남성 단수 지시사 → 정답 ✓","Estos: 복수형이라 단수 명사와 맞지 않습니다 ✗"]},{"id":"G582","q":"____ somos amigos de la infancia.","o":["Nosotros","A nosotros","Nos","Nosotras"],"a":0,"k":"주격 대명사","t":"우리는 어릴 적부터 친구이다.","e":"동사 somos(우리는 ~이다)의 주어 자리에는 주격 대명사 nosotros를 씁니다. amigos가 남성 복수(또는 남녀 혼합)이므로 nosotros가 맞고, 모두 여성이라면 nosotras, amigas가 됩니다.","x":["Nosotros: 남성(혼성) 복수 주격 → 정답 ✓","A nosotros: '우리에게'라는 뜻이라 주어가 될 수 없습니다 ✗","Nos: 목적격 대명사라 주어 자리에 올 수 없습니다 ✗","Nosotras: 여성 복수형이라 amigos(남성형)와 맞지 않습니다 ✗"]},{"id":"G583","q":"____ hermana se llama Leticia.","o":["Mí","La mía","Mi","Mía"],"a":2,"k":"소유형용사 mi","t":"내 여동생(언니) 이름은 레티시아다.","e":"명사 앞에서 '나의'는 소유형용사 mi를 씁니다. 악센트가 없는 mi는 '나의', 악센트가 있는 mí는 전치사 뒤의 '나'예요. 명사 앞에는 관사를 함께 쓰지 않습니다.","x":["Mí: 전치사 뒤에 쓰는 대명사 '나'입니다 ✗","La mía: 소유대명사(내 것)라 뒤에 명사를 둘 수 없습니다 ✗","Mi: 명사 앞 소유형용사 '나의' → 정답 ✓","Mía: 명사 뒤에 쓰는 형태입니다(una amiga mía) ✗"]},{"id":"G584","q":"¿____ es ecuatoriano?","o":["Tú","Vosotros","Ustedes","Usted"],"a":3,"k":"usted + 3인칭","t":"당신은 에콰도르 사람이세요?","e":"동사 es(3인칭 단수)와 형용사 ecuatoriano(남성 단수)에 맞는 주어는 usted(당신)입니다. usted는 2인칭 존칭이지만 동사는 3인칭 단수로 활용해요. tú였다면 'eres'가 됩니다.","x":["Tú: tú에는 eres를 써야 합니다 ✗","Vosotros: 복수라 sois와 함께 씁니다 ✗","Ustedes: 복수라 son과 함께 씁니다 ✗","Usted: 3인칭 단수 동사와 쓰는 존칭 '당신' → 정답 ✓"]},{"id":"G585","q":"¿____ prefieres el café en verano? ¿Caliente o frío?","o":["Cómo","Qué","Cuál","Cuándo"],"a":0,"k":"의문사 cómo","t":"여름에 커피를 어떻게 마시는 걸 좋아해? 뜨겁게, 아니면 차갑게?","e":"'어떤 방식·상태로'를 물을 때는 cómo를 씁니다. 대답이 'Caliente o frío(뜨겁게 또는 차갑게)'라는 상태이므로 cómo가 맞아요. preferir는 e→ie 어간변화 동사입니다.","x":["Cómo: 방식·상태를 묻는 '어떻게' → 정답 ✓","Qué: '무엇을'이라는 뜻인데 el café라는 목적어가 이미 있습니다 ✗","Cuál: 선택 대상을 묻지만 이미 목적어가 있어 맞지 않습니다 ✗","Cuándo: '언제'를 묻는 것이라 대답과 맞지 않습니다 ✗"]},{"id":"G586","q":"Andrés es ____ alto.","o":["muchísimo","muy","muchos","mucho"],"a":1,"k":"muy + 형용사","t":"안드레스는 키가 아주 크다.","e":"형용사 alto(키가 큰)를 강조할 때는 muy(매우)를 씁니다. mucho는 명사나 동사를 꾸밀 때 쓰므로 형용사 앞에는 올 수 없어요. 더 강조하려면 altísimo라고도 합니다.","x":["muchísimo: mucho의 강조형이라 형용사 앞에 쓰지 않습니다 ✗","muy: 형용사를 강조하는 '아주' → 정답 ✓","muchos: 복수 형용사형이라 맞지 않습니다 ✗","mucho: 형용사 앞에서는 muy를 씁니다 ✗"]},{"id":"G587","q":"No me gustan ____ las películas de acción.","o":["muy","muchas","mucho","muchos"],"a":2,"k":"부사 mucho","t":"나는 액션 영화를 별로 좋아하지 않는다.","e":"동사 gustar를 꾸미는 '많이'는 부사 mucho이며 형태가 변하지 않습니다. 'No me gustan mucho'는 '별로 좋아하지 않는다'는 부드러운 부정 표현이에요. 위치는 동사 바로 뒤에 두는 것이 자연스럽습니다.","x":["muy: 형용사·부사 앞에만 쓰고 동사를 꾸미지 않습니다 ✗","muchas: 'muchas las películas'처럼 관사 앞에 쓸 수 없습니다 ✗","mucho: 동사를 꾸미는 부사 → 정답 ✓","muchos: 형용사형이라 동사를 꾸밀 수 없습니다 ✗"]},{"id":"G588","q":"Me gustaría ____ hablar con el encargado de la tienda.","o":["a","ø","por","de"],"a":1,"k":"gustaría + 원형","t":"가게 매니저와 이야기하고 싶습니다.","e":"'me gustaría + 동사원형'은 '~하고 싶습니다'라는 공손한 표현입니다. gustar 뒤에는 전치사 없이 바로 동사원형이 와요. 예: Me gustaría viajar a Perú.(페루에 여행 가고 싶어요.)","x":["a: gustaría와 원형 사이에 a를 쓰지 않습니다 ✗","ø: 전치사 없이 원형이 바로 옴 → 정답 ✓","por: 이 구조에서 por는 필요 없습니다 ✗","de: 'gustar de'는 일부 지역의 옛 표현으로 원형 앞에 쓰지 않습니다 ✗"]},{"id":"G589","q":"¿Quién quiere ____ a María José la verdad?","o":["decir le","decirle","le decir","decir"],"a":1,"k":"원형 + 대명사","t":"누가 마리아 호세에게 진실을 말해 줄래?","e":"동사원형 뒤의 목적격 대명사는 원형에 붙여 씁니다. le(그녀에게)는 'a María José'를 받는 간접목적격이라 decirle가 돼요. 'a + 사람'과 le를 함께 쓰는 것이 자연스러운 스페인어입니다.","x":["decir le: 대명사는 원형에 붙여 써야 합니다 ✗","decirle: 원형 + 간접목적격 le → 정답 ✓","le decir: 대명사를 원형 앞에 둘 수 없습니다(le quiere decir는 가능) ✗","decir: 문법적으로 가능하지만 'a + 사람'과 le를 함께 쓰는 것이 표준입니다 ✗"]},{"id":"G590","q":"Los gatos de mi abuela son ____.","o":["blanca","blancas","blancos","blanco"],"a":2,"k":"형용사 일치","t":"우리 할머니의 고양이들은 하얗다.","e":"형용사는 주어의 성·수에 맞춥니다. los gatos(고양이들)는 남성 복수이므로 blancos가 됩니다. 암고양이들이라면 'las gatas son blancas'가 돼요.","x":["blanca: 여성 단수라 성·수 모두 맞지 않습니다 ✗","blancas: 여성형이라 남성 명사와 맞지 않습니다 ✗","blancos: 남성 복수 형용사 → 정답 ✓","blanco: 단수형이라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G591","q":"A Juliana y a Celia ____ han dado una beca para estudiar en el extranjero.","o":["los","le","les","las"],"a":2,"k":"간접목적격 les","t":"훌리아나와 셀리아는 해외 유학 장학금을 받았다.","e":"dar(주다)의 '~에게'는 간접목적격 대명사로 받습니다. 받는 사람이 두 명(Juliana y Celia)이므로 3인칭 복수 les를 씁니다. 간접목적격은 성 구분이 없어 여성이라도 las가 아니라 les예요. 직역하면 '그들이 훌리아나와 셀리아에게 장학금을 주었다'입니다.","x":["los: 직접목적격(그들을)이라 '~에게'를 나타내지 못합니다 ✗","le: 단수형이라 두 사람에게 맞지 않습니다 ✗","les: 3인칭 복수 간접목적격 → 정답 ✓","las: 직접목적격 여성 복수라 '~에게'에 쓰지 않습니다 ✗"]},{"id":"G592","q":"Alberto ____ un chico muy guapo.","o":["es","estás","son","está"],"a":0,"k":"ser + 묘사","t":"알베르토는 아주 잘생긴 남자다.","e":"'ser + 부정관사 + 명사'로 사람이 어떤 사람인지 설명할 때는 ser를 씁니다. 주어 Alberto는 3인칭 단수라 es가 맞아요. estar는 명사 앞에 쓰지 않습니다.","x":["es: 정체·특징을 나타내는 ser → 정답 ✓","estás: estar의 tú 형태라 인칭과 용법이 맞지 않습니다 ✗","son: 복수형이라 주어 한 명과 맞지 않습니다 ✗","está: estar 뒤에 'un chico' 같은 명사는 올 수 없습니다 ✗"]},{"id":"G593","q":"¿____ es ese chico tan guapo?","o":["Cuánto","Cuándo","Dónde","Quién"],"a":3,"k":"의문사 quién","t":"저 아주 잘생긴 남자는 누구야?","e":"사람의 정체를 물을 때는 quién(누구)을 씁니다. 대상이 한 명이므로 단수 quién, 여러 명이면 quiénes를 써요. 'tan guapo'는 '그렇게나 잘생긴'이라는 감탄의 의미입니다.","x":["Cuánto: '얼마'라는 양을 묻습니다 ✗","Cuándo: '언제'라는 시간을 묻습니다 ✗","Dónde: '어디'라는 장소를 묻습니다 ✗","Quién: 사람을 묻는 '누구' → 정답 ✓"]},{"id":"G594","q":"En ____ humilde opinión, lo que está haciendo Sergio no está bien.","o":["mi","la mía","mía","mí"],"a":0,"k":"소유형용사 mi","t":"제 소견으로는, 세르히오가 하고 있는 일은 옳지 않습니다.","e":"명사 앞의 '나의'는 소유형용사 mi를 씁니다. 'En mi humilde opinión'은 '제 소견으로는'이라는 겸손한 관용 표현이에요. 형용사 humilde가 사이에 있어도 mi를 씁니다.","x":["mi: 명사 앞 소유형용사 '나의' → 정답 ✓","la mía: 소유대명사라 뒤에 명사를 둘 수 없습니다 ✗","mía: 명사 뒤에 쓰는 형태입니다 ✗","mí: 전치사 뒤에 쓰는 대명사 '나'입니다 ✗"]},{"id":"G595","q":"No tengo ____ problema con vosotros.","o":["algún","ninguno","ningún","alguno"],"a":2,"k":"ningún","t":"너희와 나 사이에 아무 문제 없어.","e":"부정문에서 '하나도 ~없다'는 ninguno를 쓰고, 남성 단수 명사 앞에서는 -o가 떨어져 ningún이 됩니다. problema는 -a로 끝나지만 남성 명사라서 ningún problema가 맞아요. 'No hay ningún problema(전혀 문제없어요)'도 자주 씁니다.","x":["algún: 긍정어라 부정문에서는 ningún을 씁니다 ✗","ninguno: 남성 명사 바로 앞에서는 ningún으로 줄여야 합니다 ✗","ningún: 남성 단수 명사 앞 부정어 → 정답 ✓","alguno: 긍정어이며 명사 앞에서는 algún으로 줄어듭니다 ✗"]},{"id":"G596","q":"Miguel trabaja tanto como ____.","o":["yo","mí","a mí","me"],"a":0,"k":"tanto como + 주격","t":"미겔은 나만큼 일을 많이 한다.","e":"'tanto como(~만큼)' 뒤에는 비교 대상이 주어 역할을 하므로 주격 대명사 yo를 씁니다. 'Miguel trabaja tanto como yo (trabajo)'에서 동사가 생략된 거예요. como는 전치사가 아니라서 mí를 쓰지 않습니다.","x":["yo: 비교 대상의 주격 대명사 → 정답 ✓","mí: 전치사 뒤에 쓰는 형태라 como 뒤에는 쓰지 않습니다 ✗","a mí: '나에게'라는 뜻이라 맞지 않습니다 ✗","me: 목적격 대명사라 맞지 않습니다 ✗"]},{"id":"G597","q":"¿Cómo se llaman tus ____ amigas?","o":["más mejores","mejor","las mejores","mejores"],"a":3,"k":"mejor 복수","t":"너의 가장 친한 친구들 이름이 뭐야?","e":"mejor(더 좋은, 가장 좋은)는 bueno의 불규칙 비교급·최상급입니다. amigas가 복수이므로 mejores가 돼요. 이미 '더'의 뜻이 있어 más를 붙이지 않고, 소유형용사 tus가 있으니 관사도 쓰지 않습니다.","x":["más mejores: mejor에 이미 비교의 뜻이 있어 más를 붙이지 않습니다 ✗","mejor: 단수형이라 복수 명사 amigas와 맞지 않습니다 ✗","las mejores: 소유형용사 tus와 관사를 함께 쓸 수 없습니다 ✗","mejores: 복수형 '가장 좋은' → 정답 ✓"]},{"id":"G598","q":"Muchas gracias ____ invitarnos.","o":["a","para","por","de"],"a":2,"k":"gracias por","t":"초대해 주셔서 정말 감사합니다.","e":"감사의 이유는 항상 por로 나타내며, 뒤에 동사원형이 올 수 있습니다. invitarnos는 invitar(초대하다) + nos(우리를)예요. 예: Gracias por ayudarme.(도와줘서 고마워.)","x":["a: 감사의 이유를 나타내지 못합니다 ✗","para: 목적을 나타내므로 이유와 맞지 않습니다 ✗","por: 감사의 이유 '~해 줘서' → 정답 ✓","de: gracias de는 쓰지 않는 표현입니다 ✗"]},{"id":"G599","q":"Juanito siempre ha sido ____ hombre muy responsable.","o":["el","un","ø","uno"],"a":1,"k":"부정관사 + 묘사","t":"후아니토는 언제나 아주 책임감 있는 남자였다.","e":"'ser + 명사'에 형용사(muy responsable)가 붙어 사람을 묘사할 때는 부정관사를 씁니다. hombre는 남성 단수이므로 un이 맞아요. 형용사 없이 직업·신분만 말할 때는 관사를 생략합니다(Es médico).","x":["el: 정관사는 '그 남자'라는 특정 의미가 되어 묘사에 어색합니다 ✗","un: 형용사가 붙은 묘사 문장의 부정관사 → 정답 ✓","ø: 형용사로 꾸민 명사 앞에는 관사가 필요합니다 ✗","uno: 명사 앞에서는 un으로 줄여 씁니다 ✗"]},{"id":"G600","q":"¿____ son tus compañeras de piso? —De Galicia.","o":["Hacia dónde","Adónde","De dónde","Dónde"],"a":2,"k":"de dónde (출신)","t":"네 룸메이트들은 어디 출신이야? —갈리시아 출신이야.","e":"대답 'De Galicia(갈리시아 출신)'에 de가 있으므로 질문도 '¿De dónde son...?'이 되어야 합니다. 출신은 'ser de + 장소'로 말해요. 갈리시아는 스페인 북서부 지방입니다.","x":["Hacia dónde: '어느 쪽을 향해'라는 방향을 묻습니다 ✗","Adónde: '어디로 (가니)'라는 이동 방향을 묻습니다 ✗","De dónde: 출신 '어디에서' → 정답 ✓","Dónde: '어디에'라는 위치를 물으며 ser de 출신 표현과 맞지 않습니다 ✗"]},{"id":"G601","q":"Mi hija trabaja más que ____.","o":["tuyas","tuyo","tuya","la tuya"],"a":3,"k":"소유대명사","t":"내 딸은 너의 딸보다 일을 더 많이 한다.","e":"비교 대상인 '너의 딸'을 명사 없이 말할 때는 소유대명사(명사를 대신하는 소유 표현)를 씁니다. 소유대명사는 보통 정관사와 함께 쓰며, 가리키는 명사 hija(여성 단수)에 맞춰 la tuya가 됩니다. 예: Mi coche es rojo y el tuyo es azul.(내 차는 빨갛고 네 것은 파랗다.)","x":["tuyas: 여성 복수형이고 관사도 없어 딸 한 명을 가리킬 수 없습니다 ✗","tuyo: 남성 단수형이고 관사가 없어 hija를 대신할 수 없습니다 ✗","tuya: 성·수는 맞지만 명사를 대신할 때는 관사 la가 필요합니다 ✗","la tuya: 여성 단수 소유대명사(너의 것) → 정답 ✓"]},{"id":"G602","q":"Ángela es ____ vegetariana.","o":["ø","un","la","una"],"a":0,"k":"관사 생략","t":"앙헬라는 채식주의자다.","e":"ser 뒤에 직업·국적·종교·신념 등 '어떤 부류에 속하는지'를 말할 때는 보통 관사를 쓰지 않습니다. vegetariana(채식주의자)도 사람의 성향·분류를 나타내므로 관사 없이 씁니다. 단, 형용사가 붙어 꾸며 주면 관사를 씁니다. 예: Es una vegetariana muy estricta.(그녀는 아주 엄격한 채식주의자다.)","x":["ø: 분류를 나타내는 명사 앞이라 관사를 넣지 않음 → 정답 ✓","un: 남성 부정관사이고, 이 문장에는 관사가 필요 없습니다 ✗","la: 정관사(그)로 특정한 사람을 가리키게 되어 어색합니다 ✗","una: 여성 부정관사지만 꾸미는 말 없이 단순 분류를 말할 때는 쓰지 않습니다 ✗"]},{"id":"G603","q":"Estoy harto de ____ problemas.","o":["tanta","tantos","tanto","tantas"],"a":1,"k":"tanto 성·수 일치","t":"나는 그렇게 많은 문제들에 지쳤다.","e":"tanto(그렇게 많은)는 명사 앞에서 형용사처럼 쓰여 뒤 명사의 성·수에 맞춰 변합니다. problemas는 -a로 끝나지만 남성 명사(el problema)이고 복수이므로 tantos가 됩니다. estar harto de는 '~에 질리다, 지긋지긋하다'라는 뜻입니다.","x":["tanta: 여성 단수형이라 남성 복수 problemas와 맞지 않습니다 ✗","tantos: 남성 복수형 → 정답 ✓","tanto: 남성 단수형(또는 부사)이라 복수 명사 앞에 쓸 수 없습니다 ✗","tantas: 여성 복수형인데 problema는 남성 명사라서 ✗"]},{"id":"G604","q":"Ese hombre ____ un maleducado.","o":["son","es","está","estoy"],"a":1,"k":"ser 동사","t":"그 남자는 무례한 사람이다.","e":"un maleducado(무례한 사람)처럼 '부정관사 + 명사'로 사람이 어떤 사람인지 정의할 때는 ser를 씁니다. 주어 ese hombre는 3인칭 단수이므로 es가 됩니다. estar는 일시적 상태에 쓰며 명사 앞에는 쓰지 않습니다.","x":["son: 3인칭 복수형이라 단수 주어와 맞지 않습니다 ✗","es: ser의 3인칭 단수, 사람의 성격·정체를 나타냄 → 정답 ✓","está: estar는 일시적 상태에 쓰고 '관사+명사' 앞에는 쓰지 않습니다 ✗","estoy: estar의 1인칭 단수(나는)라 주어와 맞지 않습니다 ✗"]},{"id":"G605","q":"Esas gafas no son ____, son de mi hermano.","o":["mías","mía","a mí","de mí"],"a":0,"k":"소유형용사 강세형","t":"그 안경은 내 것이 아니라 내 형(오빠)의 것이다.","e":"ser 뒤에서 '~의 것'이라고 소유를 말할 때는 소유형용사 강세형(mío, mía, míos, mías)을 관사 없이 씁니다. 주어 gafas(안경)는 여성 복수 명사이므로 mías가 됩니다. 스페인에서는 gafas, 중남미에서는 lentes나 anteojos를 많이 씁니다.","x":["mías: 여성 복수 소유형(나의 것) → 정답 ✓","mía: 여성 단수형이라 복수 gafas와 맞지 않습니다 ✗","a mí: '나에게'라는 뜻이라 소유를 나타내지 못합니다 ✗","de mí: '나에 대해/나로부터'라는 뜻으로 소유 표현으로 쓰지 않습니다 ✗"]},{"id":"G606","q":"¡Qué día tan ____!","o":["sol","soleada","de sol","soleado"],"a":3,"k":"감탄문 qué...tan","t":"정말 화창한 날이구나!","e":"'¡Qué + 명사 + tan + 형용사!'는 '정말 ~한 ~구나!'라는 감탄 표현입니다. tan 뒤에는 형용사가 오고, 명사 día(남성 단수)에 맞춰 soleado(햇빛이 쨍쨍한)가 됩니다. día는 -a로 끝나지만 남성 명사라는 점에 주의하세요.","x":["sol: '해'라는 명사라 tan 뒤에 올 수 없습니다 ✗","soleada: 여성형이라 남성 명사 día와 맞지 않습니다 ✗","de sol: 'día de sol(해 뜬 날)'은 가능하지만 tan 뒤에는 형용사가 와야 합니다 ✗","soleado: 남성 단수 형용사(화창한) → 정답 ✓"]},{"id":"G607","q":"No te sientes ____ esa silla, que está rota.","o":["en","a","encima","bajo"],"a":0,"k":"sentarse en","t":"그 의자에 앉지 마, 부서졌거든.","e":"sentarse(앉다)는 앉는 장소 앞에 전치사 en(~에)을 씁니다. 'sentarse en una silla(의자에 앉다)', 'sentarse en el sofá(소파에 앉다)'처럼 씁니다. 문장의 que는 이유를 덧붙이는 '~하니까'의 뜻입니다.","x":["en: sentarse와 함께 앉는 장소를 나타냄 → 정답 ✓","a: 방향(~로)을 나타내며 'sentarse a la mesa(식탁에 앉다)' 같은 일부 표현에만 씁니다 ✗","encima: '위에'라는 뜻이지만 명사 앞에서는 encima de가 되어야 합니다 ✗","bajo: '~아래에'라는 뜻이라 의자에 앉는 의미와 맞지 않습니다 ✗"]},{"id":"G608","q":"¿Qué ____ hacer en tu tiempo libre?","o":["te gustan","gustas","te gustas","te gusta"],"a":3,"k":"gustar 구문","t":"너는 여가 시간에 무엇을 하는 것을 좋아하니?","e":"gustar는 '좋아하는 사람'을 간접목적격 대명사(~에게)로 쓰고, 좋아하는 대상이 주어가 됩니다. 여기서 대상은 hacer(하는 것)라는 동사원형이며, 동사원형은 단수 취급하므로 gusta를 씁니다. '너'는 te로 나타내 te gusta가 됩니다.","x":["te gustan: 복수 대상일 때 씁니다. 동사원형은 단수 취급이라 ✗","gustas: '네가 (남에게) 매력적이다'라는 뜻이 되어 맞지 않습니다 ✗","te gustas: '너 자신이 너에게 마음에 든다'라는 뜻이 되어 어색합니다 ✗","te gusta: 너에게 + 단수 대상(hacer) → 정답 ✓"]},{"id":"G609","q":"Todos ____ estudiando porque esta tarde tienen un examen.","o":["sois","son","estáis","están"],"a":3,"k":"estar + 현재분사","t":"모두 오늘 오후에 시험이 있어서 공부하고 있다.","e":"'estar + 현재분사(-ando/-iendo)'는 '~하고 있다'는 진행형입니다. 주어 Todos(모두)는 뒤의 tienen과 같이 3인칭 복수(ellos)이므로 están을 씁니다. ser는 진행형을 만들 수 없습니다.","x":["sois: ser의 vosotros형이라 진행형을 만들 수 없습니다 ✗","son: ser는 현재분사와 함께 진행형을 만들지 않습니다 ✗","estáis: estar의 vosotros(너희)형이지만 tienen과 맞지 않게 인칭이 다릅니다 ✗","están: estar의 3인칭 복수, 진행형 → 정답 ✓"]},{"id":"G610","q":"¿Cuánto ____ esos sofás?","o":["cuestas","cuesta","costáis","cuestan"],"a":3,"k":"costar 변화","t":"저 소파들은 얼마예요?","e":"costar(값이 ~이다)는 o가 ue로 바뀌는 불규칙 동사입니다. 주어는 '값이 나가는 물건'인 esos sofás(3인칭 복수)이므로 cuestan을 씁니다. 하나일 때는 ¿Cuánto cuesta este sofá?(이 소파는 얼마예요?)라고 합니다.","x":["cuestas: 2인칭 단수(너는)형이라 물건 주어와 맞지 않습니다 ✗","cuesta: 3인칭 단수형이라 복수 sofás와 맞지 않습니다 ✗","costáis: vosotros형이고 물건 주어와 맞지 않습니다 ✗","cuestan: 3인칭 복수형 → 정답 ✓"]},{"id":"G611","q":"Siempre desayuna zumo ____ naranja y dos rebanadas de pan con mantequilla.","o":["ø","de la","de","a"],"a":2,"k":"재료의 de","t":"그(그녀)는 항상 아침으로 오렌지 주스와 버터 바른 빵 두 조각을 먹는다.","e":"'명사 + de + 명사'는 종류나 재료를 나타내며, 이때 두 번째 명사 앞에 관사를 쓰지 않습니다. 그래서 'zumo de naranja(오렌지 주스)', 'pan con mantequilla(버터 바른 빵)'처럼 씁니다. 중남미에서는 주스를 jugo라고 합니다(jugo de naranja).","x":["ø: 전치사가 없으면 두 명사를 연결할 수 없습니다 ✗","de la: 종류·재료를 나타낼 때는 관사를 붙이지 않습니다 ✗","de: 재료·종류를 나타내는 전치사 → 정답 ✓","a: 'zumo a naranja'라는 표현은 없습니다 ✗"]},{"id":"G612","q":"Estoy leyendo una novela de una escritora ____.","o":["españolas","española","españoles","español"],"a":1,"k":"국적 형용사 일치","t":"나는 스페인 여성 작가의 소설을 읽고 있다.","e":"국적 형용사는 꾸미는 명사의 성·수에 맞춥니다. una escritora(여성 작가 한 명)는 여성 단수이므로 española가 됩니다. 남성 단수는 español, 남성 복수는 españoles, 여성 복수는 españolas입니다.","x":["españolas: 여성 복수형이라 단수 escritora와 맞지 않습니다 ✗","española: 여성 단수형 → 정답 ✓","españoles: 남성 복수형이라 ✗","español: 남성 단수형이라 여성 명사와 맞지 않습니다 ✗"]},{"id":"G613","q":"Yo me lavo ____ pelo cada día.","o":["la","ø","mi","el"],"a":3,"k":"신체 부위 + 정관사","t":"나는 매일 머리를 감는다.","e":"재귀동사(자기 자신에게 하는 동작) 뒤에 신체 부위가 오면 소유형용사(mi) 대신 정관사를 씁니다. me lavo에서 이미 '나 자신'이 드러나므로 'el pelo'라고 합니다. pelo(머리카락)는 남성 명사라 el을 씁니다. 예: Me cepillo los dientes.(나는 이를 닦는다.)","x":["la: 여성 관사라 남성 명사 pelo와 맞지 않습니다 ✗","ø: 신체 부위 명사 앞에는 정관사가 필요합니다 ✗","mi: 재귀동사로 이미 소유가 드러나므로 소유형용사는 쓰지 않습니다 ✗","el: 남성 정관사, 신체 부위 앞 → 정답 ✓"]},{"id":"G614","q":"¿Vienes ____ al cine?","o":["con nosotros","a nosotros","con nos","de nosotras"],"a":0,"k":"전치사 con","t":"우리와 함께 영화관에 갈래?","e":"'~와 함께'는 전치사 con을 쓰고, 전치사 뒤에는 전치격 대명사(mí, ti, él, nosotros 등)를 씁니다. 그래서 'con nosotros(우리와 함께)'가 됩니다. 1인칭·2인칭 단수만 conmigo(나와), contigo(너와)라는 특별한 형태가 있습니다.","x":["con nosotros: '우리와 함께' → 정답 ✓","a nosotros: '우리에게'라는 뜻이라 함께 간다는 의미가 안 됩니다 ✗","con nos: nos는 목적격 대명사로 전치사 뒤에 쓸 수 없습니다 ✗","de nosotras: '우리(여성)의/에게서'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G615","q":"Ana y Gabriel van a la discoteca ____ sábados.","o":["todos los","todas","todos","todas las"],"a":0,"k":"todos los + 요일","t":"아나와 가브리엘은 토요일마다 디스코텍에 간다.","e":"'매 ~요일마다'는 'todos los + 요일 복수형'으로 말합니다. 요일은 모두 남성 명사이므로 todos los sábados(매주 토요일)가 됩니다. 정관사 los를 빠뜨리지 않도록 주의하세요.","x":["todos los: '모든 ~마다' + 남성 복수 관사 → 정답 ✓","todas: 여성형이고 관사도 없어 틀립니다 ✗","todos: 이 의미에서는 관사 los가 반드시 필요합니다 ✗","todas las: 여성형인데 요일은 남성 명사라서 ✗"]},{"id":"G616","q":"Las lentejas ____ legumbres.","o":["es","están","estás","son"],"a":3,"k":"ser 정의","t":"렌즈콩은 콩류이다.","e":"어떤 것이 무엇인지 정의하거나 분류할 때는 ser를 씁니다. 주어 Las lentejas(렌즈콩들)는 3인칭 복수이므로 son이 됩니다. estar는 위치나 일시적 상태에 씁니다.","x":["es: 3인칭 단수형이라 복수 주어와 맞지 않습니다 ✗","están: estar는 분류·정의에 쓰지 않습니다 ✗","estás: estar의 2인칭 단수형이라 ✗","son: ser의 3인칭 복수, 분류를 나타냄 → 정답 ✓"]},{"id":"G617","q":"¿A qué se dedica tu esposo? —Es ____ biólogo.","o":["ø","el","uno","un"],"a":0,"k":"직업 앞 관사 생략","t":"네 남편은 무슨 일을 하니? — 생물학자야.","e":"ser 뒤에 직업 명사가 올 때는 보통 관사를 쓰지 않습니다. 그래서 'Es biólogo.(그는 생물학자다.)'라고 합니다. 직업에 형용사가 붙으면 관사를 씁니다. 예: Es un biólogo famoso.(그는 유명한 생물학자다.)","x":["ø: 직업 앞이라 관사를 넣지 않음 → 정답 ✓","el: 정관사(그)를 쓰면 특정 생물학자를 가리키게 되어 어색합니다 ✗","uno: 명사 앞에서는 un이 되어야 하고, 직업 앞에는 관사 자체가 필요 없습니다 ✗","un: 꾸미는 말이 없는 직업 앞에는 쓰지 않습니다 ✗"]},{"id":"G618","q":"Perdone, ¿sabe dónde está la farmacia ____ cercana?","o":["mucho","la más","más","muy"],"a":2,"k":"최상급","t":"실례합니다, 가장 가까운 약국이 어디인지 아세요?","e":"최상급은 '정관사 + 명사 + más + 형용사'로 만듭니다. 이미 la farmacia에 정관사 la가 있으므로 빈칸에는 más만 넣으면 됩니다. 'la farmacia más cercana(가장 가까운 약국)'가 됩니다.","x":["mucho: '많이'라는 뜻으로 형용사 cercana를 꾸밀 수 없습니다 ✗","la más: 관사 la가 이미 앞에 있어서 중복됩니다 ✗","más: 정관사 + 명사 + más → 최상급 정답 ✓","muy: '매우 가까운'이 되어 문장은 되지만 '어디 있는지' 묻는 맥락상 최상급이 맞습니다 ✗"]},{"id":"G619","q":"Este cuarto está desordenado, ____ ahora mismo.","o":["ordénalo","ordénalos","ordénala","ordénale"],"a":0,"k":"명령형 + 대명사","t":"이 방이 지저분하니, 지금 당장 정리해.","e":"긍정 명령형에서는 목적격 대명사를 동사 뒤에 붙여 씁니다. 정리할 대상인 este cuarto(방)는 남성 단수이므로 직접목적격 lo를 써서 ordénalo가 됩니다. 대명사를 붙이면 강세 위치를 지키기 위해 악센트(é)가 생깁니다.","x":["ordénalo: 남성 단수 lo(그것을) → 정답 ✓","ordénalos: 복수 los라서 단수 cuarto와 맞지 않습니다 ✗","ordénala: 여성 la라서 남성 명사 cuarto와 맞지 않습니다 ✗","ordénale: le는 간접목적격(~에게)이라 '방을' 정리한다는 의미가 안 됩니다 ✗"]},{"id":"G620","q":"Gloria ____ muy bien el piano.","o":["tocan","toca","toco","tocas"],"a":1,"k":"-ar 동사 현재","t":"글로리아는 피아노를 아주 잘 친다.","e":"tocar(악기를 연주하다)는 규칙 -ar 동사입니다. 주어 Gloria는 3인칭 단수(그녀)이므로 toca를 씁니다. tocar는 '만지다'라는 뜻도 있어서 'tocar el piano(피아노를 치다)', 'tocar la guitarra(기타를 치다)'처럼 씁니다.","x":["tocan: 3인칭 복수(그들)형이라 ✗","toca: 3인칭 단수형 → 정답 ✓","toco: 1인칭 단수(나)형이라 ✗","tocas: 2인칭 단수(너)형이라 ✗"]},{"id":"G621","q":"____ en Portugal siempre ha sido mi sueño.","o":["De vivir","Al vivir","Viviendo","Vivir"],"a":3,"k":"동사원형 주어","t":"포르투갈에서 사는 것은 항상 내 꿈이었다.","e":"스페인어에서 '~하는 것'처럼 동사가 문장의 주어가 될 때는 동사원형을 씁니다. 한국어의 '~하기/~하는 것'을 영어처럼 -ing(현재분사)로 바꾸지 않는 점에 주의하세요. 예: Leer es divertido.(읽는 것은 재미있다.)","x":["De vivir: 전치사 de가 붙으면 주어가 될 수 없습니다 ✗","Al vivir: '살 때'라는 시간 표현이라 주어가 될 수 없습니다 ✗","Viviendo: 현재분사(살면서)는 주어로 쓰지 않습니다 ✗","Vivir: 동사원형으로 '사는 것' → 정답 ✓"]},{"id":"G622","q":"No podemos ir a esa cafetería, hay ____ gente y no hay mesas libres.","o":["demasiada","demasiados","demasiadas","demasiado"],"a":0,"k":"demasiado 일치","t":"우리는 그 카페에 갈 수 없어, 사람이 너무 많고 빈 테이블이 없어.","e":"demasiado(너무 많은)가 명사 앞에 오면 명사의 성·수에 맞춥니다. gente(사람들)는 의미는 여럿이지만 문법적으로 여성 단수 명사이므로 demasiada가 됩니다. 'mucha gente(많은 사람)'도 같은 원리입니다.","x":["demasiada: 여성 단수형으로 gente와 일치 → 정답 ✓","demasiados: 남성 복수형이라 ✗","demasiadas: 여성 복수형인데 gente는 단수 취급이라 ✗","demasiado: 남성 단수(또는 부사)형이라 여성 명사 앞에 맞지 않습니다 ✗"]},{"id":"G623","q":"Mi padre hace ____ paella buenísima.","o":["uno","el","un","una"],"a":3,"k":"부정관사 una","t":"우리 아빠는 아주 맛있는 파에야를 만든다.","e":"처음 언급하는 '어떤 ~ 하나'에는 부정관사를 씁니다. paella(파에야)는 여성 명사이므로 una를 씁니다. buenísima는 bueno의 절대 최상급으로 '아주 맛있는/좋은'이라는 뜻입니다.","x":["uno: 명사 앞에서는 쓰지 않고, 남성형이라 ✗","el: 남성 정관사라 여성 명사와 맞지 않습니다 ✗","un: 남성 부정관사라 paella와 맞지 않습니다 ✗","una: 여성 부정관사 → 정답 ✓"]},{"id":"G624","q":"Todas las películas de esta directora son ____.","o":["buenas","buenos","bien","buena"],"a":0,"k":"형용사 성·수 일치","t":"이 감독의 영화들은 모두 좋다.","e":"ser 뒤에 오는 형용사는 주어의 성·수에 맞춥니다. 주어 las películas(영화들)는 여성 복수이므로 buenas가 됩니다. bien은 '잘'이라는 부사라서 ser 뒤에서 성질을 나타낼 수 없습니다.","x":["buenas: 여성 복수 형용사 → 정답 ✓","buenos: 남성 복수형이라 ✗","bien: 부사(잘)라서 ser 뒤의 형용사 자리에 맞지 않습니다 ✗","buena: 여성 단수형이라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G625","q":"Granada está ____ 420 kilómetros de Madrid.","o":["en","de","a","desde"],"a":2,"k":"거리의 a","t":"그라나다는 마드리드에서 420킬로미터 떨어져 있다.","e":"'~에서 얼마만큼 떨어져 있다'는 'estar a + 거리 + de + 장소'로 말합니다. 거리 앞에는 전치사 a를 씁니다. 예: Mi casa está a cinco minutos de aquí.(우리 집은 여기서 5분 거리다.)","x":["en: 장소 안의 위치를 말할 때 써서 거리 표현에 맞지 않습니다 ✗","de: 출발점(~에서)을 나타내며 거리 앞에는 쓰지 않습니다 ✗","a: 거리를 나타내는 전치사 → 정답 ✓","desde: '~부터'라는 뜻이라 거리 숫자 앞에 쓰지 않습니다 ✗"]},{"id":"G626","q":"En ese jardín ____ muchas flores.","o":["son","están","es","hay"],"a":3,"k":"hay 존재","t":"그 정원에는 꽃이 많이 있다.","e":"'~이(가) 있다'고 존재를 처음 알릴 때는 hay(haber의 특수형)를 씁니다. hay는 단수·복수 상관없이 형태가 같습니다. muchas flores처럼 불특정한 대상 앞에 쓰며, 특정한 것(las flores)의 위치에는 están을 씁니다.","x":["son: ser는 존재를 나타내지 않습니다 ✗","están: 특정한 대상의 위치에 쓰고 muchas flores 같은 불특정 대상에는 쓰지 않습니다 ✗","es: ser는 존재를 나타내지 않습니다 ✗","hay: 불특정 대상의 존재 → 정답 ✓"]},{"id":"G627","q":"Yo siempre ____ la verdad, no soy una mentirosa.","o":["digo","dicen","dices","dice"],"a":0,"k":"decir 현재","t":"나는 항상 진실을 말해, 나는 거짓말쟁이가 아니야.","e":"decir(말하다)는 불규칙 동사로 1인칭 단수가 digo입니다. 주어가 Yo(나)이므로 digo를 씁니다. 변화: digo, dices, dice, decimos, decís, dicen. 'decir la verdad(진실을 말하다)'는 자주 쓰는 표현입니다.","x":["digo: 1인칭 단수형 → 정답 ✓","dicen: 3인칭 복수형이라 ✗","dices: 2인칭 단수형이라 ✗","dice: 3인칭 단수형이라 ✗"]},{"id":"G628","q":"El bautizo de nuestro hijo va a ____ en la iglesia del barrio.","o":["tener","estar","ser","haber"],"a":2,"k":"사건의 ser","t":"우리 아들의 세례식은 동네 성당에서 열릴 것이다.","e":"행사·사건(파티, 회의, 콘서트 등)이 '어디서 열린다'고 말할 때는 estar가 아니라 ser를 씁니다. 그래서 'El bautizo va a ser en la iglesia.(세례식은 성당에서 열린다.)'가 됩니다. 예: La fiesta es en mi casa.(파티는 우리 집에서 한다.)","x":["tener: '가지다'라는 뜻이라 행사의 장소를 말할 수 없습니다 ✗","estar: 사물·사람의 위치에 쓰고, 행사가 열리는 곳에는 쓰지 않습니다 ✗","ser: 행사가 열리는 장소 → 정답 ✓","haber: 존재(있다)를 나타내며 정관사가 붙은 주어와 함께 쓰지 않습니다 ✗"]},{"id":"G629","q":"¿Has recibido ya la tarjeta de crédito? —No, todavía no ____ he recibido.","o":["le","se","lo","la"],"a":3,"k":"직접목적격 대명사","t":"신용카드 벌써 받았어? — 아니, 아직 못 받았어.","e":"앞에 나온 명사를 '그것을'로 받을 때는 직접목적격 대명사를 씁니다. la tarjeta(카드)는 여성 단수이므로 la가 됩니다. 현재완료(he recibido)처럼 동사가 두 단어일 때 대명사는 haber 앞에 둡니다.","x":["le: 간접목적격(~에게)이라 '카드를'을 대신할 수 없습니다 ✗","se: 재귀·무인칭 대명사라 맞지 않습니다 ✗","lo: 남성 단수형이라 여성 명사 tarjeta와 맞지 않습니다 ✗","la: 여성 단수 직접목적격(그것을) → 정답 ✓"]},{"id":"G630","q":"La ciudad ____ poblada de Colombia es Bogotá.","o":["mucho","muy","la más","más"],"a":3,"k":"최상급","t":"콜롬비아에서 가장 인구가 많은 도시는 보고타이다.","e":"최상급은 '정관사 + 명사 + más + 형용사 + de(~중에서)'로 만듭니다. 이미 La ciudad에 정관사가 있으므로 빈칸에는 más만 넣습니다. poblada는 '사람이 사는, 인구가 많은'이라는 뜻의 형용사입니다.","x":["mucho: 형용사 앞에 쓸 수 없습니다 ✗","muy: '매우'라는 뜻으로 최상급 de Colombia와 어울리지 않습니다 ✗","la más: 관사 la가 이미 있어 중복됩니다 ✗","más: 관사 + 명사 + más → 최상급 정답 ✓"]},{"id":"G631","q":"Mi color preferido es ____ naranja.","o":["la","ø","el","lo"],"a":2,"k":"색깔 명사 + el","t":"내가 가장 좋아하는 색은 주황색이다.","e":"색깔 이름이 명사로 쓰이면 모두 남성 명사이므로 정관사 el을 씁니다. naranja는 과일(la naranja, 오렌지)일 때는 여성이지만, 색깔(el naranja, 주황색)일 때는 남성입니다. 예: El azul es bonito.(파란색은 예쁘다.)","x":["la: 과일 '오렌지'일 때의 관사라 색깔에는 맞지 않습니다 ✗","ø: 색깔 이름을 주어·보어로 쓸 때는 관사가 필요합니다 ✗","el: 색깔 명사는 남성 → 정답 ✓","lo: 중성 관사로 'lo bueno(좋은 것)'처럼 형용사 앞에 쓰고 명사 앞에는 쓰지 않습니다 ✗"]},{"id":"G632","q":"Anita trabaja en ____ única farmacia que hay en el pueblo.","o":["ø","la","una","las"],"a":1,"k":"정관사 la","t":"아니타는 마을에 있는 유일한 약국에서 일한다.","e":"única(유일한)처럼 하나뿐인 것을 가리킬 때는 정관사를 씁니다. 하나밖에 없으니 특정한 대상이기 때문입니다. farmacia는 여성 단수이므로 la를 써서 'la única farmacia(유일한 약국)'가 됩니다.","x":["ø: 명사 앞에 한정사가 필요합니다 ✗","la: 유일한 대상이라 정관사 → 정답 ✓","una: '어떤 하나의'라는 뜻이라 '유일한'과 어울리지 않습니다 ✗","las: 복수형이라 단수 farmacia와 맞지 않습니다 ✗"]},{"id":"G633","q":"¿____ te parece la idea de Luisa?","o":["Cuánto","Cuándo","Cuál","Qué"],"a":3,"k":"¿Qué te parece?","t":"루이사의 아이디어 어떻게 생각해?","e":"'¿Qué te parece...?'는 '~에 대해 어떻게 생각해?'라고 의견을 묻는 고정 표현입니다. parecer(~처럼 보이다)는 gustar처럼 간접목적격 대명사(te)와 함께 씁니다. 한국어로는 '어떻게'지만 cómo가 아니라 qué를 쓰는 점을 기억하세요.","x":["Cuánto: '얼마나'라는 뜻이라 의견을 묻는 표현이 아닙니다 ✗","Cuándo: '언제'라는 뜻이라 맞지 않습니다 ✗","Cuál: '어느 것'이라는 뜻이라 이 표현에 쓰지 않습니다 ✗","Qué: ¿Qué te parece? 고정 표현 → 정답 ✓"]},{"id":"G634","q":"¿Me ayudas ____ poner la mesa?","o":["ø","por","a","en"],"a":2,"k":"ayudar a","t":"상 차리는 것 좀 도와줄래?","e":"ayudar(돕다) 뒤에 동사원형이 오면 전치사 a를 씁니다: 'ayudar a + 동사원형(~하는 것을 돕다)'. poner la mesa는 '상을 차리다'라는 관용 표현입니다. 예: Te ayudo a estudiar.(네가 공부하는 걸 도와줄게.)","x":["ø: ayudar 뒤 동사원형 앞에는 a가 필요합니다 ✗","por: 이유·원인을 나타내며 ayudar와 쓰지 않습니다 ✗","a: ayudar a + 동사원형 → 정답 ✓","en: 'ayudar en + 명사(~에서 돕다)'는 가능하지만 동사원형 앞에는 쓰지 않습니다 ✗"]},{"id":"G635","q":"A Lucía le gusta esquiar y a mí ____.","o":["también","tampoco","sí","también sí"],"a":0,"k":"también/tampoco","t":"루시아는 스키 타는 것을 좋아하고 나도 그래.","e":"앞 문장이 긍정(le gusta)일 때 '나도 그래'는 'a mí también'이라고 합니다. 앞 문장이 부정일 때 '나도 안 그래'는 'a mí tampoco'입니다. 앞이 부정이고 나는 긍정이면 'a mí sí'라고 합니다.","x":["también: 긍정에 대한 동의(나도) → 정답 ✓","tampoco: 부정에 대한 동의(나도 아니야)라서 ✗","sí: 앞 문장이 부정일 때 반대 의견으로 씁니다 ✗","también sí: 이런 표현은 쓰지 않습니다 ✗"]},{"id":"G636","q":"¿Venís ____ al mercado?","o":["con yo","con me","conmigo","con mí"],"a":2,"k":"conmigo","t":"너희 나랑 같이 시장에 갈래?","e":"전치사 con 뒤에 '나'가 오면 con mí가 아니라 한 단어 conmigo(나와 함께)를 씁니다. '너와 함께'도 contigo라는 특별한 형태입니다. venís는 vosotros(너희)형으로 주로 스페인에서 씁니다. 중남미에서는 ¿Vienen conmigo?라고 합니다.","x":["con yo: 주격 yo는 전치사 뒤에 쓸 수 없습니다 ✗","con me: me는 목적격 대명사라 전치사 뒤에 쓸 수 없습니다 ✗","conmigo: '나와 함께'의 특별한 형태 → 정답 ✓","con mí: 다른 전치사 뒤에는 mí를 쓰지만 con만은 conmigo가 됩니다 ✗"]},{"id":"G637","q":"¿De qué color ____ los ojos tu madre?","o":["tienen","tiene","tenéis","tienes"],"a":1,"k":"tener 3인칭","t":"너희 어머니는 눈이 무슨 색이니?","e":"스페인어에서는 신체 특징을 tener(가지다)로 말합니다: 'tener los ojos azules(파란 눈을 가지다)'. 이 문장의 주어는 tu madre(3인칭 단수)이므로 tiene가 맞습니다. los ojos는 목적어이므로 동사를 복수로 만들지 않습니다.","x":["tienen: 3인칭 복수형인데 주어는 tu madre(단수)라서 ✗","tiene: 3인칭 단수형 → 정답 ✓","tenéis: vosotros(너희)형이라 ✗","tienes: 2인칭 단수(너)형이라 ✗"]},{"id":"G638","q":"¿Quién es ____ chico rubio?","o":["ese","eso","esa","esos"],"a":0,"k":"지시형용사 ese","t":"그 금발 남자애는 누구니?","e":"지시형용사 ese(그)는 꾸미는 명사의 성·수에 맞춥니다. chico(남자아이)는 남성 단수이므로 ese가 됩니다. 형태: ese(남성 단수), esa(여성 단수), esos(남성 복수), esas(여성 복수).","x":["ese: 남성 단수 지시형용사 → 정답 ✓","eso: 중성 지시대명사(그것)로 명사 앞에 쓰지 않습니다 ✗","esa: 여성형이라 chico와 맞지 않습니다 ✗","esos: 복수형이라 단수 chico와 맞지 않습니다 ✗"]},{"id":"G639","q":"Pueden dejar sus celulares ____ aquella mesa.","o":["encima","encima de","por encima","encima a"],"a":1,"k":"encima de","t":"휴대폰을 저 테이블 위에 두셔도 됩니다.","e":"'~위에'는 'encima de + 명사'로 씁니다. encima 혼자는 부사(위에)이므로 뒤에 명사를 붙이려면 de가 필요합니다. celular(휴대폰)는 중남미에서 쓰는 말로, 스페인에서는 móvil이라고 합니다.","x":["encima: 명사 앞에서는 de가 필요합니다 ✗","encima de: '~의 위에' → 정답 ✓","por encima: '~위로(넘어서)'의 뜻이고 de도 없어 맞지 않습니다 ✗","encima a: encima는 a와 함께 쓰지 않습니다 ✗"]},{"id":"G640","q":"Estamos esperando ____ nuestros hijos.","o":["de","por","a","a los"],"a":2,"k":"사람 목적어의 a","t":"우리는 우리 아이들을 기다리고 있다.","e":"직접목적어가 특정한 사람이면 그 앞에 전치사 a를 붙입니다(인칭의 a). esperar는 '~을 기다리다'라는 뜻으로 전치사 없이 목적어를 받지만, 사람이 목적어이므로 a가 필요합니다. 뒤에 소유형용사 nuestros가 있어 관사는 넣지 않습니다.","x":["de: esperar는 de와 함께 쓰지 않습니다 ✗","por: 'esperar por'는 일부 지역에서 쓰지만 표준 표현이 아닙니다 ✗","a: 사람 목적어 앞의 a → 정답 ✓","a los: 소유형용사 nuestros가 있어서 관사 los는 중복입니다 ✗"]},{"id":"G641","q":"Elisa y su novio ____ a la playa a menudo.","o":["vais","vamos","vas","van"],"a":3,"k":"ir 현재","t":"엘리사와 그녀의 남자친구는 자주 해변에 간다.","e":"ir(가다)는 불규칙 동사입니다: voy, vas, va, vamos, vais, van. 주어 'Elisa y su novio(엘리사와 남자친구)'는 두 사람, 즉 3인칭 복수(ellos)이므로 van을 씁니다. a menudo는 '자주'라는 뜻입니다.","x":["vais: vosotros(너희)형이라 ✗","vamos: nosotros(우리)형이라 ✗","vas: 2인칭 단수(너)형이라 ✗","van: 3인칭 복수형 → 정답 ✓"]},{"id":"G642","q":"No quiero más azúcar, ya está ____ dulce.","o":["poco","mucho","tan","bastante"],"a":3,"k":"bastante 부사","t":"설탕은 더 필요 없어, 이미 충분히 달아.","e":"bastante는 형용사 앞에서 부사로 쓰여 '꽤, 충분히'라는 뜻이 됩니다. 이미 충분히 달아서 설탕이 더 필요 없다는 문맥에 잘 맞습니다. 형용사 앞에 오는 부사로 쓰일 때는 형태가 변하지 않습니다.","x":["poco: '별로 ~하지 않은'이라는 뜻이라 설탕이 필요 없다는 말과 반대입니다 ✗","mucho: 형용사 앞에서는 mucho가 아니라 muy를 씁니다 ✗","tan: '그렇게'라는 뜻으로 비교 대상(como)이 없어 어색합니다 ✗","bastante: '꽤, 충분히' → 정답 ✓"]},{"id":"G643","q":"____ pasar nuestras próximas vacaciones en Costa Rica.","o":["Queréis","Quieren","Quieres","Queremos"],"a":3,"k":"querer 현재","t":"우리는 다음 휴가를 코스타리카에서 보내고 싶다.","e":"querer(원하다)는 e가 ie로 바뀌는 불규칙 동사지만 nosotros와 vosotros에서는 바뀌지 않습니다. 소유형용사 nuestras(우리의)가 주어가 '우리'임을 알려 주므로 queremos가 맞습니다. 'querer + 동사원형'은 '~하고 싶다'입니다.","x":["Queréis: vosotros(너희)형이라 nuestras와 맞지 않습니다 ✗","Quieren: 3인칭 복수형이라 '우리의 휴가'와 맞지 않습니다 ✗","Quieres: 2인칭 단수(너)형이라 ✗","Queremos: nosotros(우리)형 → 정답 ✓"]},{"id":"G644","q":"A Julián ____ encantan las hamburguesas.","o":["los","lo","le","les"],"a":2,"k":"encantar 구문","t":"훌리안은 햄버거를 정말 좋아한다.","e":"encantar(아주 좋아하다)는 gustar처럼 '좋아하는 사람'을 간접목적격 대명사로 씁니다. A Julián은 3인칭 단수이므로 le를 씁니다. 동사 encantan이 복수인 것은 좋아하는 대상 las hamburguesas가 복수이기 때문입니다.","x":["los: 직접목적격(그것들을/그들을)이라 encantar 구문에 맞지 않습니다 ✗","lo: 직접목적격(그를)이라 ✗","le: 3인칭 단수 간접목적격(그에게) → 정답 ✓","les: 3인칭 복수형인데 Julián은 한 사람이라 ✗"]},{"id":"G645","q":"____ Estefanía no le gusta su nuevo trabajo.","o":["A","Para","ø","De"],"a":0,"k":"gustar의 a + 사람","t":"에스테파니아는 새 직장이 마음에 들지 않는다.","e":"gustar 구문에서 '누구에게' 마음에 드는지 강조하거나 명확히 할 때는 'A + 사람'을 문장 앞에 둡니다. 그래서 'A Estefanía no le gusta...'가 됩니다. 이때 a를 빼면 Estefanía가 주어처럼 보여 틀린 문장이 됩니다.","x":["A: gustar 구문의 'a + 사람' → 정답 ✓","Para: '~을 위해'라는 뜻이라 gustar와 쓰지 않습니다 ✗","ø: a를 빼면 문장 구조가 틀립니다 ✗","De: '~의/~에서'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G646","q":"Esta camiseta es ____ algodón.","o":["con","de","a","por"],"a":1,"k":"재료의 de","t":"이 티셔츠는 면으로 되어 있다.","e":"'ser de + 재료'는 '~으로 만들어졌다'라는 뜻입니다. 그래서 'es de algodón(면으로 되어 있다)'이라고 합니다. 예: La mesa es de madera.(그 테이블은 나무로 되어 있다.)","x":["con: '~와 함께/~을 가진'이라는 뜻이라 재료를 나타내지 않습니다 ✗","de: 재료를 나타내는 전치사 → 정답 ✓","a: 재료 표현에 쓰지 않습니다 ✗","por: 이유·경로를 나타내며 재료에는 쓰지 않습니다 ✗"]},{"id":"G647","q":"Andrés es ____ mejor estudiante de esta clase.","o":["un","él","ø","el"],"a":3,"k":"최상급 el mejor","t":"안드레스는 이 반에서 가장 우수한 학생이다.","e":"'el/la + mejor + 명사 + de(~중에서)'는 '~중에서 가장 좋은'이라는 최상급입니다. mejor 앞에 정관사를 붙여야 최상급이 되며, estudiante가 남학생(Andrés)을 가리키므로 el을 씁니다. 예: Es la mejor película del año.(올해 최고의 영화다.)","x":["un: '한 명의 더 나은'이 되어 최상급이 안 됩니다 ✗","él: 주격 대명사(그)라 명사 앞에 올 수 없습니다 ✗","ø: 관사가 없으면 최상급이 되지 않습니다 ✗","el: 정관사 + mejor → 최상급 정답 ✓"]},{"id":"G648","q":"En ____ mesa de la cocina hay varios platos y vasos.","o":["los","las","ø","la"],"a":3,"k":"정관사 la","t":"부엌 식탁 위에 접시와 컵이 여러 개 있다.","e":"de la cocina(부엌의)로 어떤 식탁인지 특정되었으므로 정관사를 씁니다. mesa(식탁)는 여성 단수이므로 la가 됩니다. 문장 뒷부분의 hay는 불특정한 접시와 컵이 '있다'는 뜻입니다.","x":["los: 남성 복수형이라 ✗","las: 여성 복수형이라 단수 mesa와 맞지 않습니다 ✗","ø: 단수 가산명사 앞에는 관사가 필요합니다 ✗","la: 여성 단수 정관사 → 정답 ✓"]},{"id":"G649","q":"Tengo ____ casa en el campo y otra en la ciudad.","o":["una","unas","uno","un"],"a":0,"k":"부정관사 una","t":"나는 시골에 집이 한 채 있고 도시에 또 한 채가 있다.","e":"tener 뒤에서 '(어떤) 하나의 ~'를 말할 때는 부정관사를 씁니다. casa는 여성 단수이므로 una를 씁니다. 뒤의 'otra(또 다른 하나)'와 짝을 이루어 '하나는 ~, 다른 하나는 ~'라는 의미를 만듭니다.","x":["una: 여성 단수 부정관사 → 정답 ✓","unas: 복수형(몇몇의)이라 ✗","uno: 명사 앞에 쓰지 않는 형태입니다 ✗","un: 남성형이라 여성 명사 casa와 맞지 않습니다 ✗"]},{"id":"G650","q":"¿Cuándo vas a terminar ____ estudios universitarios?","o":["tuyos","tu","vuestro","tus"],"a":3,"k":"소유형용사 tus","t":"너는 대학 공부를 언제 끝낼 거니?","e":"소유형용사 단축형(mi, tu, su 등)은 명사 앞에 오고, 소유한 사람이 아니라 '소유된 명사'의 수에 맞춥니다. estudios(학업)는 복수이므로 tu에 s를 붙여 tus가 됩니다. 동사 vas가 '너'이므로 tus가 맞습니다.","x":["tuyos: 강세형이라 명사 앞에 쓰지 않고 명사 뒤나 ser 뒤에 씁니다 ✗","tu: 단수형이라 복수 estudios와 맞지 않습니다 ✗","vuestro: '너희의'이며 단수형이라 ✗","tus: 복수 명사 앞 '너의' → 정답 ✓"]},{"id":"G651","q":"¿Cómo sueles pagar ____ compras algo?","o":["cuanto","como","cuando","que"],"a":2,"k":"접속사 cuando","t":"너는 뭔가를 살 때 보통 어떻게 계산하니?","e":"cuando는 '~할 때'라는 뜻으로 두 문장을 잇는 접속사입니다. 의문문이 아니므로 악센트 없이 씁니다(의문사일 때는 cuándo). soler + 동사원형은 '보통 ~하다'라는 뜻입니다.","x":["cuanto: '~하는 만큼'이라는 뜻이라 맞지 않습니다 ✗","como: '~처럼/~하므로'라는 뜻이라 문맥에 맞지 않습니다 ✗","cuando: '~할 때' → 정답 ✓","que: 관계사·접속사(~라는 것)로 시간을 나타내지 못합니다 ✗"]},{"id":"G652","q":"Disculpe, señora, ¿es suyo ese auto? —Sí, es ____.","o":["mí","a mí","de mí","mío"],"a":3,"k":"소유형용사 강세형","t":"실례합니다, 부인, 저 차가 당신 것인가요? — 네, 제 것이에요.","e":"ser 뒤에서 '~의 것'이라고 할 때는 소유형용사 강세형(mío, tuyo, suyo...)을 씁니다. auto(자동차)는 남성 단수이므로 mío가 됩니다. 말하는 사람이 여성이어도 형태는 소유된 물건(auto)에 맞춘다는 점이 중요합니다. auto는 중남미, coche는 스페인에서 주로 씁니다.","x":["mí: 전치사 뒤에 쓰는 대명사(나)라서 혼자 소유를 나타내지 못합니다 ✗","a mí: '나에게'라는 뜻이라 ✗","de mí: '나에 대해/나로부터'라는 뜻이라 소유 표현이 아닙니다 ✗","mío: 남성 단수 강세형(내 것) → 정답 ✓"]},{"id":"G653","q":"Por suerte, vivimos en una zona con ____ espacios verdes.","o":["mucho","muchos","muchas","mucha"],"a":1,"k":"mucho 성·수 일치","t":"다행히 우리는 녹지 공간이 많은 지역에 산다.","e":"mucho(많은)가 명사 앞에 오면 명사의 성·수에 맞춥니다. espacios verdes(녹지 공간)는 남성 복수이므로 muchos를 씁니다. por suerte는 '다행히'라는 뜻입니다.","x":["mucho: 남성 단수형이라 복수 명사와 맞지 않습니다 ✗","muchos: 남성 복수형 → 정답 ✓","muchas: 여성 복수형인데 espacio는 남성이라 ✗","mucha: 여성 단수형이라 ✗"]},{"id":"G654","q":"Ayer fui a mi trabajo ____ metro.","o":["por","a","de","en"],"a":3,"k":"교통수단 en","t":"어제 나는 지하철로 직장에 갔다.","e":"교통수단을 탈 때 '~을 타고, ~로'는 'en + 교통수단'으로 말하고 관사는 쓰지 않습니다. 예: en coche(차로), en autobús(버스로), en tren(기차로). 단, '걸어서'는 a pie, '말을 타고'는 a caballo라고 합니다.","x":["por: 교통수단 표현에 쓰지 않습니다 ✗","a: a pie(걸어서) 같은 일부 표현에만 쓰고 metro와는 쓰지 않습니다 ✗","de: 교통수단 앞에 쓰지 않습니다 ✗","en: 교통수단을 나타내는 en → 정답 ✓"]},{"id":"G655","q":"Me gustaría tener una casa ____ jardín.","o":["con","de","a","en"],"a":0,"k":"전치사 con","t":"나는 정원이 있는 집을 갖고 싶다.","e":"'~이 있는, ~이 딸린'이라는 특징은 전치사 con(~와 함께, ~을 가진)으로 나타냅니다. 'una casa con jardín(정원 딸린 집)'처럼 씁니다. 반대로 '~없는'은 sin을 씁니다: una casa sin jardín.","x":["con: '~이 딸린' → 정답 ✓","de: 재료·소속을 나타내 '정원으로 된 집'처럼 어색해집니다 ✗","a: 이런 특징을 나타내지 않습니다 ✗","en: '정원 안에 있는 집'이 되어 의미가 다릅니다 ✗"]},{"id":"G656","q":"Prefiero trabajar ____ la mañana para tener la tarde libre.","o":["para","de","por","a"],"a":2,"k":"por la mañana","t":"나는 오후를 비워 두려고 오전에 일하는 것을 선호한다.","e":"시간을 밝히지 않고 '오전에, 오후에, 밤에'라고 할 때는 'por la mañana / por la tarde / por la noche'를 씁니다. 정확한 시각과 함께 쓸 때는 de를 씁니다: a las diez de la mañana(오전 10시). 중남미 일부에서는 en la mañana도 씁니다.","x":["para: 목적·기한(~을 위해, ~까지)이라 ✗","de: 시각 뒤에서만 씁니다(a las 9 de la mañana) ✗","por: 하루 중 시간대 → 정답 ✓","a: 'a la mañana'는 일부 지역(아르헨티나 등)에서 쓰지만 표준은 por입니다 ✗"]},{"id":"G657","q":"Vivo en el ____ piso de ese bloque.","o":["primo","primera","primero","primer"],"a":3,"k":"primer 탈락형","t":"나는 저 건물의 1층(2층)에 산다.","e":"primero(첫 번째)는 남성 단수 명사 앞에서 o가 떨어져 primer가 됩니다. piso는 남성 명사이므로 'el primer piso'가 됩니다. tercero(세 번째)도 같아서 el tercer piso가 됩니다. 스페인에서 primer piso는 보통 우리식 2층에 해당합니다.","x":["primo: '사촌'이라는 전혀 다른 단어입니다 ✗","primera: 여성형이라 남성 명사 piso와 맞지 않습니다 ✗","primero: 남성 단수 명사 앞에서는 o가 탈락해야 합니다 ✗","primer: 남성 단수 명사 앞 형태 → 정답 ✓"]},{"id":"G658","q":"¿____ es la capital de Chile?","o":["Cuál","Dónde","Qué","Quién"],"a":0,"k":"cuál vs qué","t":"칠레의 수도는 어디야?","e":"'¿Cuál es...?'는 여러 개 중 하나를 고를 때 쓰며, 이름·번호·수도처럼 정보를 물을 때도 ser 앞에 cuál을 씁니다. 한국어로는 '어디'지만 수도는 '장소의 위치'가 아니라 '도시 이름'을 묻는 것이라 dónde를 쓰지 않습니다. 예: ¿Cuál es tu nombre?(네 이름이 뭐니?)","x":["Cuál: 정보(수도의 이름)를 물음 → 정답 ✓","Dónde: '어디에'는 위치를 묻는 말이라 수도 이름을 묻는 데 쓰지 않습니다 ✗","Qué: ser 앞에서 qué는 정의(무엇인가)를 묻는 말이라 ✗","Quién: '누구'라는 뜻이라 ✗"]},{"id":"G659","q":"¿Qué ves ____ la ventana de tu habitación?","o":["entre","a","desde","de"],"a":2,"k":"전치사 desde","t":"네 방 창문으로 무엇이 보여?","e":"desde는 '~에서(부터)'라는 출발점·관점을 나타냅니다. 어떤 장소에서 무언가를 바라볼 때 'ver desde + 장소'를 씁니다. 예: Desde aquí se ve el mar.(여기서 바다가 보인다.)","x":["entre: '~사이에'라는 뜻이라 ✗","a: 방향(~로)을 나타내서 '창문 쪽을 보다'가 되어 의미가 다릅니다 ✗","desde: 보는 위치(~에서) → 정답 ✓","de: 출신·소유를 주로 나타내 이 문장에서는 어색합니다 ✗"]},{"id":"G660","q":"Tienes cara de preocupada. ¿Te pasa ____?","o":["nada","algo","alguien","alguno"],"a":1,"k":"부정어 algo","t":"너 걱정스러운 얼굴이네. 무슨 일 있어?","e":"algo는 '무언가'라는 뜻의 부정대명사(정해지지 않은 것을 가리키는 말)입니다. 긍정 의문문에서 '무슨 일 있니?'라고 할 때 '¿Te pasa algo?'를 씁니다. nada(아무것도)는 주로 부정문에 씁니다.","x":["nada: '아무것도 (없다)'라는 뜻으로 주로 부정문에 쓰여 ✗","algo: '무언가' → 정답 ✓","alguien: '누군가'라는 사람을 가리켜 ✗","alguno: 형용사·대명사로 '어떤 ~(것)'인데 사물 일반을 가리키는 대명사로는 algo를 씁니다 ✗"]},{"id":"G661","q":"Este programa empieza ____ una de la tarde.","o":["al","en la","a la","a las"],"a":2,"k":"시각 표현 a la una","t":"이 프로그램은 오후 1시에 시작한다.","e":"'몇 시에'는 'a + 정관사 + 시각'으로 말합니다. 1시는 단수라서 'a la una', 2시부터는 복수라서 'a las dos, a las tres...'가 됩니다. 관사가 여성형인 것은 hora(시간)가 생략되었기 때문입니다.","x":["al: 남성 관사(a + el)라서 시각 앞에 쓰지 않습니다 ✗","en la: 시각 앞에는 en이 아니라 a를 씁니다 ✗","a la: 1시는 단수 → 정답 ✓","a las: 2시 이상의 복수 시각에 씁니다 ✗"]},{"id":"G662","q":"La chica ____ pelo rizado se llama Amaya.","o":["del","en el","con","al"],"a":0,"k":"특징의 de","t":"곱슬머리 여자아이의 이름은 아마야이다.","e":"'~을 가진(외모의 특징)'은 'de + 정관사 + 명사'로 나타낼 수 있습니다. de + el = del이 되어 'la chica del pelo rizado(곱슬머리 여자아이)'가 됩니다. 'la chica de pelo rizado'나 'con el pelo rizado'처럼 말할 수도 있습니다.","x":["del: de + el, 외모 특징 → 정답 ✓","en el: '머리카락 안에 있는'이라는 뜻이 되어 ✗","con: 'con el pelo'처럼 관사가 있으면 가능하지만, 교재 정답은 del입니다 ✗","al: a + el은 방향을 나타내 맞지 않습니다 ✗"]},{"id":"G663","q":"¿Dónde aparcaron ____ carro?","o":["vuestros","su","tus","sus"],"a":1,"k":"소유형용사 su","t":"(여러분/그들은) 차를 어디에 주차했어요?","e":"aparcaron은 ustedes(여러분) 또는 ellos(그들)의 과거형이므로 소유형용사는 su(당신들의/그들의)를 씁니다. 소유형용사는 소유되는 명사의 수에 맞추는데 carro는 단수이므로 sus가 아니라 su입니다. carro는 중남미에서 '자동차'를 뜻하며 스페인에서는 coche라고 합니다.","x":["vuestros: vosotros의 소유형이고 복수형이라 ✗","su: 단수 명사 앞 '당신들의/그들의' → 정답 ✓","tus: 2인칭 단수(너의)라 동사 aparcaron과 맞지 않습니다 ✗","sus: 복수형이라 단수 carro와 맞지 않습니다 ✗"]},{"id":"G664","q":"¿Me pone un café con ____ leche, por favor?","o":["una","ø","el","la"],"a":1,"k":"물질명사 관사 생략","t":"우유 탄 커피 한 잔 주시겠어요?","e":"'café con leche(카페라테)'는 고정된 메뉴 이름으로, 셀 수 없는 물질명사 leche 앞에 관사를 쓰지 않습니다. '¿Me pone...?'은 스페인에서 주문할 때 쓰는 표현으로 '~ 주시겠어요?'라는 뜻입니다.","x":["una: 셀 수 없는 물질명사 앞에 부정관사를 쓰지 않습니다 ✗","ø: café con leche 고정 표현 → 정답 ✓","el: 남성 관사이고, 이 표현에는 관사가 필요 없습니다 ✗","la: 특정한 우유를 가리키게 되어 어색합니다 ✗"]},{"id":"G665","q":"Según el pronóstico del tiempo, mañana ____ a llover.","o":["vais","va","van","vas"],"a":1,"k":"ir a + 동사원형","t":"일기예보에 따르면 내일 비가 올 것이다.","e":"'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래 표현입니다. llover(비가 오다) 같은 날씨 동사는 주어가 없는 3인칭 단수로 쓰므로 va가 됩니다. 예: Va a nevar.(눈이 올 거야.)","x":["vais: vosotros형이라 ✗","va: 날씨 표현은 3인칭 단수 → 정답 ✓","van: 3인칭 복수형이라 ✗","vas: 2인칭 단수(너)형이라 ✗"]},{"id":"G666","q":"¿Qué vas ____ hacer el domingo?","o":["de","por","ø","a"],"a":3,"k":"ir a + 동사원형","t":"너는 일요일에 뭐 할 거야?","e":"미래의 계획은 'ir a + 동사원형(~할 것이다)'으로 말합니다. ir 동사와 동사원형 사이에는 반드시 전치사 a가 들어갑니다. el domingo는 '이번 일요일에'라는 뜻으로 전치사 en 없이 씁니다.","x":["de: ir 다음 동사원형 앞에 de를 쓰지 않습니다 ✗","por: 이 구문에 쓰지 않습니다 ✗","ø: a가 없으면 미래 표현이 되지 않습니다 ✗","a: ir a + 동사원형 → 정답 ✓"]},{"id":"G667","q":"El lápiz está ____ la mesa. ¿Lo ves?","o":["debajo de","debajo","bajo de","de bajo"],"a":0,"k":"debajo de","t":"연필은 테이블 아래에 있어. 보여?","e":"'~아래에'는 'debajo de + 명사'로 말합니다. debajo는 부사이므로 명사 앞에서는 de를 붙여야 합니다. 같은 뜻의 전치사 bajo는 de 없이 씁니다(bajo la mesa). 반대말은 encima de(~위에)입니다.","x":["debajo de: '~아래에' → 정답 ✓","debajo: 명사 앞에서는 de가 필요합니다 ✗","bajo de: bajo는 전치사라 de를 붙이지 않습니다 ✗","de bajo: 순서가 틀린 잘못된 형태입니다 ✗"]},{"id":"G668","q":"Señor Torres, ____ a la consulta del doctor, por favor.","o":["pase","pases","pasa","pasas"],"a":0,"k":"usted 명령형","t":"토레스 씨, 진료실로 들어오세요.","e":"Señor Torres처럼 존칭으로 부르는 사람에게는 usted 명령형을 씁니다. -ar 동사의 usted 명령형은 어미를 -e로 바꿔 pasar → pase가 됩니다. 'pase'는 '들어오세요'라는 뜻으로 자주 쓰는 표현입니다.","x":["pase: usted 긍정 명령형 → 정답 ✓","pases: tú 부정 명령형(no pases)이나 접속법 형태라 ✗","pasa: tú 긍정 명령형(들어와)이라 존칭과 맞지 않습니다 ✗","pasas: 현재형(너는 지나간다)이라 명령이 아닙니다 ✗"]},{"id":"G669","q":"A Ángel siempre ____ olvida sacar la basura cuando sale de casa.","o":["le","se","se le","lo"],"a":2,"k":"olvidarse 무의지","t":"앙헬은 집에서 나갈 때 항상 쓰레기 버리는 것을 깜빡한다.","e":"'se + 간접목적격 + olvidar'는 '~가 (무심코) 잊어버리다'라는 표현으로, 의도하지 않은 일을 나타냅니다. 잊어버리는 사람(A Ángel)은 간접목적격 le로 나타내 'se le olvida'가 됩니다. 예: Se me olvidó la llave.(열쇠를 깜빡했다.)","x":["le: se가 빠지면 olvidar의 구조가 맞지 않습니다 ✗","se: 잊는 사람(le)이 빠져서 A Ángel과 연결되지 않습니다 ✗","se le: 무의지 se + 그에게 le → 정답 ✓","lo: 직접목적격(그를)이라 ✗"]},{"id":"G670","q":"El clima de Argentina es distinto en cada región ____ país.","o":["de","de la","de los","del"],"a":3,"k":"축약형 del","t":"아르헨티나의 기후는 나라의 지역마다 다르다.","e":"'그 나라의'처럼 특정한 명사 앞에 de가 오면 정관사가 필요합니다. país(나라)는 남성 단수이므로 de + el = del이 됩니다. 스페인어에서 de el은 반드시 del로 줄여 씁니다.","x":["de: 관사가 없어 특정한 나라(아르헨티나)를 가리키지 못합니다 ✗","de la: 여성 관사라 남성 명사 país와 맞지 않습니다 ✗","de los: 복수형이라 ✗","del: de + el 축약형 → 정답 ✓"]},{"id":"G671","q":"Los helados ____ en el congelador.","o":["hay","están","son","es"],"a":1,"k":"estar 위치","t":"아이스크림들은 냉동실에 있다.","e":"정관사가 붙은 특정한 사물(los helados)의 위치를 말할 때는 estar를 씁니다. 주어가 3인칭 복수이므로 están이 됩니다. 불특정한 것의 존재를 처음 알릴 때만 hay를 씁니다: Hay helados en el congelador.","x":["hay: 정관사 붙은 특정한 명사와는 쓰지 않습니다 ✗","están: 특정한 사물의 위치 → 정답 ✓","son: ser는 사물의 위치에 쓰지 않습니다 ✗","es: ser의 단수형이고 위치에 쓰지 않습니다 ✗"]},{"id":"G672","q":"Este ____ el último libro que he leído.","o":["es","estoy","son","está"],"a":0,"k":"ser 정체 설명","t":"이것이 내가 마지막으로 읽은 책이다.","e":"'이것은 ~이다'처럼 무엇인지 정체를 밝힐 때는 ser를 씁니다. 주어 Este(이것)는 3인칭 단수이므로 es가 됩니다. el último libro que he leído는 '내가 읽은 마지막(최근) 책'이라는 뜻입니다.","x":["es: ser 3인칭 단수, 정체 설명 → 정답 ✓","estoy: estar의 1인칭(나는)이라 ✗","son: 복수형이라 ✗","está: estar는 명사로 정체를 설명할 때 쓰지 않습니다 ✗"]},{"id":"G673","q":"El ciclismo no me interesa ____.","o":["nadie","algo","nada","ninguno"],"a":2,"k":"이중 부정 nada","t":"사이클은 나에게 전혀 흥미가 없다.","e":"스페인어는 no와 다른 부정어(nada, nadie, nunca)를 함께 쓰는 이중 부정이 자연스럽습니다. 'no ... nada'는 '전혀 ~않다'는 뜻이 됩니다. interesar는 gustar처럼 쓰는 동사로 '~에게 흥미를 주다'입니다.","x":["nadie: '아무도'라는 사람을 가리켜 ✗","algo: 긍정 표현(무언가)이라 부정문과 맞지 않습니다 ✗","nada: no와 함께 '전혀' → 정답 ✓","ninguno: '어떤 ~도'라는 뜻으로 명사를 대신하는데 이 문장에는 맞지 않습니다 ✗"]},{"id":"G674","q":"¿Sabes cómo se llaman ____ los padres de María?","o":["a","ø","sobre","por"],"a":1,"k":"llamarse 구문","t":"마리아의 부모님 이름이 뭔지 알아?","e":"llamarse(이름이 ~이다)는 재귀동사이며 이름을 가진 사람이 주어입니다. 이 문장에서 los padres de María가 주어이므로 앞에 전치사를 쓰지 않습니다. 주어가 복수라 se llaman이 되었습니다.","x":["a: 주어 앞에 전치사 a를 쓰지 않습니다 ✗","ø: los padres가 주어 → 정답 ✓","sobre: '~에 대해'라는 뜻이라 문장 구조가 틀립니다 ✗","por: 이유·경로를 나타내 맞지 않습니다 ✗"]},{"id":"G675","q":"¿Cuándo es ____ cumpleaños?","o":["tuyos","tu","los tuyos","tus"],"a":1,"k":"소유형용사 tu","t":"네 생일은 언제야?","e":"소유형용사 단축형은 명사 앞에 오고, 명사의 수에 맞춥니다. cumpleaños는 -s로 끝나지만 단수 명사(el cumpleaños)이며 동사 es도 단수이므로 tu를 씁니다. 복수일 때는 los cumpleaños, tus cumpleaños처럼 형태가 같습니다.","x":["tuyos: 강세형이라 명사 앞에 쓰지 않습니다 ✗","tu: 단수 명사 앞 '너의' → 정답 ✓","los tuyos: 소유대명사(너의 것들)라 명사 앞에 쓰지 않습니다 ✗","tus: 복수형인데 동사 es가 단수라서 ✗"]},{"id":"G676","q":"Gracias por ____ consejos. —De nada.","o":["vuestras","vuestro","su","tus"],"a":3,"k":"소유형용사 tus","t":"충고 고마워. — 천만에.","e":"소유형용사는 소유되는 명사의 성·수에 맞춥니다. consejos(충고)는 남성 복수이므로 tus(너의) 또는 sus(당신의)처럼 복수형을 써야 합니다. 보기 중 복수 명사와 맞는 것은 tus뿐입니다. 'Gracias por + 명사'는 '~해 줘서 고마워'입니다.","x":["vuestras: 여성 복수형이라 남성 명사 consejos와 맞지 않습니다 ✗","vuestro: 단수형이라 ✗","su: 단수형이라 복수 consejos와 맞지 않습니다 ✗","tus: 복수 명사 앞 '너의' → 정답 ✓"]},{"id":"G677","q":"Quiero contarte ____.","o":["nada","algo","algún","alguna"],"a":1,"k":"부정어 algo","t":"너에게 뭔가 이야기하고 싶어.","e":"algo는 '무언가'라는 뜻으로 긍정문에서 정해지지 않은 대상을 가리킵니다. contarte는 contar(이야기하다) + te(너에게)입니다. 반대로 '아무것도 말하고 싶지 않아'는 'No quiero contarte nada.'입니다.","x":["nada: 부정문에 쓰는 말(아무것도)이라 긍정문에 맞지 않습니다 ✗","algo: '무언가' → 정답 ✓","algún: 남성 명사 앞에 쓰는 형용사라 혼자 쓸 수 없습니다 ✗","alguna: 여성 명사를 꾸미거나 대신하는 말이라 ✗"]},{"id":"G678","q":"Voy a tomarme una pastilla ____ el dolor de cabeza.","o":["hacia","para","desde","con"],"a":1,"k":"목적의 para","t":"나는 두통 때문에(두통약으로) 알약을 하나 먹을 것이다.","e":"para는 목적·용도(~을 위해, ~용으로)를 나타냅니다. 약이 무엇에 쓰이는지 말할 때 'una pastilla para el dolor de cabeza(두통약)'라고 합니다. 예: un jarabe para la tos(기침 시럽).","x":["hacia: '~쪽으로'라는 방향이라 ✗","para: 용도·목적 → 정답 ✓","desde: '~부터'라는 출발점이라 ✗","con: '~와 함께'라 '두통과 함께 먹는다'가 되어 어색합니다 ✗"]},{"id":"G679","q":"Mis cuadernos están ____ esa estantería.","o":["a la","a","en la","en"],"a":3,"k":"위치의 en","t":"내 공책들은 그 책장에 있다.","e":"사물이 어떤 장소 '안에/위에' 있을 때는 전치사 en을 씁니다. 뒤에 지시형용사 esa가 있으므로 관사 la를 겹쳐 쓰지 않습니다. 'en esa estantería(그 책장에)'가 됩니다.","x":["a la: a는 방향이고, esa와 관사가 중복됩니다 ✗","a: a는 방향(~로)을 나타내 위치에 쓰지 않습니다 ✗","en la: esa가 이미 있어서 관사 la가 중복됩니다 ✗","en: 장소 안의 위치 → 정답 ✓"]},{"id":"G680","q":"Jalisco es un estado ____ mexicano.","o":["a","ø","desde","de"],"a":1,"k":"형용사 직접 수식","t":"할리스코는 멕시코의 한 주다.","e":"mexicano(멕시코의)는 형용사이므로 명사 estado 바로 뒤에 붙여 꾸밉니다. 전치사는 필요 없습니다. 만약 나라 이름을 쓴다면 'un estado de México'처럼 de가 필요합니다.","x":["a: 형용사 앞에 전치사를 쓰지 않습니다 ✗","ø: 형용사가 명사를 바로 꾸밈 → 정답 ✓","desde: '~부터'라는 뜻이라 ✗","de: 'de México'처럼 명사 앞에는 쓰지만 형용사 앞에는 쓰지 않습니다 ✗"]},{"id":"G681","q":"____ verano fue maravilloso.","o":["Aquella","Aquel","Aquellos","Aquello"],"a":1,"k":"지시형용사 aquel","t":"그 여름은 정말 멋졌다.","e":"aquel(저/그)은 말하는 사람에게서 멀거나 오래전의 것을 가리킵니다. 과거(fue)의 여름을 회상하는 문장이므로 aquel이 자연스럽습니다. verano(여름)는 남성 단수이므로 aquel을 씁니다(여성 aquella, 복수 aquellos/aquellas).","x":["Aquella: 여성형이라 남성 명사 verano와 맞지 않습니다 ✗","Aquel: 남성 단수 지시형용사 → 정답 ✓","Aquellos: 복수형이라 ✗","Aquello: 중성 대명사(저것)라 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G682","q":"Voy a lavarme ____ manos.","o":["las","mis","unas","ø"],"a":0,"k":"신체 부위 + 정관사","t":"나는 손을 씻을 것이다.","e":"재귀동사(lavarse)와 함께 신체 부위를 말할 때는 소유형용사 대신 정관사를 씁니다. lavarme의 me가 이미 '내 손'임을 알려 주기 때문입니다. manos는 -o로 끝나는 mano의 복수지만 여성 명사이므로 las를 씁니다.","x":["las: 여성 복수 정관사 → 정답 ✓","mis: 재귀동사로 소유가 이미 드러나서 쓰지 않습니다 ✗","unas: '몇몇 손'이 되어 어색합니다 ✗","ø: 신체 부위 앞에는 관사가 필요합니다 ✗"]},{"id":"G683","q":"Cada día ____ las noticias mientras desayuno.","o":["estoy escuchando","escuchar","escuchando","escucho"],"a":3,"k":"습관의 현재형","t":"나는 매일 아침을 먹으면서 뉴스를 듣는다.","e":"Cada día(매일)처럼 습관이나 반복되는 일을 말할 때는 단순 현재형을 씁니다. 주어가 '나'이므로 escuchar의 1인칭 escucho가 됩니다. 진행형(estoy escuchando)은 '지금 하고 있는 일'에 써서 습관 표현과 어울리지 않습니다.","x":["estoy escuchando: 지금 진행 중인 일에 써서 습관 표현에 맞지 않습니다 ✗","escuchar: 동사원형이라 활용이 필요합니다 ✗","escuchando: 현재분사만으로는 문장의 동사가 될 수 없습니다 ✗","escucho: 1인칭 현재, 습관 → 정답 ✓"]},{"id":"G684","q":"Daniel es un chico ____ sociable.","o":["bastante","bastantes de","bastante de","bastantes"],"a":0,"k":"bastante 부사","t":"다니엘은 꽤 사교적인 남자아이다.","e":"bastante가 형용사(sociable) 앞에서 '꽤'라는 부사로 쓰일 때는 형태가 변하지 않습니다. 명사 앞에서 '충분한'이라는 형용사로 쓰일 때만 복수 bastantes가 됩니다. 예: bastantes amigos(꽤 많은 친구들).","x":["bastante: 형용사를 꾸미는 부사(꽤) → 정답 ✓","bastantes de: 복수형이고 de가 붙어 틀립니다 ✗","bastante de: 형용사 앞에 de를 쓰지 않습니다 ✗","bastantes: 부사로 쓰일 때는 복수형이 없습니다 ✗"]},{"id":"G685","q":"Celia es ____ abogada.","o":["un","una","ø","unas"],"a":2,"k":"직업 앞 관사 생략","t":"셀리아는 변호사다.","e":"ser 뒤에 직업 명사만 올 때는 관사를 쓰지 않습니다. 그래서 'Celia es abogada.'가 됩니다. 형용사가 붙으면 관사를 씁니다: Celia es una abogada excelente.(셀리아는 뛰어난 변호사다.)","x":["un: 남성형이고, 직업 앞에는 관사가 필요 없습니다 ✗","una: 꾸미는 말이 없는 직업 앞에는 쓰지 않습니다 ✗","ø: 직업 앞 관사 생략 → 정답 ✓","unas: 복수형이라 ✗"]},{"id":"G686","q":"____ clima del sur de España es muy diferente al del norte.","o":["El","Los","La","Las"],"a":0,"k":"정관사 el","t":"스페인 남부의 기후는 북부의 기후와 많이 다르다.","e":"clima(기후)는 -a로 끝나지만 남성 명사입니다(그리스어에서 온 -ma 단어: el problema, el tema, el clima). 특정 지역의 기후이므로 정관사 el을 씁니다. 뒤의 'al del norte'는 'al clima del norte'의 줄임입니다.","x":["El: 남성 단수 정관사 → 정답 ✓","Los: 복수형이라 ✗","La: clima는 -a로 끝나지만 남성 명사라서 ✗","Las: 여성 복수형이라 ✗"]},{"id":"G687","q":"¿Cuál es tu color ____?","o":["favoritos","favorito","favorita","favoritas"],"a":1,"k":"형용사 일치","t":"네가 가장 좋아하는 색은 뭐니?","e":"형용사 favorito(가장 좋아하는)는 꾸미는 명사의 성·수에 맞춥니다. color(색)는 남성 단수 명사이므로 favorito가 됩니다. 예: mi comida favorita(내가 좋아하는 음식).","x":["favoritos: 남성 복수형이라 ✗","favorito: 남성 단수형 → 정답 ✓","favorita: 여성형인데 color는 남성이라 ✗","favoritas: 여성 복수형이라 ✗"]},{"id":"G688","q":"Este es ____ libro que leí en inglés.","o":["el primero","lo primero","el primer","primero"],"a":2,"k":"primer 탈락형","t":"이것은 내가 영어로 읽은 첫 번째 책이다.","e":"primero는 남성 단수 명사 앞에서 o가 떨어져 primer가 됩니다. libro(책)는 남성 단수이고 특정한 책이므로 'el primer libro(첫 번째 책)'가 됩니다. 명사 없이 쓸 때는 'Es el primero.(그게 첫 번째다.)'처럼 primero를 씁니다.","x":["el primero: 명사 앞에서는 primer로 줄여야 합니다 ✗","lo primero: '첫 번째 일/것'이라는 중성 표현이라 명사 앞에 쓰지 않습니다 ✗","el primer: 남성 단수 명사 앞 → 정답 ✓","primero: 관사가 없고 줄임형도 아니라 ✗"]},{"id":"G689","q":"Los Fernández ____ pasar sus vacaciones en lugares exóticos.","o":["preferimos","prefiero","prefieren","preferid"],"a":2,"k":"preferir 현재","t":"페르난데스 가족은 이국적인 곳에서 휴가를 보내는 것을 선호한다.","e":"'Los + 성씨'는 '~네 가족'이라는 뜻으로 3인칭 복수(ellos)입니다. preferir(선호하다)는 e가 ie로 바뀌어 prefieren이 됩니다. 소유형용사 sus(그들의)도 3인칭임을 알려 줍니다. 성씨는 복수가 되어도 형태가 변하지 않습니다(los Fernández).","x":["preferimos: nosotros(우리)형이라 ✗","prefiero: 1인칭 단수(나)형이라 ✗","prefieren: 3인칭 복수형 → 정답 ✓","preferid: vosotros 명령형이라 ✗"]},{"id":"G690","q":"El carro de Alberto es ____ bonito.","o":["mucha","muchas","muy","mucho"],"a":2,"k":"muy + 형용사","t":"알베르토의 차는 아주 예쁘다.","e":"형용사(bonito) 앞에서 '아주, 매우'는 muy를 씁니다. muy는 형태가 변하지 않습니다. mucho는 동사 뒤(Trabaja mucho.)나 명사 앞(mucho dinero)에 씁니다.","x":["mucha: 여성 단수 형용사라 형용사 앞에 쓸 수 없습니다 ✗","muchas: 여성 복수형이라 ✗","muy: 형용사 앞 '아주' → 정답 ✓","mucho: 형용사 앞에는 muy를 씁니다 ✗"]},{"id":"G691","q":"En esa ciudad hay ____ catedral impresionante.","o":["una","la","ø","un"],"a":0,"k":"hay + 부정관사","t":"그 도시에는 인상적인 대성당이 하나 있다.","e":"hay(있다)는 불특정한 대상의 존재를 말하므로 정관사(el, la)와 함께 쓰지 않고 부정관사나 수량 표현과 함께 씁니다. catedral(대성당)은 여성 명사이므로 una를 씁니다. 예: Hay un museo en el centro.(시내에 박물관이 하나 있다.)","x":["una: 여성 부정관사, hay와 함께 → 정답 ✓","la: hay 뒤에는 정관사를 쓰지 않습니다 ✗","ø: 단수 가산명사 앞에는 관사가 필요합니다 ✗","un: 남성형이라 여성 명사 catedral과 맞지 않습니다 ✗"]},{"id":"G692","q":"Yo no tengo ____ paciencia como vos.","o":["más","tanta","tan","menos"],"a":1,"k":"동등비교 tanto como","t":"나는 너만큼 인내심이 많지 않아.","e":"'~만큼 많은 + 명사'는 'tanto/tanta/tantos/tantas + 명사 + como'로 말합니다. paciencia(인내심)는 여성 단수이므로 tanta가 됩니다. 형용사·부사 앞에서는 tan을 씁니다(tan alto como). vos는 아르헨티나·우루과이 등에서 tú 대신 쓰는 2인칭입니다.","x":["más: 우등비교에는 que를 써야 하는데 문장에 como가 있어서 ✗","tanta: 여성 단수 명사 + como → 정답 ✓","tan: 형용사·부사 앞에 쓰고 명사 앞에는 쓰지 않습니다 ✗","menos: 열등비교는 que와 짝을 이루므로 como와 맞지 않습니다 ✗"]},{"id":"G693","q":"Los anteojos siempre ____ guardo en el cajón de la mesilla.","o":["los","las","ø","les"],"a":0,"k":"목적어 중복 los","t":"나는 안경을 항상 침대 옆 탁자 서랍에 보관한다.","e":"직접목적어(los anteojos)를 동사보다 앞에 두면, 동사 앞에 같은 것을 가리키는 대명사를 한 번 더 써야 합니다. anteojos(안경)는 남성 복수이므로 los가 됩니다. anteojos는 중남미에서 많이 쓰는 말로, 스페인에서는 gafas라고 합니다.","x":["los: 남성 복수 직접목적격(그것들을) → 정답 ✓","las: 여성형인데 anteojos는 남성이라 ✗","ø: 목적어가 앞에 나오면 대명사를 반드시 반복합니다 ✗","les: 간접목적격(그들에게)이라 ✗"]},{"id":"G694","q":"Hoy tengo que trabajar ____ once de la noche.","o":["hasta las","hasta","hasta la","hasta los"],"a":0,"k":"hasta las + 시각","t":"오늘 나는 밤 11시까지 일해야 한다.","e":"'~시까지'는 'hasta + 정관사 + 시각'으로 말합니다. 11시는 복수이므로 las를 써서 'hasta las once'가 됩니다. 1시만 단수라 'hasta la una'입니다.","x":["hasta las: 복수 시각 앞 → 정답 ✓","hasta: 시각 앞에는 정관사가 필요합니다 ✗","hasta la: 1시에만 쓰는 단수형이라 ✗","hasta los: 남성형이라 시각에 쓰지 않습니다 ✗"]},{"id":"G695","q":"El colegio de mi hija ____ a dos minutos a pie de nuestra casa.","o":["están","es","son","está"],"a":3,"k":"estar 위치","t":"내 딸의 학교는 우리 집에서 걸어서 2분 거리에 있다.","e":"특정한 장소(el colegio)의 위치나 거리를 말할 때는 estar를 씁니다. 주어가 3인칭 단수이므로 está가 됩니다. 'estar a + 거리/시간 + de'는 '~에서 ~만큼 떨어져 있다'이고, a pie는 '걸어서'라는 뜻입니다.","x":["están: 3인칭 복수형인데 주어는 el colegio(단수)라서 ✗","es: ser는 장소의 위치에 쓰지 않습니다 ✗","son: ser의 복수형이라 ✗","está: estar 3인칭 단수, 위치 → 정답 ✓"]},{"id":"G696","q":"Necesito que me escuchéis ____ atención.","o":["de","en","sobre","con"],"a":3,"k":"con atención","t":"너희가 내 말을 주의 깊게 들어 주면 좋겠어.","e":"'con + 명사'는 '~을 가지고, ~하게'라는 방식(부사 역할)을 나타냅니다. con atención은 '주의 깊게'라는 뜻입니다. 예: con cuidado(조심해서), con prisa(급하게). escuchéis는 접속법(바람·요청을 나타내는 동사 형태)의 vosotros형입니다.","x":["de: 방식을 나타내는 이 표현에 쓰지 않습니다 ✗","en: 'en atención a(~을 고려해)'는 다른 뜻이라 ✗","sobre: '~에 대해'라는 뜻이라 ✗","con: 방식 '~하게' → 정답 ✓"]},{"id":"G697","q":"¿____ es tu película española favorita?","o":["Cuál","Qué","Quién","Dónde"],"a":0,"k":"cuál vs qué","t":"네가 가장 좋아하는 스페인 영화는 뭐야?","e":"동사 ser 앞에서 여러 가지 중 하나를 고르게 할 때는 cuál을 씁니다. 한국어로는 '무엇'이지만 '¿Cuál es tu...favorito/a?'가 정해진 표현입니다. '¿Qué es...?'는 '~이 무엇(정의)이냐'를 묻는 말입니다.","x":["Cuál: ser 앞, 여럿 중 선택 → 정답 ✓","Qué: ser 앞에서는 정의를 묻는 뜻이 되어 ✗","Quién: '누구'라는 뜻이라 ✗","Dónde: '어디'라는 뜻이라 ✗"]},{"id":"G698","q":"¿Puedes hacerme ____ favor?","o":["un","unas","una","unos"],"a":0,"k":"hacer un favor","t":"부탁 하나 들어줄 수 있어?","e":"'hacer un favor(부탁을 들어주다)'는 자주 쓰는 표현입니다. favor는 남성 단수 명사이므로 부정관사 un을 씁니다. 'Hazme un favor.(부탁 하나만 들어줘.)'처럼도 씁니다.","x":["un: 남성 단수 부정관사 → 정답 ✓","unas: 여성 복수형이라 ✗","una: 여성형인데 favor는 남성이라 ✗","unos: 복수형이라 ✗"]},{"id":"G699","q":"____ madre de Eugenio es francesa.","o":["Una","Ella","El","La"],"a":3,"k":"정관사 la","t":"에우헤니오의 어머니는 프랑스인이다.","e":"'de Eugenio(에우헤니오의)'로 어떤 어머니인지 특정되므로 정관사를 씁니다. madre(어머니)는 여성 단수이므로 la가 됩니다. 소유형용사를 쓰면 'Su madre es francesa.'라고 할 수도 있습니다.","x":["Una: 사람마다 어머니는 한 명이므로 특정한 대상에 쓰는 정관사가 맞습니다 ✗","Ella: 주격 대명사(그녀)는 명사 앞에 올 수 없습니다 ✗","El: 남성 관사라 ✗","La: 여성 단수 정관사 → 정답 ✓"]},{"id":"G700","q":"Señor Jiménez, esta carta es ____ usted.","o":["desde","por","a","para"],"a":3,"k":"수신의 para","t":"히메네스 씨, 이 편지는 당신 앞으로 온 것입니다.","e":"para는 '~을 위한, ~에게 줄'이라는 수신자·대상을 나타냅니다. 선물이나 편지가 누구 것인지 말할 때 'ser para + 사람'을 씁니다. 예: Este regalo es para ti.(이 선물은 너를 위한 거야.)","x":["desde: '~부터'라는 출발점이라 ✗","por: 'por usted'는 '당신 때문에/당신에 의해'라는 뜻이 되어 ✗","a: ser 뒤에서 수신자를 나타낼 때는 쓰지 않습니다 ✗","para: 수신자 '~에게 (줄)' → 정답 ✓"]},{"id":"G701","q":"Esos señores son ____.","o":["japonés","japonesa","japoneses","japonesas"],"a":2,"k":"국적 형용사 일치","t":"그 신사분들은 일본인이다.","e":"국적 형용사는 주어의 성·수에 맞춥니다. esos señores(그 신사들)는 남성 복수이므로 japoneses가 됩니다. 자음으로 끝나는 국적 형용사는 복수에 -es를 붙이고, 이때 악센트가 사라집니다(japonés → japoneses).","x":["japonés: 남성 단수형이라 ✗","japonesa: 여성 단수형이라 ✗","japoneses: 남성 복수형 → 정답 ✓","japonesas: 여성 복수형이라 ✗"]},{"id":"G702","q":"____ jefe es muy amable con nosotros.","o":["Nuestros","Nos","Nosotros","Nuestro"],"a":3,"k":"소유형용사 nuestro","t":"우리 사장님은 우리에게 아주 친절하다.","e":"소유형용사 nuestro(우리의)는 소유되는 명사의 성·수에 맞춥니다. jefe(상사)는 남성 단수이므로 nuestro가 됩니다. 여성 상사라면 nuestra jefa, 복수라면 nuestros jefes입니다.","x":["Nuestros: 복수형이라 단수 jefe와 맞지 않습니다 ✗","Nos: 목적격 대명사(우리를/우리에게)라 명사 앞에 쓰지 않습니다 ✗","Nosotros: 주격 대명사(우리)라 명사 앞에 쓰지 않습니다 ✗","Nuestro: 남성 단수 '우리의' → 정답 ✓"]},{"id":"G703","q":"____ esa casa viven seis personas.","o":["A","En","Por","Para"],"a":1,"k":"장소의 en","t":"그 집에는 여섯 명이 산다.","e":"사는 장소를 말할 때는 'vivir en + 장소'로 전치사 en을 씁니다. 장소를 문장 앞에 꺼내도 전치사 en은 그대로 붙어 있습니다. 예: Vivo en Seúl.(나는 서울에 산다.)","x":["A: a는 방향(~로)이라 사는 장소에 쓰지 않습니다 ✗","En: 장소 안 '~에' → 정답 ✓","Por: '~근처/~를 지나'라는 뜻이라 ✗","Para: '~을 위해'라는 뜻이라 ✗"]},{"id":"G704","q":"____ cansados porque trabajan muchas horas.","o":["Son","Es","Está","Están"],"a":3,"k":"estar 상태","t":"그들은 오랜 시간 일하기 때문에 피곤하다.","e":"cansado(피곤한)처럼 일시적인 몸·기분 상태에는 estar를 씁니다. 형용사 cansados와 뒤 동사 trabajan이 3인칭 복수이므로 están이 됩니다. 이렇게 주어(ellos)는 생략되는 경우가 많습니다.","x":["Son: ser는 일시적 상태에 쓰지 않습니다 ✗","Es: ser 단수형이고 상태 표현에 맞지 않습니다 ✗","Está: 단수형이라 복수 cansados와 맞지 않습니다 ✗","Están: estar 3인칭 복수, 상태 → 정답 ✓"]},{"id":"G705","q":"¿Conocéis al esposo de Andrea? —Sí, ____ conocemos.","o":["las","los","la","lo"],"a":3,"k":"직접목적격 lo","t":"안드레아의 남편을 아니? — 응, 우리 그를 알아.","e":"앞에 나온 사람(el esposo de Andrea)을 '그를'로 받을 때는 직접목적격 대명사를 씁니다. 남성 단수이므로 lo가 됩니다. 스페인 일부 지역에서는 남자 사람에게 le를 쓰기도 합니다(레이스모). conocéis는 vosotros형으로 스페인에서 주로 씁니다.","x":["las: 여성 복수형이라 ✗","los: 복수형이라 한 사람을 받을 수 없습니다 ✗","la: 여성형이라 esposo와 맞지 않습니다 ✗","lo: 남성 단수 직접목적격(그를) → 정답 ✓"]},{"id":"G706","q":"Inma ____ muy tarde esta mañana.","o":["se ha levantado","he levantado","ha levantado","me he levantado"],"a":0,"k":"재귀동사 현재완료","t":"인마는 오늘 아침 아주 늦게 일어났다.","e":"levantarse(일어나다)는 재귀동사이므로 재귀대명사가 꼭 필요합니다. 주어 Inma는 3인칭 단수라 재귀대명사 se, 조동사 ha를 써서 'se ha levantado'가 됩니다. esta mañana(오늘 아침)처럼 아직 끝나지 않은 시간에는 스페인에서 현재완료를 즐겨 씁니다.","x":["se ha levantado: 3인칭 재귀 현재완료 → 정답 ✓","he levantado: 1인칭이고 재귀대명사도 없어 ✗","ha levantado: 재귀대명사 se가 없어 '~을 들어 올렸다'가 됩니다 ✗","me he levantado: 1인칭(나는)이라 주어 Inma와 맞지 않습니다 ✗"]},{"id":"G707","q":"La única cafetería del barrio está en ____ plaza.","o":["esas","ø","ese","la"],"a":3,"k":"정관사 la","t":"동네의 유일한 카페는 광장에 있다.","e":"plaza(광장)는 여성 단수 명사이며, 동네에서 누구나 아는 광장을 가리키므로 정관사 la를 씁니다. 'en la plaza(광장에)'가 됩니다. 지시형용사를 쓰려면 esa처럼 단수 여성형이어야 합니다.","x":["esas: 복수형이라 단수 plaza와 맞지 않습니다 ✗","ø: 단수 가산명사 앞에는 관사가 필요합니다 ✗","ese: 남성형이라 ✗","la: 여성 단수 정관사 → 정답 ✓"]},{"id":"G708","q":"____ verano viajo a regiones frías porque no me gusta el calor.","o":["A","En","De","Por"],"a":1,"k":"계절 앞 en","t":"나는 더위를 좋아하지 않아서 여름에는 추운 지역으로 여행한다.","e":"계절이나 달 앞에서 '~에'는 전치사 en을 씁니다. 'en verano(여름에)', 'en invierno(겨울에)', 'en enero(1월에)'처럼 관사 없이 씁니다. 'en el verano'라고 할 수도 있습니다.","x":["A: 계절 앞에 a를 쓰지 않습니다 ✗","En: 계절 앞 '~에' → 정답 ✓","De: '~의/~부터'라는 뜻이라 ✗","Por: 'por el verano(여름 무렵)'처럼 관사가 필요하고 뜻도 달라 ✗"]},{"id":"G709","q":"Agradezco mucho ____ su paciencia.","o":["en","de","a","ø"],"a":3,"k":"agradecer 타동사","t":"당신의 인내에 깊이 감사드립니다.","e":"agradecer(~에 감사하다)는 감사하는 대상을 전치사 없이 바로 직접목적어로 받습니다. 그래서 'Agradezco su paciencia.'가 됩니다. 한국어 '~에 감사하다' 때문에 전치사를 넣지 않도록 주의하세요. 'Gracias por su paciencia.'는 gracias 뒤라서 por를 씁니다.","x":["en: agradecer는 전치사를 쓰지 않습니다 ✗","de: 'agradecer de'는 쓰지 않습니다 ✗","a: 사람 앞에서는 a를 쓰지만 su paciencia는 사물이라 ✗","ø: 직접목적어를 바로 받음 → 정답 ✓"]},{"id":"G710","q":"No somos argentinos, ____ uruguayos.","o":["sino","pero","o","y"],"a":0,"k":"no...sino","t":"우리는 아르헨티나 사람이 아니라 우루과이 사람이다.","e":"'no A sino B'는 'A가 아니라 B'라고 앞의 내용을 바로잡을 때 씁니다. 앞 문장이 부정문이고 뒤가 그것을 대신하는 내용이므로 sino가 맞습니다. pero는 '하지만'으로 덧붙이는 말이라 바로잡는 뜻이 없습니다.","x":["sino: 부정 후 정정 'A가 아니라 B' → 정답 ✓","pero: '하지만'이라 정정의 의미가 없습니다 ✗","o: '또는'이라 ✗","y: '그리고'라 ✗"]},{"id":"G711","q":"Ese carro es carísimo, no puedo ____.","o":["comprar lo","comprar él","lo comprar","comprarlo"],"a":3,"k":"동사원형 + 대명사","t":"그 차는 너무 비싸서 나는 그것을 살 수 없다.","e":"동사원형 뒤에 목적격 대명사를 붙일 때는 띄어 쓰지 않고 한 단어로 씁니다: comprar + lo = comprarlo. 대명사를 앞으로 보내 'no lo puedo comprar'라고 해도 됩니다. carro(차)는 남성 단수라 lo를 씁니다.","x":["comprar lo: 대명사는 동사원형에 붙여 써야 합니다 ✗","comprar él: 주격 대명사 él은 목적어가 될 수 없습니다 ✗","lo comprar: 대명사가 동사원형 바로 앞에 올 수 없습니다 ✗","comprarlo: 동사원형 + lo 붙여 쓰기 → 정답 ✓"]},{"id":"G712","q":"Esta tarde vamos ____ playa.","o":["al","a la","a","la"],"a":1,"k":"방향 a + 관사","t":"오늘 오후에 우리는 해변에 간다.","e":"ir a(~에 가다) 뒤에 특정 장소가 오면 관사를 씁니다. playa(해변)는 여성 명사이므로 'a la playa'가 됩니다. 남성 명사일 때는 a + el = al로 줄여 씁니다(al cine).","x":["al: a + el(남성)이라 여성 명사 playa와 맞지 않습니다 ✗","a la: 여성 명사 앞 방향 → 정답 ✓","a: 관사가 빠져서 틀립니다 ✗","la: 방향의 전치사 a가 없어 틀립니다 ✗"]},{"id":"G713","q":"Los niños están jugando ____ parque.","o":["a la","al","en el","en la"],"a":2,"k":"장소의 en","t":"아이들은 공원에서 놀고 있다.","e":"어떤 장소에서 활동할 때 '~에서'는 en을 씁니다. parque(공원)는 남성 명사이므로 'en el parque'가 됩니다. a는 이동 방향(~로)에 쓰므로 jugar와 어울리지 않습니다.","x":["a la: 방향이고 여성형이라 ✗","al: 방향(~로)이라 노는 장소에는 쓰지 않습니다 ✗","en el: 남성 명사 장소 '~에서' → 정답 ✓","en la: 여성형이라 남성 명사 parque와 맞지 않습니다 ✗"]},{"id":"G714","q":"Mi vuelo llega a las seis menos ____ de la mañana.","o":["cuarto","los cuartos","el cuarto","cuartos"],"a":0,"k":"시각 menos cuarto","t":"내 비행기는 오전 6시 15분 전(5시 45분)에 도착한다.","e":"'~시 15분 전'은 '시각 + menos cuarto'로 말하며 cuarto 앞에 관사를 쓰지 않습니다. '15분'은 'y cuarto', '30분'은 'y media'입니다. 예: Son las dos y cuarto.(2시 15분이다.)","x":["cuarto: 관사 없이 '15분' → 정답 ✓","los cuartos: 시각 표현에 관사와 복수를 쓰지 않습니다 ✗","el cuarto: 시각 표현에서는 관사를 붙이지 않습니다 ✗","cuartos: 복수형을 쓰지 않습니다 ✗"]},{"id":"G715","q":"Los chicos están ____ parque de atracciones.","o":["en el","a","al","a la"],"a":0,"k":"장소의 en","t":"아이들은 놀이공원에 있다.","e":"estar(있다)로 위치를 말할 때는 'en + 장소'를 씁니다. parque de atracciones(놀이공원)는 남성 명사이므로 'en el'이 됩니다. a(~로)는 ir 같은 이동 동사와 씁니다.","x":["en el: estar와 함께 위치 → 정답 ✓","a: 이동 방향이라 estar와 맞지 않고 관사도 없습니다 ✗","al: 이동 방향(~로)이라 estar와 맞지 않습니다 ✗","a la: 방향이고 여성형이라 ✗"]},{"id":"G716","q":"En esta parte de la ciudad se vive muy ____.","o":["bien","buen","bueno","buena"],"a":0,"k":"bien vs bueno","t":"이 도시의 이 지역에서는 아주 살기 좋다.","e":"동사(vivir)를 꾸며 '잘'이라고 할 때는 부사 bien을 씁니다. bueno는 명사를 꾸미는 형용사라서 동사를 꾸미지 못합니다. 'se vive bien'은 무인칭 se 구문으로 '(사람들이) 잘 산다, 살기 좋다'라는 뜻입니다.","x":["bien: 동사를 꾸미는 부사 '잘' → 정답 ✓","buen: 남성 단수 명사 앞에 쓰는 형용사라 ✗","bueno: 형용사라 동사를 꾸밀 수 없습니다 ✗","buena: 여성 형용사라 ✗"]},{"id":"G717","q":"Fuimos a una cafetería ____ la conferencia.","o":["mientras","antes","después de","después"],"a":2,"k":"después de","t":"우리는 강연이 끝난 후에 카페에 갔다.","e":"'~후에'는 'después de + 명사/동사원형'으로 말합니다. después 혼자는 부사(나중에)라서 명사 앞에서는 de가 필요합니다. 반대말은 antes de(~전에)입니다.","x":["mientras: '~하는 동안'이라 뒤에 문장이 와야 하고 명사 앞에 바로 쓰지 않습니다 ✗","antes: 명사 앞에서는 antes de가 되어야 합니다 ✗","después de: '~후에' → 정답 ✓","después: 명사 앞에서는 de가 필요합니다 ✗"]},{"id":"G718","q":"En esa joyería ____ es carísimo.","o":["todas","toda","todo","todos"],"a":2,"k":"중성 todo","t":"그 보석 가게에서는 모든 것이 아주 비싸다.","e":"todo가 명사 없이 혼자 쓰이면 '모든 것'이라는 중성 대명사입니다. 이때는 남성 단수 형태 todo를 쓰고, 동사와 형용사도 단수 es carísimo가 됩니다. carísimo는 caro(비싼)의 절대 최상급입니다.","x":["todas: 여성 복수형이라 명사 없이 '모든 것'을 뜻하지 못합니다 ✗","toda: 여성 단수형이라 ✗","todo: '모든 것' 중성 대명사 → 정답 ✓","todos: '모든 사람들'이 되고 동사도 복수여야 합니다 ✗"]},{"id":"G719","q":"¿____ está Santiago de Compostela? —En Galicia.","o":["Cuándo","Qué","Dónde","Por qué"],"a":2,"k":"의문사 dónde","t":"산티아고 데 콤포스텔라는 어디에 있어? — 갈리시아에.","e":"장소의 위치를 물을 때는 '¿Dónde está...?(~은 어디에 있나요?)'를 씁니다. 대답 'En Galicia(갈리시아에)'가 장소이므로 dónde가 맞습니다. 의문사는 항상 악센트를 씁니다.","x":["Cuándo: '언제'라는 뜻이라 ✗","Qué: '무엇'이라는 뜻이라 ✗","Dónde: '어디에' → 정답 ✓","Por qué: '왜'라는 뜻이라 ✗"]},{"id":"G720","q":"No me gusta el café ____ azúcar, lo prefiero dulce.","o":["sin","con","a","por"],"a":0,"k":"전치사 sin","t":"나는 설탕 없는 커피를 좋아하지 않아, 달게 마시는 걸 좋아해.","e":"sin은 '~없이'라는 뜻의 전치사입니다. 뒤 문장 'lo prefiero dulce(달게 먹는 게 좋아)'로 보아 '설탕 없는 커피'가 싫다는 뜻이므로 sin이 맞습니다. 예: café sin azúcar(무설탕 커피), agua sin gas(탄산 없는 물).","x":["sin: '~없이' → 정답 ✓","con: '설탕 넣은 커피'가 싫다는 뜻이 되어 뒤 문장과 모순됩니다 ✗","a: 이 의미로 쓰지 않습니다 ✗","por: 이유를 나타내 맞지 않습니다 ✗"]},{"id":"G721","q":"____ viernes suelo levantarme un poco más tarde.","o":["La","Las","Los","En los"],"a":2,"k":"요일 + 정관사","t":"금요일마다 나는 보통 조금 더 늦게 일어난다.","e":"요일 앞에서 '~요일에'는 전치사 없이 정관사만 씁니다. 반복되는 습관(매주 ~요일마다)은 복수 정관사 los를 써서 'los viernes'라고 합니다. 이번 한 번의 금요일이면 'el viernes'입니다.","x":["La: 여성형이라 요일(남성)에 쓰지 않습니다 ✗","Las: 여성 복수형이라 ✗","Los: 남성 복수 정관사, 반복 습관 → 정답 ✓","En los: 요일 앞에는 전치사 en을 쓰지 않습니다 ✗"]},{"id":"G722","q":"El examen va a comenzar ____ una hora y media.","o":["dentro en","dentro","dentro a","dentro de"],"a":3,"k":"dentro de","t":"시험은 한 시간 반 후에 시작할 것이다.","e":"'지금부터 ~후에'는 'dentro de + 시간'으로 말합니다. dentro 혼자는 '안에'라는 부사라서 명사 앞에서는 de가 필요합니다. 예: Vuelvo dentro de diez minutos.(10분 후에 돌아올게.)","x":["dentro en: dentro는 en과 함께 쓰지 않습니다 ✗","dentro: 시간 명사 앞에서는 de가 필요합니다 ✗","dentro a: dentro는 a와 함께 쓰지 않습니다 ✗","dentro de: '~후에' → 정답 ✓"]},{"id":"G723","q":"Mañana tenemos ____ despertarnos pronto.","o":["que","a","como","de"],"a":0,"k":"tener que","t":"내일 우리는 일찍 일어나야 한다.","e":"'tener que + 동사원형'은 '~해야 한다'는 의무 표현입니다. tener와 동사원형 사이에는 que가 들어갑니다. pronto는 스페인에서 '일찍'이라는 뜻으로 자주 쓰이며 중남미에서는 temprano를 더 많이 씁니다.","x":["que: tener que + 동사원형 '~해야 한다' → 정답 ✓","a: tener a는 이런 의미로 쓰지 않습니다 ✗","como: '~처럼'이라는 뜻이라 ✗","de: 'tener de'는 쓰지 않는 표현입니다 ✗"]},{"id":"G724","q":"El pasado fin ____ semana estuve en Guadalajara.","o":["de","ø","del","de la"],"a":0,"k":"fin de semana","t":"지난 주말에 나는 과달라하라에 있었다.","e":"'fin de semana(주말)'는 고정된 표현으로 semana 앞에 관사 없이 de만 씁니다. 그래서 'el pasado fin de semana(지난 주말)'가 됩니다. 'el fin de semana pasado'라고 해도 같은 뜻입니다.","x":["de: fin de semana 고정 표현 → 정답 ✓","ø: de가 없으면 두 명사를 연결할 수 없습니다 ✗","del: 관사가 들어가지 않는 표현이고 semana는 여성이라 ✗","de la: 고정 표현에는 관사를 넣지 않습니다 ✗"]},{"id":"G725","q":"____ lenguas es mi pasión.","o":["Aprendido","Aprendiendo","Aprendo","Aprender"],"a":3,"k":"동사원형 주어","t":"언어를 배우는 것은 나의 열정이다.","e":"'~하는 것'처럼 동사가 문장의 주어가 될 때는 동사원형을 씁니다. Aprender lenguas(언어를 배우는 것)가 주어이고 단수 취급하므로 동사는 es입니다. 영어처럼 -ing(현재분사)를 주어로 쓰지 않는 점에 주의하세요.","x":["Aprendido: 과거분사(배운)라 주어가 될 수 없습니다 ✗","Aprendiendo: 현재분사(배우면서)는 주어로 쓰지 않습니다 ✗","Aprendo: 활용된 동사(나는 배운다)라 주어가 될 수 없습니다 ✗","Aprender: 동사원형 '배우는 것' → 정답 ✓"]},{"id":"G726","q":"Amalia es ____ que Rodrigo; nació tres años antes.","o":["menor","mayor","mejor","peor"],"a":1,"k":"mayor/menor","t":"아말리아는 로드리고보다 나이가 많다. 3년 먼저 태어났다.","e":"나이를 비교할 때 '더 나이가 많은'은 mayor, '더 어린'은 menor를 씁니다. 3년 먼저 태어났으니 나이가 더 많은 mayor가 맞습니다. mejor(더 좋은)와 peor(더 나쁜)는 질을 비교하는 말입니다.","x":["menor: '더 어린'이라 3년 먼저 태어났다는 말과 반대입니다 ✗","mayor: '나이가 더 많은' → 정답 ✓","mejor: '더 좋은'이라 나이와 관계없습니다 ✗","peor: '더 나쁜'이라 나이와 관계없습니다 ✗"]},{"id":"G727","q":"¿Quién es la persona ____ más divertida de tu clase?","o":["la","ø","una","ella"],"a":1,"k":"최상급 관사 중복","t":"너희 반에서 가장 재미있는 사람은 누구야?","e":"최상급은 '정관사 + 명사 + más + 형용사'로 만들고 정관사는 한 번만 씁니다. 이미 la persona에 정관사 la가 있으므로 más 앞에 관사를 또 넣지 않습니다. 영어 'the most'처럼 관사를 두 번 쓰지 않도록 주의하세요.","x":["la: 앞에 이미 la가 있어서 중복됩니다 ✗","ø: 관사 + 명사 + más 구조 → 정답 ✓","una: 최상급에 부정관사를 쓰지 않습니다 ✗","ella: 주격 대명사라 이 자리에 올 수 없습니다 ✗"]},{"id":"G728","q":"Yo nunca ____ palabrotas.","o":["decimos","digo","dices","dice"],"a":1,"k":"decir 현재","t":"나는 절대로 욕을 하지 않는다.","e":"decir(말하다)의 1인칭 단수는 불규칙형 digo입니다. 주어 Yo에 맞춰 digo를 씁니다. nunca(절대 ~않다)가 동사 앞에 오면 no 없이 부정문이 됩니다. palabrotas는 '욕, 상스러운 말'이라는 뜻입니다.","x":["decimos: nosotros(우리)형이라 ✗","digo: 1인칭 단수형 → 정답 ✓","dices: 2인칭 단수(너)형이라 ✗","dice: 3인칭 단수형이라 ✗"]},{"id":"G729","q":"¿____ dónde es una bebida típica el pisco?—De Perú y de Chile.","o":["A","En","Por","De"],"a":3,"k":"¿De dónde?","t":"피스코는 어느 나라의 전통 음료야? — 페루와 칠레야.","e":"출신·원산지를 물을 때는 '¿De dónde...?(어디 출신/어디 것)'을 씁니다. 대답이 'De Perú y de Chile'로 de로 시작하므로 질문에도 de가 필요합니다. 예: ¿De dónde eres?(너는 어디 출신이니?)","x":["A: '¿A dónde?'는 '어디로'라는 방향이라 ✗","En: '¿En dónde?'는 '어디에서'라는 위치라 ✗","Por: '¿Por dónde?'는 '어디를 거쳐'라는 경로라 ✗","De: 출신·원산지 '어디의' → 정답 ✓"]},{"id":"G730","q":"¿Has leído ____ último libro de Almudena Grandes?","o":["el","lo","ø","un"],"a":0,"k":"정관사 el","t":"알무데나 그란데스의 최신 책을 읽어 봤니?","e":"último(마지막의, 최신의)처럼 하나로 정해지는 대상 앞에는 정관사를 씁니다. libro는 남성 단수이므로 'el último libro(최신작)'가 됩니다. Almudena Grandes는 스페인의 유명한 소설가입니다.","x":["el: 하나로 특정되는 대상의 정관사 → 정답 ✓","lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗","ø: 단수 가산명사 앞에는 관사가 필요합니다 ✗","un: '마지막'은 하나뿐이라 부정관사가 어울리지 않습니다 ✗"]},{"id":"G731","q":"El documental va a empezar ____ quince minutos.","o":["en","a","hasta","de"],"a":0,"k":"en + 시간","t":"다큐멘터리는 15분 후에 시작할 것이다.","e":"'en + 시간'은 '~후에, ~만에'라는 뜻으로 쓰이며, 특히 중남미와 구어에서 '지금부터 ~후에'라는 의미로 많이 씁니다. 같은 뜻으로 'dentro de quince minutos'도 자주 쓰입니다. 예: Llego en cinco minutos.(5분 후에 도착해.)","x":["en: '~후에' → 정답 ✓","a: 'a los quince minutos'처럼 관사가 있어야 하고 뜻도 달라 ✗","hasta: '~까지'라는 뜻이라 ✗","de: 이 의미로 쓰지 않습니다 ✗"]},{"id":"G732","q":"Manuela tiene ____ gato muy lindo.","o":["uno","un","ø","el"],"a":1,"k":"부정관사 un","t":"마누엘라는 아주 귀여운 고양이를 한 마리 키운다.","e":"tener 뒤에서 처음 소개하는 '(어떤) 하나의 ~'는 부정관사를 씁니다. gato는 남성 단수이므로 un을 씁니다. uno는 명사 없이 혼자 쓸 때의 형태입니다(Tengo uno.). lindo는 중남미에서 '예쁜, 귀여운'이라는 뜻으로 많이 씁니다.","x":["uno: 명사 앞에서는 un으로 줄여야 합니다 ✗","un: 남성 단수 부정관사 → 정답 ✓","ø: muy lindo로 꾸며지는 단수 가산명사 앞에는 관사가 필요합니다 ✗","el: 처음 소개하는 대상에 정관사는 어색합니다 ✗"]},{"id":"G733","q":"A José María ____ conocí en el instituto.","o":["a él","se","ø","lo"],"a":3,"k":"목적어 중복 lo","t":"호세 마리아는 고등학교에서 알게 되었다.","e":"사람 목적어(a José María)를 동사 앞으로 꺼내면 동사 앞에 같은 대상을 받는 직접목적격 대명사를 다시 써야 합니다. José María는 남성 단수이므로 lo를 씁니다. 스페인에서는 남자 사람에게 le를 쓰기도 합니다(레이스모). instituto는 스페인의 중·고등학교를 말합니다.","x":["a él: 목적어가 이미 앞에 있어 중복되고 대명사 자리가 비어 있습니다 ✗","se: 재귀대명사라 '그를'의 뜻이 아닙니다 ✗","ø: 목적어가 앞에 나오면 대명사를 반복해야 합니다 ✗","lo: 남성 단수 직접목적격 → 정답 ✓"]},{"id":"G734","q":"Esos zapatos son muy ____.","o":["viejos","viejas","vieja","viejo"],"a":0,"k":"형용사 성·수 일치","t":"그 신발은 아주 낡았다.","e":"ser 뒤의 형용사는 주어의 성·수에 맞춥니다. zapatos(신발)는 남성 복수이므로 viejos가 됩니다. viejo는 사람에게는 '늙은', 물건에는 '낡은, 오래된'이라는 뜻입니다.","x":["viejos: 남성 복수형 → 정답 ✓","viejas: 여성 복수형이라 ✗","vieja: 여성 단수형이라 ✗","viejo: 단수형이라 복수 zapatos와 맞지 않습니다 ✗"]},{"id":"G735","q":"¿De quién ____ esto?","o":["está","están","es","hay"],"a":2,"k":"소유의 ser de","t":"이건 누구 거야?","e":"'~의 것이다'라는 소유는 'ser de + 사람'으로 나타냅니다. 그래서 '누구의 것이냐'는 '¿De quién es...?'가 됩니다. esto(이것)는 중성 단수라 동사는 es입니다. 예: Es de mi hermana.(내 여동생 거야.)","x":["está: estar는 소유를 나타내지 않습니다 ✗","están: 복수형이고 소유를 나타내지 않습니다 ✗","es: ser de, 소유 → 정답 ✓","hay: 존재를 나타내서 ✗"]},{"id":"G736","q":"Señores, ____ el documento lo antes posible, por favor.","o":["firmen","firmáis","firmas","firmad"],"a":0,"k":"ustedes 명령형","t":"여러분, 가능한 한 빨리 서류에 서명해 주세요.","e":"Señores(여러분)처럼 여러 사람에게 존칭으로 말할 때는 ustedes 명령형을 씁니다. -ar 동사는 어미를 -en으로 바꿔 firmar → firmen이 됩니다. vosotros 명령형 firmad는 친한 사이의 '너희'에게 쓰며 스페인에서만 씁니다.","x":["firmen: ustedes 긍정 명령형 → 정답 ✓","firmáis: vosotros 현재형(너희는 서명한다)이라 명령이 아닙니다 ✗","firmas: tú 현재형이라 ✗","firmad: vosotros 명령형이라 존칭 Señores와 맞지 않습니다 ✗"]},{"id":"G737","q":"Los gatos son más pequeños ____ los tigres.","o":["de","que","a","con"],"a":1,"k":"비교급 más...que","t":"고양이는 호랑이보다 작다.","e":"우등·열등 비교는 'más/menos + 형용사 + que(~보다)'로 만듭니다. 그래서 'más pequeños que los tigres(호랑이보다 작은)'가 됩니다. 숫자 앞에서만 de를 씁니다: más de diez(10개 넘게).","x":["de: 숫자 앞에서만 씁니다 ✗","que: 비교 대상 '~보다' → 정답 ✓","a: 비교 표현에 쓰지 않습니다 ✗","con: '~와 함께'라는 뜻이라 ✗"]},{"id":"G738","q":"Aunque ____ calor, voy a tomarme un café caliente.","o":["hago","haciendo","hacen","hace"],"a":3,"k":"날씨 hacer","t":"덥지만 나는 뜨거운 커피를 한 잔 마실 것이다.","e":"날씨를 말할 때 'hace + calor/frío/sol'처럼 hacer의 3인칭 단수를 씁니다. 날씨 표현에는 주어가 없으므로 항상 hace입니다. aunque는 '~이지만, ~인데도'라는 뜻입니다.","x":["hago: 1인칭(나는 만든다)이라 날씨 표현이 아닙니다 ✗","haciendo: 현재분사만으로는 동사가 될 수 없습니다 ✗","hacen: 3인칭 복수형이라 날씨 표현에 쓰지 않습니다 ✗","hace: 날씨 표현 3인칭 단수 → 정답 ✓"]},{"id":"G739","q":"Nadie sabe ____ es ese hombre que está en el aula.","o":["cuándo","dónde","quién","qué"],"a":2,"k":"간접의문 quién","t":"교실에 있는 그 남자가 누구인지 아무도 모른다.","e":"'누구인지'를 물을 때는 quién을 씁니다. 문장 속에 들어간 간접의문문(saber + 의문사)에서도 의문사는 악센트를 유지합니다. ese hombre(그 남자)가 어떤 사람인지 묻는 내용이므로 quién이 맞습니다.","x":["cuándo: '언제'라는 뜻이라 ✗","dónde: '어디'라는 뜻인데 남자는 이미 교실에 있다고 나와서 ✗","quién: '누구' → 정답 ✓","qué: '무엇'이라 사람에게 쓰면 어색합니다 ✗"]},{"id":"G740","q":"Siempre salgo del trabajo ____ seis y media.","o":["las","en las","a","a las"],"a":3,"k":"a las + 시각","t":"나는 항상 6시 반에 퇴근한다.","e":"'몇 시에'는 'a + 정관사 + 시각'으로 말합니다. 6시는 복수이므로 'a las seis'이고, '반'은 y media를 붙입니다. 예: Ceno a las nueve.(나는 9시에 저녁을 먹는다.)","x":["las: 전치사 a가 빠져서 '~시에'가 되지 않습니다 ✗","en las: 시각 앞에는 en을 쓰지 않습니다 ✗","a: 시각 앞에는 정관사 las가 필요합니다 ✗","a las: '~시에' → 정답 ✓"]},{"id":"G741","q":"Van a operar a mi abuelo ____ 6 de abril.","o":["la","al","en el","el"],"a":3,"k":"날짜 + el","t":"우리 할아버지는 4월 6일에 수술을 받을 것이다.","e":"날짜 앞에서 '~일에'는 전치사 없이 정관사 el만 씁니다. 'el 6 de abril(4월 6일에)'처럼 씁니다. día(날)가 생략된 형태라 남성 관사 el을 씁니다.","x":["la: 여성형이라 날짜에 쓰지 않습니다 ✗","al: 날짜 앞에 a를 쓰지 않습니다 ✗","en el: 날짜 앞에는 전치사 en을 쓰지 않습니다 ✗","el: 날짜 앞 정관사 → 정답 ✓"]},{"id":"G742","q":"Estoy buscando ____ mi reloj. ¿Lo has visto?","o":["ø","a","de","por"],"a":0,"k":"사물 목적어","t":"나는 내 시계를 찾고 있어. 그거 봤니?","e":"buscar(~을 찾다)는 전치사 없이 바로 목적어를 받습니다. 목적어가 사물(mi reloj)이므로 사람 앞에 붙이는 a도 쓰지 않습니다. 사람을 찾을 때는 'Busco a mi hermano.(내 동생을 찾고 있어.)'처럼 a를 씁니다.","x":["ø: 사물 직접목적어라 전치사 없음 → 정답 ✓","a: 사람 목적어 앞에만 쓰는데 reloj는 사물이라 ✗","de: buscar는 de와 쓰지 않습니다 ✗","por: 'buscar por'는 '~근처/~안을 뒤지다'의 뜻이 되어 ✗"]},{"id":"G743","q":"Casi ____ miércoles voy al cine con mi amigo Juan.","o":["todas las","todos los","todas","todos"],"a":1,"k":"todos los + 요일","t":"거의 매주 수요일마다 나는 친구 후안과 영화관에 간다.","e":"'매주 ~요일마다'는 'todos los + 요일 복수'로 말합니다. 요일은 남성 명사라 todos los miércoles가 됩니다. miércoles처럼 -s로 끝나는 요일은 단수·복수 형태가 같습니다.","x":["todas las: 여성형인데 요일은 남성이라 ✗","todos los: 남성 복수 + 관사 → 정답 ✓","todas: 여성형이고 관사도 없어 ✗","todos: 관사 los가 빠져서 틀립니다 ✗"]},{"id":"G744","q":"Nos vemos ____ tarde en la entrada del teatro, ¿de acuerdo?","o":["ese","la","esta","al"],"a":2,"k":"esta tarde","t":"오늘 오후에 극장 입구에서 만나자, 알았지?","e":"'오늘 오후'는 'esta tarde', '오늘 아침'은 'esta mañana', '오늘 밤'은 'esta noche'라고 합니다. tarde(오후)는 여성 명사이므로 지시형용사 esta(이)를 씁니다. 이때 전치사 없이 그대로 씁니다.","x":["ese: 남성형이라 여성 명사 tarde와 맞지 않습니다 ✗","la: 'la tarde'만으로는 '오늘 오후'의 뜻이 되지 않습니다 ✗","esta: '오늘 오후' → 정답 ✓","al: a + el이라 여성 명사 tarde와 맞지 않습니다 ✗"]},{"id":"G745","q":"Papá, ¿para qué sirve ____?","o":["esto","estos","este","esta"],"a":0,"k":"중성 지시대명사","t":"아빠, 이건 뭐에 쓰는 거예요?","e":"이름을 모르는 물건을 가리킬 때는 중성 지시대명사 esto(이것)를 씁니다. 중성형은 명사 없이 혼자 쓰고, 성·수가 없습니다. 예: ¿Qué es esto?(이건 뭐야?) servir para는 '~에 쓰이다'라는 뜻입니다.","x":["esto: 모르는 것을 가리키는 중성 '이것' → 정답 ✓","estos: 복수형이라 동사 sirve와 맞지 않습니다 ✗","este: 남성형으로 이미 알고 있는 남성 명사를 가리킬 때 씁니다 ✗","esta: 여성형으로 이미 알고 있는 여성 명사를 가리킬 때 씁니다 ✗"]},{"id":"G746","q":"____ fin de semana quiero visitar a mis abuelos.","o":["El","En la","Al","La"],"a":0,"k":"시간 + el","t":"이번 주말에 나는 조부모님을 방문하고 싶다.","e":"요일·주말처럼 특정한 때를 말할 때는 전치사 없이 정관사를 씁니다. fin de semana(주말)는 남성 명사이므로 'el fin de semana(이번 주말에)'가 됩니다. visitar a mis abuelos에서 a는 사람 목적어 앞의 a입니다.","x":["El: 남성 정관사로 '이번 주말에' → 정답 ✓","En la: fin은 남성 명사이고 전치사도 필요 없습니다 ✗","Al: 'al fin'은 '마침내'라는 다른 뜻이 되어 ✗","La: 여성형이라 남성 명사 fin과 맞지 않습니다 ✗"]},{"id":"G747","q":"La nueva empleada ____ buena persona.","o":["parece","parezco","se parece","pareces"],"a":0,"k":"parecer","t":"새로 온 직원은 좋은 사람 같다.","e":"parecer는 '~처럼 보이다, ~인 것 같다'라는 뜻입니다. 주어 la nueva empleada는 3인칭 단수이므로 parece가 됩니다. parecerse(재귀형)는 '~와 닮다'라는 다른 뜻입니다. 예: Se parece a su madre.(그녀는 어머니를 닮았다.)","x":["parece: 3인칭 단수 '~처럼 보인다' → 정답 ✓","parezco: 1인칭 단수(나는 ~처럼 보인다)라 ✗","se parece: '~와 닮았다'라는 뜻이고 뒤에 a가 필요합니다 ✗","pareces: 2인칭 단수(너는)형이라 ✗"]},{"id":"G748","q":"Mi esposo no duerme ____.","o":["muy","mucho","muchos","mucha"],"a":1,"k":"부사 mucho","t":"내 남편은 잠을 많이 자지 않는다.","e":"동사(dormir)를 꾸며 '많이'라고 할 때는 부사 mucho를 씁니다. 부사로 쓰일 때는 형태가 변하지 않습니다. muy는 형용사·부사 앞에서만 씁니다(muy bien).","x":["muy: 형용사·부사 앞에서만 쓰고 동사를 꾸미지 못합니다 ✗","mucho: 동사를 꾸미는 부사 '많이' → 정답 ✓","muchos: 명사 앞에 쓰는 복수 형용사라 ✗","mucha: 명사 앞에 쓰는 여성 형용사라 ✗"]},{"id":"G749","q":"Mi maleta ____ la morada.","o":["ha","es","está","hay"],"a":1,"k":"ser 정체 설명","t":"내 여행 가방은 보라색 가방이다.","e":"'la morada'는 'la maleta morada(보라색 가방)'에서 명사를 생략한 표현입니다. '내 가방은 보라색 그것이다'라고 여러 개 중 어느 것인지 정체를 밝히므로 ser를 씁니다. 위치를 말한다면 estar를 쓰겠지만 여기서는 'la + 형용사'가 와서 ser가 맞습니다.","x":["ha: haber는 완료형 조동사라 ✗","es: 어느 것인지 정체를 밝힘 → 정답 ✓","está: 위치·상태를 나타내 'la morada(보라색 것)'와 함께 쓰지 않습니다 ✗","hay: 존재를 나타내서 ✗"]},{"id":"G750","q":"Pienso que ____ amor es lo más importante en la vida.","o":["lo","el","ø","la"],"a":1,"k":"추상명사 + 정관사","t":"나는 사랑이 인생에서 가장 중요한 것이라고 생각한다.","e":"사랑, 우정, 행복처럼 추상적인 개념을 일반적으로 말하는 주어에는 정관사를 씁니다. amor는 남성 명사이므로 'el amor'가 됩니다. 뒤의 'lo más importante'는 '가장 중요한 것'이라는 중성 표현입니다.","x":["lo: 중성 관사로 형용사 앞에 쓰며 명사 앞에는 쓰지 않습니다 ✗","el: 일반 개념 주어의 정관사 → 정답 ✓","ø: 일반적인 개념을 주어로 쓸 때는 관사가 필요합니다 ✗","la: 여성형인데 amor는 남성 명사라 ✗"]}];